{
  "name": "QbD-PharmOptima",
  "description": "A scientific Design of Experiments (DoE) selector and protocol generator for pharmaceutical formulation, based on Quality by Design (QbD) principles."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ExperimentGoal {
  SCREENING = 'Screening',
  OPTIMIZATION = 'Optimization',
}

export enum FormFactor {
  PROCESS_OR_INDEPENDENT = 'Process/Independent Factors',
  MIXTURE = 'Mixture (Sum to 100%)',
}

export enum DeliverySystem {
  LIPOSOMES = 'Liposomes / Delicate Structures',
  LIPID_NANOCAPSULES = 'Lipid Nanocapsules (LNC)',
  EMULSIONS = 'Emulsions',
  MICROEMULSIONS = 'Microemulsions',
  TABLETS_SOLIDS = 'Tablets / Solid Dosage Forms',
  GENERIC_ROBUST = 'Generic / Robust System',
  GENERIC_IRREGULAR = 'Irregular Experimental Domain',
}

export interface DesignRecommendation {
  name: string;
  acronym: string;
  reasoning: string;
  sourceReference: string;
  suitability: string[];
  caveats: string[];
}

export interface AnalysisRequest {
  system: DeliverySystem;
  goal: ExperimentGoal;
  factors: string[];
  responses: string[];
}

import { DeliverySystem, DesignRecommendation, ExperimentGoal, FormFactor } from './types';

// Logic derived strictly from Chapters 3 and 5
export const RECOMMENDATIONS: Record<string, DesignRecommendation> = {
  // Screening Designs
  TAGUCHI: {
    name: "Taguchi Design",
    acronym: "Taguchi",
    reasoning: "Used for screening main effects with minimum experiments. Derived from Japanese engineering principles for robust design.",
    sourceReference: "Chapter 3, Section 3.3.1.1; Chapter 5, Table 5.1",
    suitability: ["Screening phase", "Minimizing experimental runs"],
    caveats: ["Low resolution", "Ignores interactions", "Criticized for being inefficient"]
  },
  PLACKETT_BURMAN: {
    name: "Plackett-Burman Design",
    acronym: "PBD",
    reasoning: "Efficient for identifying most influential factors out of a large number (saturated design). Identifies main effects only.",
    sourceReference: "Chapter 3, Section 3.3.1.2; Chapter 5, Table 5.1",
    suitability: ["Screening huge number of factors", "Initial stages of QbD"],
    caveats: ["confounding effects", "No center points typically"]
  },
  FULL_FACTORIAL: {
    name: "Full Factorial Design",
    acronym: "FFD",
    reasoning: "Considers all possible combinations. Best for detailed understanding when factor count is low (2-3).",
    sourceReference: "Chapter 3, Section 3.3.2; Chapter 5, Table 5.1",
    suitability: ["Screening small number of factors", "Studying interactions detailedly", "Emulsion Stability (Ch 3, 3.4.1)"],
    caveats: ["Run number increases exponentially with factors"]
  },

  // Optimization - Surface
  CENTRAL_COMPOSITE: {
    name: "Central Composite Design",
    acronym: "CCD",
    reasoning: "Highly accurate and robust. Good for stable systems where widening the experimental space (alpha points) is acceptable.",
    sourceReference: "Chapter 3, Section 3.3.3.2; Chapter 5, Table 5.1",
    suitability: ["Robust formulations (Tablets)", "Nanoemulsions (Aspirin case study)"],
    caveats: ["Unsuitable for delicate systems (Liposomes) due to extreme conditions (alpha points)"]
  },
  BOX_BEHNKEN: {
    name: "Box-Behnken Design",
    acronym: "BBD",
    reasoning: "Avoids corner points and extreme conditions. Specifically recommended for delicate structures like liposomes or proteins that might denature/degrade at extremes.",
    sourceReference: "Chapter 3, Section 3.3.3.3; Chapter 5, Table 5.1",
    suitability: ["Liposomes", "Proteins", "Delicate systems", "SMEDDS (Telmisartan case study)"],
    caveats: ["Less coverage of the corners of design space"]
  },
  D_OPTIMAL_SURFACE: {
    name: "D-Optimal Design",
    acronym: "DOD",
    reasoning: "Computer-generated design for irregular domains or when constraints exist. Maximizes the information matrix determinant.",
    sourceReference: "Chapter 3, Section 3.3.3.5; Chapter 5, Section 5.4",
    suitability: ["Irregular experimental regions", "Qualitative factors", "Emulsion Viscosity/Conductivity (Ch 3, 3.4.1)"],
    caveats: ["Requires computer algorithm", "Asymmetrical"]
  },

  // Optimization - Mixture
  SIMPLEX_LATTICE: {
    name: "Simplex Lattice Design",
    acronym: "SLD",
    reasoning: "Standard design for mixture problems where components sum to 100% and domain is a regular triangle/simplex.",
    sourceReference: "Chapter 5, Table 5.1; Chapter 3, Section 3.4.2",
    suitability: ["Microemulsions (Triangular domain)", "Simple mixtures"],
    caveats: ["Not for irregular domains"]
  },
  D_OPTIMAL_MIXTURE: {
    name: "D-Optimal Mixture Design",
    acronym: "D-Opt Mix",
    reasoning: "Essential when constraints on components create an irregular feasibility domain (not a perfect triangle).",
    sourceReference: "Chapter 5, Section 5.5 (Lipid Nanocapsules Case Study)",
    suitability: ["Lipid Nanocapsules (LNC)", "Constrained mixtures"],
    caveats: ["Requires software generation"]
  }
};

export const FISHBONE_CATEGORIES = [
  "Material Attributes",
  "Process Parameters",
  "Environment",
  "Methods",
  "Equipment"
];

import { GoogleGenAI } from "@google/genai";
import { AnalysisRequest } from "../types";

const getClient = () => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        throw new Error("API Key not found");
    }
    return new GoogleGenAI({ apiKey });
};

export const generateProtocol = async (request: AnalysisRequest, recommendedDesign: string): Promise<string> => {
    try {
        const ai = getClient();

        const prompt = `
        Acting as a pharmaceutical formulation scientist, generate a brief experimental protocol outline.

        Context:
        - Drug Delivery System: ${request.system}
        - Goal: ${request.goal}
        - Factors identified: ${request.factors.join(', ') || "Not specified"}
        - Critical Quality Attributes (Responses): ${request.responses.join(', ') || "Not specified"}
        - Selected DoE Design: ${recommendedDesign}

        Please provide:
        1. A brief scientific rationale for why ${recommendedDesign} is mathematically appropriate for ${request.system}, referencing general QbD principles.
        2. A hypothetical list of 3-4 specific independent variables (with units) and their ranges typical for this system.
        3. A hypothetical list of 2 dependent variables (responses) and their desired constraints.
        4. A standard mathematical model equation format (e.g., Y = b0 + b1X1...) relevant to this design.

        Keep the tone academic and precise. Formatted in Markdown.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-latest', // Using the latest flash model for speed/quality balance
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 0 } // Disable thinking for faster response on standard protocol generation
            }
        });

        return response.text || "No response generated.";
    } catch (error) {
        console.error("Gemini API Error:", error);
        return "Unable to generate protocol. Please check your API configuration.";
    }
};

import React, { useState } from 'react';
import { FISHBONE_CATEGORIES } from '../constants';
import { Plus, X } from 'lucide-react';

interface FishboneProps {
    onFactorsChange: (factors: string[]) => void;
}

const FishboneDiagram: React.FC<FishboneProps> = ({ onFactorsChange }) => {
    const [factors, setFactors] = useState<Record<string, string[]>>({
        "Material Attributes": [],
        "Process Parameters": [],
        "Environment": [],
        "Methods": [],
        "Equipment": []
    });
    const [inputs, setInputs] = useState<Record<string, string>>({});

    const handleAdd = (category: string) => {
        const val = inputs[category];
        if (!val || val.trim() === "") return;

        const newFactors = {
            ...factors,
            [category]: [...(factors[category] || []), val]
        };
        setFactors(newFactors);
        setInputs({ ...inputs, [category]: "" });

        // Flatten for parent
        const flatList = Object.values(newFactors).flat();
        onFactorsChange(flatList);
    };

    const handleRemove = (category: string, index: number) => {
        const newFactors = {
            ...factors,
            [category]: factors[category].filter((_, i) => i !== index)
        };
        setFactors(newFactors);
        const flatList = Object.values(newFactors).flat();
        onFactorsChange(flatList);
    };

    return (
        <div className="bg-white p-6 rounded-lg shadow-md border border-gray-200">
            <h3 className="text-lg font-bold text-science-900 mb-2">Ishikawa (Fishbone) Diagram Builder</h3>
            <p className="text-sm text-gray-600 mb-6">
                As described in Chapter 5, use the Fishbone diagram to brainstorm independent variables (Causes) that affect your formulation (Effect).
            </p>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {FISHBONE_CATEGORIES.map((cat) => (
                    <div key={cat} className="border border-science-100 rounded bg-science-50 p-3">
                        <h4 className="font-semibold text-science-800 text-sm mb-2">{cat}</h4>
                        <ul className="space-y-1 mb-2 min-h-[40px]">
                            {factors[cat]?.map((f, i) => (
                                <li key={i} className="flex justify-between items-center text-xs bg-white px-2 py-1 rounded shadow-sm">
                                    <span>{f}</span>
                                    <button onClick={() => handleRemove(cat, i)} className="text-red-400 hover:text-red-600">
                                        <X size={12} />
                                    </button>
                                </li>
                            ))}
                            {(!factors[cat] || factors[cat].length === 0) && (
                                <li className="text-xs text-gray-400 italic">No factors added</li>
                            )}
                        </ul>
                        <div className="flex gap-2">
                            <input 
                                type="text" 
                                className="flex-1 text-xs border border-gray-300 rounded px-2 py-1 focus:outline-none focus:border-science-500"
                                placeholder="Add factor..."
                                value={inputs[cat] || ""}
                                onChange={(e) => setInputs({...inputs, [cat]: e.target.value})}
                                onKeyDown={(e) => e.key === 'Enter' && handleAdd(cat)}
                            />
                            <button 
                                onClick={() => handleAdd(cat)}
                                className="bg-science-600 text-white rounded p-1 hover:bg-science-800"
                            >
                                <Plus size={14} />
                            </button>
                        </div>
                    </div>
                ))}
            </div>

            <div className="mt-8 flex items-center justify-end">
                <div className="h-1 bg-science-900 flex-1 relative">
                   <div className="absolute right-0 -top-2 w-0 h-0 border-t-[8px] border-t-transparent border-l-[12px] border-l-science-900 border-b-[8px] border-b-transparent"></div>
                </div>
                <div className="ml-4 border-2 border-science-900 p-4 rounded text-center font-bold text-science-900 w-32">
                    CQA / Response
                </div>
            </div>
        </div>
    );
};

export default FishboneDiagram;

import React, { useState } from 'react';
import { DesignRecommendation, AnalysisRequest } from '../types';
import { generateProtocol } from '../services/geminiService';
import { FileText, Loader2, BookOpen, AlertTriangle } from 'lucide-react';
import ReactMarkdown from 'react-markdown';

interface ResultsViewProps {
  recommendation: DesignRecommendation | null;
  request: AnalysisRequest;
  onReset: () => void;
}

const ResultsView: React.FC<ResultsViewProps> = ({ recommendation, request, onReset }) => {
  const [protocol, setProtocol] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  if (!recommendation) return null;

  const handleGenerateProtocol = async () => {
    setLoading(true);
    const result = await generateProtocol(request, recommendation.name);
    setProtocol(result);
    setLoading(false);
  };

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Primary Recommendation Card */}
      <div className="bg-white rounded-xl shadow-lg overflow-hidden border-t-4 border-science-600">
        <div className="p-6 md:p-8">
          <div className="flex items-center gap-2 text-science-600 font-semibold mb-2 text-sm uppercase tracking-wide">
            <BookOpen size={16} />
            Scientific Recommendation
          </div>
          <h2 className="text-3xl font-bold text-gray-900 mb-4">
            {recommendation.name} <span className="text-gray-400 font-normal">({recommendation.acronym})</span>
          </h2>

          <div className="prose text-gray-700 mb-6 border-l-4 border-science-200 pl-4 py-2 bg-science-50 rounded-r">
            <p className="font-medium text-lg">{recommendation.reasoning}</p>
          </div>

          <div className="grid md:grid-cols-2 gap-6">
            <div>
              <h4 className="font-semibold text-green-700 mb-2 flex items-center gap-2">
                Suitable For
              </h4>
              <ul className="list-disc list-inside space-y-1 text-sm text-gray-700">
                {recommendation.suitability.map((s, i) => (
                  <li key={i}>{s}</li>
                ))}
              </ul>
            </div>
            <div>
              <h4 className="font-semibold text-amber-700 mb-2 flex items-center gap-2">
                <AlertTriangle size={16} /> Caveats
              </h4>
              <ul className="list-disc list-inside space-y-1 text-sm text-gray-700">
                {recommendation.caveats.map((c, i) => (
                  <li key={i}>{c}</li>
                ))}
              </ul>
            </div>
          </div>

          <div className="mt-6 pt-6 border-t border-gray-100 text-xs text-gray-500">
            Source: {recommendation.sourceReference}
          </div>
        </div>
      </div>

      {/* Protocol Generator Section */}
      <div className="bg-slate-50 rounded-xl border border-slate-200 p-6">
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
            <FileText className="text-science-600" />
            AI Formulation Assistant
          </h3>
          {!protocol && (
            <button
              onClick={handleGenerateProtocol}
              disabled={loading}
              className="bg-science-600 text-white px-4 py-2 rounded-lg hover:bg-science-700 disabled:opacity-50 flex items-center gap-2 transition-colors"
            >
              {loading ? <Loader2 className="animate-spin" size={18} /> : null}
              {loading ? 'Generating...' : 'Generate Protocol'}
            </button>
          )}
        </div>

        {!protocol && !loading && (
          <p className="text-slate-600 text-sm">
            Use the Gemini API to generate a customized experimental protocol based on this design and your selected parameters.
          </p>
        )}

        {protocol && (
          <div className="bg-white p-6 rounded border border-gray-200 prose prose-sm max-w-none text-gray-800">
            <ReactMarkdown>{protocol}</ReactMarkdown>
          </div>
        )}
      </div>

      <div className="flex justify-center pt-8">
        <button
          onClick={onReset}
          className="text-science-600 hover:text-science-800 font-medium underline underline-offset-4"
        >
          Start New Analysis
        </button>
      </div>
    </div>
  );
};

export default ResultsView;

import React, { useState } from 'react';
import { Activity, FlaskConical, Settings, CheckCircle2, ChevronRight } from 'lucide-react';
import FishboneDiagram from './components/FishboneDiagram';
import ResultsView from './components/ResultsView';
import { AnalysisRequest, DeliverySystem, DesignRecommendation, ExperimentGoal, FormFactor } from './types';
import { RECOMMENDATIONS } from './constants';

const StepIndicator: React.FC<{ currentStep: number }> = ({ currentStep }) => (
  <div className="flex justify-center mb-8">
    {[1, 2, 3, 4].map((step) => (
      <div key={step} className="flex items-center">
        <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm border-2 
          ${step <= currentStep ? 'bg-science-600 border-science-600 text-white' : 'bg-white border-gray-300 text-gray-400'}`}>
          {step < currentStep ? <CheckCircle2 size={16} /> : step}
        </div>
        {step < 4 && (
          <div className={`w-12 h-1 
            ${step < currentStep ? 'bg-science-600' : 'bg-gray-200'}`} 
          />
        )}
      </div>
    ))}
  </div>
);

const App: React.FC = () => {
  const [step, setStep] = useState(1);
  const [request, setRequest] = useState<AnalysisRequest>({
    goal: ExperimentGoal.OPTIMIZATION,
    system: DeliverySystem.GENERIC_ROBUST,
    factors: [],
    responses: []
  });

  const [formFactor, setFormFactor] = useState<FormFactor>(FormFactor.PROCESS_OR_INDEPENDENT);
  const [isConstraintIrregular, setIsConstraintIrregular] = useState(false);
  const [recommendation, setRecommendation] = useState<DesignRecommendation | null>(null);

  const determineDesign = () => {
    let rec: DesignRecommendation;

    // Logic derived strictly from Chapters 3 & 5
    if (request.goal === ExperimentGoal.SCREENING) {
       // Screening path
       if (request.factors.length > 5) { // Arbitrary cutoff for "large number" mentioned in text
         rec = RECOMMENDATIONS.PLACKETT_BURMAN;
       } else {
         rec = RECOMMENDATIONS.FULL_FACTORIAL; // Or Taguchi, but Full Factorial is safer for interactions
       }
    } else {
      // Optimization Path
      if (formFactor === FormFactor.MIXTURE) {
        // Mixture Designs
        if (request.system === DeliverySystem.LIPID_NANOCAPSULES || isConstraintIrregular) {
          rec = RECOMMENDATIONS.D_OPTIMAL_MIXTURE; // Ch 5: LNCs use D-Opt Mix due to irregular domain
        } else {
          rec = RECOMMENDATIONS.SIMPLEX_LATTICE; // Ch 3: Microemulsions/general mixture
        }
      } else {
        // Response Surface / Independent Factors
        if (isConstraintIrregular || request.system === DeliverySystem.GENERIC_IRREGULAR) {
          rec = RECOMMENDATIONS.D_OPTIMAL_SURFACE;
        } else if (
          request.system === DeliverySystem.LIPOSOMES || 
          request.system === DeliverySystem.MICROEMULSIONS // Sometimes delicate
        ) {
          rec = RECOMMENDATIONS.BOX_BEHNKEN; // Ch 3: Suitable for delicate systems, avoids corners
        } else if (request.system === DeliverySystem.EMULSIONS) {
             // Specific Case Study Logic from Ch 3
             // Note: The app simplifies. If stability (Screening) -> FF. If Viscosity (Opt) -> D-Opt.
             // We assume optimization here.
             rec = RECOMMENDATIONS.D_OPTIMAL_SURFACE; 
        } else {
          // Default Robust
          rec = RECOMMENDATIONS.CENTRAL_COMPOSITE; // Ch 3: General robust design
        }
      }
    }
    setRecommendation(rec);
    setStep(4);
  };

  const reset = () => {
    setStep(1);
    setRecommendation(null);
    setIsConstraintIrregular(false);
    setRequest({
      goal: ExperimentGoal.OPTIMIZATION,
      system: DeliverySystem.GENERIC_ROBUST,
      factors: [],
      responses: []
    });
  };

  return (
    <div className="min-h-screen bg-science-50 text-slate-800 font-sans">
      <header className="bg-white border-b border-gray-200 py-4 shadow-sm sticky top-0 z-10">
        <div className="container mx-auto px-4 flex items-center gap-3">
          <FlaskConical className="text-science-600" size={32} />
          <div>
            <h1 className="text-xl font-bold text-science-900 tracking-tight">QbD-PharmOptima</h1>
            <p className="text-xs text-gray-500">Computer-Aided Formulation Development (Based on Hathout et al.)</p>
          </div>
        </div>
      </header>

      <main className="container mx-auto px-4 py-8 max-w-4xl">
        <StepIndicator currentStep={step} />

        {step === 1 && (
          <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200 animate-fade-in">
            <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
              <Activity className="text-science-500" />
              Define Objectives
            </h2>

            <div className="grid md:grid-cols-2 gap-6">
              <button 
                onClick={() => { setRequest({...request, goal: ExperimentGoal.SCREENING}); setStep(2); }}
                className="group p-6 border-2 border-gray-100 rounded-xl hover:border-science-500 hover:bg-science-50 transition-all text-left"
              >
                <span className="block text-lg font-bold text-gray-800 mb-2 group-hover:text-science-700">Screening</span>
                <p className="text-sm text-gray-600">Identify the most influential factors from a large pool. (e.g., Taguchi, Plackett-Burman)</p>
              </button>

              <button 
                onClick={() => { setRequest({...request, goal: ExperimentGoal.OPTIMIZATION}); setStep(2); }}
                className="group p-6 border-2 border-gray-100 rounded-xl hover:border-science-500 hover:bg-science-50 transition-all text-left"
              >
                <span className="block text-lg font-bold text-gray-800 mb-2 group-hover:text-science-700">Optimization</span>
                <p className="text-sm text-gray-600">Find the best formulation settings using Response Surface or Mixture designs.</p>
              </button>
            </div>
          </div>
        )}

        {step === 2 && (
          <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200 animate-fade-in">
            <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
              <Settings className="text-science-500" />
              Identify Factors
            </h2>

            <FishboneDiagram onFactorsChange={(f) => setRequest({...request, factors: f})} />

            <div className="mt-8 flex justify-end">
               <button 
                onClick={() => setStep(3)} 
                className="bg-science-600 text-white px-6 py-3 rounded-lg hover:bg-science-700 font-medium flex items-center gap-2"
               >
                 Next Step <ChevronRight size={18} />
               </button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200 animate-fade-in">
             <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
              <FlaskConical className="text-science-500" />
              System Characteristics
            </h2>

            <div className="space-y-6">
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">Drug Delivery System Type</label>
                <select 
                  className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-science-500 outline-none"
                  value={request.system}
                  onChange={(e) => setRequest({...request, system: e.target.value as DeliverySystem})}
                >
                  {Object.values(DeliverySystem).map((ds) => (
                    <option key={ds} value={ds}>{ds}</option>
                  ))}
                </select>
                <p className="text-xs text-gray-500 mt-2">
                  *Selection influences robustness requirements (e.g., Liposomes require designs that avoid extreme conditions).
                </p>
              </div>

              {request.goal === ExperimentGoal.OPTIMIZATION && (
                <>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Variables Nature</label>
                    <div className="flex gap-4">
                      <label className="flex items-center gap-2 cursor-pointer">
                        <input 
                          type="radio" 
                          name="formFactor" 
                          checked={formFactor === FormFactor.PROCESS_OR_INDEPENDENT} 
                          onChange={() => setFormFactor(FormFactor.PROCESS_OR_INDEPENDENT)}
                          className="text-science-600 focus:ring-science-500"
                        />
                        <span className="text-sm">Process/Independent (e.g., Temp, pH)</span>
                      </label>
                      <label className="flex items-center gap-2 cursor-pointer">
                        <input 
                          type="radio" 
                          name="formFactor" 
                          checked={formFactor === FormFactor.MIXTURE} 
                          onChange={() => setFormFactor(FormFactor.MIXTURE)}
                          className="text-science-600 focus:ring-science-500"
                        />
                        <span className="text-sm">Mixture Components (Sum = 100%)</span>
                      </label>
                    </div>
                  </div>

                  <div>
                     <label className="flex items-center gap-3 p-4 border rounded-lg cursor-pointer hover:bg-gray-50">
                        <input 
                          type="checkbox" 
                          checked={isConstraintIrregular}
                          onChange={(e) => setIsConstraintIrregular(e.target.checked)}
                          className="w-5 h-5 text-science-600 rounded focus:ring-science-500"
                        />
                        <div>
                          <span className="block font-bold text-gray-800">Irregular Feasibility Domain?</span>
                          <span className="text-xs text-gray-500">Check this if certain combinations of factors are impossible or constrained (e.g., as in LNCs).</span>
                        </div>
                     </label>
                  </div>
                </>
              )}
            </div>

            <div className="mt-8 flex justify-end">
               <button 
                onClick={determineDesign} 
                className="bg-science-600 text-white px-6 py-3 rounded-lg hover:bg-science-700 font-bold shadow-lg shadow-science-200"
               >
                 Analyze & Select Design
               </button>
            </div>
          </div>
        )}

        {step === 4 && (
          <ResultsView 
            recommendation={recommendation} 
            request={request}
            onReset={reset}
          />
        )}

      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { AnalysisRequest } from "../types";

const getClient = () => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        throw new Error("API Key not found in process.env.API_KEY");
    }
    return new GoogleGenAI({ apiKey });
};

export const generateProtocol = async (request: AnalysisRequest, recommendedDesign: string): Promise<string> => {
    try {
        const ai = getClient();

        const prompt = `
        Acting as a pharmaceutical formulation scientist, generate a brief experimental protocol outline.

        Context:
        - Drug Delivery System: ${request.system}
        - Goal: ${request.goal}
        - Factors identified: ${request.factors.join(', ') || "Not specified"}
        - Critical Quality Attributes (Responses): ${request.responses.join(', ') || "Not specified"}
        - Selected DoE Design: ${recommendedDesign}

        Please provide:
        1. A brief scientific rationale for why ${recommendedDesign} is mathematically appropriate for ${request.system}, referencing general QbD principles.
        2. A hypothetical list of 3-4 specific independent variables (with units) and their ranges typical for this system.
        3. A hypothetical list of 2 dependent variables (responses) and their desired constraints.
        4. A standard mathematical model equation format (e.g., Y = b0 + b1X1...) relevant to this design.

        Keep the tone academic and precise. Formatted in Markdown.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview', 
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 0 } // Disable thinking for standard protocol generation
            }
        });

        return response.text || "No response generated.";
    } catch (error: any) {
        console.error("Gemini API Error:", error);
        const msg = error instanceof Error ? error.message : String(error);
        return `Unable to generate protocol. Error: ${msg}. Please check your API key and network connection.`;
    }
};

import React, { useState } from 'react';
import { DesignRecommendation, AnalysisRequest } from '../types';
