              <ul className="list-disc list-inside space-y-1 text-sm text-gray-700">
                {recommendation.suitability.map((s, i) => (
                  <li key={i}>{s}</li>
                ))}
              </ul>
            </div>
            <div>
              <h4 className="font-semibold text-amber-700 mb-2 flex items-center gap-2">
                <AlertTriangle size={16} /> Caveats
              </h4>
              <ul className="list-disc list-inside space-y-1 text-sm text-gray-700">
