import { GoogleGenAI } from "@google/genai";
import { AnalysisRequest } from "../types";

const getClient = () => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        throw new Error("API Key not found in process.env.API_KEY");
    }
    return new GoogleGenAI({ apiKey });
};

export const generateProtocol = async (request: AnalysisRequest, recommendedDesign: string): Promise<string> => {
    try {
        const ai = getClient();

        // Format factors for the prompt
        const factorDetails = request.factors.map(f => 
            `- ${f.name} (${f.unit}): Range [${f.low} to ${f.high}]`
        ).join('\n');

        const prompt = `
        Acting as a pharmaceutical formulation scientist, generate a detailed experimental protocol.

        Context:
        - Drug Delivery System: ${request.system}
        - Goal: ${request.goal}
        - Selected DoE Design: ${recommendedDesign}
        - Critical Quality Attributes (Responses): ${request.responses.join(', ') || "Not specified"}

        Defined Factors & Levels:
        ${factorDetails}

        Please provide the following in Markdown format:

        1. **Scientific Rationale**: Briefly explain why ${recommendedDesign} is mathematically appropriate for ${request.system}, referencing QbD principles (e.g. robustness vs delicate systems).

        2. **Mathematical Model**: A standard model equation format (e.g., Y = b0 + b1X1...) relevant to this design.

        3. **Proposed Experimental Runs**: 
           Generate a Markdown Table representing the experimental matrix for ${recommendedDesign}.
           - Columns: Run #, ${request.factors.map(f => f.name).join(', ')}.
           - Use the actual real-world values (from the provided ranges) instead of coded values (-1, 0, 1) where possible. 
           - Include necessary center points or star points if the design requires them.
           - If the design is huge (e.g. Full Factorial with >5 factors), provide a representative subset (first 8-10 runs).

        4. **Dependent Variables**: Brief list of responses and desired constraints.

        Keep the tone academic and precise.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview', 
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 0 } 
            }
        });

        return response.text || "No response generated.";
    } catch (error: any) {
        console.error("Gemini API Error:", error);
        const msg = error instanceof Error ? error.message : String(error);
        return `Unable to generate protocol. Error: ${msg}. Please check your API key and network connection.`;
    }
};

import React from 'react';

interface VisualizerProps {
    acronym: string;
}

const DesignVisualizer: React.FC<VisualizerProps> = ({ acronym }) => {
    // Helper for dots
    const Dot = ({ cx, cy, color = "#0284c7", r = 4 }: any) => (
        <circle cx={cx} cy={cy} r={r} fill={color} stroke="white" strokeWidth="1" />
    );

    const renderDiagram = () => {
        const isMixture = ['SLD', 'D-Opt Mix'].includes(acronym);
        const isBBD = acronym === 'BBD';
        const isCCD = acronym === 'CCD';
        const isFFD = acronym === 'FFD';
        const isTaguchi = ['Taguchi', 'PBD'].includes(acronym);

        if (isMixture) {
            return (
                <svg viewBox="0 0 200 180" className="w-full h-48 drop-shadow-sm">
                    {/* Triangle */}
                    <path d="M20,160 L100,20 L180,160 Z" fill="#f0f9ff" stroke="#94a3b8" strokeWidth="2" />
                    <text x="100" y="15" textAnchor="middle" className="text-[10px] fill-slate-500">Component A (100%)</text>
                    <text x="10" y="175" textAnchor="middle" className="text-[10px] fill-slate-500">B</text>
                    <text x="190" y="175" textAnchor="middle" className="text-[10px] fill-slate-500">C</text>

                    {/* Lattice Points (Simplex) */}
                    <Dot cx="100" cy="20" /> {/* Top */}
                    <Dot cx="20" cy="160" /> {/* Left */}
                    <Dot cx="180" cy="160" /> {/* Right */}
                    <Dot cx="60" cy="90" /> {/* Mid Left */}
                    <Dot cx="140" cy="90" /> {/* Mid Right */}
                    <Dot cx="100" cy="160" /> {/* Bottom Mid */}
                    <Dot cx="100" cy="105" color="#ef4444" r={5} /> {/* Center (Centroid) */}
                </svg>
            );
        }

        // 3D Cube Representation for Surface/Screening
        return (
            <svg viewBox="0 0 200 200" className="w-full h-48 drop-shadow-sm">
                {/* Back Face */}
                <path d="M60,60 L140,60 L140,140 L60,140 Z" fill="#f8fafc" stroke="#e2e8f0" strokeWidth="2" strokeDasharray="4" />
                {/* Connecting Lines */}
                <line x1="40" y1="40" x2="60" y2="60" stroke="#cbd5e1" strokeWidth="2" />
                <line x1="120" y1="40" x2="140" y2="60" stroke="#cbd5e1" strokeWidth="2" />
                <line x1="40" y1="120" x2="60" y2="140" stroke="#cbd5e1" strokeWidth="2" />
                <line x1="120" y1="120" x2="140" y2="140" stroke="#cbd5e1" strokeWidth="2" />
                {/* Front Face */}
                <path d="M40,40 L120,40 L120,120 L40,120 Z" fill="none" stroke="#94a3b8" strokeWidth="2" />

                {/* Points Logic */}
                {/* FFD: Corners only */}
                {(isFFD || isCCD) && (
                    <>
                        {/* Front Corners */}
                        <Dot cx="40" cy="40" /> <Dot cx="120" cy="40" />
                        <Dot cx="40" cy="120" /> <Dot cx="120" cy="120" />
                        {/* Back Corners */}
                        <Dot cx="60" cy="60" color="#94a3b8" /> <Dot cx="140" cy="60" color="#94a3b8" />
                        <Dot cx="60" cy="140" color="#94a3b8" /> <Dot cx="140" cy="140" color="#94a3b8" />
                    </>
                )}

                {/* BBD: Mid-edges only */}
                {isBBD && (
                    <>
                         {/* Front Face Mids */}
                         <Dot cx="80" cy="40" /> <Dot cx="80" cy="120" /> 
                         <Dot cx="40" cy="80" /> <Dot cx="120" cy="80" />
                         {/* Connecting Mids */}
                         <Dot cx="50" cy="50" /> <Dot cx="130" cy="50" />
                         <Dot cx="50" cy="130" /> <Dot cx="130" cy="130" />
                         {/* Back Face Mids */}
                         <Dot cx="100" cy="60" color="#94a3b8" /> <Dot cx="100" cy="140" color="#94a3b8" />
                         <Dot cx="60" cy="100" color="#94a3b8" /> <Dot cx="140" cy="100" color="#94a3b8" />
                    </>
                )}

                {/* Center Point (Common for Opt) */}
                {(!isTaguchi) && <Dot cx="90" cy="90" color="#ef4444" r={5} />}

                {/* CCD: Star Points (Outside faces) */}
                {isCCD && (
                    <>
                         <Dot cx="80" cy="20" color="#eab308" /> {/* Top Alpha */}
                         <Dot cx="80" cy="160" color="#eab308" /> {/* Bottom Alpha */}
                         <Dot cx="10" cy="80" color="#eab308" /> {/* Left Alpha */}
                         <Dot cx="150" cy="80" color="#eab308" /> {/* Right Alpha */}
                    </>
                )}
            </svg>
        );
    };

    return (
        <div className="flex flex-col items-center bg-white p-4 rounded-lg border border-slate-200">
            <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4">Design Geometry (Conceptual)</h4>
            {renderDiagram()}
            <div className="mt-4 flex flex-wrap gap-4 justify-center text-[10px] text-slate-600">
                <div className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-science-600"></span> Factorial Points</div>
                <div className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-red-500"></span> Center Point</div>
                {acronym === 'CCD' && <div className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-yellow-500"></span> Axial/Star Points</div>}
            </div>
        </div>
    );
};

export default DesignVisualizer;

import React from 'react';
import { FactorDefinition } from '../types';
import { ChevronRight } from 'lucide-react';

interface FactorSettingsProps {
    factors: FactorDefinition[];
    onUpdate: (updatedFactors: FactorDefinition[]) => void;
    onNext: () => void;
}

const FactorSettings: React.FC<FactorSettingsProps> = ({ factors, onUpdate, onNext }) => {

    const handleChange = (index: number, field: keyof FactorDefinition, value: string) => {
        const updated = [...factors];
        updated[index] = { ...updated[index], [field]: value };
        onUpdate(updated);
    };

    const isComplete = factors.every(f => f.low && f.high && f.unit);

    return (
        <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200 animate-fade-in">
            <h2 className="text-2xl font-bold mb-2 text-science-900">Define Factor Levels</h2>
            <p className="text-sm text-gray-600 mb-6">
                Specify the experimental range for each factor identified. These values will be used to generate the run table.
            </p>

            <div className="overflow-x-auto">
                <table className="w-full text-sm text-left text-gray-700">
                    <thead className="text-xs text-gray-700 uppercase bg-science-50 border-b border-science-100">
                        <tr>
                            <th className="px-4 py-3 rounded-tl-lg">Factor Name</th>
                            <th className="px-4 py-3">Unit (e.g., mg, °C)</th>
                            <th className="px-4 py-3">Low Level (-1)</th>
                            <th className="px-4 py-3 rounded-tr-lg">High Level (+1)</th>
                        </tr>
                    </thead>
                    <tbody>
                        {factors.map((factor, idx) => (
                            <tr key={idx} className="border-b border-gray-100 hover:bg-gray-50">
                                <td className="px-4 py-3 font-medium text-science-800">{factor.name}</td>
                                <td className="px-4 py-2">
                                    <input 
                                        type="text" 
                                        placeholder="mg, ml, rpm..." 
                                        className="w-full p-2 border border-gray-300 rounded focus:border-science-500 focus:outline-none"
                                        value={factor.unit}
                                        onChange={(e) => handleChange(idx, 'unit', e.target.value)}
                                    />
                                </td>
                                <td className="px-4 py-2">
                                    <input 
                                        type="text" 
                                        placeholder="e.g. 100" 
                                        className="w-full p-2 border border-gray-300 rounded focus:border-science-500 focus:outline-none"
                                        value={factor.low}
                                        onChange={(e) => handleChange(idx, 'low', e.target.value)}
                                    />
                                </td>
                                <td className="px-4 py-2">
                                    <input 
                                        type="text" 
                                        placeholder="e.g. 500" 
                                        className="w-full p-2 border border-gray-300 rounded focus:border-science-500 focus:outline-none"
                                        value={factor.high}
                                        onChange={(e) => handleChange(idx, 'high', e.target.value)}
                                    />
                                </td>
                            </tr>
                        ))}
                        {factors.length === 0 && (
                            <tr>
                                <td colSpan={4} className="px-4 py-6 text-center text-gray-500 italic">
                                    No factors selected. Go back to the Fishbone diagram.
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            <div className="mt-8 flex justify-end">
               <button 
                onClick={onNext} 
                disabled={!isComplete || factors.length === 0}
                className="bg-science-600 text-white px-6 py-3 rounded-lg hover:bg-science-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium flex items-center gap-2"
               >
                 Review System & Select Design <ChevronRight size={18} />
               </button>
            </div>
        </div>
    );
};

export default FactorSettings;

