    factors: [],
    responses: []
  });

  const [formFactor, setFormFactor] = useState<FormFactor>(FormFactor.PROCESS_OR_INDEPENDENT);
  const [isConstraintIrregular, setIsConstraintIrregular] = useState(false);
  const [recommendation, setRecommendation] = useState<DesignRecommendation | null>(null);

  // When converting from Fishbone (strings) to FactorSettings (Objects)
  const handleFishboneComplete = (factorNames: string[]) => {
      // Preserve existing factors if possible to avoid clearing user input
      const newFactors: FactorDefinition[] = factorNames.map(name => {
          const existing = request.factors.find(f => f.name === name);
          return existing || { name, unit: '', low: '', high: '' };
      });

      setRequest({ ...request, factors: newFactors });
      setStep(3);
  };

  const determineDesign = () => {
    let rec: DesignRecommendation;

    // Logic derived strictly from Chapters 3 & 5
    if (request.goal === ExperimentGoal.SCREENING) {
       // Screening path
       if (request.factors.length > 5) { // Arbitrary cutoff for "large number" mentioned in text
         rec = RECOMMENDATIONS.PLACKETT_BURMAN;
       } else {
         rec = RECOMMENDATIONS.FULL_FACTORIAL; 
       }
    } else {
      // Optimization Path
      if (formFactor === FormFactor.MIXTURE) {
        // Mixture Designs
        if (request.system === DeliverySystem.LIPID_NANOCAPSULES || isConstraintIrregular) {
          rec = RECOMMENDATIONS.D_OPTIMAL_MIXTURE; 
        } else {
          rec = RECOMMENDATIONS.SIMPLEX_LATTICE; 
        }
      } else {
        // Response Surface / Independent Factors
        if (isConstraintIrregular || request.system === DeliverySystem.GENERIC_IRREGULAR) {
          rec = RECOMMENDATIONS.D_OPTIMAL_SURFACE;
        } else if (
          request.system === DeliverySystem.LIPOSOMES || 
          request.system === DeliverySystem.MICROEMULSIONS // Sometimes delicate
        ) {
          rec = RECOMMENDATIONS.BOX_BEHNKEN; 
        } else if (request.system === DeliverySystem.EMULSIONS) {
             rec = RECOMMENDATIONS.D_OPTIMAL_SURFACE; 
        } else {
          // Default Robust
          rec = RECOMMENDATIONS.CENTRAL_COMPOSITE; 
        }
      }
    }
    setRecommendation(rec);
    setStep(5);
  };

  const reset = () => {
    setStep(1);
    setRecommendation(null);
    setIsConstraintIrregular(false);
    setRequest({
      goal: ExperimentGoal.OPTIMIZATION,
      system: DeliverySystem.GENERIC_ROBUST,
      factors: [],
      responses: []
    });
  };

  return (
    <div className="min-h-screen bg-science-50 text-slate-800 font-sans">
      <header className="bg-white border-b border-gray-200 py-4 shadow-sm sticky top-0 z-10">
        <div className="container mx-auto px-4 flex items-center gap-3">
          <FlaskConical className="text-science-600" size={32} />
          <div>
            <h1 className="text-xl font-bold text-science-900 tracking-tight">QbD-PharmOptima</h1>
            <p className="text-xs text-gray-500">Computer-Aided Formulation Development (Based on Hathout et al.)</p>
          </div>
        </div>
      </header>

      <main className="container mx-auto px-4 py-8 max-w-4xl">
        <StepIndicator currentStep={step} />

        {step === 1 && (
          <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200 animate-fade-in">
            <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
              <Activity className="text-science-500" />
              Define Objectives
            </h2>

            <div className="grid md:grid-cols-2 gap-6">
              <button 
                onClick={() => { setRequest({...request, goal: ExperimentGoal.SCREENING}); setStep(2); }}
                className="group p-6 border-2 border-gray-100 rounded-xl hover:border-science-500 hover:bg-science-50 transition-all text-left"
              >
                <span className="block text-lg font-bold text-gray-800 mb-2 group-hover:text-science-700">Screening</span>
                <p className="text-sm text-gray-600">Identify the most influential factors from a large pool. (e.g., Taguchi, Plackett-Burman)</p>
              </button>

              <button 
                onClick={() => { setRequest({...request, goal: ExperimentGoal.OPTIMIZATION}); setStep(2); }}
                className="group p-6 border-2 border-gray-100 rounded-xl hover:border-science-500 hover:bg-science-50 transition-all text-left"
              >
                <span className="block text-lg font-bold text-gray-800 mb-2 group-hover:text-science-700">Optimization</span>
                <p className="text-sm text-gray-600">Find the best formulation settings using Response Surface or Mixture designs.</p>
              </button>
            </div>
          </div>
        )}

        {step === 2 && (
          <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200 animate-fade-in">
            <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
              <Settings className="text-science-500" />
              Identify Factors
            </h2>

            <FishboneDiagram onFactorsChange={(names) => {
                 // Convert existing factors to names for compatibility with FishboneDiagram which only handles strings locally
                 handleFishboneComplete(names);
            }} />
          </div>
        )}

        {step === 3 && (
            <FactorSettings 
                factors={request.factors}
                onUpdate={(updated) => setRequest({ ...request, factors: updated })}
                onNext={() => setStep(4)}
            />
        )}

        {step === 4 && (
          <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200 animate-fade-in">
             <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
              <FlaskConical className="text-science-500" />
              System Characteristics
            </h2>

            <div className="space-y-6">
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">Drug Delivery System Type</label>
                <select 
                  className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-science-500 outline-none"
                  value={request.system}
                  onChange={(e) => setRequest({...request, system: e.target.value as DeliverySystem})}
                >
                  {Object.values(DeliverySystem).map((ds) => (
                    <option key={ds} value={ds}>{ds}</option>
                  ))}
                </select>
                <p className="text-xs text-gray-500 mt-2">
                  *Selection influences robustness requirements (e.g., Liposomes require designs that avoid extreme conditions).
                </p>
              </div>

              {request.goal === ExperimentGoal.OPTIMIZATION && (
                <>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">Variables Nature</label>
                    <div className="flex gap-4">
                      <label className="flex items-center gap-2 cursor-pointer">
                        <input 
                          type="radio" 
                          name="formFactor" 
                          checked={formFactor === FormFactor.PROCESS_OR_INDEPENDENT} 
                          onChange={() => setFormFactor(FormFactor.PROCESS_OR_INDEPENDENT)}
                          className="text-science-600 focus:ring-science-500"
                        />
                        <span className="text-sm">Process/Independent (e.g., Temp, pH)</span>
                      </label>
                      <label className="flex items-center gap-2 cursor-pointer">
                        <input 
                          type="radio" 
                          name="formFactor" 
                          checked={formFactor === FormFactor.MIXTURE} 
                          onChange={() => setFormFactor(FormFactor.MIXTURE)}
                          className="text-science-600 focus:ring-science-500"
                        />
                        <span className="text-sm">Mixture Components (Sum = 100%)</span>
                      </label>
                    </div>
                  </div>

                  <div>
                     <label className="flex items-center gap-3 p-4 border rounded-lg cursor-pointer hover:bg-gray-50">
                        <input 
                          type="checkbox" 
                          checked={isConstraintIrregular}
                          onChange={(e) => setIsConstraintIrregular(e.target.checked)}
                          className="w-5 h-5 text-science-600 rounded focus:ring-science-500"
                        />
                        <div>
                          <span className="block font-bold text-gray-800">Irregular Feasibility Domain?</span>
                          <span className="text-xs text-gray-500">Check this if certain combinations of factors are impossible or constrained (e.g., as in LNCs).</span>
                        </div>
                     </label>
                  </div>
                </>
              )}
            </div>

            <div className="mt-8 flex justify-end">
               <button 
                onClick={determineDesign} 
                className="bg-science-600 text-white px-6 py-3 rounded-lg hover:bg-science-700 font-bold shadow-lg shadow-science-200"
               >
                 Analyze & Select Design
               </button>
            </div>
          </div>
        )}

        {step === 5 && (
          <ResultsView 
            recommendation={recommendation} 
            request={request}
            onReset={reset}
          />
        )}

      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { FISHBONE_CATEGORIES } from '../constants';
import { Plus, X, ChevronRight } from 'lucide-react';

interface FishboneProps {
    onFactorsChange: (factorNames: string[]) => void;
}

const FishboneDiagram: React.FC<FishboneProps> = ({ onFactorsChange }) => {
    const [factors, setFactors] = useState<Record<string, string[]>>({
        "Material Attributes": [],
        "Process Parameters": [],
        "Environment": [],
        "Methods": [],
        "Equipment": []
    });
    const [inputs, setInputs] = useState<Record<string, string>>({});

    // Helper to emit changes
    const emitChanges = (newFactors: Record<string, string[]>) => {
        const flatList = Object.values(newFactors).flat();
        // Just pass the list of names
        onFactorsChange(flatList);
    };

    const handleAdd = (category: string) => {
        const val = inputs[category];
        if (!val || val.trim() === "") return;

        const newFactors = {
            ...factors,
            [category]: [...(factors[category] || []), val]
        };
        setFactors(newFactors);
        setInputs({ ...inputs, [category]: "" });

        // Pass to parent immediately? No, wait for explicit Next usually, 
        // but the parent might want live updates if we wanted.
        // For now, we will rely on the "Next" button in the parent component 
        // which triggers the transition. The parent component's state is updated here.
    };

    const handleRemove = (category: string, index: number) => {
        const newFactors = {
            ...factors,
            [category]: factors[category].filter((_, i) => i !== index)
        };
        setFactors(newFactors);
    };

    const hasFactors = Object.values(factors).flat().length > 0;

    return (
        <div className="bg-white p-6 rounded-lg shadow-md border border-gray-200">
            <h3 className="text-lg font-bold text-science-900 mb-2">Ishikawa (Fishbone) Diagram Builder</h3>
            <p className="text-sm text-gray-600 mb-6">
                As described in Chapter 5, use the Fishbone diagram to brainstorm independent variables (Causes) that affect your formulation (Effect).
            </p>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {FISHBONE_CATEGORIES.map((cat) => (
                    <div key={cat} className="border border-science-100 rounded bg-science-50 p-3">
                        <h4 className="font-semibold text-science-800 text-sm mb-2">{cat}</h4>
                        <ul className="space-y-1 mb-2 min-h-[40px]">
                            {factors[cat]?.map((f, i) => (
                                <li key={i} className="flex justify-between items-center text-xs bg-white px-2 py-1 rounded shadow-sm">
                                    <span>{f}</span>
                                    <button onClick={() => handleRemove(cat, i)} className="text-red-400 hover:text-red-600">
                                        <X size={12} />
                                    </button>
                                </li>
                            ))}
                            {(!factors[cat] || factors[cat].length === 0) && (
                                <li className="text-xs text-gray-400 italic">No factors added</li>
                            )}
                        </ul>
                        <div className="flex gap-2">
                            <input 
                                type="text" 
                                className="flex-1 text-xs border border-gray-300 rounded px-2 py-1 focus:outline-none focus:border-science-500"
                                placeholder="Add factor..."
                                value={inputs[cat] || ""}
                                onChange={(e) => setInputs({...inputs, [cat]: e.target.value})}
                                onKeyDown={(e) => e.key === 'Enter' && handleAdd(cat)}
                            />
                            <button 
                                onClick={() => handleAdd(cat)}
                                className="bg-science-600 text-white rounded p-1 hover:bg-science-800"
                            >
                                <Plus size={14} />
                            </button>
                        </div>
                    </div>
                ))}
            </div>

            <div className="mt-8 flex justify-between items-center">
                 <div className="flex-1 flex items-center justify-end pr-4">
                     <div className="h-1 bg-science-900 flex-1 relative max-w-[200px]">
                        <div className="absolute right-0 -top-2 w-0 h-0 border-t-[8px] border-t-transparent border-l-[12px] border-l-science-900 border-b-[8px] border-b-transparent"></div>
                     </div>
                     <div className="ml-4 border-2 border-science-900 p-4 rounded text-center font-bold text-science-900 w-32">
                         CQA / Response
                     </div>
                 </div>

                <button 
                    onClick={() => emitChanges(factors)} 
                    disabled={!hasFactors}
                    className="bg-science-600 text-white px-6 py-3 rounded-lg hover:bg-science-700 font-medium flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    Next: Define Levels <ChevronRight size={18} />
                </button>
            </div>
        </div>
    );
};

