import React, { useState } from 'react';
import { ResponseDefinition } from '../types';
import { ChevronRight, Plus, Trash2 } from 'lucide-react';

interface CQASettingsProps {
    responses: ResponseDefinition[];
    onUpdate: (updated: ResponseDefinition[]) => void;
    onNext: () => void;
}

const CQASettings: React.FC<CQASettingsProps> = ({ responses, onUpdate, onNext }) => {
    const [newCQA, setNewCQA] = useState<ResponseDefinition>({
        name: '',
        unit: '',
        goal: 'Maximize'
    });

    const addCQA = () => {
        if (!newCQA.name) return;
        onUpdate([...responses, newCQA]);
        setNewCQA({ name: '', unit: '', goal: 'Maximize' });
    };

    const removeCQA = (index: number) => {
        const updated = responses.filter((_, i) => i !== index);
        onUpdate(updated);
    };

    return (
        <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200 animate-fade-in">
            <h2 className="text-2xl font-bold mb-2 text-science-900">Define Critical Quality Attributes (CQAs)</h2>
            <p className="text-sm text-gray-600 mb-6">
                What are you measuring? Define the responses (dependent variables) for your experiment.
            </p>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6 items-end bg-science-50 p-4 rounded-lg border border-science-100">
                <div className="md:col-span-1">
                    <label className="block text-xs font-bold text-gray-600 mb-1">Response Name</label>
                    <input 
                        type="text" 
                        placeholder="e.g. Particle Size"
                        className="w-full p-2 border border-gray-300 rounded text-sm"
                        value={newCQA.name}
                        onChange={(e) => setNewCQA({...newCQA, name: e.target.value})}
                    />
                </div>
                <div className="md:col-span-1">
                    <label className="block text-xs font-bold text-gray-600 mb-1">Unit</label>
                    <input 
                        type="text" 
                        placeholder="e.g. nm"
                        className="w-full p-2 border border-gray-300 rounded text-sm"
                        value={newCQA.unit}
                        onChange={(e) => setNewCQA({...newCQA, unit: e.target.value})}
                    />
                </div>
                <div className="md:col-span-1">
                    <label className="block text-xs font-bold text-gray-600 mb-1">Goal</label>
                    <select 
                        className="w-full p-2 border border-gray-300 rounded text-sm"
                        value={newCQA.goal}
                        onChange={(e) => setNewCQA({...newCQA, goal: e.target.value as any})}
                    >
                        <option value="Maximize">Maximize</option>
                        <option value="Minimize">Minimize</option>
                        <option value="Target">Target Value</option>
                    </select>
                </div>
                <div className="md:col-span-1">
                    <button 
                        onClick={addCQA}
                        disabled={!newCQA.name}
                        className="w-full bg-science-600 text-white p-2 rounded hover:bg-science-700 disabled:opacity-50 text-sm font-bold flex justify-center items-center gap-2"
                    >
                        <Plus size={16} /> Add CQA
                    </button>
                </div>
            </div>

            <div className="space-y-2 mb-8">
                {responses.map((res, idx) => (
                    <div key={idx} className="flex items-center justify-between p-3 bg-white border border-gray-200 rounded shadow-sm">
                        <div className="flex items-center gap-4">
                            <div className="w-8 h-8 rounded-full bg-science-100 text-science-700 flex items-center justify-center font-bold text-sm">
                                Y{idx + 1}
                            </div>
                            <div>
                                <p className="font-bold text-gray-800">{res.name}</p>
                                <p className="text-xs text-gray-500">{res.unit} • {res.goal}</p>
                            </div>
                        </div>
                        <button onClick={() => removeCQA(idx)} className="text-red-400 hover:text-red-600 p-2">
                            <Trash2 size={16} />
                        </button>
                    </div>
                ))}
                {responses.length === 0 && (
                    <p className="text-center text-gray-400 italic py-4">No responses defined yet.</p>
                )}
            </div>

            <div className="flex justify-end">
               <button 
                onClick={onNext} 
                disabled={responses.length === 0}
                className="bg-science-600 text-white px-6 py-3 rounded-lg hover:bg-science-700 disabled:opacity-50 font-medium flex items-center gap-2"
               >
                 Next Step <ChevronRight size={18} />
               </button>
            </div>
        </div>
    );
};

export default CQASettings;

import { GoogleGenAI, SchemaType } from "@google/genai";
import { AnalysisRequest, ExperimentalRun, AnalysisResult } from "../types";

const getClient = () => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        throw new Error("API Key not found in process.env.API_KEY");
    }
    return new GoogleGenAI({ apiKey });
};

// Returns just the runs array structure
export const generateDesignMatrix = async (request: AnalysisRequest, designName: string): Promise<ExperimentalRun[]> => {
    try {
        const ai = getClient();
        const factorDesc = request.factors.map(f => `${f.name} (${f.low} to ${f.high})`).join(', ');

        const prompt = `
        Generate a Design of Experiments (DoE) matrix for a "${designName}".
        Factors: ${factorDesc}.

        Return STRICTLY JSON format. An array of objects.
        Each object should have:
        - "id" (number, starting at 1)
        - "factors" (object where keys are factor names and values are numbers).

        Do not output any markdown code blocks. Just the raw JSON string.
        Ensure real-world values are used based on the ranges provided, not coded values.
        Generate a reasonable number of runs for this design (e.g., 8-15 for small factorial/BBD/CCD).
        Include center points if standard for this design.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 0 }
            }
        });

        const text = response.text || "[]";
        // Clean markdown if present
        const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const runs = JSON.parse(jsonStr);

        // Map to internal structure ensuring results object exists
        return runs.map((r: any) => ({
            id: r.id,
            factors: r.factors,
            results: {} 
        }));

    } catch (e) {
        console.error("Design Matrix Error", e);
        return [];
    }
};

export const analyzeExperimentalResults = async (
    request: AnalysisRequest, 
    designName: string, 
    runs: ExperimentalRun[]
): Promise<AnalysisResult> => {
    const ai = getClient();

    // Prepare data for AI
    const dataStr = JSON.stringify(runs.map(r => ({ ...r.factors, ...r.results })));
    const responseNames = request.responses.map(r => r.name).join(', ');

    const prompt = `
    Perform a statistical analysis on the following formulation experiment results.
    Design: ${designName}.
    Responses: ${responseNames}.
    Data: ${dataStr}.

    Task 1: ANOVA & Model Significance (Markdown)
    - Provide an ANOVA table summary for the main responses.
    - Identify significant terms (p < 0.05).
    - Provide the regression equation.
    - Comment on Model Fit (R-squared).
    - Provide a section called "Model Diagnostics" describing fit.

    Task 2: Visualization Data (JSON)
    - I need to plot 3D Surface plots for the most significant interactions.
    - Generate a 10x10 grid of Z values for the two most interacting factors (let's call them X and Y) for the first response variable.
    - Return a JSON object inside a distinct block separated by "|||JSON_DATA|||".
    - Structure:
      {
         "x": "Name of Factor X",
         "y": "Name of Factor Y",
         "z": "Name of Response",
         "xRange": [min, max],
         "yRange": [min, max],
         "surfaceZ": [[z11, z12...], [z21, z22...]] (10x10 matrix),
         "contourZ": [[z11, z12...]] (same matrix for contour)
      }
    - If there are multiple responses, just pick the primary one for the plot.
    `;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { thinkingConfig: { thinkingBudget: 0 } }
    });

    const fullText = response.text || "";
    const parts = fullText.split("|||JSON_DATA|||");

    let anovaText = parts[0];
    let plotData = [];

    if (parts[1]) {
        try {
            const jsonStr = parts[1].replace(/```json/g, '').replace(/```/g, '').trim();
            const data = JSON.parse(jsonStr);
            plotData.push(data);
        } catch (e) {
            console.error("Error parsing plot data", e);
        }
    }

    return { anovaText, plotData };
};

