const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results }) => {

    useEffect(() => {
        if (results.plotData && results.plotData.length > 0 && window.Plotly) {
            const data = results.plotData[0];

            // 3D Surface Plot
            const surfaceData = [{
                z: data.surfaceZ,
                type: 'surface',
                contours: {
                    z: {
                        show: true,
                        usecolormap: true,
                        highlightcolor: "#42f462",
                        project: { z: true }
