                    yaxis: { title: data.y },
                    zaxis: { title: data.z }
                },
                margin: { l: 0, r: 0, b: 0, t: 50 }
            };

            window.Plotly.newPlot('plot3d', surfaceData, layout3d);

            // Contour Plot
            const contourData = [{
                z: data.contourZ,
                x: Array.from({length: 10}, (_, i) => data.xRange[0] + i * (data.xRange[1]-data.xRange[0])/9),
                y: Array.from({length: 10}, (_, i) => data.yRange[0] + i * (data.yRange[1]-data.yRange[0])/9),
