// Returns just the runs array structure
export const generateDesignMatrix = async (request: AnalysisRequest, designName: string): Promise<ExperimentalRun[]> => {
    try {
        const ai = getClient();
        const factorDesc = request.factors.map(f => `${f.name} (${f.low} to ${f.high})`).join(', ');

        const prompt = `
        Generate a Design of Experiments (DoE) matrix for a "${designName}".
        Factors: ${factorDesc}.

        Return STRICTLY JSON format. An array of objects.
        Each object should have:
        - "id" (number, starting at 1)
        - "factors" (object where keys are factor names and values are numbers).

        Do not output any markdown code blocks. Just the raw JSON string.
        Ensure real-world values are used based on the ranges provided, not coded values.
        Generate a reasonable number of runs for this design (e.g., 8-15 for small factorial/BBD/CCD).
        Include center points if standard for this design.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 0 }
            }
        });

        const text = response.text || "[]";
        // Clean markdown if present
        const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const runs = JSON.parse(jsonStr);

        // Map to internal structure ensuring results object exists
        return runs.map((r: any) => ({
            id: r.id,
            factors: r.factors,
            results: {} 
        }));

    } catch (e) {
        console.error("Design Matrix Error", e);
        return [];
    }
};

export const analyzeExperimentalResults = async (
    request: AnalysisRequest, 
    designName: string, 
    runs: ExperimentalRun[]
): Promise<AnalysisResult> => {
    const ai = getClient();

    // Prepare data for AI
    const dataStr = JSON.stringify(runs.map(r => ({ ...r.factors, ...r.results })));
    const responseNames = request.responses.map(r => r.name).join(', ');

    const prompt = `
    Perform a statistical analysis on the following formulation experiment results.
    Design: ${designName}.
    Responses: ${responseNames}.
    Data: ${dataStr}.

    Task 1: ANOVA & Model Significance (Markdown)
    - Provide an ANOVA table summary for the main responses.
    - Identify significant terms (p < 0.05).
    - Provide the regression equation.
    - Comment on Model Fit (R-squared, Adj R-squared).
    - Provide a section called "Model Diagnostics" describing fit.

    Task 2: Visualization Data (JSON)
    - I need to plot 3D Surface plots AND Diagnostic plots for the primary response.
    - Return a JSON object inside a distinct block separated by "|||JSON_DATA|||".
    - Structure:
      {
         "plotData": [{
             "x": "Name of Factor X (most significant interaction)",
             "y": "Name of Factor Y",
             "z": "Name of Response",
             "xRange": [min, max],
             "yRange": [min, max],
             "surfaceZ": [[...]] (10x10 matrix),
             "contourZ": [[...]] (same matrix)
         }],
         "diagnostics": {
             "runOrder": [1, 2, 3...],
             "actual": [number...],
             "predicted": [number...],
             "residuals": [number...],
             "boxCox": {
                 "lambda": [-3, -2.5, ..., 3],
                 "logLikelihood": [number...] (Calculated or approximate trend for normality check)
             }
         }
      }
    `;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { thinkingConfig: { thinkingBudget: 0 } }
    });

    const fullText = response.text || "";
    const parts = fullText.split("|||JSON_DATA|||");

    let anovaText = parts[0];
    let plotData = [];
    let diagnostics;

    if (parts[1]) {
        try {
            const jsonStr = parts[1].replace(/```json/g, '').replace(/```/g, '').trim();
            const data = JSON.parse(jsonStr);
            plotData = data.plotData || [];
            diagnostics = data.diagnostics;
        } catch (e) {
            console.error("Error parsing plot data", e);
        }
    }

    return { anovaText, plotData, diagnostics };
};

import React, { useEffect } from 'react';
import { AnalysisResult } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, TrendingUp, BarChart2 } from 'lucide-react';

// Declare Plotly on window since we load via CDN
declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results }) => {

    useEffect(() => {
        if (!window.Plotly) return;

        // --- 3D & Contour Plots ---
        if (results.plotData && results.plotData.length > 0) {
            const data = results.plotData[0];

            // 3D Surface Plot
            const surfaceData = [{
                z: data.surfaceZ,
                type: 'surface',
                contours: {
                    z: { show: true, usecolormap: true, highlightcolor: "#42f462", project: { z: true } }
                }
            }];

            const layout3d = {
                title: `3D Surface: ${data.z} vs ${data.x} & ${data.y}`,
                autosize: true,
                scene: {
                    xaxis: { title: data.x },
                    yaxis: { title: data.y },
                    zaxis: { title: data.z }
                },
                margin: { l: 0, r: 0, b: 0, t: 50 }
            };
            window.Plotly.newPlot('plot3d', surfaceData, layout3d);

            // Contour Plot
            const contourData = [{
                z: data.contourZ,
                x: Array.from({length: 10}, (_, i) => data.xRange[0] + i * (data.xRange[1]-data.xRange[0])/9),
                y: Array.from({length: 10}, (_, i) => data.yRange[0] + i * (data.yRange[1]-data.yRange[0])/9),
                type: 'contour',
                colorscale: 'Jet'
            }];
            const layoutContour = {
                title: `Contour Plot: ${data.z}`,
                autosize: true,
                xaxis: { title: data.x },
                yaxis: { title: data.y }
            };
            window.Plotly.newPlot('plotContour', contourData, layoutContour);
        }

        // --- Diagnostic Plots ---
        if (results.diagnostics) {
            const diag = results.diagnostics;

            // 1. Predicted vs Run (Drift check)
            const predRunData = [
                {
                    x: diag.runOrder,
                    y: diag.predicted,
                    type: 'scatter',
                    mode: 'lines+markers',
                    name: 'Predicted',
                    line: { color: '#0284c7' }
                },
                {
                    x: diag.runOrder,
                    y: diag.actual,
                    type: 'scatter',
                    mode: 'markers',
                    name: 'Actual',
                    marker: { color: '#ef4444' }
                }
            ];
            window.Plotly.newPlot('plotPredVsRun', predRunData, {
                title: 'Predicted & Actual vs Run Order',
                xaxis: { title: 'Run Order' },
                yaxis: { title: 'Response Value' }
            });

            // 2. Predicted vs Actual (Fit check)
            const fitData = [
                {
                    x: diag.actual,
                    y: diag.predicted,
                    type: 'scatter',
                    mode: 'markers',
                    marker: { color: '#0ea5e9' }
                },
                // Diagonal reference line
                {
                    x: [Math.min(...diag.actual), Math.max(...diag.actual)],
                    y: [Math.min(...diag.actual), Math.max(...diag.actual)],
                    type: 'scatter',
                    mode: 'lines',
                    line: { dash: 'dash', color: '#94a3b8' },
                    name: 'Ideal Fit'
                }
            ];
            window.Plotly.newPlot('plotPredVsActual', fitData, {
                title: 'Predicted vs Actual',
                xaxis: { title: 'Actual' },
                yaxis: { title: 'Predicted' }
            });

            // 3. Residuals vs Run (Independence check)
            const residData = [{
                x: diag.runOrder,
                y: diag.residuals,
                type: 'scatter',
                mode: 'markers',
                marker: { color: '#f59e0b', size: 8 }
            }];
            window.Plotly.newPlot('plotResidVsRun', residData, {
                title: 'Residuals vs Run Order',
                xaxis: { title: 'Run Order' },
                yaxis: { title: 'Residuals' },
                shapes: [{
                    type: 'line', x0: 0, x1: Math.max(...diag.runOrder)+1, y0: 0, y1: 0,
                    line: { color: 'black', width: 1, dash: 'dot' }
                }]
            });

            // 4. Box-Cox (Transformation check)
            if (diag.boxCox) {
                const boxCoxData = [{
                    x: diag.boxCox.lambda,
                    y: diag.boxCox.logLikelihood,
                    type: 'scatter',
                    mode: 'lines',
                    line: { shape: 'spline', color: '#8b5cf6' }
                }];
                window.Plotly.newPlot('plotBoxCox', boxCoxData, {
                    title: 'Box-Cox Plot (Normality)',
                    xaxis: { title: 'Lambda (λ)' },
                    yaxis: { title: 'Log-Likelihood' }
                });
            }
        }

    }, [results]);

    return (
        <div className="space-y-8 pb-12">
            <div className="bg-white p-8 rounded-xl shadow-lg border border-gray-200">
                <h2 className="text-2xl font-bold text-science-900 mb-4 flex items-center gap-2">
                    <LayoutDashboard /> Statistical Analysis (ANOVA)
                </h2>
                <div className="prose prose-sm max-w-none text-gray-700 bg-slate-50 p-6 rounded border border-slate-200">
                    <ReactMarkdown>{results.anovaText}</ReactMarkdown>
                </div>
            </div>

            {results.plotData.length > 0 && (
                <div className="space-y-6">
                    <h3 className="text-xl font-bold text-gray-800 border-b pb-2">Response Surface Plots</h3>
                    <div className="grid md:grid-cols-2 gap-8">
                        <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                            <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
                                <Cuboid size={18} /> 3D Surface Response
                            </h3>
                            <div id="plot3d" className="w-full h-[400px]"></div>
                        </div>
                        <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                            <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
                                <Layers size={18} /> Contour Plot
                            </h3>
                            <div id="plotContour" className="w-full h-[400px]"></div>
                        </div>
                    </div>
                </div>
            )}

            {results.diagnostics && (
                <div className="space-y-6">
                    <h3 className="text-xl font-bold text-gray-800 border-b pb-2 flex items-center gap-2">
                        <Activity size={24} className="text-science-600"/> 
                        Model Diagnostics
                    </h3>
                    <div className="grid md:grid-cols-2 gap-8">
                        <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                            <h4 className="font-bold text-gray-700 mb-2 text-sm flex items-center gap-2">
                                <TrendingUp size={16}/> Predicted vs Run (Drift Check)
                            </h4>
                            <div id="plotPredVsRun" className="w-full h-[300px]"></div>
                        </div>
                        <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                             <h4 className="font-bold text-gray-700 mb-2 text-sm flex items-center gap-2">
                                <Activity size={16}/> Residuals vs Run (Independence)
                            </h4>
                            <div id="plotResidVsRun" className="w-full h-[300px]"></div>
                        </div>
                        <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                            <h4 className="font-bold text-gray-700 mb-2 text-sm flex items-center gap-2">
                                <BarChart2 size={16}/> Predicted vs Actual (Fit)
                            </h4>
                            <div id="plotPredVsActual" className="w-full h-[300px]"></div>
                        </div>
                        {results.diagnostics.boxCox && (
                            <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                                <h4 className="font-bold text-gray-700 mb-2 text-sm flex items-center gap-2">
                                    <Activity size={16}/> Box-Cox Plot (Transformation)
                                </h4>
                                <div id="plotBoxCox" className="w-full h-[300px]"></div>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

