// Declare Plotly on window since we load via CDN
declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors }) => {
    // Prediction State
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);

    // Initialize inputs with mid-points
    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = mid.toString();
        });
        setPredictionInputs(initial);
    }, [factors]);

    const calculatePrediction = () => {
        if (!results.modelCoefficients) return;

        const { intercept, linear, quadratic, interactions } = results.modelCoefficients;
        let y = intercept;

        // Linear Terms
        Object.entries(linear).forEach(([factorName, coeff]) => {
            const val = parseFloat(predictionInputs[factorName] || '0');
            y += coeff * val;
        });

        // Quadratic Terms
        Object.entries(quadratic).forEach(([factorName, coeff]) => {
            const val = parseFloat(predictionInputs[factorName] || '0');
            y += coeff * Math.pow(val, 2);
        });

        // Interactions
        interactions.forEach(term => {
            const val1 = parseFloat(predictionInputs[term.factor1] || '0');
            const val2 = parseFloat(predictionInputs[term.factor2] || '0');
            y += term.coefficient * val1 * val2;
        });

        setPredictedValue(y);
    };

    useEffect(() => {
        if (!window.Plotly) return;

        // --- 3D & Contour Plots ---
        if (results.plotData && results.plotData.length > 0) {
            const data = results.plotData[0];

            const surfaceData = [{
                z: data.surfaceZ,
                type: 'surface',
                contours: {
                    z: { show: true, usecolormap: true, highlightcolor: "#42f462", project: { z: true } }
                }
            }];

            const layout3d = {
                title: `3D Surface: ${data.z}`,
                autosize: true,
                scene: {
                    xaxis: { title: data.x },
                    yaxis: { title: data.y },
                    zaxis: { title: data.z }
                },
                margin: { l: 0, r: 0, b: 0, t: 50 }
            };
            window.Plotly.newPlot('plot3d', surfaceData, layout3d);

            const contourData = [{
                z: data.contourZ,
                x: Array.from({length: 10}, (_, i) => data.xRange[0] + i * (data.xRange[1]-data.xRange[0])/9),
                y: Array.from({length: 10}, (_, i) => data.yRange[0] + i * (data.yRange[1]-data.yRange[0])/9),
                type: 'contour',
                colorscale: 'Jet'
            }];
            const layoutContour = {
                title: `Contour Plot`,
                autosize: true,
                xaxis: { title: data.x },
                yaxis: { title: data.y }
            };
            window.Plotly.newPlot('plotContour', contourData, layoutContour);
        }

        // --- Diagnostic Plots ---
        if (results.diagnostics) {
            const diag = results.diagnostics;

            // 1. Predicted vs Run
            const predRunData = [
                { x: diag.runOrder, y: diag.predicted, type: 'scatter', mode: 'lines+markers', name: 'Predicted', line: { color: '#0284c7' } },
                { x: diag.runOrder, y: diag.actual, type: 'scatter', mode: 'markers', name: 'Actual', marker: { color: '#ef4444' } }
            ];
            window.Plotly.newPlot('plotPredVsRun', predRunData, {
                title: 'Pred vs Actual (Run Order)',
                xaxis: { title: 'Run Order' },
                yaxis: { title: 'Response' },
                margin: { l: 40, r: 20, b: 40, t: 40 }
            });

            // 2. Predicted vs Actual
            const fitData = [
                { x: diag.actual, y: diag.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9' } },
                { x: [Math.min(...diag.actual), Math.max(...diag.actual)], y: [Math.min(...diag.actual), Math.max(...diag.actual)], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' }, name: 'Ideal' }
            ];
            window.Plotly.newPlot('plotPredVsActual', fitData, {
                title: 'Predicted vs Actual',
                xaxis: { title: 'Actual' },
                yaxis: { title: 'Predicted' },
                margin: { l: 40, r: 20, b: 40, t: 40 }
            });

            // 3. Residuals vs Run
            const residData = [{ x: diag.runOrder, y: diag.residuals, type: 'scatter', mode: 'markers', marker: { color: '#f59e0b', size: 8 } }];
            window.Plotly.newPlot('plotResidVsRun', residData, {
                title: 'Residuals vs Run Order',
                xaxis: { title: 'Run Order' },
                yaxis: { title: 'Residuals' },
                shapes: [{ type: 'line', x0: 0, x1: Math.max(...diag.runOrder)+1, y0: 0, y1: 0, line: { color: 'black', width: 1, dash: 'dot' } }],
                margin: { l: 40, r: 20, b: 40, t: 40 }
            });

            // 4. Box-Cox (lnRSS vs Lambda)
            if (diag.boxCox) {
                const boxCoxData = [{
                    x: diag.boxCox.lambda,
                    y: diag.boxCox.lnRSS,
                    type: 'scatter',
                    mode: 'lines',
                    line: { shape: 'spline', color: '#8b5cf6', width: 3 }
                }];
                window.Plotly.newPlot('plotBoxCox', boxCoxData, {
                    title: 'Box-Cox: ln(RSS) vs Lambda',
                    xaxis: { title: 'Lambda (λ)' },
                    yaxis: { title: 'ln(RSS)' },
                    margin: { l: 50, r: 20, b: 40, t: 40 }
                });
            }
        }

    }, [results]);

    return (
        <div className="space-y-8 pb-12">
            <div className="bg-white p-8 rounded-xl shadow-lg border border-gray-200">
                <h2 className="text-2xl font-bold text-science-900 mb-4 flex items-center gap-2">
                    <LayoutDashboard /> Statistical Analysis (ANOVA)
                </h2>
                <div className="prose prose-sm max-w-none text-gray-700 bg-slate-50 p-6 rounded border border-slate-200">
                    <ReactMarkdown>{results.anovaText}</ReactMarkdown>
                </div>
            </div>

            {/* Model Diagnostics Grid */}
            {results.diagnostics && (
                <div className="space-y-4">
                    <h3 className="text-xl font-bold text-gray-800 border-b pb-2 flex items-center gap-2">
                        <Activity size={24} className="text-science-600"/> 
                        Model Diagnostics
                    </h3>
                    <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-4">
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative">
                             <div id="plotPredVsRun" className="w-full h-full"></div>
                        </div>
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative">
                             <div id="plotResidVsRun" className="w-full h-full"></div>
                        </div>
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative">
                             <div id="plotPredVsActual" className="w-full h-full"></div>
                        </div>
                        {results.diagnostics.boxCox && (
                            <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative">
                                <div id="plotBoxCox" className="w-full h-full"></div>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* Prediction Simulator */}
            {results.modelCoefficients && (
                <div className="bg-science-50 p-6 rounded-xl border border-science-200 shadow-inner">
                    <h3 className="text-xl font-bold text-science-900 mb-4 flex items-center gap-2">
                        <Calculator size={24} /> 
                        Predict Outcome for New Run
                    </h3>
                    <p className="text-sm text-science-700 mb-6">
                        Enter new factor levels below to calculate the predicted response based on the generated model equation.
                    </p>

                    <div className="grid md:grid-cols-3 gap-6 items-end">
                        {factors.map(f => (
                            <div key={f.name}>
                                <label className="block text-xs font-bold text-science-800 mb-1 uppercase">
                                    {f.name} ({f.unit})
                                </label>
                                <input 
                                    type="number"
                                    step="any"
                                    className="w-full p-2 border border-science-200 rounded text-sm focus:ring-2 focus:ring-science-500 outline-none"
                                    value={predictionInputs[f.name] || ''}
                                    onChange={(e) => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}
                                />
                                <div className="flex justify-between text-[10px] text-science-500 mt-1">
                                    <span>L: {f.low}</span>
                                    <span>H: {f.high}</span>
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="mt-6 flex items-center gap-6">
                        <button 
                            onClick={calculatePrediction}
                            className="bg-science-600 text-white px-6 py-2 rounded-lg hover:bg-science-700 font-bold flex items-center gap-2 shadow-sm"
                        >
                            <Play size={16} /> Calculate Result
                        </button>

                        {predictedValue !== null && (
                            <div className="bg-white px-6 py-2 rounded-lg border border-science-200 shadow-sm flex items-center gap-2">
                                <span className="text-xs font-bold text-gray-500 uppercase">Predicted Result:</span>
                                <span className="text-xl font-bold text-science-700">
                                    {predictedValue.toFixed(4)}
                                </span>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* Surface Plots */}
            {results.plotData.length > 0 && (
                <div className="space-y-6">
                    <h3 className="text-xl font-bold text-gray-800 border-b pb-2">Response Surface Plots</h3>
                    <div className="grid md:grid-cols-2 gap-8">
                        <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                            <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
                                <Cuboid size={18} /> 3D Surface
                            </h3>
                            <div id="plot3d" className="w-full h-[400px]"></div>
                        </div>
                        <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                            <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
                                <Layers size={18} /> Contour
                            </h3>
                            <div id="plotContour" className="w-full h-[400px]"></div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default AnalysisDashboard;

import React, { useState } from 'react';
import { DesignRecommendation, AnalysisRequest, ExperimentalRun, AnalysisResult } from '../types';
import { generateDesignMatrix, analyzeExperimentalResults } from '../services/geminiService';
import { FileText, Loader2, BookOpen, AlertTriangle, Beaker, Play } from 'lucide-react';
import DesignVisualizer from './DesignVisualizer';
import RunTable from './RunTable';
import AnalysisDashboard from './AnalysisDashboard';

interface ResultsViewProps {
  recommendation: DesignRecommendation | null;
  request: AnalysisRequest;
  onReset: () => void;
}

const ResultsView: React.FC<ResultsViewProps> = ({ recommendation, request, onReset }) => {
  const [viewState, setViewState] = useState<'PROPOSAL' | 'EXECUTION' | 'ANALYSIS'>('PROPOSAL');
  const [runs, setRuns] = useState<ExperimentalRun[]>([]);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [loading, setLoading] = useState(false);

  if (!recommendation) return null;

  const handleGenerateRuns = async () => {
    setLoading(true);
    const generatedRuns = await generateDesignMatrix(request, recommendation.name);
    setRuns(generatedRuns);
    setViewState('EXECUTION');
    setLoading(false);
  };

  const handleUpdateRun = (runId: number, responseName: string, value: string) => {
      setRuns(prev => prev.map(r => 
          r.id === runId 
          ? { ...r, results: { ...r.results, [responseName]: value } }
          : r
      ));
  };

  const handleAnalyze = async () => {
      setLoading(true);
      const result = await analyzeExperimentalResults(request, recommendation.name, runs);
      setAnalysis(result);
      setViewState('ANALYSIS');
      setLoading(false);
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">

      {/* 1. Scientific Recommendation (Always Visible Summary) */}
      <div className="bg-white rounded-xl shadow-lg overflow-hidden border-t-4 border-science-600">
        <div className="p-6 flex flex-col md:flex-row gap-8 items-start">
            <div className="flex-1">
                <div className="flex items-center gap-2 text-science-600 font-semibold mb-2 text-sm uppercase tracking-wide">
                    <BookOpen size={16} />
                    Scientific Recommendation
                </div>
                <h2 className="text-3xl font-bold text-gray-900 mb-4">
                    {recommendation.name} <span className="text-gray-400 font-normal">({recommendation.acronym})</span>
                </h2>
                <div className="prose text-gray-700 text-sm">
                    <p className="font-medium">{recommendation.reasoning}</p>
                </div>
            </div>
            <div className="w-32 flex-shrink-0 hidden md:block">
                <DesignVisualizer acronym={recommendation.acronym} />
            </div>
        </div>
      </div>

      {/* 2. Proposal State */}
      {viewState === 'PROPOSAL' && (
           <div className="bg-slate-50 rounded-xl border border-slate-200 p-8 text-center">
                <Beaker size={48} className="mx-auto text-science-400 mb-4" />
                <h3 className="text-xl font-bold text-gray-800 mb-2">Ready to Experiment?</h3>
                <p className="text-gray-600 max-w-lg mx-auto mb-6">
                    Based on your <strong>{request.factors.length} factors</strong> and <strong>{request.responses.length} responses</strong>, 
                    we will generate the optimal experimental run table for the {recommendation.name}.
                </p>
                <button
                    onClick={handleGenerateRuns}
                    disabled={loading}
                    className="bg-science-600 text-white px-8 py-3 rounded-lg hover:bg-science-700 disabled:opacity-50 flex items-center gap-2 mx-auto text-lg font-bold shadow-lg shadow-science-200 transition-all"
                >
                    {loading ? <Loader2 className="animate-spin" /> : <Play size={20} />}
                    {loading ? 'Designing Matrix...' : 'Generate Run Table'}
                </button>
           </div>
      )}

      {/* 3. Execution State (The Lab Notebook) */}
      {(viewState === 'EXECUTION' || viewState === 'ANALYSIS') && (
          <div className="space-y-4">
              <div className="flex justify-between items-end">
                 <h3 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                    <FileText className="text-science-600" /> Experimental Protocol & Data
                 </h3>
                 {viewState === 'EXECUTION' && (
                     <button 
                        onClick={handleAnalyze}
                        disabled={loading}
                        className="bg-green-600 text-white px-6 py-2 rounded shadow hover:bg-green-700 flex items-center gap-2"
                     >
                        {loading ? <Loader2 className="animate-spin" size={18}/> : null}
                        Analyze Results
                     </button>
                 )}
              </div>

              <RunTable 
                  runs={runs} 
                  factors={request.factors} 
                  responses={request.responses} 
                  onUpdateRun={handleUpdateRun} 
              />

              <p className="text-sm text-gray-500 italic text-right">
                  * Enter your experimental results in the yellow columns above.
              </p>
          </div>
      )}

      {/* 4. Analysis State */}
      {viewState === 'ANALYSIS' && analysis && (
          <div className="animate-fade-in border-t-2 border-gray-200 pt-8">
              <AnalysisDashboard results={analysis} factors={request.factors} />
          </div>
      )}

      <div className="flex justify-center pt-8">
        <button
          onClick={onReset}
          className="text-science-600 hover:text-science-800 font-medium underline underline-offset-4"
        >
          Start New Analysis
        </button>
      </div>
    </div>
  );
};

export default ResultsView;

import React, { useEffect, useState } from 'react';
import { AnalysisResult, FactorDefinition } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, TrendingUp, BarChart2, Calculator, Play } from 'lucide-react';

// Declare Plotly on window since we load via CDN
declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors }) => {
    // Prediction State
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);

    // Initialize inputs with mid-points
    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = mid.toString();
        });
        setPredictionInputs(initial);
    }, [factors]);

    const calculatePrediction = () => {
        if (!results.modelCoefficients) return;

        const { intercept, linear, quadratic, interactions } = results.modelCoefficients;
        let y = intercept;

        // Linear Terms
        Object.entries(linear).forEach(([factorName, coeff]) => {
            const val = parseFloat(predictionInputs[factorName] || '0');
            y += (coeff as number) * val;
        });

        // Quadratic Terms
        Object.entries(quadratic).forEach(([factorName, coeff]) => {
            const val = parseFloat(predictionInputs[factorName] || '0');
            y += (coeff as number) * Math.pow(val, 2);
        });

        // Interactions
        interactions.forEach(term => {
            const val1 = parseFloat(predictionInputs[term.factor1] || '0');
            const val2 = parseFloat(predictionInputs[term.factor2] || '0');
            y += term.coefficient * val1 * val2;
        });

        setPredictedValue(y);
