import React from 'react';
import { FactorDefinition } from '../types';
import { ChevronRight, Plus, Trash2, ArrowLeft } from 'lucide-react';

interface FactorSettingsProps {
    factors: FactorDefinition[];
    onUpdate: (updatedFactors: FactorDefinition[]) => void;
    onNext: () => void;
    onBack: () => void;
}

const FactorSettings: React.FC<FactorSettingsProps> = ({ factors, onUpdate, onNext, onBack }) => {

    const handleChange = (index: number, field: keyof FactorDefinition, value: string | number) => {
        const updated = [...factors];
        updated[index] = { ...updated[index], [field]: value };
        onUpdate(updated);
    };

    const addFactor = () => {
        onUpdate([...factors, { name: `Factor ${factors.length + 1}`, unit: '', low: '', high: '', levels: 2 }]);
    };

    const removeFactor = (index: number) => {
        const updated = factors.filter((_, i) => i !== index);
        onUpdate(updated);
    };

    const isComplete = factors.length > 0 && factors.every(f => f.name && f.low && f.high && f.unit && f.levels);

    return (
        <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200 animate-fade-in">
            <h2 className="text-2xl font-bold mb-2 text-science-900">Define Factor Levels</h2>
            <p className="text-sm text-gray-600 mb-6">
                Specify the experimental range and number of levels for each factor.
            </p>

            <div className="overflow-x-auto mb-6">
                <table className="w-full text-sm text-left text-gray-700">
                    <thead className="text-xs text-gray-700 uppercase bg-science-50 border-b border-science-100">
                        <tr>
                            <th className="px-4 py-3 rounded-tl-lg">Factor Name</th>
                            <th className="px-4 py-3">Unit</th>
                            <th className="px-4 py-3 w-20"># Levels</th>
                            <th className="px-4 py-3">Low Level (-1)</th>
                            <th className="px-4 py-3">High Level (+1)</th>
                            <th className="px-4 py-3 rounded-tr-lg w-10"></th>
                        </tr>
                    </thead>
                    <tbody>
                        {factors.map((factor, idx) => (
                            <tr key={idx} className="border-b border-gray-100 hover:bg-gray-50">
                                <td className="px-4 py-2">
                                    <input 
                                        type="text" 
                                        className="w-full p-2 border border-gray-300 rounded focus:border-science-500 focus:outline-none font-medium text-science-800"
                                        value={factor.name}
                                        onChange={(e) => handleChange(idx, 'name', e.target.value)}
                                    />
                                </td>
                                <td className="px-4 py-2">
                                    <input 
                                        type="text" 
                                        placeholder="mg, ml" 
                                        className="w-full p-2 border border-gray-300 rounded focus:border-science-500 focus:outline-none"
                                        value={factor.unit}
                                        onChange={(e) => handleChange(idx, 'unit', e.target.value)}
                                    />
                                </td>
                                <td className="px-4 py-2">
                                     <input 
                                        type="number" 
                                        min="2"
                                        max="10"
                                        className="w-full p-2 border border-gray-300 rounded focus:border-science-500 focus:outline-none"
                                        value={factor.levels || 2}
                                        onChange={(e) => handleChange(idx, 'levels', parseInt(e.target.value))}
                                    />
                                </td>
                                <td className="px-4 py-2">
                                    <input 
                                        type="text" 
                                        placeholder="e.g. 100" 
                                        className="w-full p-2 border border-gray-300 rounded focus:border-science-500 focus:outline-none"
                                        value={factor.low}
                                        onChange={(e) => handleChange(idx, 'low', e.target.value)}
                                    />
                                </td>
                                <td className="px-4 py-2">
                                    <input 
                                        type="text" 
                                        placeholder="e.g. 500" 
                                        className="w-full p-2 border border-gray-300 rounded focus:border-science-500 focus:outline-none"
                                        value={factor.high}
                                        onChange={(e) => handleChange(idx, 'high', e.target.value)}
                                    />
                                </td>
                                <td className="px-4 py-2 text-center">
                                    <button 
                                        onClick={() => removeFactor(idx)}
                                        className="text-gray-400 hover:text-red-500 transition-colors"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>

                <button 
                    onClick={addFactor}
                    className="flex items-center gap-2 text-science-600 font-bold text-sm hover:bg-science-50 px-4 py-2 rounded transition-colors"
                >
                    <Plus size={16} /> Add Factor
                </button>
            </div>

            <div className="mt-8 flex justify-between">
                <button 
                    onClick={onBack}
                    className="text-gray-500 hover:text-gray-700 font-medium flex items-center gap-2"
                >
                    <ArrowLeft size={18} /> Back
                </button>
               <button 
                onClick={onNext} 
                disabled={!isComplete}
                className="bg-science-600 text-white px-6 py-3 rounded-lg hover:bg-science-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium flex items-center gap-2"
               >
                 Next <ChevronRight size={18} />
               </button>
            </div>
        </div>
    );
};

export default FactorSettings;

import React, { useState } from 'react';
import { ResponseDefinition } from '../types';
import { ChevronRight, Plus, Trash2, ArrowLeft } from 'lucide-react';

interface CQASettingsProps {
    responses: ResponseDefinition[];
    onUpdate: (updated: ResponseDefinition[]) => void;
    onNext: () => void;
    onBack: () => void;
}

const CQASettings: React.FC<CQASettingsProps> = ({ responses, onUpdate, onNext, onBack }) => {
    const [newCQA, setNewCQA] = useState<ResponseDefinition>({
        name: '',
        unit: '',
        goal: 'Maximize'
    });

    const addCQA = () => {
        if (!newCQA.name) return;
        onUpdate([...responses, newCQA]);
        setNewCQA({ name: '', unit: '', goal: 'Maximize' });
    };

    const removeCQA = (index: number) => {
        const updated = responses.filter((_, i) => i !== index);
        onUpdate(updated);
    };

    return (
        <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200 animate-fade-in">
            <h2 className="text-2xl font-bold mb-2 text-science-900">Define Critical Quality Attributes (CQAs)</h2>
            <p className="text-sm text-gray-600 mb-6">
                What are you measuring? Define the responses (dependent variables) for your experiment.
            </p>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6 items-end bg-science-50 p-4 rounded-lg border border-science-100">
                <div className="md:col-span-1">
                    <label className="block text-xs font-bold text-gray-600 mb-1">Response Name</label>
                    <input 
                        type="text" 
                        placeholder="e.g. Particle Size"
                        className="w-full p-2 border border-gray-300 rounded text-sm"
                        value={newCQA.name}
                        onChange={(e) => setNewCQA({...newCQA, name: e.target.value})}
                    />
                </div>
                <div className="md:col-span-1">
                    <label className="block text-xs font-bold text-gray-600 mb-1">Unit</label>
                    <input 
                        type="text" 
                        placeholder="e.g. nm"
                        className="w-full p-2 border border-gray-300 rounded text-sm"
                        value={newCQA.unit}
                        onChange={(e) => setNewCQA({...newCQA, unit: e.target.value})}
                    />
                </div>
                <div className="md:col-span-1">
                    <label className="block text-xs font-bold text-gray-600 mb-1">Goal</label>
                    <select 
                        className="w-full p-2 border border-gray-300 rounded text-sm"
                        value={newCQA.goal}
                        onChange={(e) => setNewCQA({...newCQA, goal: e.target.value as any})}
                    >
                        <option value="Maximize">Maximize</option>
                        <option value="Minimize">Minimize</option>
                        <option value="Target">Target Value</option>
                    </select>
                </div>
                <div className="md:col-span-1">
                    <button 
                        onClick={addCQA}
                        disabled={!newCQA.name}
                        className="w-full bg-science-600 text-white p-2 rounded hover:bg-science-700 disabled:opacity-50 text-sm font-bold flex justify-center items-center gap-2"
                    >
                        <Plus size={16} /> Add CQA
                    </button>
                </div>
            </div>

            <div className="space-y-2 mb-8">
                {responses.map((res, idx) => (
                    <div key={idx} className="flex items-center justify-between p-3 bg-white border border-gray-200 rounded shadow-sm">
                        <div className="flex items-center gap-4">
                            <div className="w-8 h-8 rounded-full bg-science-100 text-science-700 flex items-center justify-center font-bold text-sm">
                                Y{idx + 1}
                            </div>
                            <div>
                                <p className="font-bold text-gray-800">{res.name}</p>
                                <p className="text-xs text-gray-500">{res.unit} • {res.goal}</p>
                            </div>
                        </div>
                        <button onClick={() => removeCQA(idx)} className="text-red-400 hover:text-red-600 p-2">
                            <Trash2 size={16} />
                        </button>
                    </div>
                ))}
                {responses.length === 0 && (
                    <p className="text-center text-gray-400 italic py-4">No responses defined yet.</p>
                )}
            </div>

            <div className="flex justify-between">
                <button 
                    onClick={onBack}
                    className="text-gray-500 hover:text-gray-700 font-medium flex items-center gap-2"
                >
                    <ArrowLeft size={18} /> Back
                </button>
               <button 
                onClick={onNext} 
                disabled={responses.length === 0}
                className="bg-science-600 text-white px-6 py-3 rounded-lg hover:bg-science-700 disabled:opacity-50 font-medium flex items-center gap-2"
               >
                 Next Step <ChevronRight size={18} />
               </button>
            </div>
        </div>
    );
};

export default CQASettings;

