const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses }) => {
    // Prediction State
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);

    // Plot Configuration State
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');

    // Initialize inputs and plot defaults
    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = mid.toString();
        });
        setPredictionInputs(initial);

        if (factors.length >= 2) {
            setPlotX(factors[0].name);
            setPlotY(factors[1].name);
        }
        if (responses.length > 0) {
            setPlotResponse(responses[0].name);
        }
    }, [factors, responses]);

    const calculatePredictionInternal = (inputs: Record<string, string>) => {
         if (!results.modelCoefficients) return 0;

        const { intercept, linear, quadratic, interactions } = results.modelCoefficients;
        let y = intercept;

        // Linear
        Object.entries(linear).forEach(([factorName, coeff]) => {
            const val = parseFloat(inputs[factorName] || '0');
            y += (coeff as number) * val;
        });
        // Quadratic
        Object.entries(quadratic).forEach(([factorName, coeff]) => {
            const val = parseFloat(inputs[factorName] || '0');
            y += (coeff as number) * Math.pow(val, 2);
        });
        // Interactions
        interactions.forEach(term => {
            const val1 = parseFloat(inputs[term.factor1] || '0');
            const val2 = parseFloat(inputs[term.factor2] || '0');
            y += term.coefficient * val1 * val2;
        });

        return y;
    };

    const calculatePrediction = () => {
        const val = calculatePredictionInternal(predictionInputs);
        setPredictedValue(val);
    };

    // Client-side Surface Generation
    useEffect(() => {
        if (!window.Plotly || !plotX || !plotY || !results.modelCoefficients) return;

        const factorX = factors.find(f => f.name === plotX);
        const factorY = factors.find(f => f.name === plotY);

        if(!factorX || !factorY) return;

        const xMin = parseFloat(factorX.low);
        const xMax = parseFloat(factorX.high);
        const yMin = parseFloat(factorY.low);
        const yMax = parseFloat(factorY.high);

        const steps = 20;
        const xValues = [];
        const yValues = [];
        const zMatrix = [];

        // Generate Grid
        for(let i=0; i<=steps; i++) {
             xValues.push(xMin + (i * (xMax - xMin) / steps));
             yValues.push(yMin + (i * (yMax - yMin) / steps));
        }

        for(let j=0; j<=steps; j++) {
            const row = [];
            for(let i=0; i<=steps; i++) {
                // Prepare inputs: varying X and Y, others held constant at predictionInputs (mid)
                const inputs = { ...predictionInputs };
                inputs[plotX] = xValues[i].toString();
                inputs[plotY] = yValues[j].toString();

                row.push(calculatePredictionInternal(inputs));
            }
            zMatrix.push(row);
        }

        // 3D Plot
        const surfaceData = [{
            z: zMatrix,
            x: xValues,
            y: yValues,
            type: 'surface',
            contours: {
                z: { show: true, usecolormap: true, highlightcolor: "#42f462", project: { z: true } }
            }
        }];
        const layout3d = {
            title: `Surface: ${plotResponse}`,
            autosize: true,
            scene: {
                xaxis: { title: plotX },
                yaxis: { title: plotY },
                zaxis: { title: plotResponse }
            },
            margin: { l: 0, r: 0, b: 0, t: 30 }
        };
        window.Plotly.newPlot('plot3d', surfaceData, layout3d);

        // Contour Plot
        const contourData = [{
            z: zMatrix,
            x: xValues,
            y: yValues,
            type: 'contour',
            colorscale: 'Jet'
        }];
        const layoutContour = {
            title: `Contour: ${plotResponse}`,
            autosize: true,
            xaxis: { title: plotX },
            yaxis: { title: plotY }
        };
        window.Plotly.newPlot('plotContour', contourData, layoutContour);

    }, [plotX, plotY, plotResponse, results.modelCoefficients, predictionInputs]);

    // Diagnostic Plots
    useEffect(() => {
        if (!window.Plotly || !results.diagnostics) return;
        const diag = results.diagnostics;

         // 1. Predicted vs Run
        const predRunData = [
            { x: diag.runOrder, y: diag.predicted, type: 'scatter', mode: 'lines+markers', name: 'Predicted', line: { color: '#0284c7' } },
            { x: diag.runOrder, y: diag.actual, type: 'scatter', mode: 'markers', name: 'Actual', marker: { color: '#ef4444' } }
        ];
        window.Plotly.newPlot('plotPredVsRun', predRunData, { title: 'Pred vs Actual (Run Order)', margin: { t: 30, b: 30, l: 30, r: 10 } });

        // 2. Residuals vs Run
        const residData = [{ x: diag.runOrder, y: diag.residuals, type: 'scatter', mode: 'markers', marker: { color: '#f59e0b', size: 8 } }];
        window.Plotly.newPlot('plotResidVsRun', residData, { title: 'Residuals vs Run Order', shapes: [{ type: 'line', x0: 0, x1: Math.max(...diag.runOrder)+1, y0: 0, y1: 0, line: { color: 'black', width: 1, dash: 'dot' } }], margin: { t: 30, b: 30, l: 30, r: 10 } });

        // 3. Predicted vs Actual
        const fitData = [
            { x: diag.actual, y: diag.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9' } },
            { x: [Math.min(...diag.actual), Math.max(...diag.actual)], y: [Math.min(...diag.actual), Math.max(...diag.actual)], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' }, name: 'Ideal' }
        ];
        window.Plotly.newPlot('plotPredVsActual', fitData, { title: 'Predicted vs Actual', margin: { t: 30, b: 30, l: 30, r: 10 } });

        // 4. Box-Cox with CI
        if (diag.boxCox) {
            const boxCoxData = [{
                x: diag.boxCox.lambda,
                y: diag.boxCox.lnRSS,
                type: 'scatter',
                mode: 'lines',
                line: { shape: 'spline', color: '#8b5cf6', width: 3 },
                name: 'ln(RSS)'
            }];

            const shapes = [];
            if (diag.boxCox.ciLimit) {
                 shapes.push({
                    type: 'line',
                    x0: Math.min(...diag.boxCox.lambda),
                    x1: Math.max(...diag.boxCox.lambda),
                    y0: diag.boxCox.ciLimit,
                    y1: diag.boxCox.ciLimit,
                    line: { color: 'red', width: 2, dash: 'dash' },
                    name: '95% CI'
                 });
            }

            window.Plotly.newPlot('plotBoxCox', boxCoxData, {
                title: 'Box-Cox Plot',
                xaxis: { title: 'Lambda (λ)' },
                yaxis: { title: 'ln(RSS)' },
                shapes: shapes,
                margin: { t: 30, b: 30, l: 40, r: 10 }
            });
        }
    }, [results.diagnostics]);


    return (
        <div className="space-y-8 pb-12">
            <div className="bg-white p-8 rounded-xl shadow-lg border border-gray-200">
                <h2 className="text-2xl font-bold text-science-900 mb-4 flex items-center gap-2">
                    <LayoutDashboard /> Statistical Analysis (ANOVA)
                </h2>
                <div className="prose prose-sm max-w-none text-gray-700 bg-slate-50 p-6 rounded border border-slate-200">
                    <ReactMarkdown>{results.anovaText}</ReactMarkdown>
                </div>
            </div>

            {/* Diagnostic Plots */}
            {results.diagnostics && (
                <div className="space-y-4">
                    <h3 className="text-xl font-bold text-gray-800 border-b pb-2 flex items-center gap-2">
                        <Activity size={24} className="text-science-600"/> 
                        Model Diagnostics
                    </h3>
                    <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-4">
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotPredVsRun" className="w-full h-full"></div></div>
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotResidVsRun" className="w-full h-full"></div></div>
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotPredVsActual" className="w-full h-full"></div></div>
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotBoxCox" className="w-full h-full"></div></div>
                    </div>
                </div>
            )}

            {/* Surface Plots */}
            <div className="space-y-6">
                <div className="flex justify-between items-center border-b pb-2">
                     <h3 className="text-xl font-bold text-gray-800">Response Surface Exploration</h3>
                </div>

                {/* Controls */}
                <div className="bg-science-50 p-4 rounded-lg flex flex-wrap gap-4 items-center">
                    <div>
                        <label className="block text-xs font-bold text-gray-600">X-Axis</label>
                        <select className="p-2 rounded border" value={plotX} onChange={e => setPlotX(e.target.value)}>
                            {factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-600">Y-Axis</label>
                        <select className="p-2 rounded border" value={plotY} onChange={e => setPlotY(e.target.value)}>
                            {factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}
                        </select>
                    </div>
                    <div>
                         <label className="block text-xs font-bold text-gray-600">Response</label>
                         <select className="p-2 rounded border" value={plotResponse} onChange={e => setPlotResponse(e.target.value)}>
                             {responses.map(r => <option key={r.name} value={r.name}>{r.name}</option>)}
                         </select>
                    </div>
                </div>

                <div className="grid md:grid-cols-2 gap-8">
                    <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                        <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
                            <Cuboid size={18} /> 3D Surface
                        </h3>
                        <div id="plot3d" className="w-full h-[400px]"></div>
                    </div>
                    <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                        <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
                            <Layers size={18} /> Contour
                        </h3>
                        <div id="plotContour" className="w-full h-[400px]"></div>
                    </div>
                </div>
            </div>

            {/* Prediction Simulator */}
            {results.modelCoefficients && (
                <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-lg">
                    <h3 className="text-xl font-bold text-science-900 mb-4 flex items-center gap-2">
                        <Calculator size={24} /> 
                        Predict Outcome Simulator
                    </h3>
                    <div className="grid md:grid-cols-3 gap-6 items-end">
                        {factors.map(f => (
                            <div key={f.name}>
                                <label className="block text-xs font-bold text-science-800 mb-1 uppercase">
                                    {f.name} ({f.unit})
                                </label>
                                <input 
                                    type="number"
                                    step="any"
                                    className="w-full p-2 border border-science-200 rounded text-sm focus:ring-2 focus:ring-science-500 outline-none"
                                    value={predictionInputs[f.name] || ''}
                                    onChange={(e) => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}
                                />
                            </div>
                        ))}
                    </div>

                    <div className="mt-6 flex items-center gap-6">
                        <button 
                            onClick={calculatePrediction}
                            className="bg-science-600 text-white px-6 py-2 rounded-lg hover:bg-science-700 font-bold flex items-center gap-2 shadow-sm"
                        >
                            <Play size={16} /> Predict Result
                        </button>
                        {predictedValue !== null && (
                            <div className="bg-slate-100 px-6 py-2 rounded-lg border border-slate-300 shadow-sm">
                                <span className="text-xs font-bold text-gray-500 uppercase mr-2">Predicted {plotResponse || 'Response'}:</span>
                                <span className="text-xl font-bold text-science-700">{predictedValue.toFixed(4)}</span>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default AnalysisDashboard;

import { GoogleGenAI, SchemaType } from "@google/genai";
import { AnalysisRequest, ExperimentalRun, AnalysisResult } from "../types";

const getClient = () => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        throw new Error("API Key not found in process.env.API_KEY");
    }
    return new GoogleGenAI({ apiKey });
};

// Returns just the runs array structure
export const generateDesignMatrix = async (request: AnalysisRequest, designName: string): Promise<ExperimentalRun[]> => {
    try {
        const ai = getClient();
        const factorDesc = request.factors.map(f => `${f.name} (${f.levels} levels: ${f.low} to ${f.high})`).join(', ');

        const prompt = `
        Generate a Design of Experiments (DoE) matrix for a "${designName}".
        Factors: ${factorDesc}.

        Return STRICTLY JSON format. An array of objects.
        Each object should have:
        - "id" (number, starting at 1)
        - "factors" (object where keys are factor names and values are numbers).

        Do not output any markdown code blocks. Just the raw JSON string.
        Ensure real-world values are used based on the ranges provided, not coded values.
        Generate a reasonable number of runs for this design (e.g., 8-15 for small factorial/BBD/CCD).
        Include center points if standard for this design.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 0 }
            }
        });

        const text = response.text || "[]";
        // Clean markdown if present
        const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const runs = JSON.parse(jsonStr);

        // Map to internal structure ensuring results object exists
        return runs.map((r: any) => ({
            id: r.id,
            factors: r.factors,
            results: {} 
        }));

    } catch (e) {
        console.error("Design Matrix Error", e);
        return [];
    }
};

export const analyzeExperimentalResults = async (
    request: AnalysisRequest, 
    designName: string, 
    runs: ExperimentalRun[]
): Promise<AnalysisResult> => {
    const ai = getClient();

    // Prepare data for AI
    const dataStr = JSON.stringify(runs.map(r => ({ ...r.factors, ...r.results })));
    const responseNames = request.responses.map(r => r.name).join(', ');

    const prompt = `
    Perform a statistical analysis on the following formulation experiment results.
    Design: ${designName}.
    Responses: ${responseNames}.
    Data: ${dataStr}.

    Task 1: ANOVA & Interpretations (Markdown)
    - **CRITICAL**: Include the general mathematical equation used to calculate the total number of runs (N) for this design (e.g., N = 2^k + 2k + cp) and explain the terms.
    - Provide an ANOVA table summary for the main responses.
    - Identify significant terms (p < 0.05).
    - Provide the regression equation (in terms of actual factors).
    - Comment on Model Fit (R-squared, Adj R-squared).
    - Provide a section called "Model Diagnostics" describing fit.

    Task 2: Visualization & Prediction Data (JSON)
    - I need plot data, diagnostics, AND the model coefficients to run predictions in the browser.
    - Return a JSON object inside a distinct block separated by "|||JSON_DATA|||".
    - Structure:
      {
         "plotData": [{
             "x": "Name of Factor X (primary)",
             "y": "Name of Factor Y (primary)",
             "z": "Name of Response",
             "xRange": [min, max],
             "yRange": [min, max],
             "surfaceZ": [[...]] (10x10 matrix),
             "contourZ": [[...]] (same matrix)
         }],
         "diagnostics": {
             "runOrder": [1, 2, 3...],
             "actual": [number...],
             "predicted": [number...],
             "residuals": [number...],
             "boxCox": {
                 "lambda": [-3, -2.5, ..., 3],
                 "lnRSS": [number...] (Natural Log of Residual Sum of Squares. IMPORTANT: This should show a minimum at the optimal lambda),
                 "ciLimit": number (The threshold value for 95% Confidence Interval, usually min(lnRSS) + X)
             }
         },
         "modelCoefficients": {
             "intercept": number,
             "linear": { "FactorName1": coeff, "FactorName2": coeff },
             "quadratic": { "FactorName1": coeff },
             "interactions": [ { "factor1": "FactorName1", "factor2": "FactorName2", "coefficient": number } ]
         }
      }
    `;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { thinkingConfig: { thinkingBudget: 0 } }
    });

    const fullText = response.text || "";
    const parts = fullText.split("|||JSON_DATA|||");

    let anovaText = parts[0];
    let plotData = [];
    let diagnostics;
    let modelCoefficients;

    if (parts[1]) {
        try {
            const jsonStr = parts[1].replace(/```json/g, '').replace(/```/g, '').trim();
            const data = JSON.parse(jsonStr);
            plotData = data.plotData || [];
            diagnostics = data.diagnostics;
            modelCoefficients = data.modelCoefficients;
        } catch (e) {
            console.error("Error parsing plot data", e);
        }
    }

    return { anovaText, plotData, diagnostics, modelCoefficients };
};

import React, { useState } from 'react';
import { Activity, FlaskConical, Settings, CheckCircle2, ChevronRight, Sliders, Target, ArrowLeft } from 'lucide-react';
import FishboneDiagram from './components/FishboneDiagram';
import FactorSettings from './components/FactorSettings';
import CQASettings from './components/CQASettings';
import ResultsView from './components/ResultsView';
import { AnalysisRequest, DeliverySystem, DesignRecommendation, ExperimentGoal, FormFactor, FactorDefinition } from './types';
import { RECOMMENDATIONS } from './constants';

const StepIndicator: React.FC<{ currentStep: number }> = ({ currentStep }) => (
  <div className="flex justify-center mb-8">
    {[1, 2, 3, 4, 5, 6].map((step) => (
      <div key={step} className="flex items-center">
        <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm border-2 
          ${step <= currentStep ? 'bg-science-600 border-science-600 text-white' : 'bg-white border-gray-300 text-gray-400'}`}>
          {step < currentStep ? <CheckCircle2 size={16} /> : step}
        </div>
        {step < 6 && (
          <div className={`w-6 md:w-10 h-1 
            ${step < currentStep ? 'bg-science-600' : 'bg-gray-200'}`} 
          />
        )}
      </div>
    ))}
  </div>
);

const App: React.FC = () => {
  const [step, setStep] = useState(1);
  const [request, setRequest] = useState<AnalysisRequest>({
    goal: ExperimentGoal.OPTIMIZATION,
    system: DeliverySystem.GENERIC_ROBUST,
    factors: [],
    responses: []
  });

  const [formFactor, setFormFactor] = useState<FormFactor>(FormFactor.PROCESS_OR_INDEPENDENT);
  const [isConstraintIrregular, setIsConstraintIrregular] = useState(false);
  const [recommendation, setRecommendation] = useState<DesignRecommendation | null>(null);

  const handleFishboneComplete = (factorNames: string[]) => {
      const newFactors: FactorDefinition[] = factorNames.map(name => {
          const existing = request.factors.find(f => f.name === name);
          return existing || { name, unit: '', low: '', high: '', levels: 2 };
      });
      setRequest({ ...request, factors: newFactors });
      setStep(3);
  };

  const determineDesign = () => {
    let rec: DesignRecommendation;

    if (request.goal === ExperimentGoal.SCREENING) {
       if (request.factors.length > 5) { 
         rec = RECOMMENDATIONS.PLACKETT_BURMAN;
       } else {
         rec = RECOMMENDATIONS.FULL_FACTORIAL; 
       }
    } else {
      if (formFactor === FormFactor.MIXTURE) {
        if (request.system === DeliverySystem.LIPID_NANOCAPSULES || isConstraintIrregular) {
          rec = RECOMMENDATIONS.D_OPTIMAL_MIXTURE; 
        } else {
          rec = RECOMMENDATIONS.SIMPLEX_LATTICE; 
        }
      } else {
        if (isConstraintIrregular || request.system === DeliverySystem.GENERIC_IRREGULAR) {
          rec = RECOMMENDATIONS.D_OPTIMAL_SURFACE;
        } else if (
          request.system === DeliverySystem.LIPOSOMES || 
          request.system === DeliverySystem.MICROEMULSIONS 
        ) {
          rec = RECOMMENDATIONS.BOX_BEHNKEN; 
        } else if (request.system === DeliverySystem.EMULSIONS) {
             rec = RECOMMENDATIONS.D_OPTIMAL_SURFACE; 
        } else {
          rec = RECOMMENDATIONS.CENTRAL_COMPOSITE; 
        }
      }
    }
    setRecommendation(rec);
    setStep(6);
  };

  const overrideDesign = (designKey: string) => {
      if (RECOMMENDATIONS[designKey]) {
          setRecommendation(RECOMMENDATIONS[designKey]);
      }
  };

  const reset = () => {
    setStep(1);
    setRecommendation(null);
    setIsConstraintIrregular(false);
    setRequest({
      goal: ExperimentGoal.OPTIMIZATION,
      system: DeliverySystem.GENERIC_ROBUST,
      factors: [],
      responses: []
    });
  };

  return (
    <div className="min-h-screen bg-science-50 text-slate-800 font-sans">
      <header className="bg-white border-b border-gray-200 py-4 shadow-sm sticky top-0 z-10">
        <div className="container mx-auto px-4 flex items-center gap-3">
          <FlaskConical className="text-science-600" size={32} />
          <div>
            <h1 className="text-xl font-bold text-science-900 tracking-tight">QbD-PharmOptima</h1>
            <p className="text-xs text-gray-500">Computer-Aided Formulation Development</p>
          </div>
        </div>
      </header>

      <main className="container mx-auto px-4 py-8 max-w-5xl">
        <StepIndicator currentStep={step} />

        {step === 1 && (
          <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200 animate-fade-in">
            <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
              <Activity className="text-science-500" />
              1. Define Objectives
            </h2>
            <div className="grid md:grid-cols-2 gap-6">
              <button 
                onClick={() => { setRequest({...request, goal: ExperimentGoal.SCREENING}); setStep(2); }}
                className="group p-6 border-2 border-gray-100 rounded-xl hover:border-science-500 hover:bg-science-50 transition-all text-left"
              >
                <span className="block text-lg font-bold text-gray-800 mb-2 group-hover:text-science-700">Screening</span>
                <p className="text-sm text-gray-600">Identify influential factors from a large pool.</p>
              </button>
              <button 
                onClick={() => { setRequest({...request, goal: ExperimentGoal.OPTIMIZATION}); setStep(2); }}
                className="group p-6 border-2 border-gray-100 rounded-xl hover:border-science-500 hover:bg-science-50 transition-all text-left"
              >
                <span className="block text-lg font-bold text-gray-800 mb-2 group-hover:text-science-700">Optimization</span>
                <p className="text-sm text-gray-600">Find best settings using Response Surface.</p>
              </button>
            </div>
          </div>
        )}

        {step === 2 && (
          <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200 animate-fade-in">
            <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
              <Settings className="text-science-500" />
              2. Identify Factors (Inputs)
            </h2>
            <FishboneDiagram onFactorsChange={handleFishboneComplete} />
             <div className="mt-4 flex justify-start">
                 <button onClick={() => setStep(1)} className="text-gray-500 flex items-center gap-2"><ArrowLeft size={16}/> Back</button>
             </div>
          </div>
        )}

        {step === 3 && (
            <FactorSettings 
                factors={request.factors}
                onUpdate={(updated) => setRequest({ ...request, factors: updated })}
                onNext={() => setStep(4)}
                onBack={() => setStep(2)}
            />
        )}

        {step === 4 && (
            <CQASettings 
                responses={request.responses}
                onUpdate={(updated) => setRequest({ ...request, responses: updated })}
                onNext={() => setStep(5)}
                onBack={() => setStep(3)}
            />
        )}

        {step === 5 && (
          <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-200 animate-fade-in">
