import React, { useEffect, useState } from 'react';
import { AnalysisResult, FactorDefinition, ResponseDefinition } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, TrendingUp, BarChart2, Calculator, Play } from 'lucide-react';

declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses }) => {
    // Prediction State
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);

    // Plot Configuration State
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');

    // Initialize inputs and plot defaults
    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = mid.toString();
        });
        setPredictionInputs(initial);

        if (factors.length >= 2) {
            setPlotX(factors[0].name);
            setPlotY(factors[1].name);
        }
        if (responses.length > 0) {
            setPlotResponse(responses[0].name);
        }
    }, [factors, responses]);

    const calculatePredictionInternal = (inputs: Record<string, string>) => {
         if (!results.modelCoefficients) return 0;

        const { intercept, linear, quadratic, interactions } = results.modelCoefficients;
        let y = intercept;

        // Linear
        Object.entries(linear).forEach(([factorName, coeff]) => {
            const val = parseFloat(inputs[factorName] || '0');
            y += (coeff as number) * val;
        });
        // Quadratic
        Object.entries(quadratic).forEach(([factorName, coeff]) => {
            const val = parseFloat(inputs[factorName] || '0');
            y += (coeff as number) * Math.pow(val, 2);
        });
        // Interactions
        interactions.forEach(term => {
            const val1 = parseFloat(inputs[term.factor1] || '0');
            const val2 = parseFloat(inputs[term.factor2] || '0');
            y += term.coefficient * val1 * val2;
        });

        return y;
    };

    const calculatePrediction = () => {
        const val = calculatePredictionInternal(predictionInputs);
        setPredictedValue(val);
    };

    // Client-side Surface Generation
    useEffect(() => {
        if (!window.Plotly || !plotX || !plotY || !results.modelCoefficients) return;

        const factorX = factors.find(f => f.name === plotX);
        const factorY = factors.find(f => f.name === plotY);

        if(!factorX || !factorY) return;

        const xMin = parseFloat(factorX.low);
        const xMax = parseFloat(factorX.high);
        const yMin = parseFloat(factorY.low);
        const yMax = parseFloat(factorY.high);

        const steps = 20;
        const xValues = [];
        const yValues = [];
        const zMatrix = [];

        // Generate Grid
        for(let i=0; i<=steps; i++) {
             xValues.push(xMin + (i * (xMax - xMin) / steps));
             yValues.push(yMin + (i * (yMax - yMin) / steps));
        }

        for(let j=0; j<=steps; j++) {
            const row = [];
            for(let i=0; i<=steps; i++) {
                // Prepare inputs: varying X and Y, others held constant at predictionInputs (mid)
                const inputs = { ...predictionInputs };
                inputs[plotX] = xValues[i].toString();
                inputs[plotY] = yValues[j].toString();

                row.push(calculatePredictionInternal(inputs));
            }
            zMatrix.push(row);
        }

        // 3D Plot
        const surfaceData = [{
            z: zMatrix,
            x: xValues,
            y: yValues,
            type: 'surface',
            contours: {
                z: { show: true, usecolormap: true, highlightcolor: "#42f462", project: { z: true } }
            }
        }];
        const layout3d = {
            title: `Surface: ${plotResponse}`,
            autosize: true,
            scene: {
                xaxis: { title: plotX },
                yaxis: { title: plotY },
                zaxis: { title: plotResponse }
            },
            margin: { l: 0, r: 0, b: 0, t: 30 }
        };
        window.Plotly.newPlot('plot3d', surfaceData, layout3d);

        // Contour Plot
        const contourData = [{
            z: zMatrix,
            x: xValues,
            y: yValues,
            type: 'contour',
            colorscale: 'Jet'
        }];
        const layoutContour = {
            title: `Contour: ${plotResponse}`,
            autosize: true,
            xaxis: { title: plotX },
            yaxis: { title: plotY }
        };
        window.Plotly.newPlot('plotContour', contourData, layoutContour);

    }, [plotX, plotY, plotResponse, results.modelCoefficients, predictionInputs]);

    // Diagnostic Plots
    useEffect(() => {
        if (!window.Plotly || !results.diagnostics) return;
        const diag = results.diagnostics;

         // 1. Predicted vs Run
        const predRunData = [
            { x: diag.runOrder, y: diag.predicted, type: 'scatter', mode: 'lines+markers', name: 'Predicted', line: { color: '#0284c7' } },
            { x: diag.runOrder, y: diag.actual, type: 'scatter', mode: 'markers', name: 'Actual', marker: { color: '#ef4444' } }
        ];
        window.Plotly.newPlot('plotPredVsRun', predRunData, { title: 'Pred vs Actual (Run Order)', margin: { t: 30, b: 30, l: 30, r: 10 } });

        // 2. Residuals vs Run
        const residData = [{ x: diag.runOrder, y: diag.residuals, type: 'scatter', mode: 'markers', marker: { color: '#f59e0b', size: 8 } }];
        window.Plotly.newPlot('plotResidVsRun', residData, { title: 'Residuals vs Run Order', shapes: [{ type: 'line', x0: 0, x1: Math.max(...diag.runOrder)+1, y0: 0, y1: 0, line: { color: 'black', width: 1, dash: 'dot' } }], margin: { t: 30, b: 30, l: 30, r: 10 } });

        // 3. Predicted vs Actual
        const fitData = [
            { x: diag.actual, y: diag.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9' } },
            { x: [Math.min(...diag.actual), Math.max(...diag.actual)], y: [Math.min(...diag.actual), Math.max(...diag.actual)], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' }, name: 'Ideal' }
        ];
        window.Plotly.newPlot('plotPredVsActual', fitData, { title: 'Predicted vs Actual', margin: { t: 30, b: 30, l: 30, r: 10 } });

        // 4. Box-Cox with CI
        if (diag.boxCox) {
            const lambda = diag.boxCox.lambda;
            const lnRSS = diag.boxCox.lnRSS;

            const boxCoxData = [{
                x: lambda,
                y: lnRSS,
                type: 'scatter',
                mode: 'lines',
                line: { shape: 'spline', color: '#8b5cf6', width: 3 },
                name: 'ln(RSS)'
            }];

            const shapes = [];
            const minY = Math.min(...lnRSS);
            const maxY = Math.max(...lnRSS);

            // 95% CI Threshold Line
            if (diag.boxCox.ciLimit) {
                 shapes.push({
                    type: 'line',
                    x0: Math.min(...lambda),
                    x1: Math.max(...lambda),
                    y0: diag.boxCox.ciLimit,
                    y1: diag.boxCox.ciLimit,
                    line: { color: 'red', width: 2, dash: 'dash' },
                    name: '95% CI Limit'
                 });
            }

            // Best Lambda Vertical Line
            if (diag.boxCox.lambdaBest !== undefined) {
                shapes.push({
                    type: 'line',
                    x0: diag.boxCox.lambdaBest,
                    x1: diag.boxCox.lambdaBest,
                    y0: minY,
                    y1: maxY,
                    line: { color: 'green', width: 1.5, dash: 'dot' },
                });
            }

            // Confidence Interval Bounds (Vertical Lines in Red)
            if (diag.boxCox.lambdaLow !== undefined) {
                shapes.push({
                    type: 'line',
                    x0: diag.boxCox.lambdaLow,
                    x1: diag.boxCox.lambdaLow,
                    y0: minY,
                    y1: diag.boxCox.ciLimit || maxY,
                    line: { color: 'red', width: 1.5 },
                });
            }
            if (diag.boxCox.lambdaHigh !== undefined) {
                 shapes.push({
                    type: 'line',
                    x0: diag.boxCox.lambdaHigh,
                    x1: diag.boxCox.lambdaHigh,
                    y0: minY,
                    y1: diag.boxCox.ciLimit || maxY,
                    line: { color: 'red', width: 1.5 },
                });
            }

            window.Plotly.newPlot('plotBoxCox', boxCoxData, {
                title: 'Box-Cox Plot',
                xaxis: { title: 'Lambda (λ)' },
                yaxis: { title: 'ln(RSS)' },
                shapes: shapes,
                margin: { t: 30, b: 30, l: 40, r: 10 }
            });
        }
    }, [results.diagnostics]);


    return (
        <div className="space-y-8 pb-12">
            <div className="bg-white p-8 rounded-xl shadow-lg border border-gray-200">
                <h2 className="text-2xl font-bold text-science-900 mb-4 flex items-center gap-2">
                    <LayoutDashboard /> Statistical Analysis (ANOVA)
                </h2>
                <div className="prose prose-sm max-w-none text-gray-700 bg-slate-50 p-6 rounded border border-slate-200">
                    <ReactMarkdown>{results.anovaText}</ReactMarkdown>
                </div>
            </div>

            {/* Diagnostic Plots */}
            {results.diagnostics && (
                <div className="space-y-4">
                    <h3 className="text-xl font-bold text-gray-800 border-b pb-2 flex items-center gap-2">
                        <Activity size={24} className="text-science-600"/> 
                        Model Diagnostics
                    </h3>
                    <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-4">
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotPredVsRun" className="w-full h-full"></div></div>
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotResidVsRun" className="w-full h-full"></div></div>
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotPredVsActual" className="w-full h-full"></div></div>
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotBoxCox" className="w-full h-full"></div></div>
                    </div>
                </div>
            )}

            {/* Surface Plots */}
            <div className="space-y-6">
                <div className="flex justify-between items-center border-b pb-2">
                     <h3 className="text-xl font-bold text-gray-800">Response Surface Exploration</h3>
                </div>

                {/* Controls */}
                <div className="bg-science-50 p-4 rounded-lg flex flex-wrap gap-4 items-center">
                    <div>
                        <label className="block text-xs font-bold text-gray-600">X-Axis</label>
                        <select className="p-2 rounded border" value={plotX} onChange={e => setPlotX(e.target.value)}>
                            {factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-600">Y-Axis</label>
                        <select className="p-2 rounded border" value={plotY} onChange={e => setPlotY(e.target.value)}>
                            {factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}
                        </select>
                    </div>
                    <div>
                         <label className="block text-xs font-bold text-gray-600">Response</label>
                         <select className="p-2 rounded border" value={plotResponse} onChange={e => setPlotResponse(e.target.value)}>
                             {responses.map(r => <option key={r.name} value={r.name}>{r.name}</option>)}
                         </select>
                    </div>
                </div>

                <div className="grid md:grid-cols-2 gap-8">
                    <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                        <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
                            <Cuboid size={18} /> 3D Surface
                        </h3>
                        <div id="plot3d" className="w-full h-[400px]"></div>
                    </div>
                    <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                        <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
                            <Layers size={18} /> Contour
                        </h3>
                        <div id="plotContour" className="w-full h-[400px]"></div>
                    </div>
                </div>
            </div>

            {/* Prediction Simulator */}
            {results.modelCoefficients && (
                <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-lg">
                    <h3 className="text-xl font-bold text-science-900 mb-4 flex items-center gap-2">
                        <Calculator size={24} /> 
                        Predict Outcome Simulator
                    </h3>
                    <div className="grid md:grid-cols-3 gap-6 items-end">
                        {factors.map(f => (
                            <div key={f.name}>
                                <label className="block text-xs font-bold text-science-800 mb-1 uppercase">
                                    {f.name} ({f.unit})
                                </label>
                                <input 
                                    type="number"
                                    step="any"
                                    className="w-full p-2 border border-science-200 rounded text-sm focus:ring-2 focus:ring-science-500 outline-none"
                                    value={predictionInputs[f.name] || ''}
                                    onChange={(e) => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}
                                />
                            </div>
                        ))}
                    </div>

                    <div className="mt-6 flex items-center gap-6">
                        <button 
                            onClick={calculatePrediction}
                            className="bg-science-600 text-white px-6 py-2 rounded-lg hover:bg-science-700 font-bold flex items-center gap-2 shadow-sm"
                        >
                            <Play size={16} /> Predict Result
                        </button>
                        {predictedValue !== null && (
                            <div className="bg-slate-100 px-6 py-2 rounded-lg border border-slate-300 shadow-sm">
                                <span className="text-xs font-bold text-gray-500 uppercase mr-2">Predicted {plotResponse || 'Response'}:</span>
                                <span className="text-xl font-bold text-science-700">{predictedValue.toFixed(4)}</span>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

