                        onChange={(e) => overrideDesign(e.target.value)}
                    >
                        {Object.entries(RECOMMENDATIONS).map(([key, rec]) => (
                            <option key={key} value={key}>{rec.name} ({rec.acronym})</option>
                        ))}
                    </select>
                     <button 
                        onClick={() => setStep(5)} 
