                     >
                         <ArrowLeft size={16} /> Back to Design
                     </button>
                </div>

                <ResultsView 
                    recommendation={recommendation} 
                    request={request}
                    onReset={reset}
                />
          </div>
        )}

      </main>
    </div>
  );
};

