                    <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-4">
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotPredVsRun" className="w-full h-full"></div></div>
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotResidVsRun" className="w-full h-full"></div></div>
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotPredVsActual" className="w-full h-full"></div></div>
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotBoxCox" className="w-full h-full"></div></div>
                    </div>
                </div>
            )}

            {/* Surface Plots */}
            <div className="space-y-6">
                <div className="flex justify-between items-center border-b pb-2">
                     <h3 className="text-xl font-bold text-gray-800">Response Surface Exploration</h3>
                </div>

                {/* Controls */}
                <div className="bg-science-50 p-4 rounded-lg flex flex-wrap gap-4 items-center">
                    <div>
                        <label className="block text-xs font-bold text-gray-600">X-Axis</label>
