                            {factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}
                        </select>
                    </div>
                    <div>
                         <label className="block text-xs font-bold text-gray-600">Response</label>
                         <select className="p-2 rounded border" value={plotResponse} onChange={e => setPlotResponse(e.target.value)}>
