import { GoogleGenAI } from "@google/genai";
import { AnalysisRequest, ExperimentalRun, AnalysisResult } from "../types";

const getClient = () => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        throw new Error("API Key not found in process.env.API_KEY");
    }
    return new GoogleGenAI({ apiKey });
};

// Returns just the runs array structure
export const generateDesignMatrix = async (request: AnalysisRequest, designName: string): Promise<ExperimentalRun[]> => {
    try {
        const ai = getClient();
        const factorDesc = request.factors.map(f => `${f.name} (${f.levels} levels: ${f.low} to ${f.high})`).join(', ');

        const isMixture = designName.toLowerCase().includes('mixture') || designName.toLowerCase().includes('simplex');
        const mixtureInstruction = isMixture 
            ? "CRITICAL: This is a Mixture Design. The sum of the values of all factors in each run MUST equal exactly 100. Adjust the values within the specified ranges to satisfy this constraint." 
            : "";

        const prompt = `
        Generate a Design of Experiments (DoE) matrix for a "${designName}".
        Factors: ${factorDesc}.
        ${mixtureInstruction}

        Return STRICTLY JSON format. An array of objects.
        Each object should have:
        - "id" (number, starting at 1)
        - "factors" (object where keys are factor names and values are numbers).

        Do not output any markdown code blocks. Just the raw JSON string.
        Ensure real-world values are used based on the ranges provided, not coded values.
        Generate a reasonable number of runs for this design (e.g., 8-15 for small factorial/BBD/CCD).
        Include center points if standard for this design.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 0 }
            }
        });

        const text = response.text || "[]";
        // Clean markdown if present
        const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const runs = JSON.parse(jsonStr);

        // Map to internal structure ensuring results object exists
        return runs.map((r: any) => ({
            id: r.id,
            factors: r.factors,
            results: {} 
        }));

    } catch (e) {
        console.error("Design Matrix Error", e);
        return [];
    }
};

export const analyzeExperimentalResults = async (
    request: AnalysisRequest, 
    designName: string, 
    runs: ExperimentalRun[]
): Promise<AnalysisResult> => {
    const ai = getClient();

    // Prepare data for AI
    const dataStr = JSON.stringify(runs.map(r => ({ ...r.factors, ...r.results })));
    const responseNames = request.responses.map(r => r.name).join(', ');
    const factorNames = JSON.stringify(request.factors.map(f => f.name));

    const prompt = `
    Perform a statistical analysis on the following formulation experiment results.
    Design: ${designName}.
    Responses: ${responseNames}.
    Data: ${dataStr}.

    Task 1: ANOVA & Interpretations (Markdown)
    - **CRITICAL**: Include the general mathematical equation used to calculate the total number of runs (N) for this design.
    - Provide an ANOVA table summary.
    - Identify significant terms (p < 0.05).
    - Discuss model fit.

    Task 2: Visualization, Statistics, & Prediction Data (JSON)
    - Return a JSON object inside a distinct block separated by "|||JSON_DATA|||".
    - **Equation Styling**: The "equation" field must be PLAIN TEXT. Do NOT use LaTeX. Do NOT use '$', '\\beta', '\\cdot', or underscores. Use '*' for multiplication. Example: "Y = 5.2 + 3.1 * FactorA + 2.5 * FactorB^2".
    - **Statistics**: Calculate 'Predicted R-squared' (using PRESS/k-fold validation concept) and 'Adequate Precision' (Signal-to-noise ratio).
    - **Accuracy**: The "modelCoefficients" object MUST correspond EXACTLY to the "equation". The simulator depends on this object.
       - Use these EXACT factor names as keys: ${factorNames}.
       - For Mixture designs: Intercept is often 0. Put component coefficients in "linear".
       - For Interactions: Use strict "factor1", "factor2" structure.

    - Structure:
      {
         "fitStatistics": {
             "rSquared": number,
             "adjRSquared": number,
             "predictedRSquared": number,
             "adequatePrecision": number,
             "equation": "string"
         },
         "plotData": [], // Leave empty, handled by client
         "diagnostics": {
             "runOrder": [1, 2, 3...],
             "actual": [number...],
             "predicted": [number...],
             "residuals": [number...],
             "boxCox": {
                 "lambda": [-3, -2.5, ..., 3],
                 "lnRSS": [number...],
                 "ciLimit": number,
                 "lambdaBest": number,
                 "lambdaLow": number,
                 "lambdaHigh": number
             }
         },
         "modelCoefficients": {
             "intercept": number,
             "linear": { "FactorName1": coeff },
             "quadratic": { "FactorName1": coeff },
             "interactions": [ { "factor1": "FactorName1", "factor2": "FactorName2", "coefficient": number } ]
         }
      }
    `;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { thinkingConfig: { thinkingBudget: 0 } }
    });

    const fullText = response.text || "";
    const parts = fullText.split("|||JSON_DATA|||");

    let anovaText = parts[0];
    let plotData = [];
    let diagnostics;
    let modelCoefficients;
    let fitStatistics;

    if (parts[1]) {
        try {
            const jsonStr = parts[1].replace(/```json/g, '').replace(/```/g, '').trim();
            const data = JSON.parse(jsonStr);
            plotData = data.plotData || [];
            diagnostics = data.diagnostics;
            modelCoefficients = data.modelCoefficients;
            fitStatistics = data.fitStatistics;
        } catch (e) {
            console.error("Error parsing plot data", e);
        }
    }

    return { anovaText, plotData, diagnostics, modelCoefficients, fitStatistics };
};

export enum ExperimentGoal {
  SCREENING = 'Screening',
  OPTIMIZATION = 'Optimization',
}

export enum FormFactor {
  PROCESS_OR_INDEPENDENT = 'Process/Independent Factors',
  MIXTURE = 'Mixture (Sum to 100%)',
}

export enum DeliverySystem {
  LIPOSOMES = 'Liposomes / Delicate Structures',
  LIPID_NANOCAPSULES = 'Lipid Nanocapsules (LNC)',
  EMULSIONS = 'Emulsions',
  MICROEMULSIONS = 'Microemulsions',
  TABLETS_SOLIDS = 'Tablets / Solid Dosage Forms',
  GENERIC_ROBUST = 'Generic / Robust System',
  GENERIC_IRREGULAR = 'Irregular Experimental Domain',
}

export interface DesignRecommendation {
  name: string;
  acronym: string;
  reasoning: string;
  sourceReference: string;
  suitability: string[];
  caveats: string[];
}

export interface FactorDefinition {
  name: string;
  unit?: string;
  low: string;
  high: string;
  levels: number; // Number of levels
}

export interface ResponseDefinition {
  name: string;
  unit: string;
  goal: 'Maximize' | 'Minimize' | 'Target';
}

export interface AnalysisRequest {
  system: DeliverySystem;
  goal: ExperimentGoal;
  factors: FactorDefinition[]; 
  responses: ResponseDefinition[];
}

export interface ExperimentalRun {
    id: number;
    factors: Record<string, number>; // Factor Name -> Value
    results: Record<string, string>; // Response Name -> Value (String to handle input state)
}

export interface ModelCoefficients {
    intercept: number;
    linear: Record<string, number>;
    quadratic: Record<string, number>;
    interactions: Array<{ factor1: string; factor2: string; coefficient: number }>;
}

export interface FitStatistics {
    rSquared: number;
    adjRSquared: number;
    predictedRSquared: number; // k-fold / PRESS based
    adequatePrecision: number;
    equation: string; // Clean text string
}

export interface AnalysisResult {
    anovaText: string; // Markdown
    fitStatistics?: FitStatistics;
    diagnosticInterpretations?: {
        predVsActual: string;
        residualsVsRun: string;
        boxCox: string;
    };
    plotData: {
        x: string; // Name of X factor
        y: string; // Name of Y factor (or Y axis in 3D)
        z: string; // Name of Response (Z axis in 3D)
        surfaceZ: number[][]; // Matrix for 3D plot
        contourZ: number[][]; // Matrix for contour
        xRange: number[];
        yRange: number[];
    }[];
    diagnostics?: {
        runOrder: number[];
        actual: number[];
        predicted: number[];
        residuals: number[];
        boxCox?: {
            lambda: number[];
            lnRSS: number[]; 
            ciLimit?: number; // Threshold line for 95% Confidence Interval
            lambdaBest?: number;
            lambdaLow?: number; // Lower 95% CI limit
            lambdaHigh?: number; // Upper 95% CI limit
        };
    };
    modelCoefficients?: ModelCoefficients; // Structured model for prediction
}

