    // Plot Configuration State
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');

    // Initialize inputs and plot defaults
    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = mid.toString();
        });
        setPredictionInputs(initial);

        if (factors.length >= 2) {
            setPlotX(factors[0].name);
            setPlotY(factors[1].name);
        }
        if (responses.length > 0) {
            setPlotResponse(responses[0].name);
        }
    }, [factors, responses]);

    const calculatePredictionInternal = (inputs: Record<string, string>) => {
         if (!results.modelCoefficients) return 0;

        const { intercept, linear, quadratic, interactions } = results.modelCoefficients;
        let y = intercept;

        // Linear
        Object.entries(linear).forEach(([factorName, coeff]) => {
            const val = parseFloat(inputs[factorName] || '0');
            if (!isNaN(val)) {
                y += (coeff as number) * val;
            }
        });
        // Quadratic
        Object.entries(quadratic).forEach(([factorName, coeff]) => {
            const val = parseFloat(inputs[factorName] || '0');
            if (!isNaN(val)) {
                y += (coeff as number) * Math.pow(val, 2);
            }
        });
        // Interactions
        interactions.forEach(term => {
            const val1 = parseFloat(inputs[term.factor1] || '0');
            const val2 = parseFloat(inputs[term.factor2] || '0');
            if (!isNaN(val1) && !isNaN(val2)) {
                y += term.coefficient * val1 * val2;
            }
        });

        return y;
    };

    const calculatePrediction = () => {
        const val = calculatePredictionInternal(predictionInputs);
        setPredictedValue(val);
    };

    // Helper to get response unit
    const getResponseUnit = (resName: string) => {
        const r = responses.find(r => r.name === resName);
        return r ? r.unit : '';
    };

    // --- Ternary Plot Logic ---
    useEffect(() => {
        if (!window.Plotly || !results.modelCoefficients || factors.length !== 3) return;

        // Ternary plots are strictly for 3 factors.
        const fA = factors[0];
        const fB = factors[1];
        const fC = factors[2];

        const aPoints = [];
        const bPoints = [];
        const cPoints = [];
        const zPoints = [];

        // Generate simplex grid (Sum = 100 assumed or calculated)
        // We iterate step 5% of range.
        // Assuming sum is 100 based on user prompt context.
        const total = 100;
        const step = 2; 

        for (let a = 0; a <= total; a += step) {
            for (let b = 0; b <= (total - a); b += step) {
                const c = total - a - b;

                // Check if valid within individual ranges
                // Note: This check assumes the ranges are valid for the total.
                // If the user set low/high that contradict a+b+c=100, this might filter too much.
                // For visualization, we plot the whole valid simplex where possible.
                const validA = a >= parseFloat(fA.low) && a <= parseFloat(fA.high);
                const validB = b >= parseFloat(fB.low) && b <= parseFloat(fB.high);
                const validC = c >= parseFloat(fC.low) && c <= parseFloat(fC.high);

                if (validA && validB && validC) {
                    const inputs = {
                        [fA.name]: a.toString(),
                        [fB.name]: b.toString(),
                        [fC.name]: c.toString()
                    };
                    const z = calculatePredictionInternal(inputs);
                    aPoints.push(a);
                    bPoints.push(b);
                    cPoints.push(c);
                    zPoints.push(z);
                }
            }
        }

        const data = [{
            type: 'scatterternary',
            mode: 'markers',
            a: aPoints,
            b: bPoints,
            c: cPoints,
            marker: {
                color: zPoints,
                colorscale: 'Viridis',
                size: 4,
                colorbar: { title: plotResponse, thickness: 20 }
            },
            text: zPoints.map(z => z.toFixed(2)),
            hoverinfo: 'text+a+b+c'
        }];

        const layout = {
            title: `Mixture Contour: ${plotResponse}`,
            ternary: {
                sum: 100,
                aaxis: { title: fA.name, min: 0 },
                baxis: { title: fB.name, min: 0 },
                caxis: { title: fC.name, min: 0 }
            },
            margin: { t: 40, b: 40, l: 40, r: 40 }
        };

        window.Plotly.newPlot('plotTernary', data, layout);

    }, [factors, results.modelCoefficients, plotResponse]);


    // Client-side Surface Generation (Cartesian)
    useEffect(() => {
        if (!window.Plotly || !plotX || !plotY || !results.modelCoefficients) return;

        const factorX = factors.find(f => f.name === plotX);
        const factorY = factors.find(f => f.name === plotY);

        if(!factorX || !factorY) return;

        const xMin = parseFloat(factorX.low);
        const xMax = parseFloat(factorX.high);
        const yMin = parseFloat(factorY.low);
        const yMax = parseFloat(factorY.high);

        const steps = 25; // Increased resolution
        const xValues = [];
        const yValues = [];
        const zMatrix = [];

        // Generate Grid
        for(let i=0; i<=steps; i++) {
             xValues.push(xMin + (i * (xMax - xMin) / steps));
             yValues.push(yMin + (i * (yMax - yMin) / steps));
        }

        for(let j=0; j<=steps; j++) {
            const row = [];
            for(let i=0; i<=steps; i++) {
                // Prepare inputs: varying X and Y, others held constant at predictionInputs
                const inputs = { ...predictionInputs };
                inputs[plotX] = xValues[i].toString();
                inputs[plotY] = yValues[j].toString();

                row.push(calculatePredictionInternal(inputs));
            }
            zMatrix.push(row);
        }

        // 3D Plot
        const surfaceData = [{
            z: zMatrix,
            x: xValues,
            y: yValues,
            type: 'surface',
            contours: {
                z: { show: true, usecolormap: true, highlightcolor: "#42f462", project: { z: true } }
            },
            colorscale: 'Viridis'
        }];
        const layout3d = {
            title: `Surface: ${plotResponse}`,
            autosize: true,
            scene: {
                xaxis: { title: plotX },
                yaxis: { title: plotY },
                zaxis: { title: plotResponse }
            },
            margin: { l: 0, r: 0, b: 0, t: 30 }
        };
        window.Plotly.newPlot('plot3d', surfaceData, layout3d);

        // Contour Plot
        const contourData = [{
            z: zMatrix,
            x: xValues,
            y: yValues,
            type: 'contour',
            colorscale: 'Viridis'
        }];
        const layoutContour = {
            title: `Contour: ${plotResponse}`,
            autosize: true,
            xaxis: { title: plotX },
            yaxis: { title: plotY }
        };
        window.Plotly.newPlot('plotContour', contourData, layoutContour);

    }, [plotX, plotY, plotResponse, results.modelCoefficients, predictionInputs]);

    // Diagnostic Plots
    useEffect(() => {
        if (!window.Plotly || !results.diagnostics) return;
        const diag = results.diagnostics;

         // 1. Predicted vs Run
        const predRunData = [
            { x: diag.runOrder, y: diag.predicted, type: 'scatter', mode: 'lines+markers', name: 'Predicted', line: { color: '#0284c7' } },
            { x: diag.runOrder, y: diag.actual, type: 'scatter', mode: 'markers', name: 'Actual', marker: { color: '#ef4444' } }
        ];
        window.Plotly.newPlot('plotPredVsRun', predRunData, { title: 'Pred vs Actual (Run Order)', margin: { t: 30, b: 30, l: 30, r: 10 } });

        // 2. Residuals vs Run
        const residData = [{ x: diag.runOrder, y: diag.residuals, type: 'scatter', mode: 'markers', marker: { color: '#f59e0b', size: 8 } }];
        window.Plotly.newPlot('plotResidVsRun', residData, { title: 'Residuals vs Run Order', shapes: [{ type: 'line', x0: 0, x1: Math.max(...diag.runOrder)+1, y0: 0, y1: 0, line: { color: 'black', width: 1, dash: 'dot' } }], margin: { t: 30, b: 30, l: 30, r: 10 } });

        // 3. Predicted vs Actual
        const fitData = [
            { x: diag.actual, y: diag.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9' } },
            { x: [Math.min(...diag.actual), Math.max(...diag.actual)], y: [Math.min(...diag.actual), Math.max(...diag.actual)], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' }, name: 'Ideal' }
        ];
        window.Plotly.newPlot('plotPredVsActual', fitData, { title: 'Predicted vs Actual', margin: { t: 30, b: 30, l: 30, r: 10 } });

        // 4. Box-Cox with CI
        if (diag.boxCox) {
            const lambda = diag.boxCox.lambda;
            const lnRSS = diag.boxCox.lnRSS;

            const boxCoxData = [{
                x: lambda,
                y: lnRSS,
                type: 'scatter',
                mode: 'lines',
                line: { shape: 'spline', color: '#8b5cf6', width: 3 },
                name: 'ln(RSS)'
            }];

            const shapes = [];
            const minY = Math.min(...lnRSS);
            const maxY = Math.max(...lnRSS);

            // 95% CI Threshold Line (Horizontal)
            if (diag.boxCox.ciLimit) {
                 shapes.push({
                    type: 'line',
                    x0: Math.min(...lambda),
                    x1: Math.max(...lambda),
                    y0: diag.boxCox.ciLimit,
                    y1: diag.boxCox.ciLimit,
                    line: { color: 'red', width: 2, dash: 'dash' },
                    name: '95% CI Limit'
                 });
            }

            // Low CI Vertical Line
            if (diag.boxCox.lambdaLow !== undefined) {
                 shapes.push({
                    type: 'line',
                    x0: diag.boxCox.lambdaLow,
                    x1: diag.boxCox.lambdaLow,
                    y0: minY,
                    y1: maxY,
                    line: { color: 'red', width: 2 },
                    name: 'Low CI'
                 });
            }

            // High CI Vertical Line
            if (diag.boxCox.lambdaHigh !== undefined) {
                 shapes.push({
                    type: 'line',
                    x0: diag.boxCox.lambdaHigh,
                    x1: diag.boxCox.lambdaHigh,
                    y0: minY,
                    y1: maxY,
                    line: { color: 'red', width: 2 },
                    name: 'High CI'
                 });
            }

            // Best Lambda Vertical Line
            if (diag.boxCox.lambdaBest !== undefined) {
                shapes.push({
                    type: 'line',
                    x0: diag.boxCox.lambdaBest,
                    x1: diag.boxCox.lambdaBest,
                    y0: minY,
                    y1: maxY,
                    line: { color: 'green', width: 1.5, dash: 'dot' },
                    name: 'Best Lambda'
                });
            }

            window.Plotly.newPlot('plotBoxCox', boxCoxData, {
                title: 'Box-Cox Plot',
                xaxis: { title: 'Lambda (λ)' },
                yaxis: { title: 'ln(RSS)' },
                shapes: shapes,
                margin: { t: 30, b: 30, l: 40, r: 10 }
            });
        }
    }, [results.diagnostics]);


    return (
        <div className="space-y-8 pb-12">
            <div className="bg-white p-8 rounded-xl shadow-lg border border-gray-200">
                <h2 className="text-2xl font-bold text-science-900 mb-4 flex items-center gap-2">
                    <LayoutDashboard /> Statistical Analysis (ANOVA)
                </h2>

                {/* Fit Statistics & Equation Section */}
                {results.fitStatistics && (
                    <div className="grid md:grid-cols-3 gap-6 mb-6">
                        <div className="md:col-span-2 bg-gradient-to-r from-science-50 to-white p-4 rounded-lg border border-science-100">
                            <h4 className="text-xs font-bold text-science-600 uppercase mb-2 flex items-center gap-1">
                                <Sigma size={14} /> Regression Equation (Actual Factors)
                            </h4>
                            <p className="font-mono text-gray-800 text-sm leading-relaxed">
                                {results.fitStatistics.equation.replace(/(\+|-)/g, ' $1 ').replace(/\*/g, ' × ')}
                            </p>
                        </div>
                        <div className="bg-white p-4 rounded-lg border border-gray-200">
                            <h4 className="text-xs font-bold text-gray-500 uppercase mb-3">Model Fit Statistics</h4>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <div className="text-[10px] text-gray-400">R²</div>
                                    <div className="text-lg font-bold text-gray-700">{results.fitStatistics.rSquared.toFixed(4)}</div>
                                </div>
                                <div>
                                    <div className="text-[10px] text-gray-400">Adj. R²</div>
                                    <div className="text-lg font-bold text-gray-700">{results.fitStatistics.adjRSquared.toFixed(4)}</div>
                                </div>
                                <div>
                                    <div className="text-[10px] text-science-600 font-bold">Pred. R² (k-fold)</div>
                                    <div className="text-lg font-bold text-science-700">{results.fitStatistics.predictedRSquared.toFixed(4)}</div>
                                </div>
                                <div>
                                    <div className="text-[10px] text-science-600 font-bold">Adeq. Precision</div>
                                    <div className="text-lg font-bold text-science-700">{results.fitStatistics.adequatePrecision.toFixed(2)}</div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                <div className="prose prose-sm max-w-none text-gray-700 bg-slate-50 p-6 rounded border border-slate-200">
                    <ReactMarkdown>{results.anovaText}</ReactMarkdown>
                </div>
            </div>

            {/* Diagnostic Plots */}
            {results.diagnostics && (
                <div className="space-y-4">
                    <h3 className="text-xl font-bold text-gray-800 border-b pb-2 flex items-center gap-2">
                        <Activity size={24} className="text-science-600"/> 
                        Model Diagnostics
                    </h3>
                    <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-4">
                        <div className="flex flex-col bg-white p-2 rounded shadow border border-gray-200">
                            <div className="h-[250px] relative"><div id="plotPredVsActual" className="w-full h-full"></div></div>
                            {results.diagnosticInterpretations && (
                                <p className="text-xs text-gray-500 p-2 italic bg-slate-50 border-t mt-1">
                                    {results.diagnosticInterpretations.predVsActual}
                                </p>
                            )}
                        </div>
                         <div className="flex flex-col bg-white p-2 rounded shadow border border-gray-200">
                            <div className="h-[250px] relative"><div id="plotResidVsRun" className="w-full h-full"></div></div>
                            {results.diagnosticInterpretations && (
                                <p className="text-xs text-gray-500 p-2 italic bg-slate-50 border-t mt-1">
                                    {results.diagnosticInterpretations.residualsVsRun}
                                </p>
                            )}
                        </div>
                        {/* Run Order plot doesn't need comment per prompt, but Box-Cox does */}
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative">
                             <div id="plotPredVsRun" className="w-full h-full"></div>
                        </div>
                         <div className="flex flex-col bg-white p-2 rounded shadow border border-gray-200">
                            <div className="h-[250px] relative"><div id="plotBoxCox" className="w-full h-full"></div></div>
                            {results.diagnosticInterpretations && (
                                <p className="text-xs text-gray-500 p-2 italic bg-slate-50 border-t mt-1">
                                    {results.diagnosticInterpretations.boxCox}
                                </p>
                            )}
                        </div>
                    </div>
                </div>
            )}

            {/* Ternary Plot Section (Only for 3 Factors) */}
            {factors.length === 3 && (
                <div className="bg-white p-6 rounded-xl shadow-lg border border-gray-200">
                     <h3 className="text-xl font-bold text-science-900 mb-4 flex items-center gap-2">
                        <Triangle size={24} /> 
                        Mixture Design (Ternary Plot)
                    </h3>
                    <p className="text-sm text-gray-500 mb-4">Visualizing response across component constraints (A+B+C=100).</p>
                    <div id="plotTernary" className="w-full h-[500px]"></div>
                </div>
            )}

            {/* Surface Plots */}
            <div className="space-y-6">
                <div className="flex justify-between items-center border-b pb-2">
                     <h3 className="text-xl font-bold text-gray-800">Response Surface Exploration</h3>
                </div>

                {/* Controls */}
                <div className="bg-science-50 p-4 rounded-lg flex flex-wrap gap-4 items-center">
                    <div>
                        <label className="block text-xs font-bold text-gray-600">X-Axis</label>
                        <select className="p-2 rounded border" value={plotX} onChange={e => setPlotX(e.target.value)}>
                            {factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-600">Y-Axis</label>
                        <select className="p-2 rounded border" value={plotY} onChange={e => setPlotY(e.target.value)}>
                            {factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}
                        </select>
                    </div>
                    <div>
                         <label className="block text-xs font-bold text-gray-600">Response</label>
                         <select className="p-2 rounded border" value={plotResponse} onChange={e => setPlotResponse(e.target.value)}>
                             {responses.map(r => <option key={r.name} value={r.name}>{r.name}</option>)}
                         </select>
                    </div>
                </div>

                <div className="grid md:grid-cols-2 gap-8">
                    <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                        <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
                            <Cuboid size={18} /> 3D Surface
                        </h3>
                        <div id="plot3d" className="w-full h-[400px]"></div>
                    </div>
                    <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                        <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
                            <Layers size={18} /> Contour
                        </h3>
                        <div id="plotContour" className="w-full h-[400px]"></div>
                    </div>
                </div>
            </div>

            {/* Prediction Simulator */}
            {results.modelCoefficients && (
                <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-lg">
                    <h3 className="text-xl font-bold text-science-900 mb-4 flex items-center gap-2">
                        <Calculator size={24} /> 
                        Predict Outcome Simulator
                    </h3>
                    <div className="grid md:grid-cols-3 gap-6 items-end">
                        {factors.map(f => (
                            <div key={f.name}>
                                <label className="block text-xs font-bold text-science-800 mb-1 uppercase">
                                    {f.name} {f.unit ? `(${f.unit})` : ''}
                                </label>
                                <input 
                                    type="number"
                                    step="any"
                                    className="w-full p-2 border border-science-200 rounded text-sm focus:ring-2 focus:ring-science-500 outline-none"
                                    value={predictionInputs[f.name] || ''}
                                    onChange={(e) => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}
                                />
                            </div>
                        ))}
                    </div>

                    <div className="mt-6 flex items-center gap-6">
                        <button 
                            onClick={calculatePrediction}
                            className="bg-science-600 text-white px-6 py-2 rounded-lg hover:bg-science-700 font-bold flex items-center gap-2 shadow-sm"
                        >
                            <Play size={16} /> Predict Result
                        </button>
                        {predictedValue !== null && (
                            <div className="bg-slate-100 px-6 py-2 rounded-lg border border-slate-300 shadow-sm flex items-center gap-3">
                                <span className="text-xs font-bold text-gray-500 uppercase">Predicted {plotResponse || 'Response'}:</span>
                                <span className="text-2xl font-bold text-science-700">
                                    {predictedValue.toFixed(4)}
                                    <span className="text-sm font-normal text-gray-500 ml-1">{getResponseUnit(plotResponse)}</span>
                                </span>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default AnalysisDashboard;

import React, { useEffect, useState } from 'react';
import { AnalysisResult, FactorDefinition, ResponseDefinition } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, TrendingUp, BarChart2, Calculator, Play, Sigma, Triangle } from 'lucide-react';

declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses }) => {
    // Prediction State
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);

    // Plot Configuration State
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');

    // Initialize inputs and plot defaults
    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = mid.toString();
        });
        setPredictionInputs(initial);

        if (factors.length >= 2) {
            setPlotX(factors[0].name);
            setPlotY(factors[1].name);
        }
        if (responses.length > 0) {
            setPlotResponse(responses[0].name);
        }
    }, [factors, responses]);

    const calculatePredictionInternal = (inputs: Record<string, string>) => {
         if (!results.modelCoefficients) return 0;

        const { intercept, linear, quadratic, interactions } = results.modelCoefficients;
        let y = intercept;

        // Linear
        Object.entries(linear).forEach(([factorName, coeff]) => {
            const val = parseFloat(inputs[factorName] || '0');
            if (!isNaN(val)) {
                y += (coeff as number) * val;
            }
        });
        // Quadratic
        Object.entries(quadratic).forEach(([factorName, coeff]) => {
            const val = parseFloat(inputs[factorName] || '0');
            if (!isNaN(val)) {
                y += (coeff as number) * Math.pow(val, 2);
            }
        });
        // Interactions
        interactions.forEach(term => {
            const val1 = parseFloat(inputs[term.factor1] || '0');
            const val2 = parseFloat(inputs[term.factor2] || '0');
            if (!isNaN(val1) && !isNaN(val2)) {
                y += term.coefficient * val1 * val2;
            }
        });

        // Strict Physical Constraint: Response cannot be negative
        return Math.max(0, y);
    };

    const calculatePrediction = () => {
        const val = calculatePredictionInternal(predictionInputs);
        setPredictedValue(val);
    };

    // Helper to get response unit
    const getResponseUnit = (resName: string) => {
        const r = responses.find(r => r.name === resName);
        return r ? r.unit : '';
    };

    // --- Ternary Plot Logic ---
    useEffect(() => {
        if (!window.Plotly || !results.modelCoefficients || factors.length !== 3) return;

        // Ternary plots are strictly for 3 factors.
        const fA = factors[0];
        const fB = factors[1];
        const fC = factors[2];

        const aPoints = [];
        const bPoints = [];
        const cPoints = [];
        const zPoints = [];

        // Generate simplex grid (Sum = 100 assumed or calculated)
        const total = 100;
        const step = 2; 

        for (let a = 0; a <= total; a += step) {
            for (let b = 0; b <= (total - a); b += step) {
                const c = total - a - b;

                const validA = a >= parseFloat(fA.low) && a <= parseFloat(fA.high);
                const validB = b >= parseFloat(fB.low) && b <= parseFloat(fB.high);
                const validC = c >= parseFloat(fC.low) && c <= parseFloat(fC.high);

                // For visualization, we plot valid points. 
                // We assume predictionInputs for other unrelated factors if any (though mixture usually implies these 3 sum to 1).
                if (validA && validB && validC) {
                    const inputs = {
                        ...predictionInputs,
                        [fA.name]: a.toString(),
                        [fB.name]: b.toString(),
                        [fC.name]: c.toString()
                    };
                    const z = calculatePredictionInternal(inputs);
                    aPoints.push(a);
                    bPoints.push(b);
                    cPoints.push(c);
                    zPoints.push(z);
                }
            }
        }

        const data = [{
            type: 'scatterternary',
            mode: 'markers',
            a: aPoints,
            b: bPoints,
            c: cPoints,
            marker: {
                color: zPoints,
                colorscale: 'Viridis',
                size: 4,
                colorbar: { title: plotResponse, thickness: 20 }
            },
            text: zPoints.map(z => z.toFixed(2)),
            hoverinfo: 'text+a+b+c'
        }];

        const layout = {
            title: `Mixture Contour: ${plotResponse}`,
            ternary: {
                sum: 100,
                aaxis: { title: fA.name, min: parseFloat(fA.low), max: parseFloat(fA.high) },
                baxis: { title: fB.name, min: parseFloat(fB.low), max: parseFloat(fB.high) },
                caxis: { title: fC.name, min: parseFloat(fC.low), max: parseFloat(fC.high) }
            },
            margin: { t: 40, b: 40, l: 40, r: 40 }
        };

        window.Plotly.newPlot('plotTernary', data, layout);

    }, [factors, results.modelCoefficients, plotResponse]);


    // Client-side Surface Generation (Cartesian)
    useEffect(() => {
        if (!window.Plotly || !plotX || !plotY || !results.modelCoefficients) return;

        const factorX = factors.find(f => f.name === plotX);
        const factorY = factors.find(f => f.name === plotY);

        if(!factorX || !factorY) return;

        const xMin = parseFloat(factorX.low);
        const xMax = parseFloat(factorX.high);
        const yMin = parseFloat(factorY.low);
        const yMax = parseFloat(factorY.high);

        const steps = 30; // Increased resolution
        const xValues = [];
        const yValues = [];
        const zMatrix = [];

        // Generate Grid
        for(let i=0; i<=steps; i++) {
             xValues.push(xMin + (i * (xMax - xMin) / steps));
             yValues.push(yMin + (i * (yMax - yMin) / steps));
        }

        for(let j=0; j<=steps; j++) {
            const row = [];
            for(let i=0; i<=steps; i++) {
                // Prepare inputs: varying X and Y, others held constant at predictionInputs
                const inputs = { ...predictionInputs };
                inputs[plotX] = xValues[i].toString();
                inputs[plotY] = yValues[j].toString();

                row.push(calculatePredictionInternal(inputs));
            }
            zMatrix.push(row);
        }

        // 3D Plot
        const surfaceData = [{
            z: zMatrix,
            x: xValues,
            y: yValues,
            type: 'surface',
            contours: {
                z: { show: true, usecolormap: true, highlightcolor: "#42f462", project: { z: true } }
            },
            colorscale: 'Viridis'
        }];
        const layout3d = {
            title: `Surface: ${plotResponse}`,
            autosize: true,
            scene: {
                xaxis: { title: plotX },
                yaxis: { title: plotY },
                zaxis: { title: plotResponse }
            },
            margin: { l: 0, r: 0, b: 0, t: 30 }
        };
        window.Plotly.newPlot('plot3d', surfaceData, layout3d);

        // Contour Plot
        const contourData = [{
            z: zMatrix,
            x: xValues,
            y: yValues,
            type: 'contour',
            colorscale: 'Viridis'
        }];
        const layoutContour = {
            title: `Contour: ${plotResponse}`,
            autosize: true,
            xaxis: { title: plotX },
            yaxis: { title: plotY }
        };
        window.Plotly.newPlot('plotContour', contourData, layoutContour);

    }, [plotX, plotY, plotResponse, results.modelCoefficients, predictionInputs]);

    // Diagnostic Plots
    useEffect(() => {
        if (!window.Plotly || !results.diagnostics) return;
        const diag = results.diagnostics;

         // 1. Predicted vs Run
        const predRunData = [
            { x: diag.runOrder, y: diag.predicted, type: 'scatter', mode: 'lines+markers', name: 'Predicted', line: { color: '#0284c7' } },
            { x: diag.runOrder, y: diag.actual, type: 'scatter', mode: 'markers', name: 'Actual', marker: { color: '#ef4444' } }
        ];
        window.Plotly.newPlot('plotPredVsRun', predRunData, { title: 'Pred vs Actual (Run Order)', margin: { t: 30, b: 30, l: 30, r: 10 } });

        // 2. Residuals vs Run
        const residData = [{ x: diag.runOrder, y: diag.residuals, type: 'scatter', mode: 'markers', marker: { color: '#f59e0b', size: 8 } }];
        window.Plotly.newPlot('plotResidVsRun', residData, { title: 'Residuals vs Run Order', shapes: [{ type: 'line', x0: 0, x1: Math.max(...diag.runOrder)+1, y0: 0, y1: 0, line: { color: 'black', width: 1, dash: 'dot' } }], margin: { t: 30, b: 30, l: 30, r: 10 } });

        // 3. Predicted vs Actual
        const fitData = [
            { x: diag.actual, y: diag.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9' } },
            { x: [Math.min(...diag.actual), Math.max(...diag.actual)], y: [Math.min(...diag.actual), Math.max(...diag.actual)], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' }, name: 'Ideal' }
        ];
        window.Plotly.newPlot('plotPredVsActual', fitData, { title: 'Predicted vs Actual', margin: { t: 30, b: 30, l: 30, r: 10 } });

        // 4. Box-Cox with CI
        if (diag.boxCox) {
            const lambda = diag.boxCox.lambda;
            const lnRSS = diag.boxCox.lnRSS;

            const boxCoxData = [{
                x: lambda,
                y: lnRSS,
                type: 'scatter',
                mode: 'lines',
                line: { shape: 'spline', color: '#8b5cf6', width: 3 },
                name: 'ln(RSS)'
            }];

            const shapes = [];
            const minY = Math.min(...lnRSS);
            const maxY = Math.max(...lnRSS);

            // 95% CI Threshold Line (Horizontal)
            if (diag.boxCox.ciLimit) {
                 shapes.push({
                    type: 'line',
                    x0: Math.min(...lambda),
                    x1: Math.max(...lambda),
                    y0: diag.boxCox.ciLimit,
                    y1: diag.boxCox.ciLimit,
                    line: { color: 'red', width: 2, dash: 'dash' },
                    name: '95% CI Limit'
                 });
            }

            // Low CI Vertical Line
            if (diag.boxCox.lambdaLow !== undefined) {
                 shapes.push({
                    type: 'line',
                    x0: diag.boxCox.lambdaLow,
                    x1: diag.boxCox.lambdaLow,
                    y0: minY,
                    y1: maxY,
                    line: { color: 'red', width: 2 },
                    name: 'Low CI'
                 });
            }

            // High CI Vertical Line
            if (diag.boxCox.lambdaHigh !== undefined) {
                 shapes.push({
                    type: 'line',
                    x0: diag.boxCox.lambdaHigh,
                    x1: diag.boxCox.lambdaHigh,
                    y0: minY,
                    y1: maxY,
                    line: { color: 'red', width: 2 },
                    name: 'High CI'
                 });
            }

            // Best Lambda Vertical Line
            if (diag.boxCox.lambdaBest !== undefined) {
                shapes.push({
                    type: 'line',
                    x0: diag.boxCox.lambdaBest,
                    x1: diag.boxCox.lambdaBest,
                    y0: minY,
                    y1: maxY,
                    line: { color: 'green', width: 1.5, dash: 'dot' },
                    name: 'Best Lambda'
                });
            }

            window.Plotly.newPlot('plotBoxCox', boxCoxData, {
                title: 'Box-Cox Plot',
                xaxis: { title: 'Lambda (λ)' },
                yaxis: { title: 'ln(RSS)' },
                shapes: shapes,
                margin: { t: 30, b: 30, l: 40, r: 10 }
            });
        }
    }, [results.diagnostics]);


    return (
        <div className="space-y-8 pb-12">
            <div className="bg-white p-8 rounded-xl shadow-lg border border-gray-200">
                <h2 className="text-2xl font-bold text-science-900 mb-4 flex items-center gap-2">
                    <LayoutDashboard /> Statistical Analysis (ANOVA)
                </h2>

                {/* Fit Statistics & Equation Section */}
                {results.fitStatistics && (
                    <div className="grid md:grid-cols-3 gap-6 mb-6">
                        <div className="md:col-span-2 bg-gradient-to-r from-science-50 to-white p-4 rounded-lg border border-science-100">
                            <h4 className="text-xs font-bold text-science-600 uppercase mb-2 flex items-center gap-1">
                                <Sigma size={14} /> Regression Equation (Actual Factors)
                            </h4>
                            <p className="font-mono text-gray-800 text-sm leading-relaxed">
                                {results.fitStatistics.equation.replace(/(\+|-)/g, ' $1 ').replace(/\*/g, ' × ')}
                            </p>
                        </div>
                        <div className="bg-white p-4 rounded-lg border border-gray-200">
                            <h4 className="text-xs font-bold text-gray-500 uppercase mb-3">Model Fit Statistics</h4>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <div className="text-[10px] text-gray-400">R²</div>
                                    <div className="text-lg font-bold text-gray-700">{results.fitStatistics.rSquared.toFixed(4)}</div>
                                </div>
                                <div>
                                    <div className="text-[10px] text-gray-400">Adj. R²</div>
                                    <div className="text-lg font-bold text-gray-700">{results.fitStatistics.adjRSquared.toFixed(4)}</div>
                                </div>
                                <div>
                                    <div className="text-[10px] text-science-600 font-bold">Pred. R² (k-fold)</div>
                                    <div className="text-lg font-bold text-science-700">{results.fitStatistics.predictedRSquared.toFixed(4)}</div>
                                </div>
                                <div>
                                    <div className="text-[10px] text-science-600 font-bold">Adeq. Precision</div>
                                    <div className="text-lg font-bold text-science-700">{results.fitStatistics.adequatePrecision.toFixed(2)}</div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                <div className="prose prose-sm max-w-none text-gray-700 bg-slate-50 p-6 rounded border border-slate-200">
                    <ReactMarkdown>{results.anovaText}</ReactMarkdown>
                </div>
            </div>

            {/* Diagnostic Plots */}
            {results.diagnostics && (
                <div className="space-y-4">
                    <h3 className="text-xl font-bold text-gray-800 border-b pb-2 flex items-center gap-2">
                        <Activity size={24} className="text-science-600"/> 
                        Model Diagnostics
                    </h3>
                    <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-4">
                        <div className="flex flex-col bg-white p-2 rounded shadow border border-gray-200">
                            <div className="h-[250px] relative"><div id="plotPredVsActual" className="w-full h-full"></div></div>
                            {results.diagnosticInterpretations && (
                                <p className="text-xs text-gray-500 p-2 italic bg-slate-50 border-t mt-1">
                                    {results.diagnosticInterpretations.predVsActual}
                                </p>
                            )}
                        </div>
                         <div className="flex flex-col bg-white p-2 rounded shadow border border-gray-200">
                            <div className="h-[250px] relative"><div id="plotResidVsRun" className="w-full h-full"></div></div>
                            {results.diagnosticInterpretations && (
                                <p className="text-xs text-gray-500 p-2 italic bg-slate-50 border-t mt-1">
                                    {results.diagnosticInterpretations.residualsVsRun}
                                </p>
                            )}
                        </div>
                        {/* Run Order plot doesn't need comment per prompt, but Box-Cox does */}
                        <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative">
                             <div id="plotPredVsRun" className="w-full h-full"></div>
                        </div>
                         <div className="flex flex-col bg-white p-2 rounded shadow border border-gray-200">
                            <div className="h-[250px] relative"><div id="plotBoxCox" className="w-full h-full"></div></div>
                            {results.diagnosticInterpretations && (
                                <p className="text-xs text-gray-500 p-2 italic bg-slate-50 border-t mt-1">
                                    {results.diagnosticInterpretations.boxCox}
                                </p>
                            )}
                        </div>
                    </div>
                </div>
            )}

            {/* Ternary Plot Section (Only for 3 Factors) */}
            {factors.length === 3 && (
                <div className="bg-white p-6 rounded-xl shadow-lg border border-gray-200">
                     <h3 className="text-xl font-bold text-science-900 mb-4 flex items-center gap-2">
                        <Triangle size={24} /> 
                        Mixture Design (Ternary Plot)
                    </h3>
                    <p className="text-sm text-gray-500 mb-4">Visualizing response across component constraints (A+B+C=100).</p>
                    <div id="plotTernary" className="w-full h-[500px]"></div>
                </div>
            )}

            {/* Surface Plots */}
            <div className="space-y-6">
                <div className="flex justify-between items-center border-b pb-2">
                     <h3 className="text-xl font-bold text-gray-800">Response Surface Exploration</h3>
                </div>

                {/* Controls */}
                <div className="bg-science-50 p-4 rounded-lg flex flex-wrap gap-4 items-center">
                    <div>
                        <label className="block text-xs font-bold text-gray-600">X-Axis</label>
                        <select className="p-2 rounded border" value={plotX} onChange={e => setPlotX(e.target.value)}>
                            {factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-600">Y-Axis</label>
                        <select className="p-2 rounded border" value={plotY} onChange={e => setPlotY(e.target.value)}>
                            {factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}
                        </select>
                    </div>
                    <div>
                         <label className="block text-xs font-bold text-gray-600">Response</label>
                         <select className="p-2 rounded border" value={plotResponse} onChange={e => setPlotResponse(e.target.value)}>
                             {responses.map(r => <option key={r.name} value={r.name}>{r.name}</option>)}
                         </select>
                    </div>
                </div>

                <div className="grid md:grid-cols-2 gap-8">
                    <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                        <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
                            <Cuboid size={18} /> 3D Surface
                        </h3>
                        <div id="plot3d" className="w-full h-[400px]"></div>
                    </div>
                    <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                        <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
                            <Layers size={18} /> Contour
                        </h3>
                        <div id="plotContour" className="w-full h-[400px]"></div>
                    </div>
                </div>
            </div>

            {/* Prediction Simulator */}
            {results.modelCoefficients && (
                <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-lg">
                    <h3 className="text-xl font-bold text-science-900 mb-4 flex items-center gap-2">
                        <Calculator size={24} /> 
                        Predict Outcome Simulator
                    </h3>
                    <div className="grid md:grid-cols-3 gap-6 items-end">
                        {factors.map(f => (
                            <div key={f.name}>
                                <label className="block text-xs font-bold text-science-800 mb-1 uppercase">
                                    {f.name} {f.unit ? `(${f.unit})` : ''}
                                </label>
                                <input 
                                    type="number"
                                    step="any"
                                    className="w-full p-2 border border-science-200 rounded text-sm focus:ring-2 focus:ring-science-500 outline-none"
                                    value={predictionInputs[f.name] || ''}
                                    onChange={(e) => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}
                                />
                            </div>
                        ))}
                    </div>

                    <div className="mt-6 flex items-center gap-6">
                        <button 
                            onClick={calculatePrediction}
                            className="bg-science-600 text-white px-6 py-2 rounded-lg hover:bg-science-700 font-bold flex items-center gap-2 shadow-sm"
                        >
                            <Play size={16} /> Predict Result
                        </button>
                        {predictedValue !== null && (
                            <div className="bg-slate-100 px-6 py-2 rounded-lg border border-slate-300 shadow-sm flex items-center gap-3">
                                <span className="text-xs font-bold text-gray-500 uppercase">Predicted {plotResponse || 'Response'}:</span>
                                <span className="text-2xl font-bold text-science-700">
                                    {predictedValue.toFixed(4)}
                                    <span className="text-sm font-normal text-gray-500 ml-1">{getResponseUnit(plotResponse)}</span>
                                </span>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

