import React, { useState, useEffect } from 'react';
import { DesignRecommendation, AnalysisRequest, ExperimentalRun, AnalysisResult } from '../types';
import { generateDesignMatrix, analyzeExperimentalResults } from '../services/geminiService';
import { FileText, Loader2, BookOpen, AlertTriangle, Beaker, Play } from 'lucide-react';
import DesignVisualizer from './DesignVisualizer';
import RunTable from './RunTable';
import AnalysisDashboard from './AnalysisDashboard';

interface ResultsViewProps {
  recommendation: DesignRecommendation | null;
  request: AnalysisRequest;
  onReset: () => void;
}

const ResultsView: React.FC<ResultsViewProps> = ({ recommendation, request, onReset }) => {
  const [viewState, setViewState] = useState<'PROPOSAL' | 'EXECUTION' | 'ANALYSIS'>('PROPOSAL');
  const [runs, setRuns] = useState<ExperimentalRun[]>([]);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [loading, setLoading] = useState(false);

  // Reset state when the recommended design changes (e.g., manual override)
  useEffect(() => {
    if (recommendation) {
        setViewState('PROPOSAL');
        setRuns([]);
        setAnalysis(null);
    }
  }, [recommendation?.name]); // Use name as dependency key

  if (!recommendation) return null;

  const handleGenerateRuns = async () => {
    setLoading(true);
    const generatedRuns = await generateDesignMatrix(request, recommendation.name);
    setRuns(generatedRuns);
    setViewState('EXECUTION');
    setLoading(false);
  };

  const handleUpdateRun = (runId: number, responseName: string, value: string) => {
      setRuns(prev => prev.map(r => 
          r.id === runId 
          ? { ...r, results: { ...r.results, [responseName]: value } }
          : r
      ));
  };

  const handleAnalyze = async () => {
      setLoading(true);
      const result = await analyzeExperimentalResults(request, recommendation.name, runs);
      setAnalysis(result);
      setViewState('ANALYSIS');
      setLoading(false);
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">

      {/* 1. Scientific Recommendation (Always Visible Summary) */}
      <div className="bg-white rounded-xl shadow-lg overflow-hidden border-t-4 border-science-600">
        <div className="p-6 flex flex-col md:flex-row gap-8 items-start">
            <div className="flex-1">
                <div className="flex items-center gap-2 text-science-600 font-semibold mb-2 text-sm uppercase tracking-wide">
                    <BookOpen size={16} />
                    Scientific Recommendation
                </div>
                <h2 className="text-3xl font-bold text-gray-900 mb-4">
                    {recommendation.name} <span className="text-gray-400 font-normal">({recommendation.acronym})</span>
                </h2>
                <div className="prose text-gray-700 text-sm">
                    <p className="font-medium">{recommendation.reasoning}</p>
                    <p className="text-xs text-gray-400 mt-2 italic border-t pt-2">Source: {recommendation.sourceReference}</p>
                </div>
            </div>
            <div className="w-64 flex-shrink-0 hidden md:block">
                <DesignVisualizer acronym={recommendation.acronym} />
            </div>
        </div>
      </div>

      {/* 2. Proposal State */}
      {viewState === 'PROPOSAL' && (
           <div className="bg-slate-50 rounded-xl border border-slate-200 p-8 text-center">
                <Beaker size={48} className="mx-auto text-science-400 mb-4" />
                <h3 className="text-xl font-bold text-gray-800 mb-2">Ready to Experiment?</h3>
                <p className="text-gray-600 max-w-lg mx-auto mb-6">
                    Based on your <strong>{request.factors.length} factors</strong> and <strong>{request.responses.length} responses</strong>, 
                    we will generate the optimal experimental run table for the {recommendation.name}.
                </p>
                <button
                    onClick={handleGenerateRuns}
                    disabled={loading}
                    className="bg-science-600 text-white px-8 py-3 rounded-lg hover:bg-science-700 disabled:opacity-50 flex items-center gap-2 mx-auto text-lg font-bold shadow-lg shadow-science-200 transition-all"
                >
                    {loading ? <Loader2 className="animate-spin" /> : <Play size={20} />}
                    {loading ? 'Designing Matrix...' : 'Generate Run Table'}
                </button>
           </div>
      )}

      {/* 3. Execution State (The Lab Notebook) */}
      {(viewState === 'EXECUTION' || viewState === 'ANALYSIS') && (
          <div className="space-y-4">
              <div className="flex justify-between items-end">
                 <h3 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                    <FileText className="text-science-600" /> Experimental Protocol & Data
                 </h3>
                 {viewState === 'EXECUTION' && (
                     <button 
                        onClick={handleAnalyze}
                        disabled={loading}
                        className="bg-green-600 text-white px-6 py-2 rounded shadow hover:bg-green-700 flex items-center gap-2"
                     >
                        {loading ? <Loader2 className="animate-spin" size={18}/> : null}
                        Analyze Results
                     </button>
                 )}
              </div>

              <RunTable 
                  runs={runs} 
                  factors={request.factors} 
                  responses={request.responses} 
                  onUpdateRun={handleUpdateRun} 
              />

              <p className="text-sm text-gray-500 italic text-right">
                  * Enter your experimental results in the yellow columns above.
              </p>
          </div>
      )}

      {/* 4. Analysis State */}
      {viewState === 'ANALYSIS' && analysis && (
          <div className="animate-fade-in border-t-2 border-gray-200 pt-8">
              <AnalysisDashboard results={analysis} factors={request.factors} responses={request.responses} />
          </div>
      )}

      <div className="flex justify-center pt-8">
        <button
          onClick={onReset}
          className="text-science-600 hover:text-science-800 font-medium underline underline-offset-4"
        >
          Start New Analysis
        </button>
      </div>
    </div>
  );
};

export default ResultsView;

import { GoogleGenAI } from "@google/genai";
import { AnalysisRequest, ExperimentalRun, AnalysisResult } from "../types";

const getClient = () => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        throw new Error("API Key not found in process.env.API_KEY");
    }
    return new GoogleGenAI({ apiKey });
};

// Returns just the runs array structure
export const generateDesignMatrix = async (request: AnalysisRequest, designName: string): Promise<ExperimentalRun[]> => {
    try {
        const ai = getClient();
        const factorDesc = request.factors.map(f => `${f.name} (${f.levels} levels: ${f.low} to ${f.high})`).join(', ');

        const isMixture = designName.toLowerCase().includes('mixture') || designName.toLowerCase().includes('simplex');
        const mixtureInstruction = isMixture 
            ? "CRITICAL: This is a Mixture Design. The sum of the values of all factors in each run MUST equal exactly 100. Adjust the values within the specified ranges to satisfy this constraint." 
            : "";

        const prompt = `
        Generate a Design of Experiments (DoE) matrix for a "${designName}".
        Factors: ${factorDesc}.
        ${mixtureInstruction}

        Return STRICTLY JSON format. An array of objects.
        Each object should have:
        - "id" (number, starting at 1)
        - "factors" (object where keys are factor names and values are numbers).

        Do not output any markdown code blocks. Just the raw JSON string.
        Ensure real-world values are used based on the ranges provided, not coded values.
        Generate a reasonable number of runs for this design (e.g., 8-15 for small factorial/BBD/CCD).
        Include center points if standard for this design.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 0 }
            }
        });

        const text = response.text || "[]";
        // Clean markdown if present
        const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
        const runs = JSON.parse(jsonStr);

        // Map to internal structure ensuring results object exists
        return runs.map((r: any) => ({
            id: r.id,
            factors: r.factors,
            results: {} 
        }));

    } catch (e) {
        console.error("Design Matrix Error", e);
        return [];
    }
};

export const analyzeExperimentalResults = async (
    request: AnalysisRequest, 
    designName: string, 
    runs: ExperimentalRun[]
): Promise<AnalysisResult> => {
    const ai = getClient();

    // Prepare data for AI
    const dataStr = JSON.stringify(runs.map(r => ({ ...r.factors, ...r.results })));
    const responseNames = request.responses.map(r => r.name).join(', ');
    const factorNames = JSON.stringify(request.factors.map(f => f.name));

    const prompt = `
    Perform a statistical analysis on the following formulation experiment results.
    Design: ${designName}.
    Responses: ${responseNames}.
    Data: ${dataStr}.

    Task 1: ANOVA & Interpretations (Markdown)
    - **CRITICAL**: Include the general mathematical equation used to calculate the total number of runs (N) for this design.
    - Provide an ANOVA table summary.
    - Identify significant terms (p < 0.05).
    - Discuss model fit.

    Task 2: Visualization, Statistics, & Prediction Data (JSON)
    - Return a JSON object inside a distinct block separated by "|||JSON_DATA|||".
    - **Equation Styling**: The "equation" field must be PLAIN TEXT. Do NOT use LaTeX. Do NOT use '$', '\\beta', '\\cdot', or underscores. Use '*' for multiplication. Example: "Y = 5.2 + 3.1 * FactorA + 2.5 * FactorB^2".
    - **Physical Constraints**: The model must be physically realistic. Responses (CQAs) cannot be negative. Ensure the coefficients generated do not produce negative values within the design space. The predicted values should generally lie within the range of the observed data, avoiding extreme extrapolation hallucinations.
    - **Statistics**: Calculate 'Predicted R-squared' (using PRESS/k-fold validation concept) and 'Adequate Precision' (Signal-to-noise ratio).
    - **Accuracy**: The "modelCoefficients" object MUST correspond EXACTLY to the "equation". The simulator depends on this object.
       - Use these EXACT factor names as keys: ${factorNames}.
       - For Mixture designs: Intercept is often 0 (Scheffe canonical form). Put component coefficients in "linear" and interaction terms in "interactions". Avoid pure quadratic terms (e.g. A^2) for mixtures if possible.
       - For Interactions: Use strict "factor1", "factor2" structure.

    - Structure:
      {
         "fitStatistics": {
             "rSquared": number,
             "adjRSquared": number,
             "predictedRSquared": number,
             "adequatePrecision": number,
             "equation": "string"
         },
         "diagnosticInterpretations": {
            "predVsActual": "Comment on the alignment of points along the diagonal line. Is the prediction accurate?",
            "residualsVsRun": "Comment on the randomness of residuals. Are there any trends or outliers?",
            "boxCox": "Comment on the position of the best lambda inside the confidence interval. Is transformation needed?"
         },
         "plotData": [], // Leave empty, handled by client
         "diagnostics": {
             "runOrder": [1, 2, 3...],
             "actual": [number...],
             "predicted": [number...],
             "residuals": [number...],
             "boxCox": {
                 "lambda": [-3, -2.5, ..., 3],
                 "lnRSS": [number...],
                 "ciLimit": number,
                 "lambdaBest": number,
                 "lambdaLow": number,
                 "lambdaHigh": number
             }
         },
         "modelCoefficients": {
             "intercept": number,
             "linear": { "FactorName1": coeff },
             "quadratic": { "FactorName1": coeff },
             "interactions": [ { "factor1": "FactorName1", "factor2": "FactorName2", "coefficient": number } ]
         }
      }
    `;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { thinkingConfig: { thinkingBudget: 0 } }
    });

    const fullText = response.text || "";
    const parts = fullText.split("|||JSON_DATA|||");

    let anovaText = parts[0];
    let plotData = [];
    let diagnostics;
    let modelCoefficients;
    let fitStatistics;
    let diagnosticInterpretations;

    if (parts[1]) {
        try {
            const jsonStr = parts[1].replace(/```json/g, '').replace(/```/g, '').trim();
            const data = JSON.parse(jsonStr);
            plotData = data.plotData || [];
            diagnostics = data.diagnostics;
            modelCoefficients = data.modelCoefficients;
            fitStatistics = data.fitStatistics;
            diagnosticInterpretations = data.diagnosticInterpretations;
        } catch (e) {
            console.error("Error parsing plot data", e);
        }
    }

    return { anovaText, plotData, diagnostics, modelCoefficients, fitStatistics, diagnosticInterpretations };
};

