export default ResultsView;

import React, { useState } from 'react';
import { ExperimentalRun, FactorDefinition, ResponseDefinition } from '../types';
import { ClipboardCopy, ClipboardPaste, Check } from 'lucide-react';

interface RunTableProps {
    runs: ExperimentalRun[];
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
    onUpdateRun: (runId: number, responseName: string, value: string) => void;
    onBulkUpdate: (updates: { runId: number, responseName: string, value: string }[]) => void;
}

const RunTable: React.FC<RunTableProps> = ({ runs, factors, responses, onUpdateRun, onBulkUpdate }) => {
    const [copied, setCopied] = useState(false);

    const handleCopy = () => {
        // Header
        const headers = ['Run #', ...factors.map(f => f.name), ...responses.map(r => r.name)].join('\t');
        // Rows
        const rows = runs.map(r => {
            const fVals = factors.map(f => r.factors[f.name]);
            const rVals = responses.map(res => r.results[res.name] || '');
            return [r.id, ...fVals, ...rVals].join('\t');
        }).join('\n');

        navigator.clipboard.writeText(`${headers}\n${rows}`);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    const handlePaste = async () => {
        try {
            const text = await navigator.clipboard.readText();
            processPaste(text);
        } catch (err) {
            console.error("Paste failed", err);
            alert("Could not read clipboard automatically. Please click inside a cell and use Ctrl+V/Cmd+V to paste data.");
        }
    };

    const processPaste = (text: string, startRunIndex = -1, startResponseIndex = -1) => {
        const rows = text.trim().split(/\r\n|\n|\r/);
        if (rows.length === 0) return;

        // Detect if headers are present in the first row
        const firstRowCols = rows[0].split('\t');
        const hasHeader = responses.some(r => firstRowCols.includes(r.name)) || factors.some(f => firstRowCols.includes(f.name));

        const dataRows = hasHeader ? rows.slice(1) : rows;
        const updates: any[] = [];

        // Determine starting run index (if pasting from a button, start at 0, else start at cell)
        const effectiveStartRun = startRunIndex === -1 ? 0 : startRunIndex;

        dataRows.forEach((rowStr, i) => {
            const targetRunIndex = effectiveStartRun + i;
            if (targetRunIndex >= runs.length) return;

            const targetRunId = runs[targetRunIndex].id;
            const cols = rowStr.split('\t');

            // Strategy 1: Cell-based paste (user pasted into a specific input)
            if (startResponseIndex !== -1) {
                cols.forEach((val, colIndex) => {
                    const targetResIndex = startResponseIndex + colIndex;
                    if (targetResIndex < responses.length) {
                        updates.push({
                            runId: targetRunId,
                            responseName: responses[targetResIndex].name,
                            value: val.trim()
                        });
                    }
                });
            } 
            // Strategy 2: Whole table paste (from button)
            else {
                 const totalCols = 1 + factors.length + responses.length; // ID + Factors + Responses

                 if (cols.length >= totalCols - 1) { // Fuzzy match full table
                     // Assume last N columns are responses
                     responses.forEach((res, rIdx) => {
                         // Get value from the end of the columns array
                         const val = cols[cols.length - responses.length + rIdx];
                         if (val !== undefined) {
                             updates.push({ runId: targetRunId, responseName: res.name, value: val.trim() });
                         }
                     });
                 } else {
                     // Fallback: Assume the pasted data is just Response data columns
                      cols.forEach((val, cIdx) => {
                          if (cIdx < responses.length) {
                               updates.push({ runId: targetRunId, responseName: responses[cIdx].name, value: val.trim() });
                          }
                      });
                 }
            }
        });

        if (updates.length > 0) {
            onBulkUpdate(updates);
        }
    };

    const handleCellPaste = (e: React.ClipboardEvent, runIndex: number, resIndex: number) => {
        const text = e.clipboardData.getData('text');
        // If it contains newlines or tabs, handle as bulk paste
        if (text.includes('\n') || text.includes('\t')) {
            e.preventDefault();
            processPaste(text, runIndex, resIndex);
        }
    };

    return (
        <div className="space-y-2">
            <div className="flex justify-end gap-2">
                <button 
                    onClick={handleCopy}
                    className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-science-700 bg-science-50 border border-science-200 rounded hover:bg-science-100 transition-colors"
                >
                    {copied ? <Check size={14} /> : <ClipboardCopy size={14} />}
                    {copied ? 'Copied!' : 'Copy Table'}
                </button>
                <button 
                    onClick={handlePaste}
                    className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-gray-700 bg-gray-50 border border-gray-200 rounded hover:bg-gray-100 transition-colors"
                >
                    <ClipboardPaste size={14} />
                    Paste Data
                </button>
            </div>

            <div className="overflow-x-auto border border-gray-200 rounded-lg shadow-sm">
                <table className="w-full text-sm text-left text-gray-700">
                    <thead className="text-xs text-gray-700 uppercase bg-science-50 border-b border-science-100">
                        <tr>
                            <th className="px-4 py-3 border-r">Run #</th>
                            {/* Factors */}
                            {factors.map((f, i) => (
                                <th key={`f-${i}`} className="px-4 py-3 bg-slate-100 text-slate-700 border-r">
                                    {f.name} {f.unit ? `(${f.unit})` : ''}
                                </th>
                            ))}
                            {/* Responses */}
                            {responses.map((r, i) => (
                                <th key={`r-${i}`} className="px-4 py-3 bg-yellow-50 text-yellow-800 border-r border-yellow-100">
                                    {r.name} ({r.unit})
                                    <span className="block text-[10px] lowercase font-normal">Enter Result</span>
                                </th>
                            ))}
                        </tr>
                    </thead>
                    <tbody>
                        {runs.map((run, runIndex) => (
                            <tr key={run.id} className="border-b border-gray-100 hover:bg-gray-50">
                                <td className="px-4 py-3 font-bold border-r">{run.id}</td>

                                {/* Factor Values (Read Only) */}
                                {factors.map((f) => (
                                    <td key={`fv-${f.name}`} className="px-4 py-3 border-r text-gray-600 select-all">
                                        {run.factors[f.name]}
                                    </td>
                                ))}

                                {/* Response Inputs */}
                                {responses.map((r, resIndex) => (
                                    <td key={`rv-${r.name}`} className="px-2 py-2 border-r bg-yellow-50/30">
                                        <input 
                                            type="number" 
                                            step="any"
                                            className="w-full p-2 border border-yellow-200 rounded focus:border-science-500 focus:ring-1 focus:ring-science-500 bg-white"
                                            placeholder="---"
                                            value={run.results[r.name] || ''}
                                            onChange={(e) => onUpdateRun(run.id, r.name, e.target.value)}
                                            onPaste={(e) => handleCellPaste(e, runIndex, resIndex)}
                                        />
                                    </td>
                                ))}
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

