import React, { useState } from 'react';
import { ExperimentalRun, FactorDefinition, ResponseDefinition } from '../types';
import { ClipboardCopy, ClipboardPaste, Check, Table } from 'lucide-react';

interface RunTableProps {
    runs: ExperimentalRun[];
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
    onUpdateRun: (runId: number, responseName: string, value: string) => void;
    onBulkUpdate: (updates: { runId: number, responseName: string, value: string }[]) => void;
}

const RunTable: React.FC<RunTableProps> = ({ runs, factors, responses, onUpdateRun, onBulkUpdate }) => {
    const [copied, setCopied] = useState(false);

    const handleCopy = () => {
        // Header
        const headers = ['Run #', ...factors.map(f => f.name), ...responses.map(r => r.name)].join('\t');
        // Rows
        const rows = runs.map(r => {
            const fVals = factors.map(f => r.factors[f.name]);
            const rVals = responses.map(res => r.results[res.name] || '');
            return [r.id, ...fVals, ...rVals].join('\t');
        }).join('\n');

        navigator.clipboard.writeText(`${headers}\n${rows}`);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    const handlePaste = async () => {
        try {
            const text = await navigator.clipboard.readText();
            processPaste(text);
        } catch (err) {
            console.error("Paste failed", err);
            alert("Could not read clipboard automatically. Please click inside a cell and use Ctrl+V/Cmd+V to paste data.");
        }
    };

    const normalize = (s: string) => s.trim().toLowerCase();

    const processPaste = (text: string, startRunIndex = -1, startResponseIndex = -1) => {
        const rows = text.trim().split(/\r\n|\n|\r/).filter(r => r.trim() !== '');
        if (rows.length === 0) return;

        const firstRowCols = rows[0].split('\t');
        const headerMap: Record<string, number> = {};
        firstRowCols.forEach((col, i) => headerMap[normalize(col)] = i);

        // Check for headers matching schema
        const responseNames = responses.map(r => normalize(r.name));
        const factorNames = factors.map(f => normalize(f.name));

        const hasKnownHeaders = responseNames.some(r => headerMap[r] !== undefined) || 
                                factorNames.some(f => headerMap[f] !== undefined) ||
                                headerMap['run #'] !== undefined || headerMap['id'] !== undefined;

        const updates: any[] = [];

        // SCENARIO 1: Structured Paste (Headers Detected)
        if (hasKnownHeaders) {
            // Assume first row is header, process subsequent rows
            const dataRows = rows.slice(1);

            // Try to find ID column
            const idColIdx = headerMap['run #'] !== undefined ? headerMap['run #'] : headerMap['id'];

            dataRows.forEach((row, idx) => {
                const cols = row.split('\t');
                let runId = -1;

                // Match by ID if possible
                if (idColIdx !== undefined && cols[idColIdx]) {
                    const parsedId = parseInt(cols[idColIdx]);
                    if (!isNaN(parsedId)) runId = parsedId;
                } 

                // Fallback to sequential match if ID missing or invalid
                if (runId === -1) {
                    const rowIndex = startRunIndex !== -1 ? startRunIndex + idx : idx;
                    if (rowIndex < runs.length) runId = runs[rowIndex].id;
                }

                if (runId !== -1) {
                    responses.forEach(res => {
                        const key = normalize(res.name);
                        const colIdx = headerMap[key];
                        if (colIdx !== undefined && cols[colIdx] !== undefined) {
                            const val = cols[colIdx].trim();
                            // Only update if value is not empty (preserve existing data if pasting partials)
                            if (val !== '') {
                                updates.push({ runId, responseName: res.name, value: val });
                            }
                        }
                    });
                }
            });
        } 
        // SCENARIO 2: Unstructured Data Paste
        else {
            const effectiveStartRun = startRunIndex === -1 ? 0 : startRunIndex;

            rows.forEach((row, i) => {
                const targetRunIndex = effectiveStartRun + i;
                if (targetRunIndex >= runs.length) return;

                const targetRunId = runs[targetRunIndex].id;
                const cols = row.split('\t');

                // If user selected a specific cell, paste relative to it
                if (startResponseIndex !== -1) {
                    cols.forEach((val, cIdx) => {
                        const targetResIndex = startResponseIndex + cIdx;
                        if (targetResIndex < responses.length) {
                             updates.push({ 
                                 runId: targetRunId, 
                                 responseName: responses[targetResIndex].name, 
                                 value: val.trim() 
                             });
                        }
                    });
                } 
                // Global paste (via button) without headers
                else {
                    // Heuristic: Does it look like a full table (ID + Factors + Responses)?
                    const expectedCols = 1 + factors.length + responses.length;

                    if (cols.length >= expectedCols - 1) { // Fuzzy match
                         // Assume last N columns are responses
                         responses.forEach((res, rIdx) => {
                             const val = cols[cols.length - responses.length + rIdx];
                             if (val) updates.push({ runId: targetRunId, responseName: res.name, value: val.trim() });
                         });
                    } else {
                        // Assume it's just response data
                        responses.forEach((res, rIdx) => {
                            if (cols[rIdx]) {
                                updates.push({ runId: targetRunId, responseName: res.name, value: cols[rIdx].trim() });
                            }
                        });
                    }
                }
            });
        }

        if (updates.length > 0) {
            onBulkUpdate(updates);
        }
    };

    const handleCellPaste = (e: React.ClipboardEvent, runIndex: number, resIndex: number) => {
        const text = e.clipboardData.getData('text');
        // If multiline or tabbed, treat as bulk paste
        if (text.includes('\n') || text.includes('\t')) {
            e.preventDefault();
            processPaste(text, runIndex, resIndex);
        }
    };

    return (
        <div className="space-y-3">
            <div className="flex justify-between items-center bg-science-50 p-2 rounded-lg border border-science-100">
                <div className="text-xs text-science-800 flex items-center gap-2 px-2">
                    <Table size={16}/>
                    <span className="font-semibold">Results Data Entry</span>
                </div>
                <div className="flex gap-2">
                    <button 
                        onClick={handleCopy}
                        className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-science-700 bg-white border border-science-200 rounded hover:bg-science-50 transition-colors shadow-sm"
                        title="Copy table to clipboard for Excel"
                    >
                        {copied ? <Check size={14} /> : <ClipboardCopy size={14} />}
                        {copied ? 'Copied!' : 'Copy Table'}
                    </button>
                    <button 
                        onClick={handlePaste}
                        className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-gray-700 bg-white border border-gray-200 rounded hover:bg-gray-50 transition-colors shadow-sm"
                        title="Paste data from Excel (Auto-detects structure)"
                    >
                        <ClipboardPaste size={14} />
                        Paste Data
                    </button>
                </div>
            </div>

            <div className="overflow-x-auto border border-gray-200 rounded-lg shadow-sm">
                <table className="w-full text-sm text-left text-gray-700">
                    <thead className="text-xs text-gray-700 uppercase bg-gray-50 border-b border-gray-200">
                        <tr>
                            <th className="px-4 py-3 border-r w-16">Run #</th>
                            {/* Factors */}
                            {factors.map((f, i) => (
                                <th key={`f-${i}`} className="px-4 py-3 bg-slate-50 text-slate-700 border-r">
                                    {f.name} <span className="text-slate-400 normal-case">{f.unit ? `(${f.unit})` : ''}</span>
                                </th>
                            ))}
                            {/* Responses */}
                            {responses.map((r, i) => (
                                <th key={`r-${i}`} className="px-4 py-3 bg-yellow-50 text-yellow-800 border-r border-yellow-100 min-w-[120px]">
                                    <div className="flex flex-col">
                                        <span>{r.name}</span>
                                        <span className="text-[10px] lowercase font-normal text-yellow-600">{r.unit || 'value'}</span>
                                    </div>
                                </th>
                            ))}
                        </tr>
                    </thead>
                    <tbody>
                        {runs.map((run, runIndex) => (
                            <tr key={run.id} className="border-b border-gray-100 hover:bg-gray-50 transition-colors">
                                <td className="px-4 py-3 font-bold border-r text-gray-500 bg-gray-50/50">{run.id}</td>

                                {/* Factor Values (Read Only) */}
                                {factors.map((f) => (
                                    <td key={`fv-${f.name}`} className="px-4 py-3 border-r text-gray-600 select-all bg-slate-50/30">
                                        {run.factors[f.name]}
                                    </td>
                                ))}

                                {/* Response Inputs */}
                                {responses.map((r, resIndex) => (
                                    <td key={`rv-${r.name}`} className="px-0 py-0 border-r bg-yellow-50/30 relative">
                                        <input 
                                            type="number" 
                                            step="any"
                                            className="w-full h-full min-h-[40px] px-4 py-2 bg-transparent focus:bg-white focus:ring-2 focus:ring-inset focus:ring-science-500 outline-none transition-all"
                                            placeholder="-"
                                            value={run.results[r.name] || ''}
                                            onChange={(e) => onUpdateRun(run.id, r.name, e.target.value)}
                                            onPaste={(e) => handleCellPaste(e, runIndex, resIndex)}
                                        />
                                    </td>
                                ))}
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
            <div className="text-xs text-gray-400 text-right mt-1">
                Tip: You can copy the table, edit in Excel, and paste it back using the buttons above.
            </div>
        </div>
    );
};

