import React, { useState, useEffect } from 'react';
import { DesignRecommendation, AnalysisRequest, ExperimentalRun, AnalysisResult } from '../types';
import { generateDesignMatrix, analyzeExperimentalResults } from '../services/geminiService';
import { FileText, Loader2, BookOpen, AlertTriangle, Beaker, Play } from 'lucide-react';
import DesignVisualizer from './DesignVisualizer';
import RunTable from './RunTable';
import AnalysisDashboard from './AnalysisDashboard';

interface ResultsViewProps {
  recommendation: DesignRecommendation | null;
  request: AnalysisRequest;
  onReset: () => void;
}

const ResultsView: React.FC<ResultsViewProps> = ({ recommendation, request, onReset }) => {
  const [viewState, setViewState] = useState<'PROPOSAL' | 'EXECUTION' | 'ANALYSIS'>('PROPOSAL');
  const [runs, setRuns] = useState<ExperimentalRun[]>([]);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [loading, setLoading] = useState(false);

  // Reset state when the recommended design changes (e.g., manual override)
  useEffect(() => {
    if (recommendation) {
        setViewState('PROPOSAL');
        setRuns([]);
        setAnalysis(null);
    }
  }, [recommendation?.name]); // Use name as dependency key

  if (!recommendation) return null;

  const handleGenerateRuns = async () => {
    setLoading(true);
    const generatedRuns = await generateDesignMatrix(request, recommendation.name);
    setRuns(generatedRuns);
    setViewState('EXECUTION');
    setLoading(false);
  };

  const handleUpdateCell = (runId: number, type: 'factor' | 'response', name: string, value: string) => {
      setRuns(prev => prev.map(r => {
          if (r.id !== runId) return r;

          if (type === 'factor') {
              const numVal = parseFloat(value);
              // Allow updating if number, otherwise ignore or handle appropriately
              // For UX, we might want to allow empty string during edit, but 'factors' is Record<string, number>
              // We'll update if valid or empty (treated as 0 or handled by component state if separated)
              // Here we stick to updating only if valid number to satisfy the Type.
              return !isNaN(numVal) 
                  ? { ...r, factors: { ...r.factors, [name]: numVal } } 
                  : r;
          } else {
              return { ...r, results: { ...r.results, [name]: value } };
          }
      }));
  };

  const handleBulkUpdate = (updates: { runId: number, type: 'factor' | 'response', name: string, value: string }[]) => {
      setRuns(prev => {
          const newRuns = [...prev];
          updates.forEach(u => {
              const runIndex = newRuns.findIndex(r => r.id === u.runId);
              if (runIndex !== -1) {
                  if (u.type === 'factor') {
                       const numVal = parseFloat(u.value);
                       if (!isNaN(numVal)) {
                           newRuns[runIndex] = {
                               ...newRuns[runIndex],
                               factors: {
                                   ...newRuns[runIndex].factors,
                                   [u.name]: numVal
                               }
                           };
                       }
                  } else {
                      newRuns[runIndex] = {
                          ...newRuns[runIndex],
                          results: {
                              ...newRuns[runIndex].results,
                              [u.name]: u.value
                          }
                      };
                  }
              }
          });
          return newRuns;
      });
  };

  const handleAnalyze = async () => {
      setLoading(true);
      const result = await analyzeExperimentalResults(request, recommendation.name, runs);
      setAnalysis(result);
      setViewState('ANALYSIS');
      setLoading(false);
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">

      {/* 1. Scientific Recommendation (Always Visible Summary) */}
      <div className="bg-white rounded-xl shadow-lg overflow-hidden border-t-4 border-science-600">
        <div className="p-6 flex flex-col md:flex-row gap-8 items-start">
            <div className="flex-1">
                <div className="flex items-center gap-2 text-science-600 font-semibold mb-2 text-sm uppercase tracking-wide">
                    <BookOpen size={16} />
                    Scientific Recommendation
                </div>
                <h2 className="text-3xl font-bold text-gray-900 mb-4">
                    {recommendation.name} <span className="text-gray-400 font-normal">({recommendation.acronym})</span>
                </h2>
                <div className="prose text-gray-700 text-sm">
                    <p className="font-medium">{recommendation.reasoning}</p>
                    <p className="text-xs text-gray-400 mt-2 italic border-t pt-2">Source: {recommendation.sourceReference}</p>
                </div>
            </div>
            <div className="w-64 flex-shrink-0 hidden md:block">
                <DesignVisualizer acronym={recommendation.acronym} />
            </div>
        </div>
      </div>

      {/* 2. Proposal State */}
      {viewState === 'PROPOSAL' && (
           <div className="bg-slate-50 rounded-xl border border-slate-200 p-8 text-center">
                <Beaker size={48} className="mx-auto text-science-400 mb-4" />
                <h3 className="text-xl font-bold text-gray-800 mb-2">Ready to Experiment?</h3>
                <p className="text-gray-600 max-w-lg mx-auto mb-6">
                    Based on your <strong>{request.factors.length} factors</strong> and <strong>{request.responses.length} responses</strong>, 
                    we will generate the optimal experimental run table for the {recommendation.name}.
                </p>
                <button
                    onClick={handleGenerateRuns}
                    disabled={loading}
                    className="bg-science-600 text-white px-8 py-3 rounded-lg hover:bg-science-700 disabled:opacity-50 flex items-center gap-2 mx-auto text-lg font-bold shadow-lg shadow-science-200 transition-all"
                >
                    {loading ? <Loader2 className="animate-spin" /> : <Play size={20} />}
                    {loading ? 'Designing Matrix...' : 'Generate Run Table'}
                </button>
           </div>
      )}

      {/* 3. Execution State (The Lab Notebook) */}
      {(viewState === 'EXECUTION' || viewState === 'ANALYSIS') && (
          <div className="space-y-4">
              <div className="flex justify-between items-end">
                 <h3 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                    <FileText className="text-science-600" /> Experimental Protocol & Data
                 </h3>
                 {viewState === 'EXECUTION' && (
                     <button 
                        onClick={handleAnalyze}
                        disabled={loading}
                        className="bg-green-600 text-white px-6 py-2 rounded shadow hover:bg-green-700 flex items-center gap-2"
                     >
                        {loading ? <Loader2 className="animate-spin" size={18}/> : null}
                        Analyze Results
                     </button>
                 )}
              </div>

              <RunTable 
                  runs={runs} 
                  factors={request.factors} 
                  responses={request.responses} 
                  onUpdateCell={handleUpdateCell} 
                  onBulkUpdate={handleBulkUpdate}
              />

              <p className="text-sm text-gray-500 italic text-right">
                  * Enter your experimental results in the yellow columns above. You can also edit Factor settings if actual values differed. 
                  Use Copy/Paste to import full tables from Excel.
              </p>
          </div>
      )}

      {/* 4. Analysis State */}
      {viewState === 'ANALYSIS' && analysis && (
          <div className="animate-fade-in border-t-2 border-gray-200 pt-8">
              <AnalysisDashboard results={analysis} factors={request.factors} responses={request.responses} />
          </div>
      )}

      <div className="flex justify-center pt-8">
        <button
          onClick={onReset}
          className="text-science-600 hover:text-science-800 font-medium underline underline-offset-4"
        >
          Start New Analysis
        </button>
      </div>
    </div>
  );
};

export default ResultsView;

import React, { useState } from 'react';
import { ExperimentalRun, FactorDefinition, ResponseDefinition } from '../types';
import { ClipboardCopy, ClipboardPaste, Check, Table, X } from 'lucide-react';

interface RunTableProps {
    runs: ExperimentalRun[];
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
    onUpdateCell: (runId: number, type: 'factor' | 'response', name: string, value: string) => void;
    onBulkUpdate: (updates: { runId: number, type: 'factor' | 'response', name: string, value: string }[]) => void;
}

const RunTable: React.FC<RunTableProps> = ({ runs, factors, responses, onUpdateCell, onBulkUpdate }) => {
    const [copied, setCopied] = useState(false);
    const [showPasteModal, setShowPasteModal] = useState(false);
    const [manualPasteData, setManualPasteData] = useState('');

    const handleCopy = () => {
        // Header
        const headers = ['Run #', ...factors.map(f => f.name), ...responses.map(r => r.name)].join('\t');
        // Rows
        const rows = runs.map(r => {
            const fVals = factors.map(f => r.factors[f.name]);
            const rVals = responses.map(res => r.results[res.name] || '');
            return [r.id, ...fVals, ...rVals].join('\t');
        }).join('\n');

        navigator.clipboard.writeText(`${headers}\n${rows}`);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    const handlePaste = async () => {
        try {
            const text = await navigator.clipboard.readText();
            processPaste(text);
        } catch (err) {
            console.warn("Clipboard API blocked, falling back to manual paste.", err);
            setShowPasteModal(true);
        }
    };

    const handleManualPasteSubmit = () => {
        if (manualPasteData.trim()) {
            processPaste(manualPasteData);
        }
        setShowPasteModal(false);
        setManualPasteData('');
    };

    const normalize = (s: string) => s.trim().toLowerCase();

    const processPaste = (text: string) => {
        const rows = text.trim().split(/\r\n|\n|\r/).filter(r => r.trim() !== '');
        if (rows.length === 0) return;

        const firstRowCols = rows[0].split('\t');
        const headerMap: Record<string, number> = {};
        firstRowCols.forEach((col, i) => headerMap[normalize(col)] = i);

        // Check for headers matching schema
        const responseNames = responses.map(r => normalize(r.name));
        const factorNames = factors.map(f => normalize(f.name));

        const hasKnownHeaders = responseNames.some(r => headerMap[r] !== undefined) || 
                                factorNames.some(f => headerMap[f] !== undefined) ||
                                headerMap['run #'] !== undefined || headerMap['id'] !== undefined;

        const updates: { runId: number, type: 'factor' | 'response', name: string, value: string }[] = [];

        // SCENARIO 1: Structured Paste (Headers Detected)
        if (hasKnownHeaders) {
            const dataRows = rows.slice(1);
            const idColIdx = headerMap['run #'] !== undefined ? headerMap['run #'] : headerMap['id'];

            dataRows.forEach((row, idx) => {
                const cols = row.split('\t');
                let runId = -1;

                // Match by ID
                if (idColIdx !== undefined && cols[idColIdx]) {
                    const parsedId = parseInt(cols[idColIdx]);
                    if (!isNaN(parsedId)) runId = parsedId;
                } 

                // Fallback to sequential
                if (runId === -1 && idx < runs.length) {
                    runId = runs[idx].id;
                }

                if (runId !== -1) {
                    // Update Factors
                    factors.forEach(f => {
                        const key = normalize(f.name);
                        const colIdx = headerMap[key];
                        if (colIdx !== undefined && cols[colIdx] !== undefined) {
                             const val = cols[colIdx].trim();
                             if (val !== '') updates.push({ runId, type: 'factor', name: f.name, value: val });
                        }
                    });

                    // Update Responses
                    responses.forEach(res => {
                        const key = normalize(res.name);
                        const colIdx = headerMap[key];
                        if (colIdx !== undefined && cols[colIdx] !== undefined) {
                            const val = cols[colIdx].trim();
                            if (val !== '') updates.push({ runId, type: 'response', name: res.name, value: val });
                        }
                    });
                }
            });
        } 
        // SCENARIO 2: Unstructured Data Paste (Assuming just responses, or try to infer)
        else {
             // For safety in unstructured paste, we prioritize just pasting RESULTS if headers aren't clear
             // Or if column count matches exactly.
             const totalExpected = 1 + factors.length + responses.length;

             rows.forEach((row, i) => {
                 if (i >= runs.length) return;
                 const runId = runs[i].id;
                 const cols = row.split('\t');

                 // If columns roughly match full table
                 if (cols.length >= totalExpected - 1) {
                     // Assume order: ID, Factor1...FactorN, Response1...ResponseM
                     // factors start at index 1 (after ID)
                     factors.forEach((f, fIdx) => {
                         const val = cols[fIdx + 1]; // +1 for ID skip
                         if (val) updates.push({ runId, type: 'factor', name: f.name, value: val.trim() });
                     });

                     // responses start after factors
                     const resStart = 1 + factors.length;
                     responses.forEach((r, rIdx) => {
                         const val = cols[resStart + rIdx];
                         if (val) updates.push({ runId, type: 'response', name: r.name, value: val.trim() });
                     });
                 } else {
                     // Assume just responses
                     responses.forEach((r, rIdx) => {
                         const val = cols[rIdx];
                         if (val) updates.push({ runId, type: 'response', name: r.name, value: val.trim() });
                     });
                 }
             });
        }

        if (updates.length > 0) {
            onBulkUpdate(updates);
        }
    };

    return (
        <div className="space-y-3">
            <div className="flex justify-between items-center bg-science-50 p-2 rounded-lg border border-science-100">
                <div className="text-xs text-science-800 flex items-center gap-2 px-2">
                    <Table size={16}/>
                    <span className="font-semibold">Results Data Entry</span>
                </div>
                <div className="flex gap-2">
                    <button 
                        onClick={handleCopy}
                        className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-science-700 bg-white border border-science-200 rounded hover:bg-science-50 transition-colors shadow-sm"
                        title="Copy table to clipboard for Excel"
                    >
                        {copied ? <Check size={14} /> : <ClipboardCopy size={14} />}
                        {copied ? 'Copied!' : 'Copy Table'}
                    </button>
                    <button 
                        onClick={handlePaste}
                        className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-gray-700 bg-white border border-gray-200 rounded hover:bg-gray-50 transition-colors shadow-sm"
                        title="Paste data from Excel"
                    >
                        <ClipboardPaste size={14} />
                        Paste Data
                    </button>
                </div>
            </div>

            <div className="overflow-x-auto border border-gray-200 rounded-lg shadow-sm">
                <table className="w-full text-sm text-left text-gray-700">
                    <thead className="text-xs text-gray-700 uppercase bg-gray-50 border-b border-gray-200">
                        <tr>
                            <th className="px-4 py-3 border-r w-16">Run #</th>
                            {/* Factors */}
                            {factors.map((f, i) => (
                                <th key={`f-${i}`} className="px-2 py-3 bg-slate-50 text-slate-700 border-r min-w-[100px]">
                                    {f.name} <span className="text-slate-400 normal-case">{f.unit ? `(${f.unit})` : ''}</span>
                                </th>
                            ))}
                            {/* Responses */}
                            {responses.map((r, i) => (
                                <th key={`r-${i}`} className="px-2 py-3 bg-yellow-50 text-yellow-800 border-r border-yellow-100 min-w-[100px]">
                                    <div className="flex flex-col">
                                        <span>{r.name}</span>
                                        <span className="text-[10px] lowercase font-normal text-yellow-600">{r.unit || 'value'}</span>
                                    </div>
                                </th>
                            ))}
                        </tr>
                    </thead>
                    <tbody>
                        {runs.map((run) => (
                            <tr key={run.id} className="border-b border-gray-100 hover:bg-gray-50 transition-colors">
                                <td className="px-4 py-3 font-bold border-r text-gray-500 bg-gray-50/50">{run.id}</td>

                                {/* Factor Inputs */}
                                {factors.map((f) => (
