    <description>Cast value 'v' to number in Object.entries loop to fix TypeScript error</description>
    <content><![CDATA[import React, { useEffect, useState, useCallback } from 'react';
import { AnalysisResult, FactorDefinition, ResponseDefinition } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, TrendingUp, BarChart2, Calculator, Play, Sigma, Triangle, Trophy, Target, ArrowDown } from 'react-feather';
import { findOptimalConditions } from '../utils/analysis-utils';
import { OptResult, trialInput, TrialInput } from '../types';
import './AnalysisDashboard.css';
import { useGeminiService } from '../services/geminiService';

interface AnalysisDashboardProps {
  results: AnalysisResult | null;
  factorDefinitions: FactorDefinition[];
  responseDefinitions: ResponseDefinition[];
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factorDefinitions, responseDefinitions }) => {
  const [topSuggestions, setTopSuggestions] = useState<OptResult[]>([]);
  const [loading, setLoading] = useState(false);
  const { generateDesignMatrix } = useGeminiService();

  useEffect(() => {
    if (results && factorDefinitions.length > 0 && responseDefinitions.length > 0) {
      const fetchSuggestions = async () => {
        setLoading(true);
        try {
          const suggestions = await generateDesignMatrix(results, factorDefinitions, responseDefinitions);
          if (suggestions) {
            setTopSuggestions(suggestions);
          }
        } catch (error) {
          console.error("Error fetching suggestions:", error);
        } finally {
          setLoading(false);
        }
      };

      fetchSuggestions();
    }
