// Returns just the runs array structure
export const generateDesignMatrix = async (request: AnalysisRequest, designName: string): Promise<ExperimentalRun[]> => {
    try {
        const ai = getClient();
        const factorDesc = request.factors.map(f => `${f.name} (${f.levels} levels: ${f.low} to ${f.high})`).join(', ');

        const isMixture = designName.toLowerCase().includes('mixture') || designName.toLowerCase().includes('simplex');

        // STRICT PROMPT INSTRUCTION FOR MIXTURE
        const mixtureInstruction = isMixture 
            ? `CRITICAL MIXTURE CONSTRAINT: This is a Mixture Design. The sum of all factor values in EVERY SINGLE RUN MUST be exactly 100. 
               Formula: Sum(${request.factors.map(f => f.name).join(', ')}) = 100.
               You MUST normalize the values to ensure they sum to 100 while respecting the relative low/high constraints as much as possible.
               Do not produce runs where the sum differs from 100.` 
            : "";

        const prompt = `
        Generate a Design of Experiments (DoE) matrix for a "${designName}".
        Factors: ${factorDesc}.

        STRICT CONFIGURATION:
        - Design Replicates: ${request.replicates} (Repeat the base design points this many times).
        - Center Points: ${request.centerPoints} (Add this many runs at the center of the domain or centroid).

        ${mixtureInstruction}

        CRITICAL RULES:
        1. Identify the standard base runs (N) determined by the design equation for ${request.factors.length} factors (e.g., 2^k, 2k+2, etc.).
        2. Multiply these base runs by ${request.replicates}.
        3. Append exactly ${request.centerPoints} center point runs.
        4. The output array must have length = (Base * ${request.replicates}) + ${request.centerPoints}.
        ${isMixture ? "5. VERIFY: Check that for every object in the array, the sum of values in 'factors' is exactly 100." : ""}

        Return STRICTLY JSON format. An array of objects.
        Each object should have:
        - "id" (number, starting at 1)
        - "factors" (object where keys are factor names and values are numbers).

        Do not output any markdown code blocks. Just the raw JSON string.
        Ensure real-world values are used based on the ranges provided, not coded values.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 0 }
            }
        });

        const text = response.text || "[]";
        // Clean markdown if present
        const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
        let runs = JSON.parse(jsonStr);

        // POST-PROCESSING ENFORCEMENT for Mixture Designs
        // We programmatically force the sum to 100 to account for any LLM rounding errors or hallucinations
        if (isMixture) {
            runs = runs.map((r: any) => {
                const factors = r.factors;
                const keys = Object.keys(factors);
                const sum = keys.reduce((acc, k) => acc + (parseFloat(factors[k]) || 0), 0);

                // If sum deviates from 100 by more than epsilon, normalize it
                if (Math.abs(sum - 100) > 0.05) {
                    const newFactors: any = {};
                    let newSum = 0;
                    let maxKey = keys[0];
                    let maxVal = -1;

                    keys.forEach(k => {
                        const val = parseFloat(factors[k]) || 0;
                        const norm = (val / sum) * 100;
                        const rounded = parseFloat(norm.toFixed(2));
                        newFactors[k] = rounded;
                        newSum += rounded;

                        // Track largest value to dump rounding error into
                        if (rounded > maxVal) {
                            maxVal = rounded;
                            maxKey = k;
                        }
                    });

                    // Fix small rounding error to ensure exact 100
                    const diff = 100 - newSum;
                    if (Math.abs(diff) > 0.001) {
                        newFactors[maxKey] = parseFloat((newFactors[maxKey] + diff).toFixed(2));
                    }
                    return { ...r, factors: newFactors };
                }
                return r;
            });
        }

        // Map to internal structure ensuring results object exists
        return runs.map((r: any) => ({
            id: r.id,
            factors: r.factors,
            results: {} 
        }));

    } catch (e) {
        console.error("Design Matrix Error", e);
        return [];
    }
};

