import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisRequest, ExperimentalRun, AnalysisResult } from "../types";

const getClient = () => {
    let apiKey = '';
    // Safely check for process.env in browser environments
    if (typeof process !== 'undefined' && process.env) {
        apiKey = process.env.API_KEY || '';
    }

    if (!apiKey) {
        console.warn("API Key not found. Please ensure process.env.API_KEY is configured.");
        // In a real app we might throw, but for preventing 'Script error' crashes we return a dummy client or throw a clear error.
        // Throwing a clear error is better than a ReferenceError.
        throw new Error("API Key is missing. Please check your configuration.");
    }
    return new GoogleGenAI({ apiKey });
};

// Returns just the runs array structure
export const generateDesignMatrix = async (request: AnalysisRequest, designName: string): Promise<ExperimentalRun[]> => {
    try {
        const ai = getClient();
        const factorDesc = request.factors.map(f => `${f.name} (${f.levels} levels: ${f.low} to ${f.high})`).join(', ');

        const isMixture = designName.toLowerCase().includes('mixture') || designName.toLowerCase().includes('simplex');

        // STRICT PROMPT INSTRUCTION FOR MIXTURE
        const mixtureInstruction = isMixture 
            ? `CRITICAL MIXTURE CONSTRAINT: This is a Mixture Design. The sum of all factor values in EVERY SINGLE RUN MUST be exactly 100. 
               Formula: Sum(${request.factors.map(f => f.name).join(', ')}) = 100.
               You MUST normalize the values to ensure they sum to 100 while respecting the relative low/high constraints as much as possible.
               Do not produce runs where the sum differs from 100.` 
            : "";

        const prompt = `
        Generate a Design of Experiments (DoE) matrix for a "${designName}".
        Factors: ${factorDesc}.

        STRICT CONFIGURATION:
        - Design Replicates: ${request.replicates} (Repeat the base design points this many times).
        - Center Points: ${request.centerPoints} (Add this many runs at the center of the domain or centroid).

        ${mixtureInstruction}

        CRITICAL RULES:
        1. Identify the standard base runs (N) determined by the design equation for ${request.factors.length} factors (e.g., 2^k, 2k+2, etc.).
        2. Multiply these base runs by ${request.replicates}.
        3. Append exactly ${request.centerPoints} center point runs.
        4. The output array must have length = (Base * ${request.replicates}) + ${request.centerPoints}.
        ${isMixture ? "5. VERIFY: Check that for every object in the array, the sum of values in 'factors' is exactly 100." : ""}

        Return STRICTLY JSON format. An array of objects.
        Each object should have:
        - "id" (number, starting at 1)
        - "factors" (object where keys are factor names and values are numbers).

        Do not output any markdown code blocks. Just the raw JSON string.
        Ensure real-world values are used based on the ranges provided, not coded values.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 0 }
            }
        });

        const text = response.text || "[]";
        // Clean markdown if present
        const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
        let runs = JSON.parse(jsonStr);

        // POST-PROCESSING ENFORCEMENT for Mixture Designs
        // We programmatically force the sum to 100 to account for any LLM rounding errors or hallucinations
        if (isMixture) {
            runs = runs.map((r: any) => {
                const factors = r.factors;
                if (!factors || typeof factors !== 'object') return r;

                const keys = Object.keys(factors);
                // Safety: if no factors defined, skip
                if (keys.length === 0) return r;

                const sum = keys.reduce((acc, k) => {
                    const val = parseFloat(factors[k]);
                    return acc + (isNaN(val) ? 0 : val);
                }, 0);

                // If sum deviates from 100 by more than epsilon, normalize it
                if (Math.abs(sum - 100) > 0.05 && sum !== 0) {
                    const newFactors: any = {};
                    let newSum = 0;
                    let maxKey = keys[0];
                    let maxVal = -1;

                    keys.forEach(k => {
                        const val = parseFloat(factors[k]) || 0;
                        const norm = (val / sum) * 100;
                        const rounded = parseFloat(norm.toFixed(2));
                        newFactors[k] = rounded;
                        newSum += rounded;

                        // Track largest value to dump rounding error into
                        if (rounded > maxVal) {
                            maxVal = rounded;
                            maxKey = k;
                        }
                    });

                    // Fix small rounding error to ensure exact 100
                    const diff = 100 - newSum;
                    if (Math.abs(diff) > 0.001) {
                        newFactors[maxKey] = parseFloat((newFactors[maxKey] + diff).toFixed(2));
                    }
                    return { ...r, factors: newFactors };
                }
                return r;
            });
        }

        // Map to internal structure ensuring results object exists
        return runs.map((r: any) => ({
            id: r.id,
            factors: r.factors,
            results: {} 
        }));

    } catch (e) {
        console.error("Design Matrix Error", e);
        return [];
    }
};

export const analyzeExperimentalResults = async (
    request: AnalysisRequest, 
    designName: string, 
    runs: ExperimentalRun[]
): Promise<AnalysisResult> => {
    try {
        const ai = getClient();
        const dataStr = JSON.stringify(runs.map(r => ({ ...r.factors, ...r.results })));
        const responseNames = request.responses.map(r => r.name).join(', ');

        const prompt = `
        Perform a statistical analysis on the formulation experiment.
        Design: ${designName}.
        Responses: ${responseNames}.
        Data: ${dataStr}.

        Goal: Provide ANOVA, scientific interpretation, and structured data for plots.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        anova_markdown: { type: Type.STRING, description: "Detailed Markdown report including ANOVA table and interpretation." },
                        fit_statistics: {
                            type: Type.OBJECT,
                            properties: {
                                r_squared: { type: Type.NUMBER },
                                adj_r_squared: { type: Type.NUMBER },
                                predicted_r_squared: { type: Type.NUMBER },
                                adequate_precision: { type: Type.NUMBER },
                                equation: { type: Type.STRING },
                            }
                        },
                        model_coefficients: {
                            type: Type.OBJECT,
                            properties: {
                                intercept: { type: Type.NUMBER },
                                linear_terms: { 
                                    type: Type.ARRAY, 
                                    items: { type: Type.OBJECT, properties: { factor: { type: Type.STRING }, coef: { type: Type.NUMBER } } } 
                                },
                                quadratic_terms: { 
                                    type: Type.ARRAY, 
                                    items: { type: Type.OBJECT, properties: { factor: { type: Type.STRING }, coef: { type: Type.NUMBER } } } 
                                },
                                interaction_terms: { 
                                    type: Type.ARRAY, 
                                    items: { type: Type.OBJECT, properties: { factor1: { type: Type.STRING }, factor2: { type: Type.STRING }, coef: { type: Type.NUMBER } } } 
                                }
                            }
                        },
                        diagnostics: {
                            type: Type.OBJECT,
                            properties: {
                                run_order: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                                actual: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                                predicted: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                                residuals: { type: Type.ARRAY, items: { type: Type.NUMBER } }
                            }
                        }
                    },
                    required: ["anova_markdown", "fit_statistics", "model_coefficients", "diagnostics"]
                }
            }
        });

        const json = JSON.parse(response.text || "{}");

        // Transform coefficients from array to record to match application types
        const linear: Record<string, number> = {};
        if (json.model_coefficients?.linear_terms) {
            json.model_coefficients.linear_terms.forEach((t: any) => {
                if(t.factor && t.coef !== undefined) linear[t.factor] = t.coef;
            });
        }

        const quadratic: Record<string, number> = {};
        if (json.model_coefficients?.quadratic_terms) {
            json.model_coefficients.quadratic_terms.forEach((t: any) => {
                if(t.factor && t.coef !== undefined) quadratic[t.factor] = t.coef;
            });
        }

        const interactions = json.model_coefficients?.interaction_terms?.map((t: any) => ({
            factor1: t.factor1,
            factor2: t.factor2,
            coefficient: t.coef
        })) || [];

        return {
            anovaText: json.anova_markdown || "Analysis generation failed or incomplete.",
            fitStatistics: {
                rSquared: json.fit_statistics?.r_squared || 0,
                adjRSquared: json.fit_statistics?.adj_r_squared || 0,
                predictedRSquared: json.fit_statistics?.predicted_r_squared || 0,
                adequatePrecision: json.fit_statistics?.adequate_precision || 0,
                equation: json.fit_statistics?.equation || ""
            },
            modelCoefficients: {
                intercept: json.model_coefficients?.intercept || 0,
                linear,
                quadratic,
                interactions
            },
            diagnostics: {
                runOrder: json.diagnostics?.run_order || [],
                actual: json.diagnostics?.actual || [],
                predicted: json.diagnostics?.predicted || [],
                residuals: json.diagnostics?.residuals || [],
                boxCox: { lambda: [], lnRSS: [] } 
            },
            plotData: [] // Plots handled client-side via coefficients
        };

    } catch (e) {
        console.error("Analysis Error", e);
        // Return a dummy error result instead of crashing
        return {
            anovaText: `### Analysis Error\n\nAn error occurred while generating the analysis: ${e instanceof Error ? e.message : String(e)}. \n\nPlease verify your API Key and ensure the input data is valid.`,
            plotData: [],
            diagnostics: { runOrder: [], actual: [], predicted: [], residuals: [] },
            modelCoefficients: { intercept: 0, linear: {}, quadratic: {}, interactions: [] }
        };
    }
};

