import React, { useEffect, useState, useCallback } from 'react';
import { AnalysisResult, FactorDefinition, ResponseDefinition } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, Calculator, Play, Sigma, Triangle, Trophy, Target, Search } from 'lucide-react';

declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
    isMixture?: boolean;
}

interface OptResult {
    factors: Record<string, number>;
    prediction: number;
    desirability: number;
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses, isMixture = false }) => {
    // Prediction State
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);

    // Plot Configuration State
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');

    // Optimization State
    const [optGoal, setOptGoal] = useState<'Maximize' | 'Minimize' | 'Target'>('Maximize');
    const [optTarget, setOptTarget] = useState<number>(0);
    const [optMin, setOptMin] = useState<number>(0);
    const [optMax, setOptMax] = useState<number>(100);
    const [topSuggestions, setTopSuggestions] = useState<OptResult[]>([]);

    // Initialize inputs and plot defaults
    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = isNaN(mid) ? "0" : mid.toString();
        });
        setPredictionInputs(initial);

        if (factors.length >= 2) {
            setPlotX(factors[0].name);
            setPlotY(factors[1].name);
        }
        if (responses.length > 0) {
            setPlotResponse(responses[0].name);
        }
    }, [factors, responses]);

    // Helper: Get Range with safety check for empty data
    const getObservedRange = useCallback((resName: string) => {
        if (!results.diagnostics || !results.diagnostics.actual || results.diagnostics.actual.length === 0) {
            return { min: 0, max: 100 };
        }
        // Filter out NaNs just in case
        const cleanData = results.diagnostics.actual.filter(v => typeof v === 'number' && !isNaN(v));
        if (cleanData.length === 0) return { min: 0, max: 100 };

        let min = Math.min(...cleanData);
        let max = Math.max(...cleanData);

        if (!isFinite(min)) min = 0;
        if (!isFinite(max)) max = 100;

        if (Math.abs(max - min) < 1e-9) {
            return { min: min - 1, max: max + 1 };
        }
        return { min, max };
    }, [results]);

    // Initialize Optimization Defaults when response changes
    useEffect(() => {
        const range = getObservedRange(plotResponse);
        setOptMin(range.min);
        setOptMax(range.max);
        setOptTarget((range.min + range.max) / 2);

        const resDef = responses.find(r => r.name === plotResponse);
        if (resDef) setOptGoal(resDef.goal);
    }, [plotResponse, getObservedRange, responses]);


    // Helper: Convert Real Value to Coded Value (-1 to +1)
    const toCoded = (val: number, factorName: string) => {
        const factor = factors.find(f => f.name === factorName);
        if (!factor) return 0;

        const low = parseFloat(factor.low);
        const high = parseFloat(factor.high);

        if (isNaN(low) || isNaN(high)) return 0;

        const mid = (high + low) / 2;
        const halfRange = (high - low) / 2;

        if (halfRange === 0) return 0;
        return (val - mid) / halfRange;
    };

    const calculatePredictionInternal = (inputs: Record<string, string | number>) => {
         if (!results.modelCoefficients) return 0;

        const { intercept, linear, quadratic, interactions } = results.modelCoefficients;
        // Ensure intercept is a number
        let y = typeof intercept === 'number' ? intercept : parseFloat(intercept as any) || 0;

        // Linear
        if (linear) {
            Object.entries(linear).forEach(([factorName, coeff]) => {
                const val = inputs[factorName];
                const realVal = typeof val === 'string' ? parseFloat(val) : val;
                const c = typeof coeff === 'number' ? coeff : parseFloat(coeff as any) || 0;

                if (typeof realVal === 'number' && !isNaN(realVal)) {
                    const codedVal = toCoded(realVal, factorName);
                    y += c * codedVal;
                }
            });
        }
        // Quadratic
        if (quadratic) {
            Object.entries(quadratic).forEach(([factorName, coeff]) => {
                const val = inputs[factorName];
                const realVal = typeof val === 'string' ? parseFloat(val) : val;
                const c = typeof coeff === 'number' ? coeff : parseFloat(coeff as any) || 0;

                if (typeof realVal === 'number' && !isNaN(realVal)) {
                    const codedVal = toCoded(realVal, factorName);
                    y += c * Math.pow(codedVal, 2);
                }
            });
        }
        // Interactions
        if (interactions && Array.isArray(interactions)) {
            interactions.forEach(term => {
                const v1 = inputs[term.factor1];
                const v2 = inputs[term.factor2];
                const realVal1 = typeof v1 === 'string' ? parseFloat(v1) : v1;
                const realVal2 = typeof v2 === 'string' ? parseFloat(v2) : v2;
                const c = typeof term.coefficient === 'number' ? term.coefficient : parseFloat(term.coefficient as any) || 0;

                if (typeof realVal1 === 'number' && !isNaN(realVal1) && typeof realVal2 === 'number' && !isNaN(realVal2)) {
                    const codedVal1 = toCoded(realVal1, term.factor1);
                    const codedVal2 = toCoded(realVal2, term.factor2);
                    y += c * codedVal1 * codedVal2;
                }
            });
        }

        return y;
    };

    const calculatePrediction = () => {
        const val = calculatePredictionInternal(predictionInputs);
        setPredictedValue(val);
    };

    const calculateDesirability = (val: number) => {
        if (isNaN(val) || !isFinite(val)) return 0;

        const range = optMax - optMin;
        if (range === 0) return 0;

        if (optGoal === 'Maximize') {
            if (val <= optMin) return 0;
            if (val >= optMax) return 1;
            return (val - optMin) / range;
        } else if (optGoal === 'Minimize') {
            if (val <= optMin) return 1;
            if (val >= optMax) return 0;
            return (optMax - val) / range;
        } else {
            // Target
            if (val < optMin || val > optMax) return 0;
            if (val === optTarget) return 1;

            const lowerRange = optTarget - optMin;
            const upperRange = optMax - optTarget;

            if (val < optTarget) {
                return lowerRange === 0 ? 0 : (val - optMin) / lowerRange;
            } else {
                return upperRange === 0 ? 0 : (optMax - val) / upperRange;
            }
        }
    };

    const findOptimalConditions = () => {
        const iterations = 5000;
        const suggestions: OptResult[] = [];

        for (let i = 0; i < iterations; i++) {
            const trialInputs: Record<string, number> = {};
            factors.forEach(f => {
                const min = parseFloat(f.low);
                const max = parseFloat(f.high);
                if (!isNaN(min) && !isNaN(max)) {
                     trialInputs[f.name] = min + Math.random() * (max - min);
                } else {
                    trialInputs[f.name] = 0;
                }
            });

            const pred = calculatePredictionInternal(trialInputs);
            const d = calculateDesirability(pred);
            if (!isNaN(pred) && !isNaN(d)) {
                suggestions.push({ factors: trialInputs, prediction: pred, desirability: d });
            }
        }

        suggestions.sort((a, b) => b.desirability - a.desirability);

        const uniqueTop: OptResult[] = [];
        for (const s of suggestions) {
            if (uniqueTop.length >= 3) break;
            const isDuplicate = uniqueTop.some(existing => {
                return factors.every(f => {
                    const low = parseFloat(f.low);
                    const high = parseFloat(f.high);
                    const range = Math.abs(high - low) || 1;
                    return Math.abs(existing.factors[f.name] - s.factors[f.name]) < (range * 0.05);
                });
            });
            if (!isDuplicate) uniqueTop.push(s);
        }

        setTopSuggestions(uniqueTop);
    };


    const getResponseUnit = (resName: string) => {
        const r = responses.find(r => r.name === resName);
        return r ? r.unit : '';
    };

    // --- Ternary Plot Logic ---
    useEffect(() => {
        // Only run if it's a mixture design and has 3 factors
        if (!isMixture || factors.length !== 3) return;

        let cleanup = false;
        try {
            if (!window.Plotly || !results.modelCoefficients) return;

            const fA = factors[0];
            const fB = factors[1];
            const fC = factors[2];
            const divId = 'plotTernary';

            const aPoints: number[] = [], bPoints: number[] = [], cPoints: number[] = [], zPoints: number[] = [];
            const total = 100, step = 2; 

            for (let a = 0; a <= total; a += step) {
                for (let b = 0; b <= (total - a); b += step) {
                    const c = total - a - b;
                    const lowA = parseFloat(fA.low), highA = parseFloat(fA.high);
                    // Use relaxed check for boundaries to allow plotting near edges
                    if (!isNaN(lowA) && !isNaN(highA)) {
                        const inputs = {
                            ...predictionInputs,
                            [fA.name]: a.toString(),
                            [fB.name]: b.toString(),
                            [fC.name]: c.toString()
                        };
                        const z = calculatePredictionInternal(inputs);
                        if (!isNaN(z)) {
                            aPoints.push(a);
                            bPoints.push(b);
                            cPoints.push(c);
                            zPoints.push(z);
                        }
                    }
                }
            }

            if (zPoints.length === 0) return;
            if (cleanup) return;

            const observed = getObservedRange(plotResponse);
            const data = [{
                type: 'scatterternary',
                mode: 'markers',
                a: aPoints, b: bPoints, c: cPoints,
                marker: {
                    color: zPoints, colorscale: 'Viridis', size: 4,
                    cmin: observed.min, cmax: observed.max,
                    colorbar: { title: plotResponse, thickness: 20 }
                },
                text: zPoints.map(z => z.toFixed(2)),
                hoverinfo: 'text+a+b+c'
            }];

            const layout = {
                title: `Mixture Contour: ${plotResponse}`,
                ternary: {
                    sum: 100,
                    aaxis: { title: fA.name, min: parseFloat(fA.low) || 0, max: parseFloat(fA.high) || 100 },
                    baxis: { title: fB.name, min: parseFloat(fB.low) || 0, max: parseFloat(fB.high) || 100 },
                    caxis: { title: fC.name, min: parseFloat(fC.low) || 0, max: parseFloat(fC.high) || 100 }
                },
                margin: { t: 40, b: 40, l: 40, r: 40 }
            };

            if (document.getElementById(divId)) {
                window.Plotly.react(divId, data, layout);
            }
        } catch (e) {
            console.error("Ternary Plot Error", e);
        }

        return () => {
            cleanup = true;
            try {
                if (document.getElementById('plotTernary')) window.Plotly.purge('plotTernary');
            } catch(e) {}
        };
    }, [factors, results.modelCoefficients, plotResponse, getObservedRange, predictionInputs, isMixture]);


    // Client-side Surface Generation (Cartesian & Desirability)
    useEffect(() => {
        let cleanup = false;
        try {
            if (!window.Plotly || !plotX || !plotY || !results.modelCoefficients) return;

            const factorX = factors.find(f => f.name === plotX);
            const factorY = factors.find(f => f.name === plotY);

            if(!factorX || !factorY) return;

            const xMin = parseFloat(factorX.low);
            const xMax = parseFloat(factorX.high);
            const yMin = parseFloat(factorY.low);
            const yMax = parseFloat(factorY.high);

            if(isNaN(xMin) || isNaN(xMax) || isNaN(yMin) || isNaN(yMax)) return;

            const steps = 30; 
            const xValues: number[] = [], yValues: number[] = [];
            const zMatrix: number[][] = [], dMatrix: number[][] = [];

            for(let i=0; i<=steps; i++) xValues.push(xMin + (i * (xMax - xMin) / steps));
            for(let i=0; i<=steps; i++) yValues.push(yMin + (i * (yMax - yMin) / steps));

            for(let j=0; j<=steps; j++) {
                const rowZ: number[] = [], rowD: number[] = [];
                for(let i=0; i<=steps; i++) {
                    const inputs: Record<string, string | number> = { ...predictionInputs };
                    inputs[plotX] = xValues[i];
                    inputs[plotY] = yValues[j];

                    const pred = calculatePredictionInternal(inputs);
                    const des = calculateDesirability(pred);

                    rowZ.push(isNaN(pred) ? 0 : pred);
                    rowD.push(isNaN(des) ? 0 : des);
                }
                zMatrix.push(rowZ);
                dMatrix.push(rowD);
            }

            if(cleanup) return;

            const observed = getObservedRange(plotResponse);
            const zRange = [observed.min, observed.max];

            // 3D Plot
            const surfaceData = [{
                z: zMatrix, x: xValues, y: yValues,
                type: 'surface', cmin: zRange[0], cmax: zRange[1],
                contours: { z: { show: true, usecolormap: true, highlightcolor: "#42f462", project: { z: true } } },
                colorscale: 'Viridis'
            }];
            const layout3d = {
                title: `Surface: ${plotResponse}`, autosize: true,
                scene: { xaxis: { title: plotX }, yaxis: { title: plotY }, zaxis: { title: plotResponse, range: zRange } },
                margin: { l: 0, r: 0, b: 0, t: 30 }
            };
            if (document.getElementById('plot3d')) window.Plotly.react('plot3d', surfaceData, layout3d);

            // Contour Plot
            const contourData = [{
                z: zMatrix, x: xValues, y: yValues,
                type: 'contour', colorscale: 'Viridis', cmin: zRange[0], cmax: zRange[1],
                contours: { start: zRange[0], end: zRange[1] }
            }];
            const layoutContour = { title: `Contour: ${plotResponse}`, autosize: true, xaxis: { title: plotX }, yaxis: { title: plotY } };
            if (document.getElementById('plotContour')) window.Plotly.react('plotContour', contourData, layoutContour);

            // Desirability Contour
            const desData = [{
                z: dMatrix, x: xValues, y: yValues,
                type: 'contour', colorscale: 'Jet', cmin: 0, cmax: 1,
                contours: { start: 0, end: 1, size: 0.1 }
            }];
            const layoutDes = { title: `Desirability (Goal: ${optGoal})`, autosize: true, xaxis: { title: plotX }, yaxis: { title: plotY } };
            if (document.getElementById('plotDesirability')) window.Plotly.react('plotDesirability', desData, layoutDes);

        } catch (e) {
            console.error("Surface Plot Error", e);
        }

        return () => {
            cleanup = true;
            try {
                if (document.getElementById('plot3d')) window.Plotly.purge('plot3d');
                if (document.getElementById('plotContour')) window.Plotly.purge('plotContour');
                if (document.getElementById('plotDesirability')) window.Plotly.purge('plotDesirability');
            } catch(e) {}
        };

    }, [plotX, plotY, plotResponse, results.modelCoefficients, predictionInputs, optGoal, optMin, optMax, optTarget]);

    // Diagnostic Plots (Run Order, Box-Cox, etc)
    useEffect(() => {
        let cleanup = false;
        try {
            if (!window.Plotly || !results.diagnostics) return;
            const diag = results.diagnostics;

            if (!diag.runOrder || !diag.actual || !diag.predicted || !diag.residuals) return;
            // Ensure no NaNs
            if (diag.actual.some(isNaN) || diag.predicted.some(isNaN)) return;
            if(cleanup) return;

            // 1. Predicted vs Actual
            const actualMin = Math.min(...diag.actual);
            const actualMax = Math.max(...diag.actual);
            const fitData = [
                { x: diag.actual, y: diag.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9' } },
                { x: [actualMin, actualMax], y: [actualMin, actualMax], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' }, name: 'Ideal' }
            ];
            if (document.getElementById('plotPredVsActual')) window.Plotly.react('plotPredVsActual', fitData, { title: 'Predicted vs Actual', margin: { t: 30, b: 30, l: 30, r: 10 } });

            // 2. Residuals vs Run Order
            const residData = [{ x: diag.runOrder, y: diag.residuals, type: 'scatter', mode: 'markers', marker: { color: '#f59e0b', size: 8 } }];
            if (document.getElementById('plotResidVsRun')) window.Plotly.react('plotResidVsRun', residData, { title: 'Residuals vs Run Order', shapes: [{ type: 'line', x0: 0, x1: Math.max(...diag.runOrder, 1)+1, y0: 0, y1: 0, line: { color: 'black', width: 1, dash: 'dot' } }], margin: { t: 30, b: 30, l: 30, r: 10 } });

            // 3. Predicted vs Run Order
            const predRunData = [
                { x: diag.runOrder, y: diag.predicted, type: 'scatter', mode: 'lines+markers', name: 'Predicted', line: { color: '#0284c7' } },
                { x: diag.runOrder, y: diag.actual, type: 'scatter', mode: 'markers', name: 'Actual', marker: { color: '#ef4444' } }
            ];
            if (document.getElementById('plotPredVsRun')) window.Plotly.react('plotPredVsRun', predRunData, { title: 'Pred vs Actual (Run Order)', margin: { t: 30, b: 30, l: 30, r: 10 } });

            // 4. Box-Cox Plot
            if (diag.boxCox && diag.boxCox.lambda && diag.boxCox.lambda.length > 0) {
                 const boxCoxData = [{ x: diag.boxCox.lambda, y: diag.boxCox.lnRSS, type: 'scatter', mode: 'lines', line: { shape: 'spline', color: '#8b5cf6', width: 3 }, name: 'ln(RSS)' }];
                 const shapes = [];

                 // Add CI Limit line (Red horizontal)
                 if (diag.boxCox.ciLimit !== undefined) {
                    const minLambda = Math.min(...diag.boxCox.lambda);
                    const maxLambda = Math.max(...diag.boxCox.lambda);
                    shapes.push({ 
                        type: 'line', x0: minLambda, x1: maxLambda, y0: diag.boxCox.ciLimit, y1: diag.boxCox.ciLimit, 
                        line: { color: 'red', width: 2, dash: 'dash' } 
                    });
                 }

                 // Add Lambda Interval lines if available (Red vertical)
                 if (diag.boxCox.lambdaLow !== undefined && diag.boxCox.lambdaHigh !== undefined) {
                     const minRSS = Math.min(...diag.boxCox.lnRSS);
                     const maxRSS = Math.max(...diag.boxCox.lnRSS);
                     shapes.push({ type: 'line', x0: diag.boxCox.lambdaLow, x1: diag.boxCox.lambdaLow, y0: minRSS, y1: maxRSS, line: { color: 'red', width: 1, dash: 'dot' } });
                     shapes.push({ type: 'line', x0: diag.boxCox.lambdaHigh, x1: diag.boxCox.lambdaHigh, y0: minRSS, y1: maxRSS, line: { color: 'red', width: 1, dash: 'dot' } });
                 }

                 if (document.getElementById('plotBoxCox')) {
                    window.Plotly.react('plotBoxCox', boxCoxData, { 
                        title: 'Box-Cox Plot (Power Transform)', 
                        xaxis: { title: 'Lambda (λ)' }, 
                        yaxis: { title: 'ln(RSS)' }, 
                        shapes: shapes, 
                        margin: { t: 30, b: 30, l: 40, r: 10 } 
                    });
                 }
            }
        } catch (e) {
            console.error("Diagnostic Plot Error", e);
        }

        return () => {
            cleanup = true;
            try {
                if (document.getElementById('plotPredVsActual')) window.Plotly.purge('plotPredVsActual');
                if (document.getElementById('plotResidVsRun')) window.Plotly.purge('plotResidVsRun');
                if (document.getElementById('plotPredVsRun')) window.Plotly.purge('plotPredVsRun');
                if (document.getElementById('plotBoxCox')) window.Plotly.purge('plotBoxCox');
            } catch(e) {}
        };
    }, [results.diagnostics]);


    return (
        <div className="space-y-8 pb-12">
            {/* Top Analysis Section */}
            <div className="bg-white p-8 rounded-xl shadow-lg border border-gray-200">
                <h2 className="text-2xl font-bold text-science-900 mb-4 flex items-center gap-2">
                    <LayoutDashboard /> Statistical Analysis (ANOVA)
                </h2>
                {results.fitStatistics && (
                    <div className="grid md:grid-cols-3 gap-6 mb-6">
                        <div className="md:col-span-2 bg-gradient-to-r from-science-50 to-white p-4 rounded-lg border border-science-100">
                            <h4 className="text-xs font-bold text-science-600 uppercase mb-2 flex items-center gap-1">
                                <Sigma size={14} /> Regression Equation (Coded)
                            </h4>
                            <p className="font-mono text-gray-800 text-sm leading-relaxed">
                                {results.fitStatistics.equation ? 
                                    results.fitStatistics.equation.replace(/(\+|-)/g, ' $1 ').replace(/\*/g, ' × ') 
                                    : "Equation not available"}
                            </p>
                        </div>
                        <div className="bg-white p-4 rounded-lg border border-gray-200">
                            <h4 className="text-xs font-bold text-gray-500 uppercase mb-3">Model Fit Statistics</h4>
                            <div className="grid grid-cols-2 gap-4">
                                <div><div className="text-[10px] text-gray-400">R²</div><div className="text-lg font-bold text-gray-700">{results.fitStatistics.rSquared?.toFixed(4) || "N/A"}</div></div>
                                <div><div className="text-[10px] text-gray-400">Adj. R²</div><div className="text-lg font-bold text-gray-700">{results.fitStatistics.adjRSquared?.toFixed(4) || "N/A"}</div></div>
                                <div><div className="text-[10px] text-science-600 font-bold">Pred. R²</div><div className="text-lg font-bold text-science-700">{results.fitStatistics.predictedRSquared?.toFixed(4) || "N/A"}</div></div>
                                <div><div className="text-[10px] text-science-600 font-bold">Adeq. Prec</div><div className="text-lg font-bold text-science-700">{results.fitStatistics.adequatePrecision?.toFixed(2) || "N/A"}</div></div>
                            </div>
                        </div>
                    </div>
                )}
                <div className="prose prose-sm max-w-none text-gray-700 bg-slate-50 p-6 rounded border border-slate-200">
                    <ReactMarkdown>{results.anovaText}</ReactMarkdown>
                </div>
            </div>

            {/* Diagnostics Grid */}
            {results.diagnostics && (
                <div className="space-y-4">
                    <h3 className="text-xl font-bold text-gray-800 border-b pb-2 flex items-center gap-2"><Activity size={24} className="text-science-600"/> Model Diagnostics</h3>
                    <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6">

                        {/* 1. Pred vs Actual */}
                        <div className="space-y-2">
                            <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotPredVsActual" className="w-full h-full"></div></div>
                            <div className="text-xs text-gray-500 bg-gray-50 p-2 rounded border border-gray-100">
                                <span className="font-bold text-science-700 block mb-1">Interpretation:</span>
                                {results.diagnosticInterpretations?.predVsActual || "Points should follow the diagonal line."}
                            </div>
                        </div>

                        {/* 2. Residuals vs Run */}
                        <div className="space-y-2">
                             <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotResidVsRun" className="w-full h-full"></div></div>
                             <div className="text-xs text-gray-500 bg-gray-50 p-2 rounded border border-gray-100">
                                <span className="font-bold text-science-700 block mb-1">Interpretation:</span>
                                {results.diagnosticInterpretations?.residualsVsRun || "Points should be randomly scattered."}
                            </div>
                        </div>

                        {/* 3. Pred vs Run Order */}
                        <div className="space-y-2">
                            <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotPredVsRun" className="w-full h-full"></div></div>
                             <div className="text-xs text-gray-500 bg-gray-50 p-2 rounded border border-gray-100">
                                <span className="font-bold text-science-700 block mb-1">Interpretation:</span>
                                {results.diagnosticInterpretations?.predVsRun || "Check for lurking variables or drifts."}
                            </div>
                        </div>

                        {/* 4. Box Cox */}
                        <div className="space-y-2">
                            <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotBoxCox" className="w-full h-full"></div></div>
                             <div className="text-xs text-gray-500 bg-gray-50 p-2 rounded border border-gray-100">
                                <span className="font-bold text-science-700 block mb-1">Interpretation:</span>
                                {results.diagnosticInterpretations?.boxCox || "Lambda=1 implies no transform needed. Check CI (Red Lines)."}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Ternary Plot (Mixture Only) */}
            {isMixture && factors.length === 3 && (
                <div className="bg-white p-6 rounded-xl shadow-lg border border-gray-200">
                     <h3 className="text-xl font-bold text-science-900 mb-4 flex items-center gap-2"><Triangle size={24} /> Mixture Design</h3>
                    <div id="plotTernary" className="w-full h-[500px]"></div>
                </div>
            )}

            {/* Response Surface */}
            <div className="space-y-6">
                <div className="bg-science-50 p-4 rounded-lg flex flex-wrap gap-4 items-center">
                    <div><label className="block text-xs font-bold text-gray-600">X-Axis</label><select className="p-2 rounded border" value={plotX} onChange={e => setPlotX(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select></div>
                    <div><label className="block text-xs font-bold text-gray-600">Y-Axis</label><select className="p-2 rounded border" value={plotY} onChange={e => setPlotY(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select></div>
                    <div><label className="block text-xs font-bold text-gray-600">Response</label><select className="p-2 rounded border" value={plotResponse} onChange={e => setPlotResponse(e.target.value)}>{responses.map(r => <option key={r.name} value={r.name}>{r.name}</option>)}</select></div>
                </div>

                <div className="grid md:grid-cols-2 gap-8">
                    <div className="bg-white p-4 rounded-xl shadow border border-gray-200"><h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2"><Cuboid size={18} /> 3D Surface</h3><div id="plot3d" className="w-full h-[400px]"></div></div>
                    <div className="bg-white p-4 rounded-xl shadow border border-gray-200"><h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2"><Layers size={18} /> Contour</h3><div id="plotContour" className="w-full h-[400px]"></div></div>
                </div>
            </div>

            {/* Optimization & Desirability Section */}
            <div className="bg-gradient-to-b from-indigo-50 to-white p-8 rounded-xl border border-indigo-100 shadow-xl space-y-8">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center">
                    <div>
                        <h2 className="text-2xl font-bold text-indigo-900 flex items-center gap-2">
                            <Trophy className="text-yellow-500" /> Optimization & Desirability
                        </h2>
                        <p className="text-sm text-indigo-600 mt-1">Goal based optimization for: <strong>{plotResponse}</strong></p>
                    </div>
                </div>

                {/* Optimization Config */}
                <div className="grid md:grid-cols-4 gap-4 bg-white p-6 rounded-lg shadow-sm border border-indigo-100">
                    <div>
                        <label className="block text-xs font-bold text-gray-500 mb-1">Optimization Goal</label>
                        <select className="w-full p-2 border border-gray-300 rounded text-sm" value={optGoal} onChange={e => setOptGoal(e.target.value as any)}>
                            <option value="Maximize">Maximize Response</option>
                            <option value="Minimize">Minimize Response</option>
                            <option value="Target">Target Value</option>
                        </select>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-500 mb-1">Lower Limit</label>
                        <input type="number" className="w-full p-2 border border-gray-300 rounded text-sm" value={optMin} onChange={e => setOptMin(parseFloat(e.target.value))}/>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-500 mb-1">Upper Limit</label>
                        <input type="number" className="w-full p-2 border border-gray-300 rounded text-sm" value={optMax} onChange={e => setOptMax(parseFloat(e.target.value))}/>
                    </div>
                    {optGoal === 'Target' && (
                        <div>
                            <label className="block text-xs font-bold text-gray-500 mb-1">Target Value</label>
                            <input type="number" className="w-full p-2 border border-gray-300 rounded text-sm font-bold text-indigo-700" value={optTarget} onChange={e => setOptTarget(parseFloat(e.target.value))}/>
                        </div>
                    )}
                    <div className="md:col-span-4 flex justify-end mt-2">
                        <button 
                            onClick={findOptimalConditions}
                            className="bg-indigo-600 text-white px-6 py-2 rounded-lg hover:bg-indigo-700 font-bold flex items-center gap-2 shadow-lg shadow-indigo-200 transition-all"
                        >
                            <Search size={18} /> Find Best 3 Suggestions
                        </button>
                    </div>
                </div>

                {/* Optimization Results */}
                {topSuggestions.length > 0 && (
                     <div className="grid md:grid-cols-2 gap-8">
                         {/* Top 3 Cards */}
                         <div className="space-y-4">
                            <h3 className="font-bold text-indigo-800 flex items-center gap-2"><Target size={18} /> Best Conditions Found</h3>
                            {topSuggestions.map((suggestion, idx) => (
                                <div key={idx} className={`relative p-4 rounded-xl border ${idx===0 ? 'bg-yellow-50 border-yellow-200' : 'bg-white border-gray-200'} shadow-sm flex items-center gap-4 transition-transform hover:scale-[1.02]`}>
                                    <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-lg shadow-inner
                                        ${idx === 0 ? 'bg-yellow-400 text-yellow-900' : idx === 1 ? 'bg-gray-300 text-gray-700' : 'bg-orange-300 text-orange-900'}`}
                                    >
                                        {idx + 1}
                                    </div>
                                    <div className="flex-1">
                                        <div className="flex justify-between items-center mb-2">
                                            <span className="text-xs font-bold text-gray-500 uppercase tracking-wide">Desirability: {(suggestion.desirability * 100).toFixed(1)}%</span>
                                            <span className="text-sm font-bold text-indigo-700 bg-indigo-50 px-2 py-1 rounded">Pred: {suggestion.prediction.toFixed(3)} {getResponseUnit(plotResponse)}</span>
                                        </div>
                                        <div className="text-xs grid grid-cols-2 gap-x-4 gap-y-1 text-gray-700">
                                            {Object.entries(suggestion.factors).map(([k, v]) => (
                                                <div key={k} className="flex justify-between border-b border-gray-100 pb-1">
                                                    <span>{k}:</span> <strong>{(v as number).toFixed(2)}</strong>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            ))}
                         </div>

                         {/* Desirability Plot */}
                         <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                            <h3 className="font-bold text-indigo-800 mb-2 flex items-center gap-2">
                                <Activity size={18} /> Desirability Landscape
                            </h3>
                            <div id="plotDesirability" className="w-full h-[350px]"></div>
                            <p className="text-[10px] text-gray-400 text-center mt-2">
                                Red/Blue regions indicate areas with 0% desirability. Green/Red regions (1.0) match your goal.
                            </p>
                         </div>
                     </div>
                )}
            </div>

            {/* Prediction Simulator (Existing) */}
            {results.modelCoefficients && (
                <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-lg">
                    <h3 className="text-xl font-bold text-science-900 mb-4 flex items-center gap-2">
                        <Calculator size={24} /> Predict Outcome Simulator
                    </h3>
                    <div className="grid md:grid-cols-3 gap-6 items-end">
                        {factors.map(f => (
                            <div key={f.name}>
                                <label className="block text-xs font-bold text-science-800 mb-1 uppercase">
                                    {f.name} {f.unit ? `(${f.unit})` : ''}
                                </label>
                                <input type="number" step="any" className="w-full p-2 border border-science-200 rounded text-sm focus:ring-2 focus:ring-science-500 outline-none" value={predictionInputs[f.name] || ''} onChange={(e) => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}/>
                            </div>
                        ))}
                    </div>
                    <div className="mt-6 flex items-center gap-6">
                        <button onClick={calculatePrediction} className="bg-science-600 text-white px-6 py-2 rounded-lg hover:bg-science-700 font-bold flex items-center gap-2 shadow-sm"><Play size={16} /> Predict Result</button>
                        {predictedValue !== null && (
                            <div className="bg-slate-100 px-6 py-2 rounded-lg border border-slate-300 shadow-sm flex items-center gap-3">
                                <span className="text-xs font-bold text-gray-500 uppercase">Predicted {plotResponse || 'Response'}:</span>
                                <span className="text-2xl font-bold text-science-700">{predictedValue.toFixed(4)}<span className="text-sm font-normal text-gray-500 ml-1">{getResponseUnit(plotResponse)}</span></span>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

