import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisRequest, ExperimentalRun, AnalysisResult, ResponseAnalysis } from "../types";

const getClient = () => {
    let apiKey = '';
    // Safely check for process.env in browser environments
    if (typeof process !== 'undefined' && process.env) {
        apiKey = process.env.API_KEY || '';
    }

    if (!apiKey) {
        console.warn("API Key not found. Please ensure process.env.API_KEY is configured.");
        throw new Error("API Key is missing. Please check your configuration.");
    }
    return new GoogleGenAI({ apiKey });
};

// Returns just the runs array structure
export const generateDesignMatrix = async (request: AnalysisRequest, designName: string): Promise<ExperimentalRun[]> => {
    try {
        const ai = getClient();
        const factorDesc = request.factors.map(f => `${f.name} (${f.levels} levels: ${f.low} to ${f.high})`).join(', ');

        const isMixture = designName.toLowerCase().includes('mixture') || designName.toLowerCase().includes('simplex');

        // STRICT PROMPT INSTRUCTION FOR MIXTURE
        const mixtureInstruction = isMixture 
            ? `CRITICAL MIXTURE CONSTRAINT: This is a Mixture Design. The sum of all factor values in EVERY SINGLE RUN MUST be exactly 100. 
               Formula: Sum(${request.factors.map(f => f.name).join(', ')}) = 100.
               You MUST normalize the values to ensure they sum to 100 while respecting the relative low/high constraints as much as possible.
               Do not produce runs where the sum differs from 100.` 
            : "";

        const prompt = `
        Generate a Design of Experiments (DoE) matrix for a "${designName}".
        Factors: ${factorDesc}.

        STRICT CONFIGURATION:
        - Design Replicates: ${request.replicates} (Repeat the base design points this many times).
        - Center Points: ${request.centerPoints} (Add this many runs at the center of the domain or centroid).

        ${mixtureInstruction}

        CRITICAL RULES:
        1. Identify the standard base runs (N) determined by the design equation for ${request.factors.length} factors (e.g., 2^k, 2k+2, etc.).
        2. Multiply these base runs by ${request.replicates}.
        3. Append exactly ${request.centerPoints} center point runs.
        4. The output array must have length = (Base * ${request.replicates}) + ${request.centerPoints}.
        ${isMixture ? "5. VERIFY: Check that for every object in the array, the sum of values in 'factors' is exactly 100." : ""}

        Return STRICTLY JSON format. An array of objects.
        Each object should have:
        - "id" (number, starting at 1)
        - "factors" (object where keys are factor names and values are numbers).

        Do not output any markdown code blocks. Just the raw JSON string.
        Ensure real-world values are used based on the ranges provided, not coded values.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 0 }
            }
        });

        const text = response.text || "[]";
        // Clean markdown if present
        const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
        let runs = JSON.parse(jsonStr);

        // POST-PROCESSING ENFORCEMENT for Mixture Designs
        if (isMixture) {
            runs = runs.map((r: any) => {
                const factors = r.factors;
                if (!factors || typeof factors !== 'object') return r;

                const keys = Object.keys(factors);
                if (keys.length === 0) return r;

                const sum = keys.reduce((acc, k) => {
                    const val = parseFloat(factors[k]);
                    return acc + (isNaN(val) ? 0 : val);
                }, 0);

                if (Math.abs(sum - 100) > 0.05 && sum !== 0) {
                    const newFactors: any = {};
                    let newSum = 0;
                    let maxKey = keys[0];
                    let maxVal = -1;

                    keys.forEach(k => {
                        const val = parseFloat(factors[k]) || 0;
                        const norm = (val / sum) * 100;
                        const rounded = parseFloat(norm.toFixed(2));
                        newFactors[k] = rounded;
                        newSum += rounded;

                        if (rounded > maxVal) {
                            maxVal = rounded;
                            maxKey = k;
                        }
                    });

                    const diff = 100 - newSum;
                    if (Math.abs(diff) > 0.001) {
                        newFactors[maxKey] = parseFloat((newFactors[maxKey] + diff).toFixed(2));
                    }
                    return { ...r, factors: newFactors };
                }
                return r;
            });
        }

        return runs.map((r: any) => ({
            id: r.id,
            factors: r.factors,
            results: {} 
        }));

    } catch (e) {
        console.error("Design Matrix Error", e);
        return [];
    }
};

const analyzeSingleResponse = async (
    designName: string,
    responseName: string,
    factorData: any[],
    responseData: any[]
): Promise<ResponseAnalysis> => {
    const ai = getClient();

    const combinedData = factorData.map((f, i) => ({ ...f, [responseName]: responseData[i] }));
    const dataStr = JSON.stringify(combinedData);

    const prompt = `
    Perform a statistical analysis for the response "${responseName}".
    Design: ${designName}.
    Data: ${dataStr}.

    CRITICAL INSTRUCTIONS:
    1. **Model Coefficients**: MUST be calculated using CODED VALUES (-1 for Low, +1 for High). This is essential for the prediction engine.
    2. **Consistency**: The "equation" string must match the "model_coefficients".
    3. **ANOVA**: Provide a professional scientific interpretation in Markdown.
    4. **Diagnostics**: 
       - Calculate actual vs predicted values.
       - Generate data for Box-Cox Plot (Lambda vs lnRSS).
       - Provide brief scientific interpretations.
    `;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    anova_markdown: { type: Type.STRING },
                    fit_statistics: {
                        type: Type.OBJECT,
                        properties: {
                            r_squared: { type: Type.NUMBER },
                            adj_r_squared: { type: Type.NUMBER },
                            predicted_r_squared: { type: Type.NUMBER },
                            adequate_precision: { type: Type.NUMBER },
                            equation: { type: Type.STRING },
                        }
                    },
                    diagnostic_interpretations: {
                        type: Type.OBJECT,
                        properties: {
                            pred_vs_actual: { type: Type.STRING },
                            residuals_vs_run: { type: Type.STRING },
                            pred_vs_run: { type: Type.STRING },
                            box_cox: { type: Type.STRING }
                        }
                    },
                    model_coefficients: {
                        type: Type.OBJECT,
                        properties: {
                            intercept: { type: Type.NUMBER },
                            linear_terms: { 
                                type: Type.ARRAY, 
                                items: { type: Type.OBJECT, properties: { factor: { type: Type.STRING }, coef: { type: Type.NUMBER } } } 
                            },
                            quadratic_terms: { 
                                type: Type.ARRAY, 
                                items: { type: Type.OBJECT, properties: { factor: { type: Type.STRING }, coef: { type: Type.NUMBER } } } 
                            },
                            interaction_terms: { 
                                type: Type.ARRAY, 
                                items: { type: Type.OBJECT, properties: { factor1: { type: Type.STRING }, factor2: { type: Type.STRING }, coef: { type: Type.NUMBER } } } 
                            }
                        }
                    },
                    diagnostics: {
                        type: Type.OBJECT,
                        properties: {
                            run_order: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                            actual: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                            predicted: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                            residuals: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                            boxCox: {
                                type: Type.OBJECT,
                                properties: {
                                    lambda: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                                    lnRSS: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                                    ciLimit: { type: Type.NUMBER },
                                    lambdaBest: { type: Type.NUMBER },
                                    lambdaLow: { type: Type.NUMBER },
                                    lambdaHigh: { type: Type.NUMBER }
                                }
                            }
                        }
                    }
                },
                required: ["anova_markdown", "fit_statistics", "model_coefficients", "diagnostics", "diagnostic_interpretations"]
            }
        }
    });

    const json = JSON.parse(response.text || "{}");

    // Transform coefficients
    const linear: Record<string, number> = {};
    if (json.model_coefficients?.linear_terms) {
        json.model_coefficients.linear_terms.forEach((t: any) => {
            if(t.factor && t.coef !== undefined) linear[t.factor] = t.coef;
        });
    }

    const quadratic: Record<string, number> = {};
    if (json.model_coefficients?.quadratic_terms) {
        json.model_coefficients.quadratic_terms.forEach((t: any) => {
            if(t.factor && t.coef !== undefined) quadratic[t.factor] = t.coef;
        });
    }

    const interactions = json.model_coefficients?.interaction_terms?.map((t: any) => ({
        factor1: t.factor1,
        factor2: t.factor2,
        coefficient: t.coef
    })) || [];

    return {
        responseName,
        anovaText: json.anova_markdown || "Analysis unavailable.",
        fitStatistics: {
            rSquared: json.fit_statistics?.r_squared || 0,
            adjRSquared: json.fit_statistics?.adj_r_squared || 0,
            predictedRSquared: json.fit_statistics?.predicted_r_squared || 0,
            adequatePrecision: json.fit_statistics?.adequate_precision || 0,
            equation: json.fit_statistics?.equation || ""
        },
        diagnosticInterpretations: {
            predVsActual: json.diagnostic_interpretations?.pred_vs_actual || "",
            residualsVsRun: json.diagnostic_interpretations?.residuals_vs_run || "",
            predVsRun: json.diagnostic_interpretations?.pred_vs_run || "",
            boxCox: json.diagnostic_interpretations?.box_cox || ""
        },
        modelCoefficients: {
            intercept: json.model_coefficients?.intercept || 0,
            linear,
            quadratic,
            interactions
        },
        diagnostics: {
            runOrder: json.diagnostics?.run_order || [],
            actual: json.diagnostics?.actual || [],
            predicted: json.diagnostics?.predicted || [],
            residuals: json.diagnostics?.residuals || [],
            boxCox: json.diagnostics?.boxCox
        }
    };
};

export const analyzeExperimentalResults = async (
    request: AnalysisRequest, 
    designName: string, 
    runs: ExperimentalRun[]
): Promise<AnalysisResult> => {
    // 1. Filter Valid Runs
    const validRuns = runs.filter(r => {
        // Run is valid if it has valid number factors and at least one valid response
        const hasFactors = Object.values(r.factors).every(v => typeof v === 'number');
        const hasAnyResponse = request.responses.some(res => {
            const val = r.results[res.name];
            return val !== undefined && val !== '' && !isNaN(parseFloat(val));
        });
        return hasFactors && hasAnyResponse;
    });

    if (validRuns.length < request.factors.length + 2) {
         throw new Error("Insufficient valid data points. Please complete more experimental runs.");
    }

    // 2. Prepare Data Arrays
    const factorData = validRuns.map(r => r.factors);

    // 3. Run Analysis for EACH Response in Parallel
    const analysisPromises = request.responses.map(res => {
        const responseValues = validRuns.map(r => parseFloat(r.results[res.name]));
        // If this response has too many NaNs/Invalid, we might skip or fail.
        // For now, assuming validRuns logic holds enough.
        return analyzeSingleResponse(designName, res.name, factorData, responseValues);
    });

    try {
        const results = await Promise.all(analysisPromises);

        const resultsByResponse: Record<string, ResponseAnalysis> = {};
        results.forEach(r => {
            resultsByResponse[r.responseName] = r;
        });

        return {
            resultsByResponse
        };

    } catch (e) {
        console.error("Batch Analysis Error", e);
        throw new Error("Analysis failed. Please check inputs.");
    }
};

import React, { useEffect, useState, useCallback } from 'react';
import { AnalysisResult, FactorDefinition, ResponseDefinition } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, Calculator, Play, Sigma, Triangle, Trophy, Target, Search } from 'lucide-react';

declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
    isMixture?: boolean;
}

interface OptResult {
    factors: Record<string, number>;
    prediction: number;
    desirability: number;
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses, isMixture = false }) => {
    // Prediction State
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);

    // Plot Configuration State
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');

    // Optimization State
    const [optGoal, setOptGoal] = useState<'Maximize' | 'Minimize' | 'Target'>('Maximize');
    const [optTarget, setOptTarget] = useState<number>(0);
    const [optMin, setOptMin] = useState<number>(0);
    const [optMax, setOptMax] = useState<number>(100);
    const [topSuggestions, setTopSuggestions] = useState<OptResult[]>([]);

    // Initialize inputs and plot defaults
    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = isNaN(mid) ? "0" : mid.toString();
        });
        setPredictionInputs(initial);

        if (factors.length >= 2) {
            setPlotX(factors[0].name);
            setPlotY(factors[1].name);
        }
        if (responses.length > 0) {
            setPlotResponse(responses[0].name);
        }
    }, [factors, responses]);

    // Retrieve active result based on selected plotResponse
    const activeResult = results.resultsByResponse[plotResponse];

    // Helper: Get Range with safety check for empty data
    const getObservedRange = useCallback((resName: string) => {
        const res = results.resultsByResponse[resName];
        if (!res || !res.diagnostics || !res.diagnostics.actual || res.diagnostics.actual.length === 0) {
            return { min: 0, max: 100 };
        }
        // Filter out NaNs just in case
        const cleanData = res.diagnostics.actual.filter(v => typeof v === 'number' && !isNaN(v));
        if (cleanData.length === 0) return { min: 0, max: 100 };

        let min = Math.min(...cleanData);
        let max = Math.max(...cleanData);

        if (Math.abs(max - min) < 1e-9) {
            return { min: min - 1, max: max + 1 };
        }
        return { min, max };
    }, [results]);

    // Initialize Optimization Defaults when response changes
    useEffect(() => {
        const range = getObservedRange(plotResponse);
        setOptMin(range.min);
        setOptMax(range.max);
        setOptTarget((range.min + range.max) / 2);

        const resDef = responses.find(r => r.name === plotResponse);
        if (resDef) setOptGoal(resDef.goal);
    }, [plotResponse, getObservedRange, responses]);


    // Helper: Convert Real Value to Coded Value (-1 to +1)
    const toCoded = (val: number, factorName: string) => {
        const factor = factors.find(f => f.name === factorName);
        if (!factor) return 0;

        const low = parseFloat(factor.low);
        const high = parseFloat(factor.high);

        if (isNaN(low) || isNaN(high)) return 0;

        const mid = (high + low) / 2;
        const halfRange = (high - low) / 2;

        if (halfRange === 0) return 0;
        return (val - mid) / halfRange;
    };

    // Calculate prediction AND Clamp it to observed range
    const calculatePredictionInternal = (inputs: Record<string, string | number>) => {
         if (!activeResult || !activeResult.modelCoefficients) return 0;

        const { intercept, linear, quadratic, interactions } = activeResult.modelCoefficients;
        // Ensure intercept is a number
        let y = typeof intercept === 'number' ? intercept : parseFloat(intercept as any) || 0;

        // Linear
        if (linear) {
            Object.entries(linear).forEach(([factorName, coeff]) => {
                const val = inputs[factorName];
                const realVal = typeof val === 'string' ? parseFloat(val) : val;
                const c = typeof coeff === 'number' ? coeff : parseFloat(coeff as any) || 0;

                if (typeof realVal === 'number' && !isNaN(realVal)) {
                    const codedVal = toCoded(realVal, factorName);
                    y += c * codedVal;
                }
            });
        }
        // Quadratic
        if (quadratic) {
            Object.entries(quadratic).forEach(([factorName, coeff]) => {
                const val = inputs[factorName];
                const realVal = typeof val === 'string' ? parseFloat(val) : val;
                const c = typeof coeff === 'number' ? coeff : parseFloat(coeff as any) || 0;

                if (typeof realVal === 'number' && !isNaN(realVal)) {
                    const codedVal = toCoded(realVal, factorName);
                    y += c * Math.pow(codedVal, 2);
                }
            });
        }
        // Interactions
        if (interactions && Array.isArray(interactions)) {
            interactions.forEach(term => {
                const v1 = inputs[term.factor1];
                const v2 = inputs[term.factor2];
                const realVal1 = typeof v1 === 'string' ? parseFloat(v1) : v1;
                const realVal2 = typeof v2 === 'string' ? parseFloat(v2) : v2;
                const c = typeof term.coefficient === 'number' ? term.coefficient : parseFloat(term.coefficient as any) || 0;

                if (typeof realVal1 === 'number' && !isNaN(realVal1) && typeof realVal2 === 'number' && !isNaN(realVal2)) {
                    const codedVal1 = toCoded(realVal1, term.factor1);
                    const codedVal2 = toCoded(realVal2, term.factor2);
                    y += c * codedVal1 * codedVal2;
                }
            });
        }

        // UNIVERSAL CLAMPING: Ensure prediction respects physical reality of observed data
        const { min, max } = getObservedRange(plotResponse);
        return Math.max(min, Math.min(max, y));
    };

    const calculatePrediction = () => {
        const val = calculatePredictionInternal(predictionInputs);
        setPredictedValue(val);
    };

    const calculateDesirability = (val: number) => {
        if (isNaN(val) || !isFinite(val)) return 0;

        const range = optMax - optMin;
        if (range === 0) return 0;

        if (optGoal === 'Maximize') {
            if (val <= optMin) return 0;
            if (val >= optMax) return 1;
            return (val - optMin) / range;
        } else if (optGoal === 'Minimize') {
            if (val <= optMin) return 1;
            if (val >= optMax) return 0;
            return (optMax - val) / range;
        } else {
            // Target
            if (val < optMin || val > optMax) return 0;
            if (val === optTarget) return 1;

            const lowerRange = optTarget - optMin;
            const upperRange = optMax - optTarget;

            if (val < optTarget) {
                return lowerRange === 0 ? 0 : (val - optMin) / lowerRange;
            } else {
                return upperRange === 0 ? 0 : (optMax - val) / upperRange;
            }
        }
    };

    const findOptimalConditions = () => {
        if (!activeResult) return;
        const iterations = 5000;
        const suggestions: OptResult[] = [];

        for (let i = 0; i < iterations; i++) {
            const trialInputs: Record<string, number> = {};
            factors.forEach(f => {
                const min = parseFloat(f.low);
                const max = parseFloat(f.high);
                if (!isNaN(min) && !isNaN(max)) {
                     trialInputs[f.name] = min + Math.random() * (max - min);
                } else {
                    trialInputs[f.name] = 0;
                }
            });

            const pred = calculatePredictionInternal(trialInputs);
            const d = calculateDesirability(pred);
            if (!isNaN(pred) && !isNaN(d)) {
                suggestions.push({ factors: trialInputs, prediction: pred, desirability: d });
            }
        }

        suggestions.sort((a, b) => b.desirability - a.desirability);

        const uniqueTop: OptResult[] = [];
        for (const s of suggestions) {
            if (uniqueTop.length >= 3) break;
            const isDuplicate = uniqueTop.some(existing => {
                return factors.every(f => {
                    const low = parseFloat(f.low);
                    const high = parseFloat(f.high);
                    const range = Math.abs(high - low) || 1;
                    return Math.abs(existing.factors[f.name] - s.factors[f.name]) < (range * 0.05);
                });
            });
            if (!isDuplicate) uniqueTop.push(s);
        }

        setTopSuggestions(uniqueTop);
    };


    const getResponseUnit = (resName: string) => {
        const r = responses.find(r => r.name === resName);
        return r ? r.unit : '';
    };

    // --- Ternary Plot Logic ---
    useEffect(() => {
        // Only run if it's a mixture design and has 3 factors
        if (!isMixture || factors.length !== 3) return;

        let cleanup = false;
        try {
            if (!window.Plotly || !activeResult?.modelCoefficients) return;

            const fA = factors[0];
            const fB = factors[1];
            const fC = factors[2];
            const divId = 'plotTernary';

            const aPoints: number[] = [], bPoints: number[] = [], cPoints: number[] = [], zPoints: number[] = [];
            const total = 100, step = 2; 

            for (let a = 0; a <= total; a += step) {
                for (let b = 0; b <= (total - a); b += step) {
                    const c = total - a - b;
                    const lowA = parseFloat(fA.low), highA = parseFloat(fA.high);
                    // Use relaxed check for boundaries to allow plotting near edges
                    if (!isNaN(lowA) && !isNaN(highA)) {
                        const inputs = {
                            ...predictionInputs,
                            [fA.name]: a.toString(),
                            [fB.name]: b.toString(),
                            [fC.name]: c.toString()
                        };
                        const z = calculatePredictionInternal(inputs);
                        if (!isNaN(z)) {
                            aPoints.push(a);
                            bPoints.push(b);
                            cPoints.push(c);
                            zPoints.push(z);
                        }
                    }
                }
            }

            if (zPoints.length === 0) return;
            if (cleanup) return;

            const observed = getObservedRange(plotResponse);
            const data = [{
                type: 'scatterternary',
                mode: 'markers',
                a: aPoints, b: bPoints, c: cPoints,
                marker: {
                    color: zPoints, colorscale: 'Viridis', size: 4,
                    cmin: observed.min, cmax: observed.max,
                    colorbar: { title: plotResponse, thickness: 20 }
                },
                text: zPoints.map(z => z.toFixed(2)),
                hoverinfo: 'text+a+b+c'
            }];

            const layout = {
                title: `Mixture Contour: ${plotResponse}`,
                ternary: {
                    sum: 100,
                    aaxis: { title: fA.name, min: parseFloat(fA.low) || 0, max: parseFloat(fA.high) || 100 },
                    baxis: { title: fB.name, min: parseFloat(fB.low) || 0, max: parseFloat(fB.high) || 100 },
                    caxis: { title: fC.name, min: parseFloat(fC.low) || 0, max: parseFloat(fC.high) || 100 }
                },
                margin: { t: 40, b: 40, l: 40, r: 40 }
            };

            if (document.getElementById(divId)) {
                window.Plotly.react(divId, data, layout);
            }
        } catch (e) {
            console.error("Ternary Plot Error", e);
        }

        return () => {
            cleanup = true;
            try {
                if (document.getElementById('plotTernary')) window.Plotly.purge('plotTernary');
            } catch(e) {}
        };
    }, [factors, activeResult, plotResponse, getObservedRange, predictionInputs, isMixture]);


    // Client-side Surface Generation (Cartesian & Desirability)
    useEffect(() => {
        let cleanup = false;
        try {
            if (!window.Plotly || !plotX || !plotY || !activeResult?.modelCoefficients) return;

            const factorX = factors.find(f => f.name === plotX);
            const factorY = factors.find(f => f.name === plotY);

            if(!factorX || !factorY) return;

            const xMin = parseFloat(factorX.low);
            const xMax = parseFloat(factorX.high);
            const yMin = parseFloat(factorY.low);
            const yMax = parseFloat(factorY.high);

            if(isNaN(xMin) || isNaN(xMax) || isNaN(yMin) || isNaN(yMax)) return;

            const steps = 30; 
            const xValues: number[] = [], yValues: number[] = [];
            const zMatrix: number[][] = [], dMatrix: number[][] = [];

            for(let i=0; i<=steps; i++) xValues.push(xMin + (i * (xMax - xMin) / steps));
            for(let i=0; i<=steps; i++) yValues.push(yMin + (i * (yMax - yMin) / steps));

            for(let j=0; j<=steps; j++) {
                const rowZ: number[] = [], rowD: number[] = [];
                for(let i=0; i<=steps; i++) {
                    const inputs: Record<string, string | number> = { ...predictionInputs };
                    inputs[plotX] = xValues[i];
                    inputs[plotY] = yValues[j];

                    const pred = calculatePredictionInternal(inputs);
                    const des = calculateDesirability(pred);

                    rowZ.push(isNaN(pred) ? 0 : pred);
                    rowD.push(isNaN(des) ? 0 : des);
                }
                zMatrix.push(rowZ);
                dMatrix.push(rowD);
            }

            if(cleanup) return;

            const observed = getObservedRange(plotResponse);
            const zRange = [observed.min, observed.max];

            // 3D Plot
            const surfaceData = [{
                z: zMatrix, x: xValues, y: yValues,
                type: 'surface', cmin: zRange[0], cmax: zRange[1],
                contours: { z: { show: true, usecolormap: true, highlightcolor: "#42f462", project: { z: true } } },
                colorscale: 'Viridis'
            }];
            const layout3d = {
                title: `Surface: ${plotResponse}`, autosize: true,
                scene: { xaxis: { title: plotX }, yaxis: { title: plotY }, zaxis: { title: plotResponse, range: zRange } },
                margin: { l: 0, r: 0, b: 0, t: 30 }
            };
            if (document.getElementById('plot3d')) window.Plotly.react('plot3d', surfaceData, layout3d);

            // Contour Plot
            const contourData = [{
                z: zMatrix, x: xValues, y: yValues,
                type: 'contour', colorscale: 'Viridis', cmin: zRange[0], cmax: zRange[1],
                contours: { start: zRange[0], end: zRange[1] }
            }];
            const layoutContour = { title: `Contour: ${plotResponse}`, autosize: true, xaxis: { title: plotX }, yaxis: { title: plotY } };
            if (document.getElementById('plotContour')) window.Plotly.react('plotContour', contourData, layoutContour);

            // Desirability Contour - Fixed to use Absolute Scaling and Red-Yellow-Green scale
            const desData = [{
                z: dMatrix, x: xValues, y: yValues,
                type: 'contour', 
                colorscale: [
                    [0, 'rgb(239, 68, 68)'],   // Red (Bad)
                    [0.5, 'rgb(234, 179, 8)'], // Yellow
                    [1, 'rgb(34, 197, 94)']    // Green (Good)
                ], 
                zmin: 0, zmax: 1, // Absolute range 0-1
                contours: { 
                    start: 0, 
                    end: 1, 
                    size: 0.1,
                    showlabels: true,
                    labelfont: { size: 10, color: 'white' }
                },
                colorbar: {
                    title: 'Desirability',
                    titleside: 'right',
                    thickness: 15
                }
            }];
            const layoutDes = { title: `Desirability (Goal: ${optGoal})`, autosize: true, xaxis: { title: plotX }, yaxis: { title: plotY } };
            if (document.getElementById('plotDesirability')) window.Plotly.react('plotDesirability', desData, layoutDes);

        } catch (e) {
            console.error("Surface Plot Error", e);
        }

        return () => {
            cleanup = true;
            try {
                if (document.getElementById('plot3d')) window.Plotly.purge('plot3d');
                if (document.getElementById('plotContour')) window.Plotly.purge('plotContour');
                if (document.getElementById('plotDesirability')) window.Plotly.purge('plotDesirability');
            } catch(e) {}
        };

    }, [plotX, plotY, plotResponse, activeResult, predictionInputs, optGoal, optMin, optMax, optTarget]);

    // Diagnostic Plots (Run Order, Box-Cox, etc)
    useEffect(() => {
        let cleanup = false;
        try {
            if (!window.Plotly || !activeResult?.diagnostics) return;
            const diag = activeResult.diagnostics;

            if (!diag.runOrder || !diag.actual || !diag.predicted || !diag.residuals) return;
            // Ensure no NaNs
            if (diag.actual.some(isNaN) || diag.predicted.some(isNaN)) return;
            if(cleanup) return;

            // 1. Predicted vs Actual
            const actualMin = Math.min(...diag.actual);
            const actualMax = Math.max(...diag.actual);
            const fitData = [
                { x: diag.actual, y: diag.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9' } },
                { x: [actualMin, actualMax], y: [actualMin, actualMax], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' }, name: 'Ideal' }
            ];
            if (document.getElementById('plotPredVsActual')) window.Plotly.react('plotPredVsActual', fitData, { title: 'Predicted vs Actual', margin: { t: 30, b: 30, l: 30, r: 10 } });

            // 2. Residuals vs Run Order
            const residData = [{ x: diag.runOrder, y: diag.residuals, type: 'scatter', mode: 'markers', marker: { color: '#f59e0b', size: 8 } }];
            if (document.getElementById('plotResidVsRun')) window.Plotly.react('plotResidVsRun', residData, { title: 'Residuals vs Run Order', shapes: [{ type: 'line', x0: 0, x1: Math.max(...diag.runOrder, 1)+1, y0: 0, y1: 0, line: { color: 'black', width: 1, dash: 'dot' } }], margin: { t: 30, b: 30, l: 30, r: 10 } });

            // 3. Predicted vs Run Order
            const predRunData = [
                { x: diag.runOrder, y: diag.predicted, type: 'scatter', mode: 'lines+markers', name: 'Predicted', line: { color: '#0284c7' } },
                { x: diag.runOrder, y: diag.actual, type: 'scatter', mode: 'markers', name: 'Actual', marker: { color: '#ef4444' } }
            ];
            if (document.getElementById('plotPredVsRun')) window.Plotly.react('plotPredVsRun', predRunData, { title: 'Pred vs Actual (Run Order)', margin: { t: 30, b: 30, l: 30, r: 10 } });

            // 4. Box-Cox Plot
            if (diag.boxCox && diag.boxCox.lambda && diag.boxCox.lambda.length > 0) {
                 const boxCoxData = [{ x: diag.boxCox.lambda, y: diag.boxCox.lnRSS, type: 'scatter', mode: 'lines', line: { shape: 'spline', color: '#8b5cf6', width: 3 }, name: 'ln(RSS)' }];
                 const shapes = [];

                 // Add CI Limit line (Red horizontal)
                 if (diag.boxCox.ciLimit !== undefined) {
                    const minLambda = Math.min(...diag.boxCox.lambda);
                    const maxLambda = Math.max(...diag.boxCox.lambda);
                    shapes.push({ 
                        type: 'line', x0: minLambda, x1: maxLambda, y0: diag.boxCox.ciLimit, y1: diag.boxCox.ciLimit, 
                        line: { color: 'red', width: 2, dash: 'dash' } 
                    });
                 }

                 // Add Lambda Interval lines if available (Red vertical)
                 if (diag.boxCox.lambdaLow !== undefined && diag.boxCox.lambdaHigh !== undefined) {
                     const minRSS = Math.min(...diag.boxCox.lnRSS);
                     const maxRSS = Math.max(...diag.boxCox.lnRSS);
                     shapes.push({ type: 'line', x0: diag.boxCox.lambdaLow, x1: diag.boxCox.lambdaLow, y0: minRSS, y1: maxRSS, line: { color: 'red', width: 1, dash: 'dot' } });
                     shapes.push({ type: 'line', x0: diag.boxCox.lambdaHigh, x1: diag.boxCox.lambdaHigh, y0: minRSS, y1: maxRSS, line: { color: 'red', width: 1, dash: 'dot' } });
                 }

                 // Add Current Lambda (1.0) Line - Green
                 const minRSS = Math.min(...diag.boxCox.lnRSS);
                 const maxRSS = Math.max(...diag.boxCox.lnRSS);
                 shapes.push({ 
                     type: 'line', x0: 1, x1: 1, y0: minRSS, y1: maxRSS, 
                     line: { color: '#22c55e', width: 2, dash: 'dash' }
                 });

                 const annotations = [{
                     x: 1, y: maxRSS, xref: 'x', yref: 'y',
                     text: 'Current (λ=1)', showarrow: false, yshift: 10, font: { color: '#22c55e', size: 10 }
                 }];

                 if (document.getElementById('plotBoxCox')) {
                    window.Plotly.react('plotBoxCox', boxCoxData, { 
                        title: 'Box-Cox Plot (Power Transform)', 
                        xaxis: { title: 'Lambda (λ)' }, 
                        yaxis: { title: 'ln(RSS)' }, 
                        shapes: shapes, 
                        annotations: annotations,
                        margin: { t: 40, b: 30, l: 40, r: 10 } 
                    });
                 }
            }
        } catch (e) {
            console.error("Diagnostic Plot Error", e);
        }

        return () => {
            cleanup = true;
            try {
                if (document.getElementById('plotPredVsActual')) window.Plotly.purge('plotPredVsActual');
                if (document.getElementById('plotResidVsRun')) window.Plotly.purge('plotResidVsRun');
                if (document.getElementById('plotPredVsRun')) window.Plotly.purge('plotPredVsRun');
                if (document.getElementById('plotBoxCox')) window.Plotly.purge('plotBoxCox');
            } catch(e) {}
        };
    }, [activeResult]);

    if (!activeResult) {
        return <div className="p-8 text-center text-gray-500">Select a response to view analysis details.</div>;
    }

    return (
        <div className="space-y-8 pb-12">
            {/* Top Analysis Section */}
            <div className="bg-white p-8 rounded-xl shadow-lg border border-gray-200">
                <h2 className="text-2xl font-bold text-science-900 mb-4 flex items-center gap-2">
                    <LayoutDashboard /> Statistical Analysis (ANOVA)
                </h2>
                {activeResult.fitStatistics && (
                    <div className="grid md:grid-cols-3 gap-6 mb-6">
                        <div className="md:col-span-2 bg-gradient-to-r from-science-50 to-white p-4 rounded-lg border border-science-100">
                            <h4 className="text-xs font-bold text-science-600 uppercase mb-2 flex items-center gap-1">
                                <Sigma size={14} /> Regression Equation (Coded)
                            </h4>
                            <p className="font-mono text-gray-800 text-sm leading-relaxed">
                                {activeResult.fitStatistics.equation ? 
                                    activeResult.fitStatistics.equation.replace(/(\+|-)/g, ' $1 ').replace(/\*/g, ' × ') 
                                    : "Equation not available"}
                            </p>
                        </div>
                        <div className="bg-white p-4 rounded-lg border border-gray-200">
                            <h4 className="text-xs font-bold text-gray-500 uppercase mb-3">Model Fit Statistics</h4>
                            <div className="grid grid-cols-2 gap-4">
                                <div><div className="text-[10px] text-gray-400">R²</div><div className="text-lg font-bold text-gray-700">{activeResult.fitStatistics.rSquared?.toFixed(4) || "N/A"}</div></div>
                                <div><div className="text-[10px] text-gray-400">Adj. R²</div><div className="text-lg font-bold text-gray-700">{activeResult.fitStatistics.adjRSquared?.toFixed(4) || "N/A"}</div></div>
                                <div><div className="text-[10px] text-science-600 font-bold">Pred. R²</div><div className="text-lg font-bold text-science-700">{activeResult.fitStatistics.predictedRSquared?.toFixed(4) || "N/A"}</div></div>
                                <div><div className="text-[10px] text-science-600 font-bold">Adeq. Prec</div><div className="text-lg font-bold text-science-700">{activeResult.fitStatistics.adequatePrecision?.toFixed(2) || "N/A"}</div></div>
                            </div>
                        </div>
                    </div>
                )}
                <div className="prose prose-sm max-w-none text-gray-700 bg-slate-50 p-6 rounded border border-slate-200">
                    <ReactMarkdown>{activeResult.anovaText}</ReactMarkdown>
                </div>
            </div>

            {/* Diagnostics Grid */}
            {activeResult.diagnostics && (
                <div className="space-y-4">
                    <h3 className="text-xl font-bold text-gray-800 border-b pb-2 flex items-center gap-2"><Activity size={24} className="text-science-600"/> Model Diagnostics</h3>
                    <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6">

                        {/* 1. Pred vs Actual */}
                        <div className="space-y-2">
                            <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotPredVsActual" className="w-full h-full"></div></div>
                            <div className="text-xs text-gray-500 bg-gray-50 p-2 rounded border border-gray-100">
                                <span className="font-bold text-science-700 block mb-1">Interpretation:</span>
                                {activeResult.diagnosticInterpretations?.predVsActual || "Points should follow the diagonal line."}
                            </div>
                        </div>

                        {/* 2. Residuals vs Run */}
                        <div className="space-y-2">
                             <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotResidVsRun" className="w-full h-full"></div></div>
                             <div className="text-xs text-gray-500 bg-gray-50 p-2 rounded border border-gray-100">
                                <span className="font-bold text-science-700 block mb-1">Interpretation:</span>
                                {activeResult.diagnosticInterpretations?.residualsVsRun || "Points should be randomly scattered."}
                            </div>
                        </div>

                        {/* 3. Pred vs Run Order */}
                        <div className="space-y-2">
                            <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotPredVsRun" className="w-full h-full"></div></div>
                             <div className="text-xs text-gray-500 bg-gray-50 p-2 rounded border border-gray-100">
                                <span className="font-bold text-science-700 block mb-1">Interpretation:</span>
                                {activeResult.diagnosticInterpretations?.predVsRun || "Check for lurking variables or drifts."}
                            </div>
                        </div>

                        {/* 4. Box Cox */}
                        <div className="space-y-2">
                            <div className="bg-white p-2 rounded shadow border border-gray-200 h-[250px] relative"><div id="plotBoxCox" className="w-full h-full"></div></div>
                             <div className="text-xs text-gray-500 bg-gray-50 p-2 rounded border border-gray-100">
                                <span className="font-bold text-science-700 block mb-1">Interpretation:</span>
                                {activeResult.diagnosticInterpretations?.boxCox || "Lambda=1 implies no transform needed. Check CI (Red Lines)."}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Ternary Plot (Mixture Only) */}
            {isMixture && factors.length === 3 && (
                <div className="bg-white p-6 rounded-xl shadow-lg border border-gray-200">
                     <h3 className="text-xl font-bold text-science-900 mb-4 flex items-center gap-2"><Triangle size={24} /> Mixture Design</h3>
                    <div id="plotTernary" className="w-full h-[500px]"></div>
                </div>
            )}

            {/* Response Surface */}
            <div className="space-y-6">
                <div className="bg-science-50 p-4 rounded-lg flex flex-wrap gap-4 items-center">
                    <div><label className="block text-xs font-bold text-gray-600">X-Axis</label><select className="p-2 rounded border" value={plotX} onChange={e => setPlotX(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select></div>
                    <div><label className="block text-xs font-bold text-gray-600">Y-Axis</label><select className="p-2 rounded border" value={plotY} onChange={e => setPlotY(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select></div>
                    <div><label className="block text-xs font-bold text-gray-600">Response</label><select className="p-2 rounded border" value={plotResponse} onChange={e => setPlotResponse(e.target.value)}>{responses.map(r => <option key={r.name} value={r.name}>{r.name}</option>)}</select></div>
                </div>

                <div className="grid md:grid-cols-2 gap-8">
                    <div className="bg-white p-4 rounded-xl shadow border border-gray-200"><h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2"><Cuboid size={18} /> 3D Surface</h3><div id="plot3d" className="w-full h-[400px]"></div></div>
                    <div className="bg-white p-4 rounded-xl shadow border border-gray-200"><h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2"><Layers size={18} /> Contour</h3><div id="plotContour" className="w-full h-[400px]"></div></div>
                </div>
            </div>

            {/* Optimization & Desirability Section */}
            <div className="bg-gradient-to-b from-indigo-50 to-white p-8 rounded-xl border border-indigo-100 shadow-xl space-y-8">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center">
                    <div>
                        <h2 className="text-2xl font-bold text-indigo-900 flex items-center gap-2">
                            <Trophy className="text-yellow-500" /> Optimization & Desirability
                        </h2>
                        <p className="text-sm text-indigo-600 mt-1">Goal based optimization for: <strong>{plotResponse}</strong></p>
                    </div>
                </div>

                {/* Optimization Config */}
                <div className="grid md:grid-cols-4 gap-4 bg-white p-6 rounded-lg shadow-sm border border-indigo-100">
                    <div>
                        <label className="block text-xs font-bold text-gray-500 mb-1">Optimization Goal</label>
                        <select className="w-full p-2 border border-gray-300 rounded text-sm" value={optGoal} onChange={e => setOptGoal(e.target.value as any)}>
                            <option value="Maximize">Maximize Response</option>
                            <option value="Minimize">Minimize Response</option>
                            <option value="Target">Target Value</option>
                        </select>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-500 mb-1">Lower Limit</label>
                        <input type="number" className="w-full p-2 border border-gray-300 rounded text-sm" value={optMin} onChange={e => setOptMin(parseFloat(e.target.value))}/>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-500 mb-1">Upper Limit</label>
                        <input type="number" className="w-full p-2 border border-gray-300 rounded text-sm" value={optMax} onChange={e => setOptMax(parseFloat(e.target.value))}/>
                    </div>
                    {optGoal === 'Target' && (
                        <div>
                            <label className="block text-xs font-bold text-gray-500 mb-1">Target Value</label>
                            <input type="number" className="w-full p-2 border border-gray-300 rounded text-sm font-bold text-indigo-700" value={optTarget} onChange={e => setOptTarget(parseFloat(e.target.value))}/>
                        </div>
                    )}
                    <div className="md:col-span-4 flex justify-end mt-2">
                        <button 
                            onClick={findOptimalConditions}
                            className="bg-indigo-600 text-white px-6 py-2 rounded-lg hover:bg-indigo-700 font-bold flex items-center gap-2 shadow-lg shadow-indigo-200 transition-all"
                        >
                            <Search size={18} /> Find Best 3 Suggestions
                        </button>
                    </div>
                </div>

                {/* Optimization Results */}
                {topSuggestions.length > 0 && (
                     <div className="grid md:grid-cols-2 gap-8">
                         {/* Top 3 Cards */}
                         <div className="space-y-4">
                            <h3 className="font-bold text-indigo-800 flex items-center gap-2"><Target size={18} /> Best Conditions Found</h3>
                            {topSuggestions.map((suggestion, idx) => (
                                <div key={idx} className={`relative p-4 rounded-xl border ${idx===0 ? 'bg-yellow-50 border-yellow-200' : 'bg-white border-gray-200'} shadow-sm flex items-center gap-4 transition-transform hover:scale-[1.02]`}>
                                    <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-lg shadow-inner
                                        ${idx === 0 ? 'bg-yellow-400 text-yellow-900' : idx === 1 ? 'bg-gray-300 text-gray-700' : 'bg-orange-300 text-orange-900'}`}
                                    >
                                        {idx + 1}
                                    </div>
                                    <div className="flex-1">
                                        <div className="flex justify-between items-center mb-2">
                                            <span className="text-xs font-bold text-gray-500 uppercase tracking-wide">Desirability: {(suggestion.desirability * 100).toFixed(1)}%</span>
                                            <span className="text-sm font-bold text-indigo-700 bg-indigo-50 px-2 py-1 rounded">Pred: {suggestion.prediction.toFixed(3)} {getResponseUnit(plotResponse)}</span>
                                        </div>
                                        <div className="text-xs grid grid-cols-2 gap-x-4 gap-y-1 text-gray-700">
                                            {Object.entries(suggestion.factors).map(([k, v]) => (
                                                <div key={k} className="flex justify-between border-b border-gray-100 pb-1">
                                                    <span>{k}:</span> <strong>{(v as number).toFixed(2)}</strong>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            ))}
                         </div>

                         {/* Desirability Plot */}
                         <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                            <h3 className="font-bold text-indigo-800 mb-2 flex items-center gap-2">
                                <Activity size={18} /> Desirability Landscape
                            </h3>
                            <div id="plotDesirability" className="w-full h-[350px]"></div>
                            <p className="text-[10px] text-gray-400 text-center mt-2">
                                Red/Blue regions indicate areas with 0% desirability. Green/Red regions (1.0) match your goal.
                            </p>
                         </div>
                     </div>
                )}
            </div>

            {/* Prediction Simulator (Existing) */}
            {activeResult.modelCoefficients && (
                <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-lg">
                    <h3 className="text-xl font-bold text-science-900 mb-4 flex items-center gap-2">
                        <Calculator size={24} /> Predict Outcome Simulator
                    </h3>
                    <div className="grid md:grid-cols-3 gap-6 items-end">
                        {factors.map(f => (
                            <div key={f.name}>
                                <label className="block text-xs font-bold text-science-800 mb-1 uppercase">
                                    {f.name} {f.unit ? `(${f.unit})` : ''}
                                </label>
                                <input type="number" step="any" className="w-full p-2 border border-science-200 rounded text-sm focus:ring-2 focus:ring-science-500 outline-none" value={predictionInputs[f.name] || ''} onChange={(e) => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}/>
                            </div>
                        ))}
                    </div>
                    <div className="mt-6 flex items-center gap-6">
                        <button onClick={calculatePrediction} className="bg-science-600 text-white px-6 py-2 rounded-lg hover:bg-science-700 font-bold flex items-center gap-2 shadow-sm"><Play size={16} /> Predict Result</button>
                        {predictedValue !== null && (
                            <div className="bg-slate-100 px-6 py-2 rounded-lg border border-slate-300 shadow-sm flex items-center gap-3">
                                <span className="text-xs font-bold text-gray-500 uppercase">Predicted {plotResponse || 'Response'}:</span>
                                <span className="text-2xl font-bold text-science-700">{predictedValue.toFixed(4)}<span className="text-sm font-normal text-gray-500 ml-1">{getResponseUnit(plotResponse)}</span></span>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default AnalysisDashboard;

import React, { useEffect, useState, useCallback } from 'react';
import { AnalysisResult, FactorDefinition, ResponseDefinition } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, Calculator, Play, Sigma, Triangle, Trophy, Target, Search } from 'lucide-react';

declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
    isMixture?: boolean;
}

interface OptResult {
    factors: Record<string, number>;
    prediction: number;
    desirability: number;
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses, isMixture = false }) => {
    // Prediction State
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);

    // Plot Configuration State
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');

    // Optimization State
    const [optGoal, setOptGoal] = useState<'Maximize' | 'Minimize' | 'Target'>('Maximize');
    const [optTarget, setOptTarget] = useState<number>(0);
    const [optMin, setOptMin] = useState<number>(0);
    const [optMax, setOptMax] = useState<number>(100);
    const [topSuggestions, setTopSuggestions] = useState<OptResult[]>([]);

    // Initialize inputs and plot defaults
    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = isNaN(mid) ? "0" : mid.toString();
        });
        setPredictionInputs(initial);

        if (factors.length >= 2) {
            setPlotX(factors[0].name);
            setPlotY(factors[1].name);
        }
        if (responses.length > 0) {
            setPlotResponse(responses[0].name);
        }
    }, [factors, responses]);

    // Retrieve active result based on selected plotResponse
    const activeResult = results.resultsByResponse[plotResponse];

    // Helper: Get Range with safety check for empty data
    const getObservedRange = useCallback((resName: string) => {
        const res = results.resultsByResponse[resName];
        if (!res || !res.diagnostics || !res.diagnostics.actual || res.diagnostics.actual.length === 0) {
            return { min: 0, max: 100 };
        }
        const cleanData = res.diagnostics.actual.filter(v => typeof v === 'number' && !isNaN(v));
        if (cleanData.length === 0) return { min: 0, max: 100 };

        let min = Math.min(...cleanData);
        let max = Math.max(...cleanData);

        if (Math.abs(max - min) < 1e-9) {
            return { min: min - 1, max: max + 1 };
        }
        return { min, max };
    }, [results]);

    // Initialize Optimization Defaults when response changes
    useEffect(() => {
        const range = getObservedRange(plotResponse);
        setOptMin(range.min);
        setOptMax(range.max);
        setOptTarget((range.min + range.max) / 2);

        const resDef = responses.find(r => r.name === plotResponse);
        if (resDef) setOptGoal(resDef.goal);
    }, [plotResponse, getObservedRange, responses]);


    // Helper: Convert Real Value to Coded Value (-1 to +1)
    const toCoded = (val: number, factorName: string) => {
        const factor = factors.find(f => f.name === factorName);
        if (!factor) return 0;
        const low = parseFloat(factor.low);
        const high = parseFloat(factor.high);
        if (isNaN(low) || isNaN(high)) return 0;
        const mid = (high + low) / 2;
        const halfRange = (high - low) / 2;
        if (halfRange === 0) return 0;
        return (val - mid) / halfRange;
    };

    // Calculate prediction AND Clamp it to observed range
    const calculatePredictionInternal = (inputs: Record<string, string | number>) => {
         if (!activeResult || !activeResult.modelCoefficients) return 0;

        const { intercept, linear, quadratic, interactions } = activeResult.modelCoefficients;
        let y = typeof intercept === 'number' ? intercept : parseFloat(intercept as any) || 0;

        if (linear) {
            Object.entries(linear).forEach(([factorName, coeff]) => {
                const val = inputs[factorName];
                const realVal = typeof val === 'string' ? parseFloat(val) : val;
                const c = typeof coeff === 'number' ? coeff : parseFloat(coeff as any) || 0;
                if (typeof realVal === 'number' && !isNaN(realVal)) {
                    y += c * toCoded(realVal, factorName);
                }
            });
        }
        if (quadratic) {
            Object.entries(quadratic).forEach(([factorName, coeff]) => {
                const val = inputs[factorName];
                const realVal = typeof val === 'string' ? parseFloat(val) : val;
                const c = typeof coeff === 'number' ? coeff : parseFloat(coeff as any) || 0;
                if (typeof realVal === 'number' && !isNaN(realVal)) {
                    y += c * Math.pow(toCoded(realVal, factorName), 2);
                }
            });
        }
        if (interactions && Array.isArray(interactions)) {
            interactions.forEach(term => {
                const v1 = inputs[term.factor1];
                const v2 = inputs[term.factor2];
                const realVal1 = typeof v1 === 'string' ? parseFloat(v1) : v1;
                const realVal2 = typeof v2 === 'string' ? parseFloat(v2) : v2;
                const c = typeof term.coefficient === 'number' ? term.coefficient : parseFloat(term.coefficient as any) || 0;
                if (typeof realVal1 === 'number' && !isNaN(realVal1) && typeof realVal2 === 'number' && !isNaN(realVal2)) {
                    y += c * toCoded(realVal1, term.factor1) * toCoded(realVal2, term.factor2);
                }
            });
        }

        // PHYSICAL CLAMPING: Predictions must lie within the experimental domain's observed response range
        const { min, max } = getObservedRange(plotResponse);
        return Math.max(min, Math.min(max, y));
    };

    const calculatePrediction = () => {
        const val = calculatePredictionInternal(predictionInputs);
        setPredictedValue(val);
    };

    const calculateDesirability = (val: number) => {
        if (isNaN(val) || !isFinite(val)) return 0;
        const range = optMax - optMin;
        if (range <= 0) return 0;

        if (optGoal === 'Maximize') {
            if (val <= optMin) return 0;
            if (val >= optMax) return 1;
            return (val - optMin) / range;
        } else if (optGoal === 'Minimize') {
            if (val <= optMin) return 1;
            if (val >= optMax) return 0;
            return (optMax - val) / range;
        } else {
            // Target
            if (val < optMin || val > optMax) return 0;
            if (val === optTarget) return 1;
            const lowerRange = optTarget - optMin;
            const upperRange = optMax - optTarget;
            if (val < optTarget) {
                return lowerRange <= 0 ? 0 : (val - optMin) / lowerRange;
            } else {
                return upperRange <= 0 ? 0 : (optMax - val) / upperRange;
            }
        }
    };

    const findOptimalConditions = () => {
        if (!activeResult) return;
        const iterations = 8000;
        const suggestions: OptResult[] = [];

        for (let i = 0; i < iterations; i++) {
            const trialInputs: Record<string, number> = {};
            factors.forEach(f => {
                const min = parseFloat(f.low);
                const max = parseFloat(f.high);
                if (!isNaN(min) && !isNaN(max)) {
                     trialInputs[f.name] = min + Math.random() * (max - min);
                } else {
                    trialInputs[f.name] = 0;
                }
            });

            const pred = calculatePredictionInternal(trialInputs);
            const d = calculateDesirability(pred);
            if (!isNaN(pred) && !isNaN(d)) {
                suggestions.push({ factors: trialInputs, prediction: pred, desirability: d });
            }
        }

        suggestions.sort((a, b) => b.desirability - a.desirability);

        // Selection logic to ensure diversity of solutions (not just 3 points right next to each other)
        const uniqueTop: OptResult[] = [];
        for (const s of suggestions) {
            if (uniqueTop.length >= 3) break;
            const isDuplicate = uniqueTop.some(existing => {
                return factors.every(f => {
                    const low = parseFloat(f.low);
                    const high = parseFloat(f.high);
                    const range = Math.abs(high - low) || 1;
                    return Math.abs(existing.factors[f.name] - s.factors[f.name]) < (range * 0.10);
                });
            });
            if (!isDuplicate) uniqueTop.push(s);
        }

        setTopSuggestions(uniqueTop);
    };

    const getResponseUnit = (resName: string) => {
        const r = responses.find(r => r.name === resName);
        return r ? r.unit : '';
    };

    // Plots...
    useEffect(() => {
        let cleanup = false;
        try {
            if (!window.Plotly || !plotX || !plotY || !activeResult?.modelCoefficients) return;
            const factorX = factors.find(f => f.name === plotX);
            const factorY = factors.find(f => f.name === plotY);
            if(!factorX || !factorY) return;

            const xMin = parseFloat(factorX.low), xMax = parseFloat(factorX.high);
            const yMin = parseFloat(factorY.low), yMax = parseFloat(factorY.high);
            if(isNaN(xMin) || isNaN(xMax) || isNaN(yMin) || isNaN(yMax)) return;

            const steps = 30; 
            const xValues: number[] = [], yValues: number[] = [];
            const zMatrix: number[][] = [], dMatrix: number[][] = [];

            for(let i=0; i<=steps; i++) xValues.push(xMin + (i * (xMax - xMin) / steps));
            for(let i=0; i<=steps; i++) yValues.push(yMin + (i * (yMax - yMin) / steps));

            for(let j=0; j<=steps; j++) {
                const rowZ: number[] = [], rowD: number[] = [];
                for(let i=0; i<=steps; i++) {
                    const inputs: Record<string, string | number> = { ...predictionInputs };
                    inputs[plotX] = xValues[i];
                    inputs[plotY] = yValues[j];
                    const pred = calculatePredictionInternal(inputs);
                    rowZ.push(pred);
                    rowD.push(calculateDesirability(pred));
                }
                zMatrix.push(rowZ);
                dMatrix.push(rowD);
            }
            if(cleanup) return;

            const observed = getObservedRange(plotResponse);
            const zRange = [observed.min, observed.max];

            // 3D Surface
            window.Plotly.react('plot3d', [{
                z: zMatrix, x: xValues, y: yValues, type: 'surface', colorscale: 'Viridis', cmin: zRange[0], cmax: zRange[1]
            }], { 
                title: `Surface: ${plotResponse}`,
                scene: { xaxis: { title: plotX }, yaxis: { title: plotY }, zaxis: { title: plotResponse } },
                margin: { l: 0, r: 0, b: 0, t: 30 }
            });

            // Contour
            window.Plotly.react('plotContour', [{
                z: zMatrix, x: xValues, y: yValues, type: 'contour', colorscale: 'Viridis', cmin: zRange[0], cmax: zRange[1]
            }], { title: `Contour: ${plotResponse}`, xaxis: { title: plotX }, yaxis: { title: plotY } });

            // Desirability Contour with Marker Overlays
            const desTraces: any[] = [{
                z: dMatrix, x: xValues, y: yValues,
                type: 'contour', 
                colorscale: [[0, '#ef4444'], [0.5, '#facc15'], [1, '#22c55e']],
                zmin: 0, zmax: 1,
                colorbar: { title: 'Desirability', thickness: 15 }
            }];

            // Add markers for top suggestions if they exist in the current X-Y plane
            if (topSuggestions.length > 0) {
                const markerX = topSuggestions.map(s => s.factors[plotX]);
                const markerY = topSuggestions.map(s => s.factors[plotY]);
                desTraces.push({
                    x: markerX, y: markerY,
                    mode: 'markers+text',
                    type: 'scatter',
                    text: ['1', '2', '3'],
                    textposition: 'top center',
                    marker: { color: 'white', size: 12, line: { color: 'black', width: 2 } },
                    name: 'Best Suggestions'
                });
            }

            window.Plotly.react('plotDesirability', desTraces, { 
                title: `Desirability Map (Goal: ${optGoal})`, 
                xaxis: { title: plotX }, yaxis: { title: plotY },
                showlegend: false
            });

        } catch (e) { console.error(e); }
        return () => { cleanup = true; };
    }, [plotX, plotY, plotResponse, activeResult, predictionInputs, optGoal, optMin, optMax, optTarget, topSuggestions]);

    // Diagnostic Plots logic... (similar to previous version, ensuring they use activeResult)
    useEffect(() => {
        if (!window.Plotly || !activeResult?.diagnostics) return;
        const d = activeResult.diagnostics;
        const actualMin = Math.min(...d.actual), actualMax = Math.max(...d.actual);

        window.Plotly.react('plotPredVsActual', [
            { x: d.actual, y: d.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9' } },
            { x: [actualMin, actualMax], y: [actualMin, actualMax], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' } }
        ], { title: 'Predicted vs Actual', margin: { t: 30, b: 30, l: 30, r: 10 } });

        if (d.boxCox) {
            window.Plotly.react('plotBoxCox', [{ x: d.boxCox.lambda, y: d.boxCox.lnRSS, type: 'scatter', mode: 'lines', line: { color: '#8b5cf6', width: 3 } }], {
                title: 'Box-Cox Plot', xaxis: { title: 'Lambda' }, yaxis: { title: 'ln(RSS)' },
                shapes: d.boxCox.ciLimit ? [{ type: 'line', x0: Math.min(...d.boxCox.lambda), x1: Math.max(...d.boxCox.lambda), y0: d.boxCox.ciLimit, y1: d.boxCox.ciLimit, line: { color: 'red', dash: 'dash' } }] : []
            });
        }
    }, [activeResult]);

    if (!activeResult) return <div className="p-8 text-center text-gray-500">Select a response to view analysis details.</div>;

    return (
        <div className="space-y-8 pb-12">
            {/* Analysis Stats */}
            <div className="bg-white p-8 rounded-xl shadow-lg border border-gray-200">
                <h2 className="text-2xl font-bold text-science-900 mb-4 flex items-center gap-2"><LayoutDashboard /> Model Analysis: {plotResponse}</h2>
                <div className="grid md:grid-cols-3 gap-6 mb-6">
                    <div className="md:col-span-2 bg-slate-50 p-4 rounded-lg border border-slate-200">
                        <h4 className="text-xs font-bold text-science-600 uppercase mb-2 flex items-center gap-1"><Sigma size={14} /> Mathematical Model (Coded)</h4>
                        <p className="font-mono text-gray-800 text-sm">{activeResult.fitStatistics.equation || "Model not calculated."}</p>
                    </div>
                    <div className="bg-white p-4 rounded-lg border border-gray-200 grid grid-cols-2 gap-2">
                        <div><div className="text-[10px] text-gray-400">R²</div><div className="text-lg font-bold">{activeResult.fitStatistics.rSquared.toFixed(4)}</div></div>
                        <div><div className="text-[10px] text-gray-400">Adj. R²</div><div className="text-lg font-bold">{activeResult.fitStatistics.adjRSquared.toFixed(4)}</div></div>
                    </div>
                </div>
                <div className="prose prose-sm max-w-none text-gray-700 bg-slate-50 p-6 rounded border border-slate-200">
                    <ReactMarkdown>{activeResult.anovaText}</ReactMarkdown>
                </div>
            </div>

            {/* Diagnostics */}
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="bg-white p-2 rounded shadow h-[250px]"><div id="plotPredVsActual" className="w-full h-full"></div></div>
                <div className="bg-white p-2 rounded shadow h-[250px]"><div id="plotBoxCox" className="w-full h-full"></div></div>
                <div className="bg-blue-50 p-4 rounded border border-blue-100 flex flex-col justify-center">
                    <h4 className="font-bold text-blue-900 mb-2">Diagnostic Insight</h4>
                    <p className="text-xs text-blue-800">{activeResult.diagnosticInterpretations.predVsActual}</p>
                </div>
            </div>

            {/* Surfaces */}
            <div className="bg-science-50 p-4 rounded-lg flex flex-wrap gap-4 items-center">
                <div><label className="block text-xs font-bold text-gray-600">X-Axis</label><select className="p-2 rounded border" value={plotX} onChange={e => setPlotX(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select></div>
                <div><label className="block text-xs font-bold text-gray-600">Y-Axis</label><select className="p-2 rounded border" value={plotY} onChange={e => setPlotY(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select></div>
                <div><label className="block text-xs font-bold text-gray-600">Response</label><select className="p-2 rounded border" value={plotResponse} onChange={e => setPlotResponse(e.target.value)}>{responses.map(r => <option key={r.name} value={r.name}>{r.name}</option>)}</select></div>
            </div>

            <div className="grid md:grid-cols-2 gap-8">
                <div className="bg-white p-4 rounded-xl shadow border border-gray-200"><div id="plot3d" className="w-full h-[400px]"></div></div>
                <div className="bg-white p-4 rounded-xl shadow border border-gray-200"><div id="plotDesirability" className="w-full h-[400px]"></div></div>
            </div>

            {/* Optimization Results */}
            <div className="bg-gradient-to-b from-indigo-50 to-white p-8 rounded-xl border border-indigo-100 shadow-xl">
                <div className="flex justify-between items-center mb-6">
                    <h2 className="text-2xl font-bold text-indigo-900 flex items-center gap-2"><Trophy className="text-yellow-500" /> Goal Optimization: {plotResponse}</h2>
                    <button onClick={findOptimalConditions} className="bg-indigo-600 text-white px-6 py-2 rounded-lg hover:bg-indigo-700 font-bold flex items-center gap-2 shadow-lg"><Search size={18} /> Solve Optimization</button>
                </div>
                <div className="grid md:grid-cols-4 gap-4 mb-8">
                    <div><label className="text-xs font-bold text-gray-500">Goal</label><select className="w-full p-2 border rounded" value={optGoal} onChange={e => setOptGoal(e.target.value as any)}><option value="Maximize">Maximize</option><option value="Minimize">Minimize</option><option value="Target">Target</option></select></div>
                    <div><label className="text-xs font-bold text-gray-500">Min Threshold</label><input type="number" className="w-full p-2 border rounded" value={optMin} onChange={e => setOptMin(parseFloat(e.target.value))}/></div>
                    <div><label className="text-xs font-bold text-gray-500">Max Threshold</label><input type="number" className="w-full p-2 border rounded" value={optMax} onChange={e => setOptMax(parseFloat(e.target.value))}/></div>
                    {optGoal === 'Target' && <div><label className="text-xs font-bold text-gray-500">Target Value</label><input type="number" className="w-full p-2 border rounded" value={optTarget} onChange={e => setOptTarget(parseFloat(e.target.value))}/></div>}
                </div>
                {topSuggestions.length > 0 && (
                    <div className="grid md:grid-cols-3 gap-6">
                        {topSuggestions.map((s, idx) => (
                            <div key={idx} className={`p-4 rounded-xl border-2 ${idx === 0 ? 'border-green-500 bg-green-50' : 'border-gray-200 bg-white'} shadow-sm`}>
                                <div className="flex justify-between items-center mb-2">
                                    <span className="text-xs font-bold text-gray-400"># {idx + 1} Recommendation</span>
                                    <span className="text-xs font-bold text-indigo-600">Prob: {(s.desirability * 100).toFixed(1)}%</span>
                                </div>
                                <div className="text-lg font-bold text-indigo-900 mb-2">{s.prediction.toFixed(3)} {getResponseUnit(plotResponse)}</div>
                                <div className="space-y-1">
                                    {Object.entries(s.factors).map(([k, v]) => (
                                        <div key={k} className="flex justify-between text-xs border-b pb-1"><span>{k}:</span><span className="font-bold">{v.toFixed(2)}</span></div>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* Predictor */}
            <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-lg">
                <h3 className="text-xl font-bold text-science-900 mb-4 flex items-center gap-2"><Calculator size={24} /> Model Predictor</h3>
                <div className="grid md:grid-cols-3 gap-6">
                    {factors.map(f => (
                        <div key={f.name}>
                            <label className="block text-xs font-bold text-gray-500 mb-1">{f.name} ({f.low} - {f.high})</label>
                            <input type="number" step="any" className="w-full p-2 border rounded focus:ring-2 ring-science-500 outline-none" value={predictionInputs[f.name] || ''} onChange={(e) => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}/>
                        </div>
                    ))}
                </div>
                <div className="mt-6 flex items-center gap-6">
                    <button onClick={calculatePrediction} className="bg-science-600 text-white px-8 py-2 rounded-lg hover:bg-science-700 font-bold flex items-center gap-2"><Play size={16} /> Predict Result</button>
                    {predictedValue !== null && (
                        <div className="bg-science-50 px-8 py-2 rounded-lg border border-science-200">
                            <span className="text-xs font-bold text-science-600 block">Clamped Model Output:</span>
                            <span className="text-2xl font-bold text-science-900">{predictedValue.toFixed(4)} <span className="text-sm font-normal text-gray-500">{getResponseUnit(plotResponse)}</span></span>
                        </div>
                    )}
                </div>
                <p className="text-[10px] text-gray-400 mt-4 italic">* Prediction is derived from the regression model coefficients and clamped to the observed experimental range.</p>
            </div>
        </div>
    );
};

export default AnalysisDashboard;

import React, { useEffect, useState, useCallback } from 'react';
import { AnalysisResult, FactorDefinition, ResponseDefinition } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, Calculator, Play, Sigma, Triangle, Trophy, Target, Search } from 'lucide-react';

declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
    isMixture?: boolean;
}

interface OptResult {
    factors: Record<string, number>;
    prediction: number;
    desirability: number;
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses, isMixture = false }) => {
    // Prediction State
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);

    // Plot Configuration State
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');

    // Optimization State
    const [optGoal, setOptGoal] = useState<'Maximize' | 'Minimize' | 'Target'>('Maximize');
    const [optTarget, setOptTarget] = useState<number>(0);
    const [optMin, setOptMin] = useState<number>(0);
    const [optMax, setOptMax] = useState<number>(100);
    const [topSuggestions, setTopSuggestions] = useState<OptResult[]>([]);

    // Initialize inputs and plot defaults
    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = isNaN(mid) ? "0" : mid.toString();
        });
        setPredictionInputs(initial);

        if (factors.length >= 2) {
            setPlotX(factors[0].name);
            setPlotY(factors[1].name);
        }
        if (responses.length > 0) {
            setPlotResponse(responses[0].name);
        }
    }, [factors, responses]);

    // Retrieve active result based on selected plotResponse
    const activeResult = results.resultsByResponse[plotResponse];

    // Helper: Get Range with safety check for empty data
    const getObservedRange = useCallback((resName: string) => {
        const res = results.resultsByResponse[resName];
        if (!res || !res.diagnostics || !res.diagnostics.actual || res.diagnostics.actual.length === 0) {
            return { min: 0, max: 100 };
        }
        const cleanData = res.diagnostics.actual.filter(v => typeof v === 'number' && !isNaN(v));
        if (cleanData.length === 0) return { min: 0, max: 100 };

        let min = Math.min(...cleanData);
        let max = Math.max(...cleanData);

        if (Math.abs(max - min) < 1e-9) {
            return { min: min - 1, max: max + 1 };
        }
        return { min, max };
    }, [results]);

    // Initialize Optimization Defaults when response changes
    useEffect(() => {
        const range = getObservedRange(plotResponse);
        setOptMin(range.min);
        setOptMax(range.max);
        setOptTarget((range.min + range.max) / 2);

        const resDef = responses.find(r => r.name === plotResponse);
        if (resDef) setOptGoal(resDef.goal);
    }, [plotResponse, getObservedRange, responses]);


    // Helper: Convert Real Value to Coded Value (-1 to +1)
    const toCoded = (val: number, factorName: string) => {
        const factor = factors.find(f => f.name === factorName);
        if (!factor) return 0;
        const low = parseFloat(factor.low);
        const high = parseFloat(factor.high);
        if (isNaN(low) || isNaN(high)) return 0;
        const mid = (high + low) / 2;
        const halfRange = (high - low) / 2;
        if (halfRange === 0) return 0;
        return (val - mid) / halfRange;
    };

    // Calculate prediction AND Clamp it to observed range
    const calculatePredictionInternal = (inputs: Record<string, string | number>) => {
         if (!activeResult || !activeResult.modelCoefficients) return 0;

        const { intercept, linear, quadratic, interactions } = activeResult.modelCoefficients;
        let y = typeof intercept === 'number' ? intercept : parseFloat(intercept as any) || 0;

        if (linear) {
            Object.entries(linear).forEach(([factorName, coeff]) => {
                const val = inputs[factorName];
                const realVal = typeof val === 'string' ? parseFloat(val) : val;
                const c = typeof coeff === 'number' ? coeff : parseFloat(coeff as any) || 0;
                if (typeof realVal === 'number' && !isNaN(realVal)) {
                    y += c * toCoded(realVal, factorName);
                }
            });
        }
        if (quadratic) {
            Object.entries(quadratic).forEach(([factorName, coeff]) => {
                const val = inputs[factorName];
                const realVal = typeof val === 'string' ? parseFloat(val) : val;
                const c = typeof coeff === 'number' ? coeff : parseFloat(coeff as any) || 0;
                if (typeof realVal === 'number' && !isNaN(realVal)) {
                    y += c * Math.pow(toCoded(realVal, factorName), 2);
                }
            });
        }
        if (interactions && Array.isArray(interactions)) {
            interactions.forEach(term => {
                const v1 = inputs[term.factor1];
                const v2 = inputs[term.factor2];
                const realVal1 = typeof v1 === 'string' ? parseFloat(v1) : v1;
                const realVal2 = typeof v2 === 'string' ? parseFloat(v2) : v2;
                const c = typeof term.coefficient === 'number' ? term.coefficient : parseFloat(term.coefficient as any) || 0;
                if (typeof realVal1 === 'number' && !isNaN(realVal1) && typeof realVal2 === 'number' && !isNaN(realVal2)) {
                    y += c * toCoded(realVal1, term.factor1) * toCoded(realVal2, term.factor2);
                }
            });
        }

        // PHYSICAL CLAMPING: Predictions must lie within the experimental domain's observed response range
        const { min, max } = getObservedRange(plotResponse);
        return Math.max(min, Math.min(max, y));
    };

    const calculatePrediction = () => {
        const val = calculatePredictionInternal(predictionInputs);
        setPredictedValue(val);
    };

    const calculateDesirability = (val: number) => {
        if (isNaN(val) || !isFinite(val)) return 0;
        const range = optMax - optMin;
        if (range <= 0) return 0;

        if (optGoal === 'Maximize') {
            if (val <= optMin) return 0;
            if (val >= optMax) return 1;
            return (val - optMin) / range;
        } else if (optGoal === 'Minimize') {
            if (val <= optMin) return 1;
            if (val >= optMax) return 0;
            return (optMax - val) / range;
        } else {
            // Target
            if (val < optMin || val > optMax) return 0;
            if (val === optTarget) return 1;
            const lowerRange = optTarget - optMin;
            const upperRange = optMax - optTarget;
            if (val < optTarget) {
                return lowerRange <= 0 ? 0 : (val - optMin) / lowerRange;
            } else {
                return upperRange <= 0 ? 0 : (optMax - val) / upperRange;
            }
        }
    };

    const findOptimalConditions = () => {
        if (!activeResult) return;
        const iterations = 10000;
        const suggestions: OptResult[] = [];

        for (let i = 0; i < iterations; i++) {
            const trialInputs: Record<string, number> = {};
            factors.forEach(f => {
                const min = parseFloat(f.low);
                const max = parseFloat(f.high);
                if (!isNaN(min) && !isNaN(max)) {
                     trialInputs[f.name] = min + Math.random() * (max - min);
                } else {
                    trialInputs[f.name] = 0;
                }
            });

            const pred = calculatePredictionInternal(trialInputs);
            const d = calculateDesirability(pred);
            if (!isNaN(pred) && !isNaN(d)) {
                suggestions.push({ factors: trialInputs, prediction: pred, desirability: d });
            }
        }

        suggestions.sort((a, b) => b.desirability - a.desirability);

        const uniqueTop: OptResult[] = [];
        for (const s of suggestions) {
            if (uniqueTop.length >= 3) break;
            const isDuplicate = uniqueTop.some(existing => {
                return factors.every(f => {
                    const low = parseFloat(f.low);
                    const high = parseFloat(f.high);
                    const range = Math.abs(high - low) || 1;
                    return Math.abs(existing.factors[f.name] - s.factors[f.name]) < (range * 0.12);
                });
            });
            if (!isDuplicate) uniqueTop.push(s);
        }

        setTopSuggestions(uniqueTop);
    };

    const getResponseUnit = (resName: string) => {
        const r = responses.find(r => r.name === resName);
        return r ? r.unit : '';
    };

    // Plots...
    useEffect(() => {
        let cleanup = false;
        try {
            if (!window.Plotly || !plotX || !plotY || !activeResult?.modelCoefficients) return;
            const factorX = factors.find(f => f.name === plotX);
            const factorY = factors.find(f => f.name === plotY);
            if(!factorX || !factorY) return;

            const xMin = parseFloat(factorX.low), xMax = parseFloat(factorX.high);
            const yMin = parseFloat(factorY.low), yMax = parseFloat(factorY.high);
            if(isNaN(xMin) || isNaN(xMax) || isNaN(yMin) || isNaN(yMax)) return;

            const steps = 40; 
            const xValues: number[] = [], yValues: number[] = [];
            const zMatrix: number[][] = [], dMatrix: number[][] = [];

            for(let i=0; i<=steps; i++) xValues.push(xMin + (i * (xMax - xMin) / steps));
            for(let i=0; i<=steps; i++) yValues.push(yMin + (i * (yMax - yMin) / steps));

            for(let j=0; j<=steps; j++) {
                const rowZ: number[] = [], rowD: number[] = [];
                for(let i=0; i<=steps; i++) {
                    const inputs: Record<string, string | number> = { ...predictionInputs };
                    inputs[plotX] = xValues[i];
                    inputs[plotY] = yValues[j];
                    const pred = calculatePredictionInternal(inputs);
                    rowZ.push(pred);
                    rowD.push(calculateDesirability(pred));
                }
                zMatrix.push(rowZ);
                dMatrix.push(rowD);
            }
            if(cleanup) return;

            const observed = getObservedRange(plotResponse);
            const zRange = [observed.min, observed.max];

            // Common Marker Trace for Overlays
            const markerTrace = topSuggestions.length > 0 ? {
                x: topSuggestions.map(s => s.factors[plotX]),
                y: topSuggestions.map(s => s.factors[plotY]),
                mode: 'markers+text',
                type: 'scatter',
                text: ['1', '2', '3'],
                textposition: 'top center',
                marker: { color: 'white', size: 10, line: { color: 'black', width: 2 } },
                showlegend: false
            } : null;

            // 1. 3D Surface
            const p3d = document.getElementById('plot3d');
            if (p3d) {
                window.Plotly.react('plot3d', [{
                    z: zMatrix, x: xValues, y: yValues, type: 'surface', colorscale: 'Viridis', cmin: zRange[0], cmax: zRange[1]
                }], { 
                    title: `Surface: ${plotResponse}`,
                    scene: { xaxis: { title: plotX }, yaxis: { title: plotY }, zaxis: { title: plotResponse } },
                    margin: { l: 0, r: 0, b: 0, t: 30 }
                });
            }

            // 2. Response Contour
            const pContour = document.getElementById('plotContour');
            if (pContour) {
                const contourTraces: any[] = [{
                    z: zMatrix, x: xValues, y: yValues, type: 'contour', colorscale: 'Viridis', cmin: zRange[0], cmax: zRange[1],
                    contours: { showlabels: true }
                }];
                if (markerTrace) contourTraces.push(markerTrace);
                window.Plotly.react('plotContour', contourTraces, { title: `Response Map: ${plotResponse}`, xaxis: { title: plotX }, yaxis: { title: plotY } });
            }

            // 3. Desirability Contour
            const pDes = document.getElementById('plotDesirability');
            if (pDes) {
                const desTraces: any[] = [{
                    z: dMatrix, x: xValues, y: yValues,
                    type: 'contour', 
                    colorscale: [[0, '#ef4444'], [0.3, '#f97316'], [0.7, '#facc15'], [1, '#22c55e']],
                    zmin: 0, zmax: 1,
                    colorbar: { title: 'Prob.', thickness: 15 },
                    contours: { showlabels: true }
                }];
                if (markerTrace) desTraces.push(markerTrace);
                window.Plotly.react('plotDesirability', desTraces, { 
                    title: `Desirability Prob. Map (0-1)`, 
                    xaxis: { title: plotX }, yaxis: { title: plotY },
                    showlegend: false
                });
            }

        } catch (e) { console.error(e); }
        return () => { cleanup = true; };
    }, [plotX, plotY, plotResponse, activeResult, predictionInputs, optGoal, optMin, optMax, optTarget, topSuggestions]);

    // Diagnostic Plots logic
    useEffect(() => {
        if (!window.Plotly || !activeResult?.diagnostics) return;
        const d = activeResult.diagnostics;
        const actualMin = Math.min(...d.actual), actualMax = Math.max(...d.actual);

        const pFit = document.getElementById('plotPredVsActual');
        if (pFit) {
            window.Plotly.react('plotPredVsActual', [
                { x: d.actual, y: d.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9' } },
                { x: [actualMin, actualMax], y: [actualMin, actualMax], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' } }
            ], { title: 'Predicted vs Actual', margin: { t: 30, b: 30, l: 30, r: 10 }, xaxis: { title: 'Actual' }, yaxis: { title: 'Predicted' } });
        }

        const pBox = document.getElementById('plotBoxCox');
        if (pBox && d.boxCox) {
            window.Plotly.react('plotBoxCox', [{ x: d.boxCox.lambda, y: d.boxCox.lnRSS, type: 'scatter', mode: 'lines', line: { color: '#8b5cf6', width: 3 } }], {
                title: 'Box-Cox Plot', xaxis: { title: 'Lambda' }, yaxis: { title: 'ln(RSS)' },
                shapes: d.boxCox.ciLimit ? [{ type: 'line', x0: Math.min(...d.boxCox.lambda), x1: Math.max(...d.boxCox.lambda), y0: d.boxCox.ciLimit, y1: d.boxCox.ciLimit, line: { color: 'red', dash: 'dash' } }] : []
            });
        }
    }, [activeResult]);

    if (!activeResult) return <div className="p-8 text-center text-gray-500">Select a response to view analysis details.</div>;

    return (
        <div className="space-y-8 pb-12">
            {/* Analysis Stats */}
            <div className="bg-white p-8 rounded-xl shadow-lg border border-gray-200">
                <h2 className="text-2xl font-bold text-science-900 mb-4 flex items-center gap-2"><LayoutDashboard /> Model Analysis: {plotResponse}</h2>
                <div className="grid md:grid-cols-3 gap-6 mb-6">
                    <div className="md:col-span-2 bg-slate-50 p-4 rounded-lg border border-slate-200">
                        <h4 className="text-xs font-bold text-science-600 uppercase mb-2 flex items-center gap-1"><Sigma size={14} /> Mathematical Model (Coded)</h4>
                        <p className="font-mono text-gray-800 text-sm">{activeResult.fitStatistics.equation || "Model not calculated."}</p>
                    </div>
                    <div className="bg-white p-4 rounded-lg border border-gray-200 grid grid-cols-2 gap-2">
                        <div><div className="text-[10px] text-gray-400 uppercase font-bold">R²</div><div className="text-lg font-bold">{activeResult.fitStatistics.rSquared.toFixed(4)}</div></div>
                        <div><div className="text-[10px] text-gray-400 uppercase font-bold">Adj. R²</div><div className="text-lg font-bold">{activeResult.fitStatistics.adjRSquared.toFixed(4)}</div></div>
                    </div>
                </div>
                <div className="prose prose-sm max-w-none text-gray-700 bg-slate-50 p-6 rounded border border-slate-200 shadow-inner overflow-auto max-h-[400px]">
                    <ReactMarkdown>{activeResult.anovaText}</ReactMarkdown>
                </div>
            </div>

            {/* Diagnostics */}
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="bg-white p-2 rounded shadow h-[250px]"><div id="plotPredVsActual" className="w-full h-full"></div></div>
                <div className="bg-white p-2 rounded shadow h-[250px]"><div id="plotBoxCox" className="w-full h-full"></div></div>
                <div className="bg-blue-50 p-4 rounded border border-blue-100 flex flex-col justify-center">
                    <h4 className="font-bold text-blue-900 mb-2">Diagnostic Insight</h4>
                    <p className="text-xs text-blue-800 leading-relaxed italic">"{activeResult.diagnosticInterpretations.predVsActual}"</p>
                    <p className="text-xs text-blue-600 mt-2">Box-Cox: {activeResult.diagnosticInterpretations.boxCox}</p>
                </div>
            </div>

            {/* Surfaces Selection */}
            <div className="bg-science-50 p-4 rounded-lg flex flex-wrap gap-6 items-center border border-science-100 shadow-sm">
                <div><label className="block text-[10px] font-bold text-gray-400 uppercase mb-1">X-Axis Factor</label><select className="p-2 rounded border text-sm font-medium" value={plotX} onChange={e => setPlotX(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select></div>
                <div><label className="block text-[10px] font-bold text-gray-400 uppercase mb-1">Y-Axis Factor</label><select className="p-2 rounded border text-sm font-medium" value={plotY} onChange={e => setPlotY(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select></div>
                <div><label className="block text-[10px] font-bold text-gray-400 uppercase mb-1">Response CQA</label><select className="p-2 rounded border text-sm font-medium" value={plotResponse} onChange={e => setPlotResponse(e.target.value)}>{responses.map(r => <option key={r.name} value={r.name}>{r.name}</option>)}</select></div>
            </div>

            {/* Visualization Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="bg-white p-4 rounded-xl shadow border border-gray-200"><div id="plot3d" className="w-full h-[350px]"></div></div>
                <div className="bg-white p-4 rounded-xl shadow border border-gray-200"><div id="plotContour" className="w-full h-[350px]"></div></div>
                <div className="bg-white p-4 rounded-xl shadow border border-gray-200"><div id="plotDesirability" className="w-full h-[350px]"></div></div>
            </div>

            {/* Optimization Results */}
            <div className="bg-gradient-to-b from-indigo-50 to-white p-8 rounded-xl border border-indigo-100 shadow-xl">
                <div className="flex justify-between items-center mb-6">
                    <div>
                        <h2 className="text-2xl font-bold text-indigo-900 flex items-center gap-2"><Trophy className="text-yellow-500" /> Multi-Objective Optimization</h2>
                        <p className="text-xs text-indigo-500">Numerical optimization based on defined goals for <strong>{plotResponse}</strong></p>
                    </div>
                    <button onClick={findOptimalConditions} className="bg-indigo-600 text-white px-8 py-3 rounded-lg hover:bg-indigo-700 font-bold flex items-center gap-2 shadow-lg transition-all hover:scale-105 active:scale-95"><Search size={18} /> Solve Optimization</button>
                </div>

                <div className="grid md:grid-cols-4 gap-4 mb-8 bg-white/50 p-4 rounded-lg">
                    <div><label className="text-[10px] font-bold text-gray-500 uppercase">Goal</label><select className="w-full p-2 border rounded text-sm" value={optGoal} onChange={e => setOptGoal(e.target.value as any)}><option value="Maximize">Maximize</option><option value="Minimize">Minimize</option><option value="Target">Target</option></select></div>
                    <div><label className="text-[10px] font-bold text-gray-500 uppercase">Lower Limit</label><input type="number" className="w-full p-2 border rounded text-sm" value={optMin} onChange={e => setOptMin(parseFloat(e.target.value))}/></div>
                    <div><label className="text-[10px] font-bold text-gray-500 uppercase">Upper Limit</label><input type="number" className="w-full p-2 border rounded text-sm" value={optMax} onChange={e => setOptMax(parseFloat(e.target.value))}/></div>
                    {optGoal === 'Target' && <div><label className="text-[10px] font-bold text-gray-500 uppercase">Target Value</label><input type="number" className="w-full p-2 border rounded text-sm font-bold text-indigo-700" value={optTarget} onChange={e => setOptTarget(parseFloat(e.target.value))}/></div>}
                </div>

                {topSuggestions.length > 0 ? (
                    <div className="grid md:grid-cols-3 gap-6">
                        {topSuggestions.map((s, idx) => (
                            <div key={idx} className={`relative p-5 rounded-xl border-2 transition-all hover:shadow-md ${idx === 0 ? 'border-green-500 bg-green-50' : 'border-gray-200 bg-white'}`}>
                                <div className="absolute -top-3 -right-3 w-8 h-8 rounded-full bg-indigo-600 text-white flex items-center justify-center font-bold shadow-md">{idx + 1}</div>
                                <div className="flex justify-between items-center mb-3">
                                    <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Recommendation</span>
                                    <span className="text-xs font-bold text-green-600 bg-green-100 px-2 py-0.5 rounded-full">Des: {(s.desirability * 100).toFixed(1)}%</span>
                                </div>
                                <div className="text-xl font-bold text-indigo-900 mb-4">{s.prediction.toFixed(3)} <span className="text-sm font-normal text-gray-400">{getResponseUnit(plotResponse)}</span></div>
                                <div className="space-y-2">
                                    {Object.entries(s.factors).map(([k, v]) => (
                                        <div key={k} className="flex justify-between text-xs border-b border-gray-100 pb-1.5">
                                            <span className="text-gray-500">{k}:</span>
                                            <span className="font-bold text-gray-800">{v.toFixed(2)}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="text-center p-12 text-indigo-300 border-2 border-dashed border-indigo-100 rounded-xl">
                        Click "Solve Optimization" to generate the best solutions within your design space.
                    </div>
                )}
            </div>

            {/* Predictor */}
            <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-lg">
                <h3 className="text-xl font-bold text-science-900 mb-4 flex items-center gap-2"><Calculator size={24} /> Equation-Based Predictor</h3>
                <div className="grid md:grid-cols-3 lg:grid-cols-4 gap-6">
                    {factors.map(f => (
                        <div key={f.name}>
                            <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1">{f.name} ({f.low} - {f.high})</label>
                            <input type="number" step="any" className="w-full p-2 border rounded focus:ring-2 ring-science-500 outline-none text-sm" value={predictionInputs[f.name] || ''} onChange={(e) => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}/>
                        </div>
                    ))}
                </div>
                <div className="mt-8 flex items-center gap-8 border-t pt-6">
                    <button onClick={calculatePrediction} className="bg-science-600 text-white px-10 py-3 rounded-lg hover:bg-science-700 font-bold flex items-center gap-2 shadow-lg active:scale-95 transition-all"><Play size={18} /> Predict Result</button>
                    {predictedValue !== null && (
                        <div className="bg-science-50 px-10 py-3 rounded-lg border border-science-200 flex flex-col">
                            <span className="text-[10px] font-bold text-science-600 uppercase">Clamped Model Estimate:</span>
                            <span className="text-3xl font-black text-science-900 leading-none">{predictedValue.toFixed(4)} <span className="text-sm font-normal text-gray-400">{getResponseUnit(plotResponse)}</span></span>
                        </div>
                    )}
                </div>
                <p className="text-[10px] text-gray-400 mt-4 italic">* Prediction is derived strictly from coded model coefficients and clamped to valid experimental boundaries to prevent extrapolation artifacts.</p>
            </div>
        </div>
    );
};

export default AnalysisDashboard;

import React, { useEffect, useState, useCallback } from 'react';
import { AnalysisResult, FactorDefinition, ResponseDefinition } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, Calculator, Play, Sigma, Triangle, Trophy, Target, Search, MousePointer2 } from 'lucide-react';

declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
    isMixture?: boolean;
}

interface OptResult {
    factors: Record<string, number>;
    prediction: number;
    desirability: number;
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses, isMixture = false }) => {
    // Prediction State
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);

    // Plot Configuration State
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');

    // Optimization State
    const [optGoal, setOptGoal] = useState<'Maximize' | 'Minimize' | 'Target'>('Maximize');
    const [optTarget, setOptTarget] = useState<number>(0);
    const [optMin, setOptMin] = useState<number>(0);
    const [optMax, setOptMax] = useState<number>(100);
    const [topSuggestions, setTopSuggestions] = useState<OptResult[]>([]);

    // Initialize inputs and plot defaults
    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = isNaN(mid) ? "0" : mid.toString();
        });
        setPredictionInputs(initial);

        if (factors.length >= 2) {
            setPlotX(factors[0].name);
            setPlotY(factors[1].name);
        }
        if (responses.length > 0) {
            setPlotResponse(responses[0].name);
        }
    }, [factors, responses]);

    // Retrieve active result based on selected plotResponse
    const activeResult = results.resultsByResponse[plotResponse];

    // Helper: Get Range with safety check for empty data
    const getObservedRange = useCallback((resName: string) => {
        const res = results.resultsByResponse[resName];
        if (!res || !res.diagnostics || !res.diagnostics.actual || res.diagnostics.actual.length === 0) {
            return { min: 0, max: 100 };
        }
        const cleanData = res.diagnostics.actual.filter(v => typeof v === 'number' && !isNaN(v));
        if (cleanData.length === 0) return { min: 0, max: 100 };

        let min = Math.min(...cleanData);
        let max = Math.max(...cleanData);

        if (Math.abs(max - min) < 1e-9) {
            return { min: min - 1, max: max + 1 };
        }
        return { min, max };
    }, [results]);

    // Initialize Optimization Defaults when response changes
    useEffect(() => {
        const range = getObservedRange(plotResponse);
        setOptMin(range.min);
        setOptMax(range.max);
        setOptTarget((range.min + range.max) / 2);

        const resDef = responses.find(r => r.name === plotResponse);
        if (resDef) setOptGoal(resDef.goal);
    }, [plotResponse, getObservedRange, responses]);


    // Helper: Convert Real Value to Coded Value (-1 to +1)
    const toCoded = (val: number, factorName: string) => {
        const factor = factors.find(f => f.name === factorName);
        if (!factor) return 0;
        const low = parseFloat(factor.low);
        const high = parseFloat(factor.high);
        if (isNaN(low) || isNaN(high)) return 0;
        const mid = (high + low) / 2;
        const halfRange = (high - low) / 2;
        if (halfRange === 0) return 0;
        return (val - mid) / halfRange;
    };

    // Strict Equation Calculation Logic
    const calculatePredictionInternal = useCallback((inputs: Record<string, string | number>) => {
         if (!activeResult || !activeResult.modelCoefficients) return 0;

        const { intercept, linear, quadratic, interactions } = activeResult.modelCoefficients;
        let y = typeof intercept === 'number' ? intercept : parseFloat(intercept as any) || 0;

        if (linear) {
            Object.entries(linear).forEach(([factorName, coeff]) => {
                const val = inputs[factorName];
                const realVal = typeof val === 'string' ? parseFloat(val) : val;
                const c = typeof coeff === 'number' ? coeff : parseFloat(coeff as any) || 0;
                if (typeof realVal === 'number' && !isNaN(realVal)) {
                    y += c * toCoded(realVal, factorName);
                }
            });
        }
        if (quadratic) {
            Object.entries(quadratic).forEach(([factorName, coeff]) => {
                const val = inputs[factorName];
                const realVal = typeof val === 'string' ? parseFloat(val) : val;
                const c = typeof coeff === 'number' ? coeff : parseFloat(coeff as any) || 0;
                if (typeof realVal === 'number' && !isNaN(realVal)) {
                    y += c * Math.pow(toCoded(realVal, factorName), 2);
                }
            });
        }
        if (interactions && Array.isArray(interactions)) {
            interactions.forEach(term => {
                const v1 = inputs[term.factor1];
                const v2 = inputs[term.factor2];
                const realVal1 = typeof v1 === 'string' ? parseFloat(v1) : v1;
                const realVal2 = typeof v2 === 'string' ? parseFloat(v2) : v2;
                const c = typeof term.coefficient === 'number' ? term.coefficient : parseFloat(term.coefficient as any) || 0;
                if (typeof realVal1 === 'number' && !isNaN(realVal1) && typeof realVal2 === 'number' && !isNaN(realVal2)) {
                    y += c * toCoded(realVal1, term.factor1) * toCoded(realVal2, term.factor2);
                }
            });
        }

        // PHYSICAL BOUNDARIES: We strictly clamp the prediction to the domain of observed results
        // This ensures the model does not "hallucinate" extreme values outside the experimental range.
        const { min, max } = getObservedRange(plotResponse);
        return Math.max(min, Math.min(max, y));
    }, [activeResult, factors, getObservedRange, plotResponse]);

    const calculatePrediction = () => {
        const val = calculatePredictionInternal(predictionInputs);
        setPredictedValue(val);
    };

    // Desirability Function (Individual Response)
    const calculateDesirability = useCallback((val: number) => {
        if (isNaN(val) || !isFinite(val)) return 0;
        const range = optMax - optMin;
        if (range <= 0) return 0;

        if (optGoal === 'Maximize') {
            if (val <= optMin) return 0;
            if (val >= optMax) return 1;
            return (val - optMin) / range;
        } else if (optGoal === 'Minimize') {
            if (val <= optMin) return 1;
            if (val >= optMax) return 0;
            return (optMax - val) / range;
        } else {
            // Target
            if (val < optMin || val > optMax) return 0;
            if (val === optTarget) return 1;
            const lowerRange = optTarget - optMin;
            const upperRange = optMax - optTarget;
            if (val < optTarget) {
                return lowerRange <= 0 ? 0 : (val - optMin) / lowerRange;
            } else {
                return upperRange <= 0 ? 0 : (optMax - val) / upperRange;
            }
        }
    }, [optMax, optMin, optGoal, optTarget]);

    // Optimization Solver
    const findOptimalConditions = () => {
        if (!activeResult) return;
        const iterations = 15000;
        const suggestions: OptResult[] = [];

        for (let i = 0; i < iterations; i++) {
            const trialInputs: Record<string, number> = {};
            factors.forEach(f => {
                const min = parseFloat(f.low);
                const max = parseFloat(f.high);
                if (!isNaN(min) && !isNaN(max)) {
                     // Strictly abide by the ranges given
                     trialInputs[f.name] = min + Math.random() * (max - min);
                } else {
                    trialInputs[f.name] = 0;
                }
            });

            const pred = calculatePredictionInternal(trialInputs);
            const d = calculateDesirability(pred);
            if (!isNaN(pred) && !isNaN(d)) {
                suggestions.push({ factors: trialInputs, prediction: pred, desirability: d });
            }
        }

        suggestions.sort((a, b) => b.desirability - a.desirability);

        // Filter for unique suggestions (spatially separated)
        const uniqueTop: OptResult[] = [];
        for (const s of suggestions) {
            if (uniqueTop.length >= 3) break;
            const isDuplicate = uniqueTop.some(existing => {
                return factors.every(f => {
                    const low = parseFloat(f.low);
                    const high = parseFloat(f.high);
                    const range = Math.abs(high - low) || 1;
                    return Math.abs(existing.factors[f.name] - s.factors[f.name]) < (range * 0.15);
                });
            });
            if (!isDuplicate) uniqueTop.push(s);
        }

        setTopSuggestions(uniqueTop);
    };

    const getResponseUnit = (resName: string) => {
        const r = responses.find(r => r.name === resName);
        return r ? r.unit : '';
    };

    // Plotting Effect
    useEffect(() => {
        let cleanup = false;
        try {
            if (!window.Plotly || !plotX || !plotY || !activeResult?.modelCoefficients) return;
            const factorX = factors.find(f => f.name === plotX);
            const factorY = factors.find(f => f.name === plotY);
            if(!factorX || !factorY) return;

            const xMin = parseFloat(factorX.low), xMax = parseFloat(factorX.high);
            const yMin = parseFloat(factorY.low), yMax = parseFloat(factorY.high);
            if(isNaN(xMin) || isNaN(xMax) || isNaN(yMin) || isNaN(yMax)) return;

            const steps = 45; 
            const xValues: number[] = [], yValues: number[] = [];
            const zMatrix: number[][] = [], dMatrix: number[][] = [];

            for(let i=0; i<=steps; i++) xValues.push(xMin + (i * (xMax - xMin) / steps));
            for(let i=0; i<=steps; i++) yValues.push(yMin + (i * (yMax - yMin) / steps));

            for(let j=0; j<=steps; j++) {
                const rowZ: number[] = [], rowD: number[] = [];
                for(let i=0; i<=steps; i++) {
                    const inputs: Record<string, string | number> = { ...predictionInputs };
                    inputs[plotX] = xValues[i];
                    inputs[plotY] = yValues[j];
                    const pred = calculatePredictionInternal(inputs);
                    rowZ.push(pred);
                    rowD.push(calculateDesirability(pred));
                }
                zMatrix.push(rowZ);
                dMatrix.push(rowD);
            }
            if(cleanup) return;

            const observed = getObservedRange(plotResponse);
            const zRange = [observed.min, observed.max];

            // Trace for Markers (Top 3 Suggestions)
            const markerTrace = topSuggestions.length > 0 ? {
                x: topSuggestions.map(s => s.factors[plotX]),
                y: topSuggestions.map(s => s.factors[plotY]),
                mode: 'markers+text',
                type: 'scatter',
                text: topSuggestions.map((_, i) => `#${i + 1}`),
                textposition: 'top center',
                textfont: { family: 'sans-serif', size: 12, color: 'black' },
                marker: { 
                    color: 'white', size: 14, 
                    line: { color: '#4f46e5', width: 2.5 },
                    symbol: 'circle'
                },
                name: 'Best Suggestions',
                showlegend: false
            } : null;

            // 1. 3D Surface
            const p3d = document.getElementById('plot3d');
            if (p3d) {
                window.Plotly.react('plot3d', [{
                    z: zMatrix, x: xValues, y: yValues, type: 'surface', colorscale: 'Viridis', cmin: zRange[0], cmax: zRange[1]
                }], { 
                    title: { text: `Surface: ${plotResponse}`, font: { size: 14, weight: 'bold' } },
                    scene: { xaxis: { title: plotX }, yaxis: { title: plotY }, zaxis: { title: plotResponse } },
                    margin: { l: 0, r: 0, b: 0, t: 40 }
                });
            }

            // 2. Response Contour
            const pContour = document.getElementById('plotContour');
            if (pContour) {
                const contourTraces: any[] = [{
                    z: zMatrix, x: xValues, y: yValues, type: 'contour', colorscale: 'Viridis', cmin: zRange[0], cmax: zRange[1],
                    contours: { showlabels: true, labelfont: { size: 10, color: 'white' } },
                    line: { width: 0.5, color: 'rgba(255,255,255,0.3)' }
                }];
                if (markerTrace) contourTraces.push(markerTrace);
                window.Plotly.react('plotContour', contourTraces, { 
                    title: { text: `Response Map`, font: { size: 14 } },
                    xaxis: { title: plotX }, 
                    yaxis: { title: plotY },
                    margin: { t: 40, b: 40, l: 40, r: 20 }
                });
            }

            // 3. Desirability Contour (Probability Map 0-1)
            const pDes = document.getElementById('plotDesirability');
            if (pDes) {
                const desTraces: any[] = [{
                    z: dMatrix, x: xValues, y: yValues,
                    type: 'contour', 
                    // High probability is green, low is red.
                    colorscale: [[0, '#fef2f2'], [0.1, '#fee2e2'], [0.3, '#fdba74'], [0.6, '#facc15'], [1, '#22c55e']],
                    zmin: 0, zmax: 1,
                    colorbar: { title: 'Prob.', thickness: 15, len: 0.8 },
                    contours: { showlabels: true, start: 0, end: 1, size: 0.1 }
                }];
                if (markerTrace) desTraces.push(markerTrace);
                window.Plotly.react('plotDesirability', desTraces, { 
                    title: { text: `Desirability Prob. Map (0 to 1)`, font: { size: 14, color: '#4f46e5' } }, 
                    xaxis: { title: plotX }, 
                    yaxis: { title: plotY },
                    showlegend: false,
                    margin: { t: 40, b: 40, l: 40, r: 20 }
                });
            }

        } catch (e) { console.error("Plotting Error:", e); }
        return () => { cleanup = true; };
    }, [plotX, plotY, plotResponse, activeResult, predictionInputs, optGoal, optMin, optMax, optTarget, topSuggestions, calculatePredictionInternal, calculateDesirability, getObservedRange, factors]);

    // Diagnostic Plots logic
    useEffect(() => {
        if (!window.Plotly || !activeResult?.diagnostics) return;
        const d = activeResult.diagnostics;
        const actualMin = Math.min(...d.actual), actualMax = Math.max(...d.actual);

        const pFit = document.getElementById('plotPredVsActual');
        if (pFit) {
            window.Plotly.react('plotPredVsActual', [
                { x: d.actual, y: d.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9', size: 8 } },
                { x: [actualMin, actualMax], y: [actualMin, actualMax], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' } }
            ], { 
                title: { text: 'Predicted vs Actual', font: { size: 12 } },
                margin: { t: 30, b: 40, l: 40, r: 10 }, 
                xaxis: { title: 'Actual' }, 
                yaxis: { title: 'Predicted' } 
            });
        }

        const pBox = document.getElementById('plotBoxCox');
        if (pBox && d.boxCox) {
            window.Plotly.react('plotBoxCox', [{ x: d.boxCox.lambda, y: d.boxCox.lnRSS, type: 'scatter', mode: 'lines', line: { color: '#8b5cf6', width: 3 } }], {
                title: { text: 'Box-Cox Plot', font: { size: 12 } }, 
                xaxis: { title: 'Lambda (λ)' }, 
                yaxis: { title: 'ln(RSS)' },
                margin: { t: 30, b: 40, l: 40, r: 10 },
                shapes: d.boxCox.ciLimit ? [{ type: 'line', x0: Math.min(...d.boxCox.lambda), x1: Math.max(...d.boxCox.lambda), y0: d.boxCox.ciLimit, y1: d.boxCox.ciLimit, line: { color: 'red', dash: 'dash', width: 2 } }] : []
            });
        }
    }, [activeResult]);

    if (!activeResult) return <div className="p-8 text-center text-gray-500">Select a response to view analysis details.</div>;

    return (
        <div className="space-y-8 pb-12">
            {/* Analysis Stats */}
            <div className="bg-white p-8 rounded-xl shadow-lg border border-gray-200">
                <h2 className="text-2xl font-bold text-science-900 mb-4 flex items-center gap-2"><LayoutDashboard /> Model Analysis: {plotResponse}</h2>
                <div className="grid md:grid-cols-3 gap-6 mb-6">
                    <div className="md:col-span-2 bg-slate-50 p-4 rounded-lg border border-slate-200">
                        <h4 className="text-xs font-bold text-science-600 uppercase mb-2 flex items-center gap-1"><Sigma size={14} /> Mathematical Model (Coded)</h4>
                        <p className="font-mono text-gray-800 text-sm whitespace-pre-wrap">{activeResult.fitStatistics.equation || "Model not calculated."}</p>
                    </div>
                    <div className="bg-white p-4 rounded-lg border border-gray-200 grid grid-cols-2 gap-2">
                        <div className="bg-science-50/50 p-2 rounded">
                            <div className="text-[10px] text-gray-400 uppercase font-bold tracking-tighter leading-none mb-1">R-Squared</div>
                            <div className="text-lg font-black text-science-900 leading-none">{activeResult.fitStatistics.rSquared.toFixed(4)}</div>
                        </div>
                        <div className="bg-slate-50 p-2 rounded">
                            <div className="text-[10px] text-gray-400 uppercase font-bold tracking-tighter leading-none mb-1">Adj. R-Squared</div>
                            <div className="text-lg font-black text-slate-900 leading-none">{activeResult.fitStatistics.adjRSquared.toFixed(4)}</div>
                        </div>
                    </div>
                </div>
                <div className="prose prose-sm max-w-none text-gray-700 bg-slate-50 p-6 rounded border border-slate-200 shadow-inner overflow-auto max-h-[400px]">
                    <ReactMarkdown>{activeResult.anovaText}</ReactMarkdown>
                </div>
            </div>

            {/* Diagnostics */}
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="bg-white p-2 rounded shadow h-[250px]"><div id="plotPredVsActual" className="w-full h-full"></div></div>
                <div className="bg-white p-2 rounded shadow h-[250px]"><div id="plotBoxCox" className="w-full h-full"></div></div>
                <div className="bg-science-50 p-4 rounded border border-science-100 flex flex-col justify-center">
                    <h4 className="font-bold text-science-900 mb-2 text-sm uppercase flex items-center gap-2"><Activity size={16}/> Reliability Report</h4>
                    <p className="text-xs text-gray-700 leading-relaxed italic border-l-2 border-science-300 pl-3">"{activeResult.diagnosticInterpretations.predVsActual}"</p>
                    <div className="mt-3 pt-3 border-t border-science-100 flex items-start gap-2">
                        <Triangle size={14} className="text-science-500 mt-0.5 shrink-0" />
                        <p className="text-[10px] text-science-800">Box-Cox Analysis: {activeResult.diagnosticInterpretations.boxCox}</p>
                    </div>
                </div>
            </div>

            {/* Selection Panel */}
            <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-md flex flex-wrap gap-8 items-center">
                <div>
                    <label className="block text-[10px] font-bold text-gray-400 uppercase mb-2">Primary Response</label>
                    <select className="p-2.5 rounded-lg border-2 border-slate-100 bg-slate-50 text-sm font-bold text-science-900 focus:border-science-500 outline-none min-w-[200px]" value={plotResponse} onChange={e => setPlotResponse(e.target.value)}>
                        {responses.map(r => <option key={r.name} value={r.name}>{r.name}</option>)}
                    </select>
                </div>
                <div className="flex gap-4">
                    <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase mb-2">X Factor</label>
                        <select className="p-2 rounded border text-sm font-medium" value={plotX} onChange={e => setPlotX(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select>
                    </div>
                    <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase mb-2">Y Factor</label>
                        <select className="p-2 rounded border text-sm font-medium" value={plotY} onChange={e => setPlotY(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select>
                    </div>
                </div>
            </div>

            {/* 3D and 2D Contours */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                    <div id="plot3d" className="w-full h-[380px]"></div>
                </div>
                <div className="bg-white p-4 rounded-xl shadow border border-gray-200">
                    <div id="plotContour" className="w-full h-[380px]"></div>
                </div>
                <div className="bg-white p-4 rounded-xl shadow-lg border-2 border-indigo-100">
                    <div id="plotDesirability" className="w-full h-[380px]"></div>
                </div>
            </div>

            {/* Numerical Optimization Solver */}
            <div className="bg-gradient-to-br from-indigo-900 to-indigo-800 p-8 rounded-2xl border border-indigo-700 shadow-2xl text-white">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8">
                    <div>
                        <h2 className="text-2xl font-black flex items-center gap-3">
                            <Trophy className="text-yellow-400" size={32} /> Numerical Optimization Solver
                        </h2>
                        <p className="text-indigo-200 text-sm mt-1">Calculating the desirability index based on your quality goals for <strong>{plotResponse}</strong>.</p>
                    </div>
                    <button 
                        onClick={findOptimalConditions} 
                        className="bg-white text-indigo-900 px-10 py-4 rounded-xl hover:bg-indigo-50 font-black flex items-center gap-3 shadow-xl transition-all hover:-translate-y-1 active:scale-95 group"
                    >
                        <Search size={20} className="group-hover:scale-125 transition-transform" /> 
                        Solve Desirability
                    </button>
                </div>

                <div className="grid md:grid-cols-4 gap-6 mb-10 bg-indigo-950/30 p-6 rounded-xl border border-indigo-700/50">
                    <div><label className="text-[10px] font-bold text-indigo-300 uppercase block mb-2">Optimization Strategy</label><select className="w-full p-3 bg-indigo-900/50 border border-indigo-600 rounded-lg text-sm text-white focus:ring-2 ring-indigo-400 outline-none" value={optGoal} onChange={e => setOptGoal(e.target.value as any)}><option value="Maximize">Maximize Response</option><option value="Minimize">Minimize Response</option><option value="Target">Target Value</option></select></div>
                    <div><label className="text-[10px] font-bold text-indigo-300 uppercase block mb-2">Low Limit (Des=0)</label><input type="number" className="w-full p-3 bg-indigo-900/50 border border-indigo-600 rounded-lg text-sm text-white" value={optMin} onChange={e => setOptMin(parseFloat(e.target.value))}/></div>
                    <div><label className="text-[10px] font-bold text-indigo-300 uppercase block mb-2">High Limit (Des=1)</label><input type="number" className="w-full p-3 bg-indigo-900/50 border border-indigo-600 rounded-lg text-sm text-white" value={optMax} onChange={e => setOptMax(parseFloat(e.target.value))}/></div>
                    {optGoal === 'Target' && <div><label className="text-[10px] font-bold text-indigo-300 uppercase block mb-2">Desired Target</label><input type="number" className="w-full p-3 bg-indigo-900/50 border border-indigo-600 rounded-lg text-sm text-white font-black" value={optTarget} onChange={e => setOptTarget(parseFloat(e.target.value))}/></div>}
                </div>

                {topSuggestions.length > 0 ? (
                    <div className="grid md:grid-cols-3 gap-6">
                        {topSuggestions.map((s, idx) => (
                            <div key={idx} className={`relative p-6 rounded-2xl border-2 transition-all group ${idx === 0 ? 'border-yellow-400 bg-white/10 shadow-yellow-400/20 shadow-2xl' : 'border-indigo-600 bg-indigo-950/20'}`}>
                                <div className={`absolute -top-4 -left-4 w-10 h-10 rounded-full flex items-center justify-center font-black shadow-lg ${idx === 0 ? 'bg-yellow-400 text-indigo-900' : 'bg-indigo-600 text-white'}`}>{idx + 1}</div>
                                <div className="flex justify-between items-center mb-4">
                                    <span className="text-[10px] font-black text-indigo-300 uppercase tracking-widest">Candidate #{idx+1}</span>
                                    <span className={`text-xs font-black px-2.5 py-1 rounded-full ${idx === 0 ? 'bg-yellow-400 text-indigo-900' : 'bg-indigo-700 text-indigo-200'}`}>Prob: {(s.desirability * 100).toFixed(1)}%</span>
                                </div>
                                <div className="text-3xl font-black text-white mb-6 leading-none tracking-tighter">
                                    {s.prediction.toFixed(4)} 
                                    <span className="text-sm font-normal text-indigo-300 ml-2">{getResponseUnit(plotResponse)}</span>
                                </div>
                                <div className="space-y-2.5">
                                    {Object.entries(s.factors).map(([k, v]) => (
                                        <div key={k} className="flex justify-between text-xs border-b border-indigo-700/50 pb-2">
                                            <span className="text-indigo-300 font-medium">{k}:</span>
                                            <span className="font-black text-white">{v.toFixed(3)}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="text-center p-16 text-indigo-300 border-2 border-dashed border-indigo-600 rounded-2xl bg-indigo-950/10">
                        <MousePointer2 size={40} className="mx-auto mb-4 opacity-30" />
                        <p className="font-bold">Solve for desirability to identify the most robust coordinates.</p>
                    </div>
                )}
            </div>

            {/* Interactive Predictor */}
            <div className="bg-white p-8 rounded-2xl border border-gray-200 shadow-xl overflow-hidden relative">
                <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
                    <Calculator size={120} />
                </div>
                <h3 className="text-xl font-black text-slate-900 mb-6 flex items-center gap-2">
                    <Calculator size={24} className="text-science-600" /> Factor-Level Predictor
                </h3>
                <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-8">
                    {factors.map(f => (
                        <div key={f.name}>
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-wider">{f.name} ({f.low} - {f.high})</label>
                            <input type="number" step="any" className="w-full p-3 bg-slate-50 border-2 border-slate-100 rounded-xl focus:border-science-500 focus:bg-white outline-none text-sm font-bold text-slate-800 transition-all" value={predictionInputs[f.name] || ''} onChange={(e) => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}/>
                        </div>
                    ))}
                </div>
                <div className="mt-10 flex flex-col md:flex-row items-center gap-8 border-t border-slate-100 pt-8">
                    <button onClick={calculatePrediction} className="w-full md:w-auto bg-science-900 text-white px-12 py-4 rounded-xl hover:bg-black font-black flex items-center justify-center gap-3 shadow-xl transition-all active:scale-95"><Play size={18} /> Calculate Response</button>
                    {predictedValue !== null && (
                        <div className="bg-science-50 px-10 py-4 rounded-2xl border-2 border-science-100 flex flex-col items-center md:items-start min-w-[200px]">
                            <span className="text-[10px] font-black text-science-600 uppercase tracking-widest mb-1">Model-Predicted {plotResponse}:</span>
                            <span className="text-4xl font-black text-science-900 tracking-tighter leading-none">{predictedValue.toFixed(4)} <span className="text-base font-medium text-science-500 lowercase">{getResponseUnit(plotResponse)}</span></span>
                        </div>
                    )}
                </div>
                <div className="mt-6 flex items-start gap-3 bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <Sigma size={16} className="text-slate-400 shrink-0 mt-0.5" />
                    <p className="text-[10px] text-slate-500 leading-relaxed font-medium">
                        Calculation strictly abides by the generated regression model and coded factor ranges. Output is physically clamped to the observed experimental domain ({getObservedRange(plotResponse).min.toFixed(2)} to {getObservedRange(plotResponse).max.toFixed(2)}) to prevent extrapolation errors.
                    </p>
                </div>
            </div>
        </div>
    );
};

export default AnalysisDashboard;

import React, { useEffect, useState, useCallback } from 'react';
import { AnalysisResult, FactorDefinition, ResponseDefinition } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, Calculator, Play, Sigma, Triangle, Trophy, Target, Search, MousePointer2, Info } from 'lucide-react';

declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
    isMixture?: boolean;
}

interface OptResult {
    factors: Record<string, number>;
    prediction: number;
    desirability: number;
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses, isMixture = false }) => {
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');
    const [optGoal, setOptGoal] = useState<'Maximize' | 'Minimize' | 'Target'>('Maximize');
    const [optTarget, setOptTarget] = useState<number>(0);
    const [optMin, setOptMin] = useState<number>(0);
    const [optMax, setOptMax] = useState<number>(100);
    const [topSuggestions, setTopSuggestions] = useState<OptResult[]>([]);

    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = isNaN(mid) ? "0" : mid.toString();
        });
        setPredictionInputs(initial);
        if (factors.length >= 2) {
            setPlotX(factors[0].name);
            setPlotY(factors[1].name);
        }
        if (responses.length > 0) {
            setPlotResponse(responses[0].name);
        }
    }, [factors, responses]);

    const activeResult = results.resultsByResponse[plotResponse];

    const getObservedRange = useCallback((resName: string) => {
        const res = results.resultsByResponse[resName];
        if (!res || !res.diagnostics || !res.diagnostics.actual || res.diagnostics.actual.length === 0) {
            return { min: 0, max: 100 };
        }
        const cleanData = res.diagnostics.actual.filter(v => typeof v === 'number' && !isNaN(v));
        if (cleanData.length === 0) return { min: 0, max: 100 };
        return { min: Math.min(...cleanData), max: Math.max(...cleanData) };
    }, [results]);

    useEffect(() => {
        const range = getObservedRange(plotResponse);
        setOptMin(range.min);
        setOptMax(range.max);
        setOptTarget((range.min + range.max) / 2);
        const resDef = responses.find(r => r.name === plotResponse);
        if (resDef) setOptGoal(resDef.goal);
    }, [plotResponse, getObservedRange, responses]);

    const toCoded = (val: number, factorName: string) => {
        const factor = factors.find(f => f.name === factorName);
        if (!factor) return 0;
        const low = parseFloat(factor.low);
        const high = parseFloat(factor.high);
        const mid = (high + low) / 2;
        const halfRange = (high - low) / 2;
        return halfRange === 0 ? 0 : (val - mid) / halfRange;
    };

    const calculatePredictionInternal = useCallback((inputs: Record<string, string | number>) => {
        if (!activeResult || !activeResult.modelCoefficients) return 0;
        const { intercept, linear, quadratic, interactions } = activeResult.modelCoefficients;
        let y = typeof intercept === 'number' ? intercept : parseFloat(intercept as any) || 0;

        if (linear) Object.entries(linear).forEach(([name, coeff]) => {
            const val = typeof inputs[name] === 'string' ? parseFloat(inputs[name] as string) : (inputs[name] as number);
            if (!isNaN(val)) y += coeff * toCoded(val, name);
        });
        if (quadratic) Object.entries(quadratic).forEach(([name, coeff]) => {
            const val = typeof inputs[name] === 'string' ? parseFloat(inputs[name] as string) : (inputs[name] as number);
            if (!isNaN(val)) y += coeff * Math.pow(toCoded(val, name), 2);
        });
        if (interactions) interactions.forEach(t => {
            const v1 = typeof inputs[t.factor1] === 'string' ? parseFloat(inputs[t.factor1] as string) : (inputs[t.factor1] as number);
            const v2 = typeof inputs[t.factor2] === 'string' ? parseFloat(inputs[t.factor2] as string) : (inputs[t.factor2] as number);
            if (!isNaN(v1) && !isNaN(v2)) y += t.coefficient * toCoded(v1, t.factor1) * toCoded(v2, t.factor2);
        });

        const { min, max } = getObservedRange(plotResponse);
        return Math.max(min, Math.min(max, y));
    }, [activeResult, factors, getObservedRange, plotResponse]);

    const calculatePrediction = () => setPredictedValue(calculatePredictionInternal(predictionInputs));

    const calculateDesirability = useCallback((val: number) => {
        const range = optMax - optMin;
        if (range <= 0 || isNaN(val)) return 0;
        if (optGoal === 'Maximize') return val <= optMin ? 0 : val >= optMax ? 1 : (val - optMin) / range;
        if (optGoal === 'Minimize') return val <= optMin ? 1 : val >= optMax ? 0 : (optMax - val) / range;
        if (val < optMin || val > optMax) return 0;
        if (val === optTarget) return 1;
        return val < optTarget ? (val - optMin) / (optTarget - optMin) : (optMax - val) / (optMax - optTarget);
    }, [optMax, optMin, optGoal, optTarget]);

    const findOptimalConditions = () => {
        if (!activeResult) return;
        const suggestions: OptResult[] = [];
        for (let i = 0; i < 15000; i++) {
            const trial: Record<string, number> = {};
            factors.forEach(f => {
                const low = parseFloat(f.low), high = parseFloat(f.high);
                trial[f.name] = low + Math.random() * (high - low);
            });
            const pred = calculatePredictionInternal(trial);
            const d = calculateDesirability(pred);
            suggestions.push({ factors: trial, prediction: pred, desirability: d });
        }
        suggestions.sort((a, b) => b.desirability - a.desirability);
        const unique: OptResult[] = [];
        for (const s of suggestions) {
            if (unique.length >= 3) break;
            const isDup = unique.some(e => factors.every(f => Math.abs(e.factors[f.name] - s.factors[f.name]) < (Math.abs(parseFloat(f.high) - parseFloat(f.low)) * 0.15)));
            if (!isDup) unique.push(s);
        }
        setTopSuggestions(unique);
    };

    useEffect(() => {
        if (!window.Plotly || !plotX || !plotY || !activeResult) return;
        const factorX = factors.find(f => f.name === plotX), factorY = factors.find(f => f.name === plotY);
        if (!factorX || !factorY) return;

        const xMin = parseFloat(factorX.low), xMax = parseFloat(factorX.high);
        const yMin = parseFloat(factorY.low), yMax = parseFloat(factorY.high);
        const steps = 40;
        const xVals = [], yVals = [], zMat = [], dMat = [];

        for (let i = 0; i <= steps; i++) xVals.push(xMin + (i * (xMax - xMin) / steps));
        for (let i = 0; i <= steps; i++) yVals.push(yMin + (i * (yMax - yMin) / steps));

        for (let j = 0; j <= steps; j++) {
            const rowZ = [], rowD = [];
            for (let i = 0; i <= steps; i++) {
                const inputs = { ...predictionInputs, [plotX]: xVals[i], [plotY]: yVals[j] };
                const pred = calculatePredictionInternal(inputs);
                rowZ.push(pred);
                rowD.push(calculateDesirability(pred));
            }
            zMat.push(rowZ);
            dMat.push(rowD);
        }

        const observed = getObservedRange(plotResponse);
        const markerTrace = topSuggestions.length > 0 ? {
            x: topSuggestions.map(s => s.factors[plotX]), y: topSuggestions.map(s => s.factors[plotY]),
            mode: 'markers+text', type: 'scatter', text: ['#1', '#2', '#3'], textposition: 'top center',
            marker: { color: 'white', size: 12, line: { color: 'black', width: 2 } }, showlegend: false
        } : null;

        if (document.getElementById('plot3d')) window.Plotly.react('plot3d', [{ z: zMat, x: xVals, y: yVals, type: 'surface', colorscale: 'Viridis' }], { scene: { xaxis: { title: plotX }, yaxis: { title: plotY }, zaxis: { title: plotResponse } }, margin: { l: 0, r: 0, b: 0, t: 30 } });
        if (document.getElementById('plotContour')) {
            const traces: any = [{ z: zMat, x: xVals, y: yVals, type: 'contour', colorscale: 'Viridis', contours: { showlabels: true } }];
            if (markerTrace) traces.push(markerTrace);
            window.Plotly.react('plotContour', traces, { xaxis: { title: plotX }, yaxis: { title: plotY } });
        }
        if (document.getElementById('plotDesirability')) {
            const traces: any = [{ z: dMat, x: xVals, y: yVals, type: 'contour', colorscale: [[0, '#fee2e2'], [0.3, '#fdba74'], [0.7, '#facc15'], [1, '#22c55e']], zmin: 0, zmax: 1, contours: { showlabels: true } }];
            if (markerTrace) traces.push(markerTrace);
            window.Plotly.react('plotDesirability', traces, { title: 'Probability Map (0-1)', xaxis: { title: plotX }, yaxis: { title: plotY } });
        }
    }, [plotX, plotY, plotResponse, activeResult, predictionInputs, topSuggestions, calculatePredictionInternal, calculateDesirability, factors, getObservedRange]);

    useEffect(() => {
        if (!window.Plotly || !activeResult?.diagnostics) return;
        const d = activeResult.diagnostics;
        const actualMin = Math.min(...d.actual), actualMax = Math.max(...d.actual);

        window.Plotly.react('plotPredVsActual', [{ x: d.actual, y: d.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9' } }, { x: [actualMin, actualMax], y: [actualMin, actualMax], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' } }], { xaxis: { title: 'Actual' }, yaxis: { title: 'Predicted' }, margin: { t: 30, b: 40, l: 40, r: 10 } });
        window.Plotly.react('plotResidVsRun', [{ x: d.runOrder, y: d.residuals, type: 'scatter', mode: 'markers', marker: { color: '#f97316' } }], { xaxis: { title: 'Run Order' }, yaxis: { title: 'Residuals' }, shapes: [{ type: 'line', x0: Math.min(...d.runOrder), x1: Math.max(...d.runOrder), y0: 0, y1: 0, line: { color: 'black', dash: 'dot' } }], margin: { t: 30, b: 40, l: 40, r: 10 } });

        if (d.boxCox) {
            const shapes: any = [];
            if (d.boxCox.ciLimit) shapes.push({ type: 'line', x0: Math.min(...d.boxCox.lambda), x1: Math.max(...d.boxCox.lambda), y0: d.boxCox.ciLimit, y1: d.boxCox.ciLimit, line: { color: 'red', dash: 'dash' } });
            if (d.boxCox.lambdaLow && d.boxCox.lambdaHigh) {
                shapes.push({ type: 'line', x0: d.boxCox.lambdaLow, x1: d.boxCox.lambdaLow, y0: Math.min(...d.boxCox.lnRSS), y1: Math.max(...d.boxCox.lnRSS), line: { color: 'red', dash: 'dot', width: 1 } });
                shapes.push({ type: 'line', x0: d.boxCox.lambdaHigh, x1: d.boxCox.lambdaHigh, y0: Math.min(...d.boxCox.lnRSS), y1: Math.max(...d.boxCox.lnRSS), line: { color: 'red', dash: 'dot', width: 1 } });
            }
            window.Plotly.react('plotBoxCox', [{ x: d.boxCox.lambda, y: d.boxCox.lnRSS, type: 'scatter', mode: 'lines', line: { color: '#8b5cf6', width: 3 } }], { xaxis: { title: 'Lambda' }, yaxis: { title: 'ln(RSS)' }, shapes, margin: { t: 30, b: 40, l: 40, r: 10 } });
        }
    }, [activeResult]);

    if (!activeResult) return <div className="p-8 text-center text-gray-500 italic">Please select a response to view the analysis dashboard.</div>;

    const stats = activeResult.fitStatistics;
    const adeqPrecComment = stats.adequatePrecision > 4 ? "Signal-to-noise ratio is adequate (> 4)." : "Signal is low compared to noise (< 4).";
    const predR2Diff = Math.abs(stats.adjRSquared - stats.predictedRSquared);
    const predR2Comment = predR2Diff < 0.2 ? "Adjusted and Predicted R² are in reasonable agreement (diff < 0.2)." : "Difference between Adjusted and Predicted R² is > 0.2; check for outliers or model over-fitting.";

    return (
        <div className="space-y-8 pb-20 max-w-full">
            {/* Model Summary */}
            <div className="bg-white p-8 rounded-2xl shadow-xl border border-gray-100">
                <div className="flex justify-between items-start mb-6">
                    <h2 className="text-2xl font-black text-science-900 flex items-center gap-3"><LayoutDashboard /> Model Report: {plotResponse}</h2>
                    <div className="flex gap-2">
                        <div className="bg-science-50 p-2 rounded text-center min-w-[100px] border border-science-100">
                            <span className="text-[10px] font-bold text-science-600 block uppercase">R-Squared</span>
                            <span className="text-xl font-black">{stats.rSquared.toFixed(4)}</span>
                        </div>
                        <div className="bg-slate-50 p-2 rounded text-center min-w-[100px] border border-slate-100">
                            <span className="text-[10px] font-bold text-slate-500 block uppercase">Adj R-Squared</span>
                            <span className="text-xl font-black">{stats.adjRSquared.toFixed(4)}</span>
                        </div>
                    </div>
                </div>

                <div className="grid lg:grid-cols-3 gap-6 mb-8">
                    <div className="lg:col-span-2 bg-slate-50 p-6 rounded-xl border border-slate-200">
                        <div className="flex items-center gap-2 mb-3">
                            <Sigma className="text-science-600" size={18} />
                            <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest">Coded Regression Equation</h4>
                        </div>
                        <p className="font-mono text-sm text-slate-800 break-words leading-relaxed">{stats.equation || "Linear model calculation failed."}</p>
                    </div>
                    <div className="space-y-4">
                        <div className="p-4 bg-blue-50 rounded-xl border border-blue-100">
                            <div className="flex justify-between items-center mb-1">
                                <span className="text-[10px] font-bold text-blue-600 uppercase">Predicted R²</span>
                                <span className="font-black text-blue-900">{stats.predictedRSquared.toFixed(4)}</span>
                            </div>
                            <p className="text-[9px] text-blue-700 leading-tight"><Info size={10} className="inline mr-1"/>{predR2Comment}</p>
                        </div>
                        <div className="p-4 bg-emerald-50 rounded-xl border border-emerald-100">
                            <div className="flex justify-between items-center mb-1">
                                <span className="text-[10px] font-bold text-emerald-600 uppercase">Adeq Precision</span>
                                <span className="font-black text-emerald-900">{stats.adequatePrecision.toFixed(2)}</span>
                            </div>
                            <p className="text-[9px] text-emerald-700 leading-tight"><Info size={10} className="inline mr-1"/>{adeqPrecComment}</p>
                        </div>
                    </div>
                </div>

                <div className="prose prose-sm max-w-none text-slate-600 bg-slate-50/50 p-6 rounded-xl border border-slate-100 shadow-inner max-h-[300px] overflow-y-auto">
                    <ReactMarkdown>{activeResult.anovaText}</ReactMarkdown>
                </div>
            </div>

            {/* Diagnostics Panel */}
            <div className="space-y-4">
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2 px-1"><Activity className="text-science-500" /> Diagnostics & Reliability</h3>
                <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                    <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                        <div id="plotPredVsActual" className="w-full h-[250px]"></div>
                        <p className="text-[10px] text-slate-400 mt-2 px-2 italic">Scientific Interpretation: {activeResult.diagnosticInterpretations.predVsActual}</p>
                    </div>
                    <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                        <div id="plotResidVsRun" className="w-full h-[250px]"></div>
                        <p className="text-[10px] text-slate-400 mt-2 px-2 italic">Interpretation: Points should be randomly dispersed around zero; no trends should be visible.</p>
                    </div>
                    <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                        <div id="plotBoxCox" className="w-full h-[250px]"></div>
                        <p className="text-[10px] text-slate-400 mt-2 px-2 italic">Box-Cox: Red dash/dots show 95% Confidence Interval. Lambda=1 indicates no transform needed. {activeResult.diagnosticInterpretations.boxCox}</p>
                    </div>
                </div>
            </div>

            {/* Visualizations Selection */}
            <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-md flex flex-wrap gap-6 items-center">
                <div className="flex gap-4">
                    <div><label className="block text-[10px] font-black text-slate-400 uppercase mb-1">X Factor</label><select className="p-2 rounded border text-sm font-bold bg-slate-50" value={plotX} onChange={e => setPlotX(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select></div>
                    <div><label className="block text-[10px] font-black text-slate-400 uppercase mb-1">Y Factor</label><select className="p-2 rounded border text-sm font-bold bg-slate-50" value={plotY} onChange={e => setPlotY(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select></div>
                </div>
                <div className="flex-1">
                    <label className="block text-[10px] font-black text-slate-400 uppercase mb-1">Active Response CQA</label>
                    <select className="w-full p-2 rounded border text-sm font-bold bg-science-50 text-science-900" value={plotResponse} onChange={e => setPlotResponse(e.target.value)}>{responses.map(r => <option key={r.name} value={r.name}>{r.name}</option>)}</select>
                </div>
            </div>

            {/* Surface Plots */}
            <div className="grid lg:grid-cols-3 gap-8">
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm"><div id="plot3d" className="w-full h-[350px]"></div></div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm"><div id="plotContour" className="w-full h-[350px]"></div></div>
                <div className="bg-white p-4 rounded-xl border-2 border-indigo-100 shadow-lg"><div id="plotDesirability" className="w-full h-[350px]"></div></div>
            </div>

            {/* Numerical Solver */}
            <div className="bg-slate-900 p-10 rounded-3xl shadow-2xl text-white relative overflow-hidden">
                <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none rotate-12"><Trophy size={200} /></div>
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
                    <div>
                        <h2 className="text-3xl font-black flex items-center gap-3 tracking-tighter"><Trophy className="text-yellow-400" /> Desirability Solver</h2>
                        <p className="text-slate-400 text-sm mt-1">Multi-criteria optimization based on the regression model and your defined targets.</p>
                    </div>
                    <button onClick={findOptimalConditions} className="bg-white text-slate-900 px-10 py-4 rounded-2xl hover:bg-slate-100 font-black flex items-center gap-3 shadow-xl transition-all active:scale-95"><Search size={20}/> Solve for Best Suggestions</button>
                </div>

                <div className="grid md:grid-cols-4 gap-6 mb-12 bg-slate-800/50 p-6 rounded-2xl border border-slate-700">
                    <div><label className="text-[10px] font-black text-slate-500 uppercase block mb-2">Strategy</label><select className="w-full p-3 bg-slate-800 border border-slate-600 rounded-xl text-sm" value={optGoal} onChange={e => setOptGoal(e.target.value as any)}><option value="Maximize">Maximize Response</option><option value="Minimize">Minimize Response</option><option value="Target">Target Value</option></select></div>
                    <div><label className="text-[10px] font-black text-slate-500 uppercase block mb-2">Lower Limit</label><input type="number" className="w-full p-3 bg-slate-800 border border-slate-600 rounded-xl text-sm" value={optMin} onChange={e => setOptMin(parseFloat(e.target.value))}/></div>
                    <div><label className="text-[10px] font-black text-slate-500 uppercase block mb-2">Upper Limit</label><input type="number" className="w-full p-3 bg-slate-800 border border-slate-600 rounded-xl text-sm" value={optMax} onChange={e => setOptMax(parseFloat(e.target.value))}/></div>
                    {optGoal === 'Target' && <div><label className="text-[10px] font-black text-slate-500 uppercase block mb-2">Target</label><input type="number" className="w-full p-3 bg-slate-800 border border-slate-600 rounded-xl text-sm font-black text-science-400" value={optTarget} onChange={e => setOptTarget(parseFloat(e.target.value))}/></div>}
                </div>

                {topSuggestions.length > 0 ? (
                    <div className="grid md:grid-cols-3 gap-8">
                        {topSuggestions.map((s, idx) => (
                            <div key={idx} className={`relative p-8 rounded-3xl border-2 transition-all ${idx === 0 ? 'border-science-500 bg-science-950/20' : 'border-slate-700 bg-slate-800/20'}`}>
                                <div className={`absolute -top-4 -left-4 w-10 h-10 rounded-full flex items-center justify-center font-black shadow-lg ${idx === 0 ? 'bg-science-500 text-white' : 'bg-slate-700 text-slate-300'}`}>{idx + 1}</div>
                                <div className="flex justify-between items-center mb-4">
                                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Candidate</span>
                                    <span className="text-xs font-black text-science-400 bg-science-400/10 px-3 py-1 rounded-full">{(s.desirability * 100).toFixed(1)}% Prob.</span>
                                </div>
                                <div className="text-4xl font-black text-white mb-6 leading-none tracking-tighter">{s.prediction.toFixed(4)} <span className="text-sm font-normal text-slate-500">{getResponseUnit(plotResponse)}</span></div>
                                <div className="space-y-3">
                                    {Object.entries(s.factors).map(([k, v]) => (
                                        <div key={k} className="flex justify-between text-xs border-b border-slate-800 pb-2">
                                            <span className="text-slate-400">{k}:</span>
                                            <span className="font-black text-slate-100">{v.toFixed(3)}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="text-center p-20 text-slate-500 border-2 border-dashed border-slate-700 rounded-3xl"><MousePointer2 size={40} className="mx-auto mb-4 opacity-20" /><p className="font-bold">Enter goal thresholds and solve for the best 3 suggestions.</p></div>
                )}
            </div>

            {/* Predictor */}
            <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-xl">
                <h3 className="text-xl font-black text-slate-900 mb-6 flex items-center gap-2"><Calculator size={24} className="text-science-600" /> Interactive Predictor</h3>
                <div className="grid md:grid-cols-4 gap-6 mb-8">
                    {factors.map(f => (
                        <div key={f.name}>
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-1 tracking-widest">{f.name} ({f.low}-{f.high})</label>
                            <input type="number" step="any" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl focus:border-science-500 outline-none text-sm font-bold" value={predictionInputs[f.name] || ''} onChange={e => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}/>
                        </div>
                    ))}
                </div>
                <div className="flex items-center gap-10 pt-6 border-t border-slate-100">
                    <button onClick={calculatePrediction} className="bg-slate-900 text-white px-10 py-4 rounded-xl hover:bg-black font-black flex items-center gap-3 shadow-lg active:scale-95 transition-all"><Play size={18} /> Run Model Estimation</button>
                    {predictedValue !== null && (
                        <div className="flex flex-col">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Clamped Predicted Result:</span>
                            <span className="text-4xl font-black text-science-900 tracking-tighter leading-none">{predictedValue.toFixed(4)} <span className="text-sm font-normal text-slate-400">{getResponseUnit(plotResponse)}</span></span>
                        </div>
                    )}
                </div>
                <p className="text-[10px] text-slate-400 mt-6 italic flex items-center gap-1"><Sigma size={10} /> Prediction strictly uses the coded model coefficients. Result is physically clamped to the observed response domain (Min/Max of experiments).</p>
            </div>
        </div>
    );
};

export default AnalysisDashboard;

import React, { useEffect, useState, useCallback } from 'react';
import { AnalysisResult, FactorDefinition, ResponseDefinition } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, Calculator, Play, Sigma, Triangle, Trophy, Target, Search, MousePointer2, Info } from 'lucide-react';

declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
    isMixture?: boolean;
}

interface OptResult {
    factors: Record<string, number>;
    prediction: number;
    desirability: number;
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses, isMixture = false }) => {
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');
    const [optGoal, setOptGoal] = useState<'Maximize' | 'Minimize' | 'Target'>('Maximize');
    const [optTarget, setOptTarget] = useState<number>(0);
    const [optMin, setOptMin] = useState<number>(0);
    const [optMax, setOptMax] = useState<number>(100);
    const [topSuggestions, setTopSuggestions] = useState<OptResult[]>([]);

    // Helper to get unit for a response name
    const getResponseUnit = (name: string) => {
        return responses.find(r => r.name === name)?.unit || '';
    };

    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = isNaN(mid) ? "0" : mid.toString();
        });
        setPredictionInputs(initial);
        if (factors.length >= 2) {
            setPlotX(factors[0].name);
            setPlotY(factors[1].name);
        }
        if (responses.length > 0) {
            setPlotResponse(responses[0].name);
        }
    }, [factors, responses]);

    const activeResult = results.resultsByResponse[plotResponse];

    const getObservedRange = useCallback((resName: string) => {
        const res = results.resultsByResponse[resName];
        if (!res || !res.diagnostics || !res.diagnostics.actual || res.diagnostics.actual.length === 0) {
            return { min: 0, max: 100 };
        }
        const cleanData = res.diagnostics.actual.filter(v => typeof v === 'number' && !isNaN(v));
        if (cleanData.length === 0) return { min: 0, max: 100 };
        return { min: Math.min(...cleanData), max: Math.max(...cleanData) };
    }, [results]);

    useEffect(() => {
        const range = getObservedRange(plotResponse);
        setOptMin(range.min);
        setOptMax(range.max);
        setOptTarget((range.min + range.max) / 2);
        const resDef = responses.find(r => r.name === plotResponse);
        if (resDef) setOptGoal(resDef.goal);
    }, [plotResponse, getObservedRange, responses]);

    const toCoded = (val: number, factorName: string) => {
        const factor = factors.find(f => f.name === factorName);
        if (!factor) return 0;
        const low = parseFloat(factor.low);
        const high = parseFloat(factor.high);
        const mid = (high + low) / 2;
        const halfRange = (high - low) / 2;
        return halfRange === 0 ? 0 : (val - mid) / halfRange;
    };

    const calculatePredictionInternal = useCallback((inputs: Record<string, string | number>) => {
        if (!activeResult || !activeResult.modelCoefficients) return 0;
        const { intercept, linear, quadratic, interactions } = activeResult.modelCoefficients;
        let y = typeof intercept === 'number' ? intercept : parseFloat(intercept as any) || 0;

        if (linear) Object.entries(linear).forEach(([name, coeff]) => {
            const val = typeof inputs[name] === 'string' ? parseFloat(inputs[name] as string) : (inputs[name] as number);
            if (!isNaN(val)) y += coeff * toCoded(val, name);
        });
        if (quadratic) Object.entries(quadratic).forEach(([name, coeff]) => {
            const val = typeof inputs[name] === 'string' ? parseFloat(inputs[name] as string) : (inputs[name] as number);
            if (!isNaN(val)) y += coeff * Math.pow(toCoded(val, name), 2);
        });
        if (interactions) interactions.forEach(t => {
            const v1 = typeof inputs[t.factor1] === 'string' ? parseFloat(inputs[t.factor1] as string) : (inputs[t.factor1] as number);
            const v2 = typeof inputs[t.factor2] === 'string' ? parseFloat(inputs[t.factor2] as string) : (inputs[t.factor2] as number);
            if (!isNaN(v1) && !isNaN(v2)) y += t.coefficient * toCoded(v1, t.factor1) * toCoded(v2, t.factor2);
        });

        const { min, max } = getObservedRange(plotResponse);
        return Math.max(min, Math.min(max, y));
    }, [activeResult, factors, getObservedRange, plotResponse]);

    const calculatePrediction = () => setPredictedValue(calculatePredictionInternal(predictionInputs));

    const calculateDesirability = useCallback((val: number) => {
        const range = optMax - optMin;
        if (range <= 0 || isNaN(val)) return 0;
        if (optGoal === 'Maximize') return val <= optMin ? 0 : val >= optMax ? 1 : (val - optMin) / range;
        if (optGoal === 'Minimize') return val <= optMin ? 1 : val >= optMax ? 0 : (optMax - val) / range;
        if (val < optMin || val > optMax) return 0;
        if (val === optTarget) return 1;
        return val < optTarget ? (val - optMin) / (optTarget - optMin) : (optMax - val) / (optMax - optTarget);
    }, [optMax, optMin, optGoal, optTarget]);

    const findOptimalConditions = () => {
        if (!activeResult) return;
        const suggestions: OptResult[] = [];
        for (let i = 0; i < 15000; i++) {
            const trial: Record<string, number> = {};
            factors.forEach(f => {
                const low = parseFloat(f.low), high = parseFloat(f.high);
                trial[f.name] = low + Math.random() * (high - low);
            });
            const pred = calculatePredictionInternal(trial);
            const d = calculateDesirability(pred);
            suggestions.push({ factors: trial, prediction: pred, desirability: d });
        }
        suggestions.sort((a, b) => b.desirability - a.desirability);
        const unique: OptResult[] = [];
        for (const s of suggestions) {
            if (unique.length >= 3) break;
            const isDup = unique.some(e => factors.every(f => Math.abs(e.factors[f.name] - s.factors[f.name]) < (Math.abs(parseFloat(f.high) - parseFloat(f.low)) * 0.15)));
            if (!isDup) unique.push(s);
        }
        setTopSuggestions(unique);
    };

    useEffect(() => {
        if (!window.Plotly || !plotX || !plotY || !activeResult) return;
        const factorX = factors.find(f => f.name === plotX), factorY = factors.find(f => f.name === plotY);
        if (!factorX || !factorY) return;

        const xMin = parseFloat(factorX.low), xMax = parseFloat(factorX.high);
        const yMin = parseFloat(factorY.low), yMax = parseFloat(factorY.high);
        const steps = 40;
        const xVals = [], yVals = [], zMat = [], dMat = [];

        for (let i = 0; i <= steps; i++) xVals.push(xMin + (i * (xMax - xMin) / steps));
        for (let i = 0; i <= steps; i++) yVals.push(yMin + (i * (yMax - yMin) / steps));

        for (let j = 0; j <= steps; j++) {
            const rowZ = [], rowD = [];
            for (let i = 0; i <= steps; i++) {
                const inputs = { ...predictionInputs, [plotX]: xVals[i], [plotY]: yVals[j] };
                const pred = calculatePredictionInternal(inputs);
                rowZ.push(pred);
                rowD.push(calculateDesirability(pred));
            }
            zMat.push(rowZ);
            dMat.push(rowD);
        }

        const observed = getObservedRange(plotResponse);
        const markerTrace = topSuggestions.length > 0 ? {
            x: topSuggestions.map(s => s.factors[plotX]), y: topSuggestions.map(s => s.factors[plotY]),
            mode: 'markers+text', type: 'scatter', text: ['#1', '#2', '#3'], textposition: 'top center',
            marker: { color: 'white', size: 12, line: { color: 'black', width: 2 } }, showlegend: false
        } : null;

        if (document.getElementById('plot3d')) window.Plotly.react('plot3d', [{ z: zMat, x: xVals, y: yVals, type: 'surface', colorscale: 'Viridis' }], { scene: { xaxis: { title: plotX }, yaxis: { title: plotY }, zaxis: { title: plotResponse } }, margin: { l: 0, r: 0, b: 0, t: 30 } });
        if (document.getElementById('plotContour')) {
            const traces: any = [{ z: zMat, x: xVals, y: yVals, type: 'contour', colorscale: 'Viridis', contours: { showlabels: true } }];
            if (markerTrace) traces.push(markerTrace);
            window.Plotly.react('plotContour', traces, { xaxis: { title: plotX }, yaxis: { title: plotY } });
        }
        if (document.getElementById('plotDesirability')) {
            const traces: any = [{ z: dMat, x: xVals, y: yVals, type: 'contour', colorscale: [[0, '#fee2e2'], [0.3, '#fdba74'], [0.7, '#facc15'], [1, '#22c55e']], zmin: 0, zmax: 1, contours: { showlabels: true } }];
            if (markerTrace) traces.push(markerTrace);
            window.Plotly.react('plotDesirability', traces, { title: 'Probability Map (0-1)', xaxis: { title: plotX }, yaxis: { title: plotY } });
        }
    }, [plotX, plotY, plotResponse, activeResult, predictionInputs, topSuggestions, calculatePredictionInternal, calculateDesirability, factors, getObservedRange]);

    useEffect(() => {
        if (!window.Plotly || !activeResult?.diagnostics) return;
        const d = activeResult.diagnostics;
        const actualMin = Math.min(...d.actual), actualMax = Math.max(...d.actual);

        window.Plotly.react('plotPredVsActual', [{ x: d.actual, y: d.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9' } }, { x: [actualMin, actualMax], y: [actualMin, actualMax], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' } }], { xaxis: { title: 'Actual' }, yaxis: { title: 'Predicted' }, margin: { t: 30, b: 40, l: 40, r: 10 } });
        window.Plotly.react('plotResidVsRun', [{ x: d.runOrder, y: d.residuals, type: 'scatter', mode: 'markers', marker: { color: '#f97316' } }], { xaxis: { title: 'Run Order' }, yaxis: { title: 'Residuals' }, shapes: [{ type: 'line', x0: Math.min(...d.runOrder), x1: Math.max(...d.runOrder), y0: 0, y1: 0, line: { color: 'black', dash: 'dot' } }], margin: { t: 30, b: 40, l: 40, r: 10 } });

        if (d.boxCox) {
            const shapes: any = [];
            if (d.boxCox.ciLimit) shapes.push({ type: 'line', x0: Math.min(...d.boxCox.lambda), x1: Math.max(...d.boxCox.lambda), y0: d.boxCox.ciLimit, y1: d.boxCox.ciLimit, line: { color: 'red', dash: 'dash' } });
            if (d.boxCox.lambdaLow && d.boxCox.lambdaHigh) {
                shapes.push({ type: 'line', x0: d.boxCox.lambdaLow, x1: d.boxCox.lambdaLow, y0: Math.min(...d.boxCox.lnRSS), y1: Math.max(...d.boxCox.lnRSS), line: { color: 'red', dash: 'dot', width: 1 } });
                shapes.push({ type: 'line', x0: d.boxCox.lambdaHigh, x1: d.boxCox.lambdaHigh, y0: Math.min(...d.boxCox.lnRSS), y1: Math.max(...d.boxCox.lnRSS), line: { color: 'red', dash: 'dot', width: 1 } });
            }
            window.Plotly.react('plotBoxCox', [{ x: d.boxCox.lambda, y: d.boxCox.lnRSS, type: 'scatter', mode: 'lines', line: { color: '#8b5cf6', width: 3 } }], { xaxis: { title: 'Lambda' }, yaxis: { title: 'ln(RSS)' }, shapes, margin: { t: 30, b: 40, l: 40, r: 10 } });
        }
    }, [activeResult]);

    if (!activeResult) return <div className="p-8 text-center text-gray-500 italic">Please select a response to view the analysis dashboard.</div>;

    const stats = activeResult.fitStatistics;
    const adeqPrecComment = stats.adequatePrecision > 4 ? "Signal-to-noise ratio is adequate (> 4)." : "Signal is low compared to noise (< 4).";
    const predR2Diff = Math.abs(stats.adjRSquared - stats.predictedRSquared);
    const predR2Comment = predR2Diff < 0.2 ? "Adjusted and Predicted R² are in reasonable agreement (diff < 0.2)." : "Difference between Adjusted and Predicted R² is > 0.2; check for outliers or model over-fitting.";

    return (
        <div className="space-y-8 pb-20 max-w-full">
            {/* Model Summary */}
            <div className="bg-white p-8 rounded-2xl shadow-xl border border-gray-100">
                <div className="flex justify-between items-start mb-6">
                    <h2 className="text-2xl font-black text-science-900 flex items-center gap-3"><LayoutDashboard /> Model Report: {plotResponse}</h2>
                    <div className="flex gap-2">
                        <div className="bg-science-50 p-2 rounded text-center min-w-[100px] border border-science-100">
                            <span className="text-[10px] font-bold text-science-600 block uppercase">R-Squared</span>
                            <span className="text-xl font-black">{stats.rSquared.toFixed(4)}</span>
                        </div>
                        <div className="bg-slate-50 p-2 rounded text-center min-w-[100px] border border-slate-100">
                            <span className="text-[10px] font-bold text-slate-500 block uppercase">Adj R-Squared</span>
                            <span className="text-xl font-black">{stats.adjRSquared.toFixed(4)}</span>
                        </div>
                    </div>
                </div>

                <div className="grid lg:grid-cols-3 gap-6 mb-8">
                    <div className="lg:col-span-2 bg-slate-50 p-6 rounded-xl border border-slate-200">
                        <div className="flex items-center gap-2 mb-3">
                            <Sigma className="text-science-600" size={18} />
                            <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest">Coded Regression Equation</h4>
                        </div>
                        <p className="font-mono text-sm text-slate-800 break-words leading-relaxed">{stats.equation || "Linear model calculation failed."}</p>
                    </div>
                    <div className="space-y-4">
                        <div className="p-4 bg-blue-50 rounded-xl border border-blue-100">
                            <div className="flex justify-between items-center mb-1">
                                <span className="text-[10px] font-bold text-blue-600 uppercase">Predicted R²</span>
                                <span className="font-black text-blue-900">{stats.predictedRSquared.toFixed(4)}</span>
                            </div>
                            <p className="text-[9px] text-blue-700 leading-tight"><Info size={10} className="inline mr-1"/>{predR2Comment}</p>
                        </div>
                        <div className="p-4 bg-emerald-50 rounded-xl border border-emerald-100">
                            <div className="flex justify-between items-center mb-1">
                                <span className="text-[10px] font-bold text-emerald-600 uppercase">Adeq Precision</span>
                                <span className="font-black text-emerald-900">{stats.adequatePrecision.toFixed(2)}</span>
                            </div>
                            <p className="text-[9px] text-emerald-700 leading-tight"><Info size={10} className="inline mr-1"/>{adeqPrecComment}</p>
                        </div>
                    </div>
                </div>

                <div className="prose prose-sm max-w-none text-slate-600 bg-slate-50/50 p-6 rounded-xl border border-slate-100 shadow-inner max-h-[300px] overflow-y-auto">
                    <ReactMarkdown>{activeResult.anovaText}</ReactMarkdown>
                </div>
            </div>

            {/* Diagnostics Panel */}
            <div className="space-y-4">
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2 px-1"><Activity className="text-science-500" /> Diagnostics & Reliability</h3>
                <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                    <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                        <div id="plotPredVsActual" className="w-full h-[250px]"></div>
                        <p className="text-[10px] text-slate-400 mt-2 px-2 italic">Scientific Interpretation: {activeResult.diagnosticInterpretations.predVsActual}</p>
                    </div>
                    <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                        <div id="plotResidVsRun" className="w-full h-[250px]"></div>
                        <p className="text-[10px] text-slate-400 mt-2 px-2 italic">Interpretation: Points should be randomly dispersed around zero; no trends should be visible.</p>
                    </div>
                    <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                        <div id="plotBoxCox" className="w-full h-[250px]"></div>
                        <p className="text-[10px] text-slate-400 mt-2 px-2 italic">Box-Cox: Red dash/dots show 95% Confidence Interval. Lambda=1 indicates no transform needed. {activeResult.diagnosticInterpretations.boxCox}</p>
                    </div>
                </div>
            </div>

            {/* Visualizations Selection */}
            <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-md flex flex-wrap gap-6 items-center">
                <div className="flex gap-4">
                    <div><label className="block text-[10px] font-black text-slate-400 uppercase mb-1">X Factor</label><select className="p-2 rounded border text-sm font-bold bg-slate-50" value={plotX} onChange={e => setPlotX(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select></div>
                    <div><label className="block text-[10px] font-black text-slate-400 uppercase mb-1">Y Factor</label><select className="p-2 rounded border text-sm font-bold bg-slate-50" value={plotY} onChange={e => setPlotY(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select></div>
                </div>
                <div className="flex-1">
                    <label className="block text-[10px] font-black text-slate-400 uppercase mb-1">Active Response CQA</label>
                    <select className="w-full p-2 rounded border text-sm font-bold bg-science-50 text-science-900" value={plotResponse} onChange={e => setPlotResponse(e.target.value)}>{responses.map(r => <option key={r.name} value={r.name}>{r.name}</option>)}</select>
                </div>
            </div>

            {/* Surface Plots */}
            <div className="grid lg:grid-cols-3 gap-8">
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm"><div id="plot3d" className="w-full h-[350px]"></div></div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm"><div id="plotContour" className="w-full h-[350px]"></div></div>
                <div className="bg-white p-4 rounded-xl border-2 border-indigo-100 shadow-lg"><div id="plotDesirability" className="w-full h-[350px]"></div></div>
            </div>

            {/* Numerical Solver */}
            <div className="bg-slate-900 p-10 rounded-3xl shadow-2xl text-white relative overflow-hidden">
                <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none rotate-12"><Trophy size={200} /></div>
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
                    <div>
                        <h2 className="text-3xl font-black flex items-center gap-3 tracking-tighter"><Trophy className="text-yellow-400" /> Desirability Solver</h2>
                        <p className="text-slate-400 text-sm mt-1">Multi-criteria optimization based on the regression model and your defined targets.</p>
                    </div>
                    <button onClick={findOptimalConditions} className="bg-white text-slate-900 px-10 py-4 rounded-2xl hover:bg-slate-100 font-black flex items-center gap-3 shadow-xl transition-all active:scale-95"><Search size={20}/> Solve for Best Suggestions</button>
                </div>

                <div className="grid md:grid-cols-4 gap-6 mb-12 bg-slate-800/50 p-6 rounded-2xl border border-slate-700">
                    <div><label className="text-[10px] font-black text-slate-500 uppercase block mb-2">Strategy</label><select className="w-full p-3 bg-slate-800 border border-slate-600 rounded-xl text-sm" value={optGoal} onChange={e => setOptGoal(e.target.value as any)}><option value="Maximize">Maximize Response</option><option value="Minimize">Minimize Response</option><option value="Target">Target Value</option></select></div>
                    <div><label className="text-[10px] font-black text-slate-500 uppercase block mb-2">Lower Limit</label><input type="number" className="w-full p-3 bg-slate-800 border border-slate-600 rounded-xl text-sm" value={optMin} onChange={e => setOptMin(parseFloat(e.target.value))}/></div>
                    <div><label className="text-[10px] font-black text-slate-500 uppercase block mb-2">Upper Limit</label><input type="number" className="w-full p-3 bg-slate-800 border border-slate-600 rounded-xl text-sm" value={optMax} onChange={e => setOptMax(parseFloat(e.target.value))}/></div>
                    {optGoal === 'Target' && <div><label className="text-[10px] font-black text-slate-500 uppercase block mb-2">Target</label><input type="number" className="w-full p-3 bg-slate-800 border border-slate-600 rounded-xl text-sm font-black text-science-400" value={optTarget} onChange={e => setOptTarget(parseFloat(e.target.value))}/></div>}
                </div>

                {topSuggestions.length > 0 ? (
                    <div className="grid md:grid-cols-3 gap-8">
                        {topSuggestions.map((s, idx) => (
                            <div key={idx} className={`relative p-8 rounded-3xl border-2 transition-all ${idx === 0 ? 'border-science-500 bg-science-950/20' : 'border-slate-700 bg-slate-800/20'}`}>
                                <div className={`absolute -top-4 -left-4 w-10 h-10 rounded-full flex items-center justify-center font-black shadow-lg ${idx === 0 ? 'bg-science-500 text-white' : 'bg-slate-700 text-slate-300'}`}>{idx + 1}</div>
                                <div className="flex justify-between items-center mb-4">
                                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Candidate</span>
                                    <span className="text-xs font-black text-science-400 bg-science-400/10 px-3 py-1 rounded-full">{(s.desirability * 100).toFixed(1)}% Prob.</span>
                                </div>
                                <div className="text-4xl font-black text-white mb-6 leading-none tracking-tighter">{s.prediction.toFixed(4)} <span className="text-sm font-normal text-slate-500">{getResponseUnit(plotResponse)}</span></div>
                                <div className="space-y-3">
                                    {Object.entries(s.factors).map(([k, v]) => (
                                        <div key={k} className="flex justify-between text-xs border-b border-slate-800 pb-2">
                                            <span className="text-slate-400">{k}:</span>
                                            <span className="font-black text-slate-100">{v.toFixed(3)}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="text-center p-20 text-slate-500 border-2 border-dashed border-slate-700 rounded-3xl"><MousePointer2 size={40} className="mx-auto mb-4 opacity-20" /><p className="font-bold">Enter goal thresholds and solve for the best 3 suggestions.</p></div>
                )}
            </div>

            {/* Predictor */}
            <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-xl">
                <h3 className="text-xl font-black text-slate-900 mb-6 flex items-center gap-2"><Calculator size={24} className="text-science-600" /> Interactive Predictor</h3>
                <div className="grid md:grid-cols-4 gap-6 mb-8">
                    {factors.map(f => (
                        <div key={f.name}>
                            <label className="block text-[10px] font-black text-slate-400 uppercase mb-1 tracking-widest">{f.name} ({f.low}-{f.high})</label>
                            <input type="number" step="any" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl focus:border-science-500 outline-none text-sm font-bold" value={predictionInputs[f.name] || ''} onChange={e => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}/>
                        </div>
                    ))}
                </div>
                <div className="flex items-center gap-10 pt-6 border-t border-slate-100">
                    <button onClick={calculatePrediction} className="bg-slate-900 text-white px-10 py-4 rounded-xl hover:bg-black font-black flex items-center gap-3 shadow-lg active:scale-95 transition-all"><Play size={18} /> Run Model Estimation</button>
                    {predictedValue !== null && (
                        <div className="flex flex-col">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Clamped Predicted Result:</span>
                            <span className="text-4xl font-black text-science-900 tracking-tighter leading-none">{predictedValue.toFixed(4)} <span className="text-sm font-normal text-slate-400">{getResponseUnit(plotResponse)}</span></span>
                        </div>
                    )}
                </div>
                <p className="text-[10px] text-slate-400 mt-6 italic flex items-center gap-1"><Sigma size={10} /> Prediction strictly uses the coded model coefficients. Result is physically clamped to the observed response domain (Min/Max of experiments).</p>
            </div>
        </div>
    );
};

export default AnalysisDashboard;

import React, { useEffect, useState, useCallback, useRef } from 'react';
import { AnalysisResult, FactorDefinition, ResponseDefinition } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, Calculator, Play, Sigma, Triangle, Trophy, Target, Search, MousePointer2, Info, Maximize2 } from 'lucide-react';

declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
    isMixture?: boolean;
}

interface OptResult {
    factors: Record<string, number>;
    prediction: number;
    desirability: number;
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses, isMixture = false }) => {
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');
    const [optGoal, setOptGoal] = useState<'Maximize' | 'Minimize' | 'Target'>('Maximize');
    const [optTarget, setOptTarget] = useState<number>(0);
    const [optMin, setOptMin] = useState<number>(0);
    const [optMax, setOptMax] = useState<number>(100);
    const [topSuggestions, setTopSuggestions] = useState<OptResult[]>([]);

    const containerRefs = {
        plot3d: useRef<HTMLDivElement>(null),
        plotContour: useRef<HTMLDivElement>(null),
        plotDesirability: useRef<HTMLDivElement>(null)
    };

    const getResponseUnit = (name: string) => {
        return responses.find(r => r.name === name)?.unit || '';
    };

    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = isNaN(mid) ? "0" : mid.toString();
        });
        setPredictionInputs(initial);
        if (factors.length >= 2) {
            setPlotX(factors[0].name);
            setPlotY(factors[1].name);
        }
        if (responses.length > 0) {
            setPlotResponse(responses[0].name);
        }
    }, [factors, responses]);

    const activeResult = results.resultsByResponse[plotResponse];

    const getObservedRange = useCallback((resName: string) => {
        const res = results.resultsByResponse[resName];
        if (!res || !res.diagnostics || !res.diagnostics.actual || res.diagnostics.actual.length === 0) {
            return { min: 0, max: 100 };
        }
        const cleanData = res.diagnostics.actual.filter(v => typeof v === 'number' && !isNaN(v));
        if (cleanData.length === 0) return { min: 0, max: 100 };
        return { min: Math.min(...cleanData), max: Math.max(...cleanData) };
    }, [results]);

    useEffect(() => {
        const range = getObservedRange(plotResponse);
        setOptMin(range.min);
        setOptMax(range.max);
        setOptTarget((range.min + range.max) / 2);
        const resDef = responses.find(r => r.name === plotResponse);
        if (resDef) setOptGoal(resDef.goal);
    }, [plotResponse, getObservedRange, responses]);

    const toCoded = (val: number, factorName: string) => {
        const factor = factors.find(f => f.name === factorName);
        if (!factor) return 0;
        const low = parseFloat(factor.low);
        const high = parseFloat(factor.high);
        const mid = (high + low) / 2;
        const halfRange = (high - low) / 2;
        return halfRange === 0 ? 0 : (val - mid) / halfRange;
    };

    const calculatePredictionInternal = useCallback((inputs: Record<string, string | number>) => {
        if (!activeResult || !activeResult.modelCoefficients) return 0;
        const { intercept, linear, quadratic, interactions } = activeResult.modelCoefficients;
        let y = typeof intercept === 'number' ? intercept : parseFloat(intercept as any) || 0;

        if (linear) Object.entries(linear).forEach(([name, coeff]) => {
            const val = typeof inputs[name] === 'string' ? parseFloat(inputs[name] as string) : (inputs[name] as number);
            if (!isNaN(val)) y += coeff * toCoded(val, name);
        });
        if (quadratic) Object.entries(quadratic).forEach(([name, coeff]) => {
            const val = typeof inputs[name] === 'string' ? parseFloat(inputs[name] as string) : (inputs[name] as number);
            if (!isNaN(val)) y += coeff * Math.pow(toCoded(val, name), 2);
        });
        if (interactions) interactions.forEach(t => {
            const v1 = typeof inputs[t.factor1] === 'string' ? parseFloat(inputs[t.factor1] as string) : (inputs[t.factor1] as number);
            const v2 = typeof inputs[t.factor2] === 'string' ? parseFloat(inputs[t.factor2] as string) : (inputs[t.factor2] as number);
            if (!isNaN(v1) && !isNaN(v2)) y += t.coefficient * toCoded(v1, t.factor1) * toCoded(v2, t.factor2);
        });

        const { min, max } = getObservedRange(plotResponse);
        return Math.max(min, Math.min(max, y));
    }, [activeResult, factors, getObservedRange, plotResponse]);

    const calculatePrediction = () => setPredictedValue(calculatePredictionInternal(predictionInputs));

    const calculateDesirability = useCallback((val: number) => {
        const range = optMax - optMin;
        if (range <= 0 || isNaN(val)) return 0;
        if (optGoal === 'Maximize') return val <= optMin ? 0 : val >= optMax ? 1 : (val - optMin) / range;
        if (optGoal === 'Minimize') return val <= optMin ? 1 : val >= optMax ? 0 : (optMax - val) / range;
        if (val < optMin || val > optMax) return 0;
        if (val === optTarget) return 1;
        return val < optTarget ? (val - optMin) / (optTarget - optMin) : (optMax - val) / (optMax - optTarget);
    }, [optMax, optMin, optGoal, optTarget]);

    const findOptimalConditions = () => {
        if (!activeResult) return;
        const suggestions: OptResult[] = [];
        for (let i = 0; i < 15000; i++) {
            const trial: Record<string, number> = {};
            factors.forEach(f => {
                const low = parseFloat(f.low), high = parseFloat(f.high);
                trial[f.name] = low + Math.random() * (high - low);
            });
            const pred = calculatePredictionInternal(trial);
            const d = calculateDesirability(pred);
            suggestions.push({ factors: trial, prediction: pred, desirability: d });
        }
        suggestions.sort((a, b) => b.desirability - a.desirability);
        const unique: OptResult[] = [];
        for (const s of suggestions) {
            if (unique.length >= 3) break;
            const isDup = unique.some(e => factors.every(f => Math.abs(e.factors[f.name] - s.factors[f.name]) < (Math.abs(parseFloat(f.high) - parseFloat(f.low)) * 0.15)));
            if (!isDup) unique.push(s);
        }
        setTopSuggestions(unique);
    };

    useEffect(() => {
        if (!window.Plotly || !plotX || !plotY || !activeResult) return;
        const factorX = factors.find(f => f.name === plotX), factorY = factors.find(f => f.name === plotY);
        if (!factorX || !factorY) return;

        const xMin = parseFloat(factorX.low), xMax = parseFloat(factorX.high);
        const yMin = parseFloat(factorY.low), yMax = parseFloat(factorY.high);
        const steps = 50; // Higher resolution for smoother plots
        const xVals = [], yVals = [], zMat = [], dMat = [];

        for (let i = 0; i <= steps; i++) xVals.push(xMin + (i * (xMax - xMin) / steps));
        for (let i = 0; i <= steps; i++) yVals.push(yMin + (i * (yMax - yMin) / steps));

        for (let j = 0; j <= steps; j++) {
            const rowZ = [], rowD = [];
            for (let i = 0; i <= steps; i++) {
                const inputs = { ...predictionInputs, [plotX]: xVals[i], [plotY]: yVals[j] };
                const pred = calculatePredictionInternal(inputs);
                rowZ.push(pred);
                rowD.push(calculateDesirability(pred));
            }
            zMat.push(rowZ);
            dMat.push(rowD);
        }

        const observed = getObservedRange(plotResponse);
        const markerTrace = topSuggestions.length > 0 ? {
            x: topSuggestions.map(s => s.factors[plotX]),
            y: topSuggestions.map(s => s.factors[plotY]),
            mode: 'markers+text',
            type: 'scatter',
            text: ['#1', '#2', '#3'],
            textposition: 'top center',
            marker: { 
                color: '#fff', 
                size: 14, 
                line: { color: '#1e293b', width: 2.5 },
                symbol: 'circle'
            },
            textfont: { family: 'Inter, sans-serif', weight: 'bold', size: 10 },
            showlegend: false
        } : null;

        // Scientific color scales
        const responseColorScale = 'Viridis';
        const desirabilityColorScale = [
            [0, '#ef4444'],   // Red
            [0.25, '#f97316'], // Orange
            [0.5, '#facc15'],  // Yellow
            [0.75, '#a3e635'], // Light Green
            [1, '#22c55e']     // Success Green
        ];

        const commonLayout = {
            margin: { l: 40, r: 20, t: 40, b: 40 },
            font: { family: 'Inter, sans-serif', size: 11 },
            paper_bgcolor: 'rgba(0,0,0,0)',
            plot_bgcolor: 'rgba(0,0,0,0)'
        };

        // 3D Surface Rendering
        if (containerRefs.plot3d.current) {
            window.Plotly.react(containerRefs.plot3d.current, [{
                z: zMat, x: xVals, y: yVals,
                type: 'surface',
                colorscale: responseColorScale,
                colorbar: { title: { text: plotResponse, font: { size: 10 } }, thickness: 15, len: 0.8 },
                lighting: { ambient: 0.7, diffuse: 0.8, specular: 0.2, roughness: 0.9 },
                contours: {
                    z: { show: true, usecolormap: true, highlightcolor: "#42f4f4", project: { z: true } }
                }
            }], {
                ...commonLayout,
                title: { text: `3D Response Surface`, font: { size: 14, weight: 'bold' } },
                scene: {
                    xaxis: { title: plotX, backgroundcolor: "rgb(250, 250, 250)", showbackground: true, gridcolor: "rgb(255, 255, 255)" },
                    yaxis: { title: plotY, backgroundcolor: "rgb(245, 245, 245)", showbackground: true, gridcolor: "rgb(255, 255, 255)" },
                    zaxis: { title: plotResponse, backgroundcolor: "rgb(240, 240, 240)", showbackground: true, gridcolor: "rgb(255, 255, 255)" },
                    camera: { eye: { x: 1.5, y: 1.5, z: 1.2 } }
                }
            }, { responsive: true });
        }

        // Response Contour Enhancement
        if (containerRefs.plotContour.current) {
            const traces: any = [{
                z: zMat, x: xVals, y: yVals,
                type: 'contour',
                colorscale: 'Portland', // Distinctive high-contrast scale
                contours: { showlabels: true, labelfont: { size: 10, color: 'white' } },
                line: { smoothing: 1, width: 0.5, color: 'rgba(255,255,255,0.2)' },
                colorbar: { title: { text: 'Response', font: { size: 10 } }, thickness: 12, len: 0.8 }
            }];
            if (markerTrace) traces.push(markerTrace);
            window.Plotly.react(containerRefs.plotContour.current, traces, {
                ...commonLayout,
                title: { text: `Isopleth Model Map`, font: { size: 14, weight: 'bold' } },
                xaxis: { title: plotX, gridcolor: '#f1f5f9' },
                yaxis: { title: plotY, gridcolor: '#f1f5f9' }
            }, { responsive: true });
        }

        // Desirability Map Enhancement
        if (containerRefs.plotDesirability.current) {
            const traces: any = [{
                z: dMat, x: xVals, y: yVals,
                type: 'contour',
                colorscale: desirabilityColorScale,
                zmin: 0, zmax: 1,
                contours: { showlabels: true, start: 0, end: 1, size: 0.1, labelfont: { size: 9 } },
                colorbar: { title: { text: 'Prob.', font: { size: 10 } }, thickness: 12, len: 0.8 },
                line: { smoothing: 1.2, width: 0.8, color: 'rgba(0,0,0,0.1)' }
            }];
            if (markerTrace) traces.push(markerTrace);
            window.Plotly.react(containerRefs.plotDesirability.current, traces, {
                ...commonLayout,
                title: { text: `Desirability Prob. Landscape`, font: { size: 14, weight: 'bold', color: '#4338ca' } },
                xaxis: { title: plotX, gridcolor: '#f1f5f9' },
                yaxis: { title: plotY, gridcolor: '#f1f5f9' }
            }, { responsive: true });
        }
    }, [plotX, plotY, plotResponse, activeResult, predictionInputs, topSuggestions, calculatePredictionInternal, calculateDesirability, factors, getObservedRange]);

    useEffect(() => {
        if (!window.Plotly || !activeResult?.diagnostics) return;
        const d = activeResult.diagnostics;
        const actualMin = Math.min(...d.actual), actualMax = Math.max(...d.actual);

        const diagnosticLayout = {
            margin: { t: 30, b: 40, l: 40, r: 10 },
            font: { family: 'Inter, sans-serif', size: 10 },
            paper_bgcolor: 'rgba(0,0,0,0)',
            plot_bgcolor: 'rgba(255,255,255,0.5)'
        };

        const predVsActualEl = document.getElementById('plotPredVsActual');
        if (predVsActualEl) {
            window.Plotly.react(predVsActualEl, [
                { x: d.actual, y: d.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9', size: 8, opacity: 0.7, line: { color: 'white', width: 1 } }, name: 'Data Points' },
                { x: [actualMin, actualMax], y: [actualMin, actualMax], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8', width: 1.5 }, name: 'Perfect Fit' }
            ], { ...diagnosticLayout, title: 'Predicted vs Actual', xaxis: { title: 'Actual Observed' }, yaxis: { title: 'Model Predicted' }, showlegend: false });
        }

        const residVsRunEl = document.getElementById('plotResidVsRun');
        if (residVsRunEl) {
            window.Plotly.react(residVsRunEl, [
                { x: d.runOrder, y: d.residuals, type: 'scatter', mode: 'markers', marker: { color: '#f97316', size: 8, opacity: 0.7, line: { color: 'white', width: 1 } } }
            ], { 
                ...diagnosticLayout, 
                title: 'Residuals vs Run Order', 
                xaxis: { title: 'Experiment ID' }, 
                yaxis: { title: 'Residual Error' }, 
                shapes: [{ type: 'line', x0: Math.min(...d.runOrder), x1: Math.max(...d.runOrder), y0: 0, y1: 0, line: { color: 'rgba(0,0,0,0.5)', dash: 'dot', width: 1 } }] 
            });
        }

        const boxCoxEl = document.getElementById('plotBoxCox');
        if (boxCoxEl && d.boxCox) {
            const shapes: any = [];
            if (d.boxCox.ciLimit) shapes.push({ type: 'line', x0: Math.min(...d.boxCox.lambda), x1: Math.max(...d.boxCox.lambda), y0: d.boxCox.ciLimit, y1: d.boxCox.ciLimit, line: { color: '#ef4444', dash: 'dash', width: 1.5 } });
            if (d.boxCox.lambdaLow && d.boxCox.lambdaHigh) {
                shapes.push({ type: 'line', x0: d.boxCox.lambdaLow, x1: d.boxCox.lambdaLow, y0: Math.min(...d.boxCox.lnRSS), y1: Math.max(...d.boxCox.lnRSS), line: { color: '#ef4444', dash: 'dot', width: 1 } });
                shapes.push({ type: 'line', x0: d.boxCox.lambdaHigh, x1: d.boxCox.lambdaHigh, y0: Math.min(...d.boxCox.lnRSS), y1: Math.max(...d.boxCox.lnRSS), line: { color: '#ef4444', dash: 'dot', width: 1 } });
            }
            window.Plotly.react(boxCoxEl, [{ 
                x: d.boxCox.lambda, y: d.boxCox.lnRSS, 
                type: 'scatter', mode: 'lines', 
                line: { color: '#8b5cf6', width: 3, shape: 'spline' },
                fill: 'tozeroy', fillcolor: 'rgba(139, 92, 246, 0.05)'
            }], { ...diagnosticLayout, title: 'Box-Cox Transform Analysis', xaxis: { title: 'Lambda (λ)' }, yaxis: { title: 'ln(RSS)' }, shapes });
        }
    }, [activeResult]);

    if (!activeResult) return <div className="p-12 text-center text-slate-400 italic bg-white rounded-2xl border-2 border-dashed border-slate-200">Please select a response to view the analysis dashboard.</div>;

    const stats = activeResult.fitStatistics;
    const adeqPrecComment = stats.adequatePrecision > 4 ? "Excellent: Signal is sufficient for design space navigation." : "Warning: Low signal strength. Model may struggle with prediction.";
    const predR2Diff = Math.abs(stats.adjRSquared - stats.predictedRSquared);
    const predR2Comment = predR2Diff < 0.2 ? "Agreement: Model generalizes well to new data." : "Mismatch: Possible over-fitting or outlier influence.";

    return (
        <div className="space-y-8 pb-24 animate-in fade-in duration-700">
            {/* Executive Model Summary */}
            <div className="bg-white p-8 rounded-3xl shadow-xl border border-slate-100 ring-1 ring-slate-200/50">
                <div className="flex flex-col lg:flex-row justify-between items-start gap-6 mb-8">
                    <div>
                        <div className="flex items-center gap-2 mb-1">
                            <span className="px-2 py-0.5 rounded bg-science-100 text-science-700 text-[10px] font-black uppercase tracking-wider">ANOVA Validated</span>
                            <span className="text-slate-400 text-[10px] font-medium">• 95% Confidence Level</span>
                        </div>
                        <h2 className="text-3xl font-black text-slate-900 tracking-tight flex items-center gap-3"><LayoutDashboard className="text-science-500" /> Analytical Report: {plotResponse}</h2>
                    </div>
                    <div className="flex gap-3">
                        <div className="group bg-white p-4 rounded-2xl text-center min-w-[120px] border border-slate-100 shadow-sm transition-all hover:border-science-300">
                            <span className="text-[10px] font-bold text-slate-400 block uppercase mb-1">R-Squared</span>
                            <span className="text-2xl font-black text-slate-900 leading-none">{stats.rSquared.toFixed(4)}</span>
                        </div>
                        <div className="group bg-slate-50 p-4 rounded-2xl text-center min-w-[120px] border border-slate-200 shadow-inner transition-all hover:bg-slate-100">
                            <span className="text-[10px] font-bold text-slate-500 block uppercase mb-1">Adj R-Squared</span>
                            <span className="text-2xl font-black text-slate-900 leading-none">{stats.adjRSquared.toFixed(4)}</span>
                        </div>
                    </div>
                </div>

                <div className="grid lg:grid-cols-12 gap-6 mb-8">
                    <div className="lg:col-span-8 bg-slate-950 p-6 rounded-2xl border border-slate-800 shadow-2xl relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-4 opacity-10 rotate-12 group-hover:rotate-0 transition-transform"><Sigma size={60} className="text-white" /></div>
                        <div className="flex items-center gap-2 mb-4">
                            <Calculator className="text-science-400" size={16} />
