                                    <span className="text-lg font-black text-white">{(s.desirability * 100).toFixed(1)}% Desirability</span>
                                </div>
                                <div className="text-5xl font-black text-white mb-8 leading-none tracking-tighter">{s.prediction.toFixed(4)} <span className="text-base font-normal text-slate-500 block mt-1">{getResponseUnit(plotResponse)}</span></div>
                                <div className="space-y-4 pt-6 border-t border-slate-800/50">
