                        <MousePointer2 size={60} className="mx-auto mb-6 opacity-20" /><p className="text-xl font-bold tracking-tight">Enter goal constraints and initiate the search.</p>
                    </div>
                )}
            </div>

            <div className="bg-white p-10 rounded-[2.5rem] border border-slate-200 shadow-2xl relative group overflow-hidden">
                <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none"><Calculator size={150} /></div>
                <div className="relative z-10">
                    <h3 className="text-2xl font-black text-slate-900 mb-8 flex items-center gap-3"><Calculator size={30} className="text-science-600" /> Real-Time Equation Calculator</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8 mb-12">
                        {factors.map(f => (
                            <div key={f.name} className="space-y-2">
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-1 tracking-widest px-1">{f.name} <span className="text-slate-300 normal-case ml-1">[{f.low}-{f.high}]</span></label>
                                <input type="number" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-science-500 focus:bg-white outline-none text-base font-bold text-slate-800 shadow-sm" value={predictionInputs[f.name] || ''} onChange={e => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}/>
                            </div>
                        ))}
                    </div>
                    <div className="flex flex-col md:flex-row items-center gap-12 pt-10 border-t border-slate-100">
                        <button onClick={calculatePrediction} className="w-full md:w-auto bg-slate-950 text-white px-14 py-5 rounded-2xl hover:bg-black font-black flex items-center justify-center gap-4 shadow-2xl transition-all active:scale-95 group/btn"><Play size={20} /> Execute Prediction</button>
                        {predictedValue !== null && (
