                                <div className="flex items-baseline gap-3"><span className="text-6xl font-black text-slate-900 tracking-tighter leading-none">{predictedValue.toFixed(4)}</span><span className="text-xl font-bold text-slate-400 lowercase">{getResponseUnit(plotResponse)}</span></div>
                            </div>
                        )}
                    </div>
                    <div className="mt-10 flex items-start gap-4 bg-science-50/50 p-6 rounded-3xl border border-science-100/50 transition-all hover:bg-science-50">
                        <Sigma size={20} className="text-science-500 shrink-0 mt-1" />
                        <div className="space-y-1">
                            <p className="text-xs text-slate-600 leading-relaxed font-bold">Model Integrity Notice:</p>
                            <p className="text-[10px] text-slate-500 leading-relaxed">This predictor strictly utilizes the 95% confidence interval regression coefficients. Results are clamped to the experimental boundaries to ensure scientific validity.</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AnalysisDashboard;

import React, { useEffect, useState, useCallback, useRef } from 'react';
import { AnalysisResult, FactorDefinition, ResponseDefinition, ResponseAnalysis } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Cuboid, Layers, Activity, Calculator, Play, Sigma, Triangle, Trophy, Target, Search, MousePointer2, Info, Maximize2, Download } from 'lucide-react';

declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
    isMixture?: boolean;
}

interface OptResult {
    factors: Record<string, number>;
    prediction: number;
    desirability: number;
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses, isMixture = false }) => {
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');
    const [optGoal, setOptGoal] = useState<'Maximize' | 'Minimize' | 'Target'>('Maximize');
    const [optTarget, setOptTarget] = useState<number>(0);
    const [optMin, setOptMin] = useState<number>(0);
    const [optMax, setOptMax] = useState<number>(100);
    const [topSuggestions, setTopSuggestions] = useState<OptResult[]>([]);

    const containerRefs = {
        plot3d: useRef<HTMLDivElement>(null),
        plotContour: useRef<HTMLDivElement>(null),
        plotDesirability: useRef<HTMLDivElement>(null)
    };

    const getResponseUnit = (name: string) => {
        return responses.find(r => r.name === name)?.unit || '';
    };

    const handleExportWord = () => {
        const header = `
            <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
            <head><meta charset='utf-8'><title>QbD-PharmOptima Report</title>
            <style>
                body { font-family: 'Segoe UI', Arial, sans-serif; }
                h1 { color: #0c4a6e; border-bottom: 2px solid #0ea5e9; }
                h2 { color: #075985; margin-top: 30px; border-left: 10px solid #0ea5e9; padding-left: 10px; }
                table { border-collapse: collapse; width: 100%; margin-bottom: 20px; }
                th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
                th { background-color: #f0f9ff; font-weight: bold; }
                .equation { font-family: 'Courier New', monospace; background: #f8fafc; padding: 10px; border: 1px solid #e2e8f0; }
                .stat-box { display: inline-block; padding: 10px; background: #f0f9ff; border: 1px solid #bae6fd; margin-right: 10px; }
                .markdown { font-size: 11pt; color: #334155; }
            </style>
            </head><body>
        `;

        let content = `<h1>QbD-PharmOptima: Pharmaceutical Formulation Report</h1>`;
        content += `<p>Generated on: ${new Date().toLocaleString()}</p>`;

        // Factors Summary
        content += `<h2>Independent Variables (Factors)</h2>`;
        content += `<table><thead><tr><th>Factor</th><th>Unit</th><th>Range</th><th>Levels</th></tr></thead><tbody>`;
        factors.forEach(f => {
            content += `<tr><td>${f.name}</td><td>${f.unit || '-'}</td><td>${f.low} to ${f.high}</td><td>${f.levels}</td></tr>`;
        });
        content += `</tbody></table>`;

        // Response Summary Loop
        Object.entries(results.resultsByResponse).forEach(([name, res]) => {
            content += `<h2>Analysis for Response: ${name}</h2>`;

            content += `<h3>Model Fit Statistics</h3>`;
            content += `<div class='stat-box'><b>R²:</b> ${res.fitStatistics.rSquared.toFixed(4)}</div>`;
            content += `<div class='stat-box'><b>Adj R²:</b> ${res.fitStatistics.adjRSquared.toFixed(4)}</div>`;
            content += `<div class='stat-box'><b>Pred R²:</b> ${res.fitStatistics.predictedRSquared.toFixed(4)}</div>`;
            content += `<div class='stat-box'><b>Adeq Precision:</b> ${res.fitStatistics.adequatePrecision.toFixed(2)}</div>`;

            content += `<h3>Regression Equation (Coded)</h3>`;
            content += `<p class='equation'>${res.fitStatistics.equation}</p>`;

            content += `<h3>ANOVA Interpretation</h3>`;
            content += `<div class='markdown'>${res.anovaText.replace(/\n/g, '<br/>')}</div>`;

            content += `<h3>Diagnostic Commentary</h3>`;
            content += `<ul>`;
            content += `<li><b>Actual vs Predicted:</b> ${res.diagnosticInterpretations.predVsActual}</li>`;
            content += `<li><b>Residual Stability:</b> ${res.diagnosticInterpretations.residualsVsRun}</li>`;
            content += `<li><b>Box-Cox Transform:</b> ${res.diagnosticInterpretations.boxCox}</li>`;
            content += `</ul>`;
        });

        // Optimization Results if they exist
        if (topSuggestions.length > 0) {
            content += `<h2>Optimization Benchmarks</h2>`;
            content += `<p>Goal: ${optGoal} (Targeting ${optMin} to ${optMax})</p>`;
            content += `<table><thead><tr><th>Rank</th><th>${plotResponse} Predict</th><th>Desirability</th>`;
            factors.forEach(f => content += `<th>${f.name}</th>`);
            content += `</tr></thead><tbody>`;
            topSuggestions.forEach((s, idx) => {
                content += `<tr><td>#${idx + 1}</td><td>${s.prediction.toFixed(4)}</td><td>${(s.desirability * 100).toFixed(1)}%</td>`;
                factors.forEach(f => content += `<td>${s.factors[f.name].toFixed(3)}</td>`);
                content += `</tr>`;
            });
            content += `</tbody></table>`;
        }

        const footer = `</body></html>`;
        const blob = new Blob([header + content + footer], { type: 'application/msword' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `QbD_Report_${plotResponse.replace(/\s+/g, '_')}.doc`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => {
            const mid = (parseFloat(f.low) + parseFloat(f.high)) / 2;
            initial[f.name] = isNaN(mid) ? "0" : mid.toString();
        });
        setPredictionInputs(initial);
        if (factors.length >= 2) {
            setPlotX(factors[0].name);
            setPlotY(factors[1].name);
        }
        if (responses.length > 0) {
            setPlotResponse(responses[0].name);
        }
    }, [factors, responses]);

    const activeResult = results.resultsByResponse[plotResponse];

    const getObservedRange = useCallback((resName: string) => {
        const res = results.resultsByResponse[resName];
        if (!res || !res.diagnostics || !res.diagnostics.actual || res.diagnostics.actual.length === 0) {
            return { min: 0, max: 100 };
        }
        const cleanData = res.diagnostics.actual.filter(v => typeof v === 'number' && !isNaN(v));
        if (cleanData.length === 0) return { min: 0, max: 100 };
        return { min: Math.min(...cleanData), max: Math.max(...cleanData) };
    }, [results]);

    useEffect(() => {
        const range = getObservedRange(plotResponse);
        setOptMin(range.min);
        setOptMax(range.max);
        setOptTarget((range.min + range.max) / 2);
        const resDef = responses.find(r => r.name === plotResponse);
        if (resDef) setOptGoal(resDef.goal);
    }, [plotResponse, getObservedRange, responses]);

    const toCoded = (val: number, factorName: string) => {
        const factor = factors.find(f => f.name === factorName);
        if (!factor) return 0;
        const low = parseFloat(factor.low), high = parseFloat(factor.high);
        const mid = (high + low) / 2, halfRange = (high - low) / 2;
        return halfRange === 0 ? 0 : (val - mid) / halfRange;
    };

    const calculatePredictionInternal = useCallback((inputs: Record<string, string | number>) => {
        if (!activeResult || !activeResult.modelCoefficients) return 0;
        const { intercept, linear, quadratic, interactions } = activeResult.modelCoefficients;
        let y = typeof intercept === 'number' ? intercept : parseFloat(intercept as any) || 0;
        if (linear) Object.entries(linear).forEach(([name, coeff]) => {
            const val = typeof inputs[name] === 'string' ? parseFloat(inputs[name] as string) : (inputs[name] as number);
            if (!isNaN(val)) y += coeff * toCoded(val, name);
        });
        if (quadratic) Object.entries(quadratic).forEach(([name, coeff]) => {
            const val = typeof inputs[name] === 'string' ? parseFloat(inputs[name] as string) : (inputs[name] as number);
            if (!isNaN(val)) y += coeff * Math.pow(toCoded(val, name), 2);
        });
        if (interactions) interactions.forEach(t => {
            const v1 = typeof inputs[t.factor1] === 'string' ? parseFloat(inputs[t.factor1] as string) : (inputs[t.factor1] as number);
            const v2 = typeof inputs[t.factor2] === 'string' ? parseFloat(inputs[t.factor2] as string) : (inputs[t.factor2] as number);
            if (!isNaN(v1) && !isNaN(v2)) y += t.coefficient * toCoded(v1, t.factor1) * toCoded(v2, t.factor2);
        });
        const { min, max } = getObservedRange(plotResponse);
        return Math.max(min, Math.min(max, y));
    }, [activeResult, factors, getObservedRange, plotResponse]);

    const calculatePrediction = () => setPredictedValue(calculatePredictionInternal(predictionInputs));

    const calculateDesirability = useCallback((val: number) => {
        const range = optMax - optMin;
        if (range <= 0 || isNaN(val)) return 0;
        if (optGoal === 'Maximize') return val <= optMin ? 0 : val >= optMax ? 1 : (val - optMin) / range;
        if (optGoal === 'Minimize') return val <= optMin ? 1 : val >= optMax ? 0 : (optMax - val) / range;
        if (val < optMin || val > optMax) return 0;
        if (val === optTarget) return 1;
        return val < optTarget ? (val - optMin) / (optTarget - optMin) : (optMax - val) / (optMax - optTarget);
    }, [optMax, optMin, optGoal, optTarget]);

    const findOptimalConditions = () => {
        if (!activeResult) return;
        const suggestions: OptResult[] = [];
        for (let i = 0; i < 15000; i++) {
            const trial: Record<string, number> = {};
            factors.forEach(f => {
                const low = parseFloat(f.low), high = parseFloat(f.high);
                trial[f.name] = low + Math.random() * (high - low);
            });
            const pred = calculatePredictionInternal(trial);
            const d = calculateDesirability(pred);
            suggestions.push({ factors: trial, prediction: pred, desirability: d });
        }
        suggestions.sort((a, b) => b.desirability - a.desirability);
        const unique: OptResult[] = [];
        for (const s of suggestions) {
            if (unique.length >= 3) break;
            const isDup = unique.some(e => factors.every(f => Math.abs(e.factors[f.name] - s.factors[f.name]) < (Math.abs(parseFloat(f.high) - parseFloat(f.low)) * 0.15)));
            if (!isDup) unique.push(s);
        }
        setTopSuggestions(unique);
    };

    useEffect(() => {
        if (!window.Plotly || !plotX || !plotY || !activeResult) return;
        const factorX = factors.find(f => f.name === plotX), factorY = factors.find(f => f.name === plotY);
        if (!factorX || !factorY) return;
        const xMin = parseFloat(factorX.low), xMax = parseFloat(factorX.high);
        const yMin = parseFloat(factorY.low), yMax = parseFloat(factorY.high);
        const steps = 50;
        const xVals = [], yVals = [], zMat = [], dMat = [];
        for (let i = 0; i <= steps; i++) xVals.push(xMin + (i * (xMax - xMin) / steps));
        for (let i = 0; i <= steps; i++) yVals.push(yMin + (i * (yMax - yMin) / steps));
        for (let j = 0; j <= steps; j++) {
            const rowZ = [], rowD = [];
            for (let i = 0; i <= steps; i++) {
                const inputs = { ...predictionInputs, [plotX]: xVals[i], [plotY]: yVals[j] };
                const pred = calculatePredictionInternal(inputs);
                rowZ.push(pred);
                rowD.push(calculateDesirability(pred));
            }
            zMat.push(rowZ);
            dMat.push(rowD);
        }
        const observed = getObservedRange(plotResponse);
        const markerTrace = topSuggestions.length > 0 ? {
            x: topSuggestions.map(s => s.factors[plotX]),
            y: topSuggestions.map(s => s.factors[plotY]),
            mode: 'markers+text', type: 'scatter', text: ['#1', '#2', '#3'], textposition: 'top center',
            marker: { color: '#fff', size: 14, line: { color: '#1e293b', width: 2.5 }, symbol: 'circle' },
            textfont: { family: 'Inter, sans-serif', weight: 'bold', size: 10 }, showlegend: false
        } : null;
        const desirabilityColorScale = [[0, '#ef4444'], [0.25, '#f97316'], [0.5, '#facc15'], [0.75, '#a3e635'], [1, '#22c55e']];
        const commonLayout = { margin: { l: 40, r: 20, t: 40, b: 40 }, font: { family: 'Inter, sans-serif', size: 11 }, paper_bgcolor: 'rgba(0,0,0,0)', plot_bgcolor: 'rgba(0,0,0,0)' };
        if (containerRefs.plot3d.current) {
            window.Plotly.react(containerRefs.plot3d.current, [{ z: zMat, x: xVals, y: yVals, type: 'surface', colorscale: 'Viridis', contours: { z: { show: true, usecolormap: true, highlightcolor: "#42f4f4", project: { z: true } } } }], { ...commonLayout, title: { text: `3D Response Surface`, font: { size: 14, weight: 'bold' } }, scene: { xaxis: { title: plotX }, yaxis: { title: plotY }, zaxis: { title: plotResponse }, camera: { eye: { x: 1.5, y: 1.5, z: 1.2 } } } });
        }
        if (containerRefs.plotContour.current) {
            const traces: any = [{ z: zMat, x: xVals, y: yVals, type: 'contour', colorscale: 'Portland', contours: { showlabels: true }, line: { smoothing: 1 } }];
            if (markerTrace) traces.push(markerTrace);
            window.Plotly.react(containerRefs.plotContour.current, traces, { ...commonLayout, title: { text: `Isopleth Model Map`, font: { size: 14, weight: 'bold' } }, xaxis: { title: plotX }, yaxis: { title: plotY } });
        }
        if (containerRefs.plotDesirability.current) {
            const traces: any = [{ z: dMat, x: xVals, y: yVals, type: 'contour', colorscale: desirabilityColorScale, zmin: 0, zmax: 1, contours: { showlabels: true, start: 0, end: 1, size: 0.1 } }];
            if (markerTrace) traces.push(markerTrace);
            window.Plotly.react(containerRefs.plotDesirability.current, traces, { ...commonLayout, title: { text: `Desirability Prob. Landscape`, font: { size: 14, weight: 'bold', color: '#4338ca' } }, xaxis: { title: plotX }, yaxis: { title: plotY } });
        }
    }, [plotX, plotY, plotResponse, activeResult, predictionInputs, topSuggestions, calculatePredictionInternal, calculateDesirability, factors, getObservedRange]);

    useEffect(() => {
        if (!window.Plotly || !activeResult?.diagnostics) return;
        const d = activeResult.diagnostics;
        const actualMin = Math.min(...d.actual), actualMax = Math.max(...d.actual);
        const diagnosticLayout = { margin: { t: 30, b: 40, l: 40, r: 10 }, font: { family: 'Inter, sans-serif', size: 10 }, paper_bgcolor: 'rgba(0,0,0,0)', plot_bgcolor: 'rgba(255,255,255,0.5)' };
        const pva = document.getElementById('plotPredVsActual');
        if (pva) window.Plotly.react(pva, [{ x: d.actual, y: d.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9' } }, { x: [actualMin, actualMax], y: [actualMin, actualMax], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' } }], { ...diagnosticLayout, title: 'Predicted vs Actual', xaxis: { title: 'Actual' }, yaxis: { title: 'Predicted' }, showlegend: false });
        const rvr = document.getElementById('plotResidVsRun');
        if (rvr) window.Plotly.react(rvr, [{ x: d.runOrder, y: d.residuals, type: 'scatter', mode: 'markers', marker: { color: '#f97316' } }], { ...diagnosticLayout, title: 'Residuals vs Run', xaxis: { title: 'Run' }, yaxis: { title: 'Residual' }, shapes: [{ type: 'line', x0: Math.min(...d.runOrder), x1: Math.max(...d.runOrder), y0: 0, y1: 0, line: { color: 'rgba(0,0,0,0.5)', dash: 'dot' } }] });
        const bc = document.getElementById('plotBoxCox');
        if (bc && d.boxCox) {
            const shapes: any = [];
            if (d.boxCox.ciLimit) shapes.push({ type: 'line', x0: Math.min(...d.boxCox.lambda), x1: Math.max(...d.boxCox.lambda), y0: d.boxCox.ciLimit, y1: d.boxCox.ciLimit, line: { color: '#ef4444', dash: 'dash' } });
            // FIXED: Use 'bc' instead of undefined 'boxCoxEl'
            window.Plotly.react(bc, [{ x: d.boxCox.lambda, y: d.boxCox.lnRSS, type: 'scatter', mode: 'lines', line: { color: '#8b5cf6', width: 3 } }], { ...diagnosticLayout, title: 'Box-Cox Analysis', xaxis: { title: 'Lambda' }, yaxis: { title: 'ln(RSS)' }, shapes });
        }
    }, [activeResult]);

    if (!activeResult) return <div className="p-12 text-center text-slate-400 italic bg-white rounded-2xl border-2 border-dashed border-slate-200">Please select a response to view the analysis dashboard.</div>;

    const stats = activeResult.fitStatistics;
    const adeqPrecComment = stats.adequatePrecision > 4 ? "Excellent: Signal is sufficient for design space navigation." : "Warning: Low signal strength. Model may struggle with prediction.";
    const predR2Diff = Math.abs(stats.adjRSquared - stats.predictedRSquared);
    const predR2Comment = predR2Diff < 0.2 ? "Agreement: Model generalizes well to new data." : "Mismatch: Possible over-fitting or outlier influence.";

    return (
        <div className="space-y-8 pb-24 animate-in fade-in duration-700">
            <div className="bg-white p-8 rounded-3xl shadow-xl border border-slate-100 ring-1 ring-slate-200/50">
                <div className="flex flex-col lg:flex-row justify-between items-start gap-6 mb-8">
                    <div>
                        <div className="flex items-center gap-2 mb-1">
                            <span className="px-2 py-0.5 rounded bg-science-100 text-science-700 text-[10px] font-black uppercase tracking-wider">ANOVA Validated</span>
                            <span className="text-slate-400 text-[10px] font-medium">• 95% Confidence Level</span>
                        </div>
                        <h2 className="text-3xl font-black text-slate-900 tracking-tight flex items-center gap-3"><LayoutDashboard className="text-science-500" /> Analytical Report: {plotResponse}</h2>
                    </div>
                    <div className="flex gap-3">
                        <button onClick={handleExportWord} className="bg-blue-600 text-white px-6 py-2 rounded-xl hover:bg-blue-700 font-bold flex items-center gap-2 shadow-lg transition-all active:scale-95">
                            <Download size={18} /> Export Results to Word
                        </button>
                        <div className="bg-white p-4 rounded-2xl text-center min-w-[120px] border border-slate-100 shadow-sm">
                            <span className="text-[10px] font-bold text-slate-400 block uppercase mb-1">R-Squared</span>
                            <span className="text-2xl font-black text-slate-900 leading-none">{stats.rSquared.toFixed(4)}</span>
                        </div>
                        <div className="bg-slate-50 p-4 rounded-2xl text-center min-w-[120px] border border-slate-200 shadow-inner">
                            <span className="text-[10px] font-bold text-slate-500 block uppercase mb-1">Adj R-Squared</span>
                            <span className="text-2xl font-black text-slate-900 leading-none">{stats.adjRSquared.toFixed(4)}</span>
                        </div>
                    </div>
                </div>

                <div className="grid lg:grid-cols-12 gap-6 mb-8">
                    <div className="lg:col-span-8 bg-slate-950 p-6 rounded-2xl border border-slate-800 shadow-2xl relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-4 opacity-10 rotate-12 group-hover:rotate-0 transition-transform"><Sigma size={60} className="text-white" /></div>
                        <div className="flex items-center gap-2 mb-4">
                            <Calculator className="text-science-400" size={16} />
                            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Global Predictive Equation (Coded)</h4>
                        </div>
                        <div className="font-mono text-sm text-science-50 break-words leading-relaxed bg-slate-900/50 p-4 rounded-xl border border-slate-800 shadow-inner">
                            {stats.equation || "Linear regression coefficients undefined."}
                        </div>
                    </div>
                    <div className="lg:col-span-4 space-y-4">
                        <div className="p-5 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                            <div className="flex justify-between items-center mb-2">
                                <span className="text-[10px] font-black text-indigo-600 uppercase tracking-wider flex items-center gap-1.5"><Activity size={12}/> Predicted R²</span>
                                <span className="text-lg font-black text-indigo-900">{stats.predictedRSquared.toFixed(4)}</span>
                            </div>
                            <div className="flex gap-2 items-start text-[9px] text-indigo-700 bg-white/50 p-2 rounded-lg leading-tight border border-indigo-100/50">
                                <Info size={10} className="shrink-0 mt-0.5"/>
                                <span>{predR2Comment}</span>
                            </div>
                        </div>
                        <div className="p-5 bg-emerald-50/50 rounded-2xl border border-emerald-100">
                            <div className="flex justify-between items-center mb-2">
                                <span className="text-[10px] font-black text-emerald-600 uppercase tracking-wider flex items-center gap-1.5"><Maximize2 size={12}/> Adeq Precision</span>
                                <span className="text-lg font-black text-emerald-900">{stats.adequatePrecision.toFixed(2)}</span>
                            </div>
                            <div className="flex gap-2 items-start text-[9px] text-emerald-700 bg-white/50 p-2 rounded-lg leading-tight border border-emerald-100/50">
                                <Info size={10} className="shrink-0 mt-0.5"/>
                                <span>{adeqPrecComment}</span>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="bg-slate-50 p-1 rounded-2xl border border-slate-200">
                    <div className="prose prose-sm max-w-none text-slate-600 bg-white p-6 rounded-xl shadow-inner max-h-[350px] overflow-y-auto">
                        <ReactMarkdown>{activeResult.anovaText}</ReactMarkdown>
                    </div>
                </div>
            </div>

            <div className="space-y-4">
                <div className="flex items-center gap-3 px-2">
                    <div className="w-10 h-1 bg-science-500 rounded-full"></div>
                    <h3 className="text-xl font-black text-slate-800 tracking-tight flex items-center gap-2 italic">Refined Diagnostics</h3>
                </div>
                <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                    <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm"><div id="plotPredVsActual" className="w-full h-[260px]"></div></div>
                    <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm"><div id="plotResidVsRun" className="w-full h-[260px]"></div></div>
                    <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm"><div id="plotBoxCox" className="w-full h-[260px]"></div></div>
                </div>
            </div>

            <div className="bg-slate-900 p-6 rounded-3xl shadow-xl flex flex-wrap gap-6 items-center border border-slate-800">
                <div className="flex gap-4">
                    <div>
                        <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 px-1 tracking-widest">Abscissa (X)</label>
                        <select className="p-2.5 rounded-xl border-2 border-slate-800 bg-slate-950 text-xs font-bold text-slate-200 focus:border-science-500 outline-none" value={plotX} onChange={e => setPlotX(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select>
                    </div>
                    <div>
                        <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 px-1 tracking-widest">Ordinate (Y)</label>
                        <select className="p-2.5 rounded-xl border-2 border-slate-800 bg-slate-950 text-xs font-bold text-slate-200 focus:border-science-500 outline-none" value={plotY} onChange={e => setPlotY(e.target.value)}>{factors.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}</select>
                    </div>
                </div>
                <div className="flex-1">
                    <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 px-1 tracking-widest">Response Surface Target</label>
                    <select className="w-full p-2.5 rounded-xl border-2 border-slate-800 bg-science-900/30 text-xs font-black text-science-100 focus:border-science-400 outline-none" value={plotResponse} onChange={e => setPlotResponse(e.target.value)}>{responses.map(r => <option key={r.name} value={r.name}>{r.name}</option>)}</select>
                </div>
            </div>

            <div className="grid lg:grid-cols-3 gap-8">
                <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-lg relative h-[400px]"><div ref={containerRefs.plot3d} className="w-full h-full"></div></div>
                <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-lg relative h-[400px]"><div ref={containerRefs.plotContour} className="w-full h-full"></div></div>
                <div className="bg-indigo-50/30 p-5 rounded-3xl border-2 border-indigo-100 shadow-2xl relative h-[400px] ring-2 ring-indigo-500/10"><div ref={containerRefs.plotDesirability} className="w-full h-full"></div></div>
            </div>

            <div className="bg-slate-950 p-10 rounded-[3rem] shadow-2xl text-white relative overflow-hidden border border-slate-800">
                <div className="absolute -top-10 -right-10 p-10 opacity-5 pointer-events-none rotate-12 scale-150"><Trophy size={200} /></div>
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8 mb-12 relative z-10">
                    <div>
                        <div className="inline-flex items-center gap-2 bg-yellow-400/10 text-yellow-400 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-tighter mb-4 border border-yellow-400/20">Quality Optimizer</div>
                        <h2 className="text-4xl font-black flex items-center gap-4 tracking-tighter leading-none"><Trophy className="text-yellow-400 drop-shadow-[0_0_10px_rgba(250,204,21,0.5)]" size={40} /> Numerical Solver</h2>
                        <p className="text-slate-400 text-base mt-2 max-w-xl font-medium">Finding the Pareto-optimal coordinates to satisfy your formulation goals using numerical search over the modeled design space.</p>
                    </div>
                    <button onClick={findOptimalConditions} className="group bg-white text-slate-950 px-12 py-5 rounded-2xl hover:bg-science-100 font-black flex items-center gap-4 shadow-[0_20px_50px_rgba(0,0,0,0.3)] transition-all active:scale-95 transform hover:-translate-y-1"><Search size={22} /> Run Search Algorithm</button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-16 bg-slate-900/40 p-8 rounded-3xl border border-slate-800 backdrop-blur-md">
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase block tracking-widest">Goal</label><select className="w-full p-4 bg-slate-800 border-2 border-slate-700 rounded-2xl text-sm font-bold focus:border-science-500 outline-none" value={optGoal} onChange={e => setOptGoal(e.target.value as any)}><option value="Maximize">Maximize Quality</option><option value="Minimize">Minimize Penalty</option><option value="Target">Exact Target</option></select></div>
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase block tracking-widest">Lower Limit (d=0)</label><input type="number" className="w-full p-4 bg-slate-800 border-2 border-slate-700 rounded-2xl text-sm font-bold focus:border-science-500 outline-none" value={optMin} onChange={e => setOptMin(parseFloat(e.target.value))}/></div>
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase block tracking-widest">Upper Limit (d=1)</label><input type="number" className="w-full p-4 bg-slate-800 border-2 border-slate-700 rounded-2xl text-sm font-bold focus:border-science-500 outline-none" value={optMax} onChange={e => setOptMax(parseFloat(e.target.value))}/></div>
                    {optGoal === 'Target' && <div className="space-y-2"><label className="text-[10px] font-black text-science-400 uppercase block tracking-widest">Set-point</label><input type="number" className="w-full p-4 bg-slate-800 border-2 border-science-500 rounded-2xl text-sm font-black text-science-100" value={optTarget} onChange={e => setOptTarget(parseFloat(e.target.value))}/></div>}
                </div>

                {topSuggestions.length > 0 ? (
                    <div className="grid md:grid-cols-3 gap-8 relative z-10">
                        {topSuggestions.map((s, idx) => (
                            <div key={idx} className={`group relative p-8 rounded-[2.5rem] border-2 transition-all cursor-default ${idx === 0 ? 'border-science-500 bg-science-950/20 shadow-2xl scale-105' : 'border-slate-800 bg-slate-900/40'}`}>
                                <div className={`absolute -top-5 -left-5 w-12 h-12 rounded-2xl flex items-center justify-center font-black ${idx === 0 ? 'bg-science-500 text-white' : 'bg-slate-700 text-slate-300'}`}>{idx + 1}</div>
                                <div className="flex justify-between items-center mb-6">
                                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Top Predictor</span>
                                    <span className="text-lg font-black text-white">{(s.desirability * 100).toFixed(1)}% Desirability</span>
                                </div>
                                <div className="text-5xl font-black text-white mb-8 leading-none tracking-tighter">{s.prediction.toFixed(4)} <span className="text-base font-normal text-slate-500 block mt-1">{getResponseUnit(plotResponse)}</span></div>
                                <div className="space-y-4 pt-6 border-t border-slate-800/50">
                                    {Object.entries(s.factors).map(([k, v]) => (
                                        <div key={k} className="flex justify-between text-xs items-center">
                                            <span className="text-slate-400 font-medium">{k}</span>
                                            <span className="font-black text-slate-100 bg-slate-800/50 px-3 py-1 rounded-lg">{v.toFixed(3)}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="text-center p-24 text-slate-600 border-2 border-dashed border-slate-800 rounded-[3rem] bg-slate-900/10">
                        <MousePointer2 size={60} className="mx-auto mb-6 opacity-20" /><p className="text-xl font-bold tracking-tight">Enter goal constraints and initiate the search.</p>
                    </div>
                )}
            </div>

            <div className="bg-white p-10 rounded-[2.5rem] border border-slate-200 shadow-2xl relative group overflow-hidden">
                <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none"><Calculator size={150} /></div>
                <div className="relative z-10">
                    <h3 className="text-2xl font-black text-slate-900 mb-8 flex items-center gap-3"><Calculator size={30} className="text-science-600" /> Real-Time Equation Calculator</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8 mb-12">
                        {factors.map(f => (
                            <div key={f.name} className="space-y-2">
                                <label className="block text-[10px] font-black text-slate-400 uppercase mb-1 tracking-widest px-1">{f.name} <span className="text-slate-300 normal-case ml-1">[{f.low}-{f.high}]</span></label>
                                <input type="number" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-science-500 focus:bg-white outline-none text-base font-bold text-slate-800 shadow-sm" value={predictionInputs[f.name] || ''} onChange={e => setPredictionInputs({...predictionInputs, [f.name]: e.target.value})}/>
                            </div>
                        ))}
                    </div>
                    <div className="flex flex-col md:flex-row items-center gap-12 pt-10 border-t border-slate-100">
                        <button onClick={calculatePrediction} className="w-full md:w-auto bg-slate-950 text-white px-14 py-5 rounded-2xl hover:bg-black font-black flex items-center justify-center gap-4 shadow-2xl transition-all active:scale-95 group/btn"><Play size={20} /> Execute Prediction</button>
                        {predictedValue !== null && (
                            <div className="flex flex-col items-center md:items-start group/res">
                                <span className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2 leading-none">Statistical Best Estimate</span>
                                <div className="flex items-baseline gap-3"><span className="text-6xl font-black text-slate-900 tracking-tighter leading-none">{predictedValue.toFixed(4)}</span><span className="text-xl font-bold text-slate-400 lowercase">{getResponseUnit(plotResponse)}</span></div>
                            </div>
                        )}
                    </div>
                    <div className="mt-10 flex items-start gap-4 bg-science-50/50 p-6 rounded-3xl border border-science-100/50 transition-all hover:bg-science-50">
                        <Sigma size={20} className="text-science-500 shrink-0 mt-1" />
                        <div className="space-y-1">
                            <p className="text-xs text-slate-600 leading-relaxed font-bold">Model Integrity Notice:</p>
                            <p className="text-[10px] text-slate-500 leading-relaxed">This predictor strictly utilizes the 95% confidence interval regression coefficients. Results are clamped to the experimental boundaries to ensure scientific validity.</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

