const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses, isMixture = false }) => {
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');
    const [optGoal, setOptGoal] = useState<'Maximize' | 'Minimize' | 'Target'>('Maximize');
    const [optTarget, setOptTarget] = useState<number>(0);
    const [optMin, setOptMin] = useState<number>(0);
    const [optMax, setOptMax] = useState<number>(100);
    const [topSuggestions, setTopSuggestions] = useState<OptResult[]>([]);

    const containerRefs = {
        plot3d: useRef<HTMLDivElement>(null),
        plotContour: useRef<HTMLDivElement>(null),
        plotDesirability: useRef<HTMLDivElement>(null)
    };

    const getResponseUnit = (name: string) => responses.find(r => r.name === name)?.unit || '';

    const handleExportWord = () => {
        const header = `
            <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
            <head><meta charset='utf-8'><title>QbD-PharmOptima Report</title>
            <style>
                body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; padding: 40px; }
                h1 { color: #0c4a6e; border-bottom: 3px solid #0ea5e9; padding-bottom: 10px; }
                h2 { color: #075985; margin-top: 30px; border-left: 12px solid #0ea5e9; padding-left: 15px; background: #f0f9ff; }
                h3 { color: #0284c7; margin-top: 20px; }
                table { border-collapse: collapse; width: 100%; margin: 20px 0; border: 2px solid #0c4a6e; }
                th, td { border: 1px solid #cbd5e1; padding: 12px; text-align: left; }
                th { background-color: #f1f5f9; color: #1e293b; font-weight: 800; text-transform: uppercase; font-size: 9pt; }
                .equation { font-family: 'Consolas', 'Courier New', monospace; background: #0f172a; color: #38bdf8; padding: 20px; border-radius: 8px; font-size: 11pt; margin: 15px 0; }
                .stat-box { display: inline-block; padding: 15px; background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 12px; margin: 10px 10px 10px 0; box-shadow: 2px 2px 5px rgba(0,0,0,0.05); }
                .markdown { font-size: 11pt; color: #334155; line-height: 1.6; }
                .footer { margin-top: 50px; font-size: 8pt; color: #94a3b8; border-top: 1px solid #e2e8f0; padding-top: 10px; }
            </style>
            </head><body>
        `;

        let content = `<h1>QbD-PharmOptima: Scientific Formulation Report</h1>`;
        content += `<p>Date: ${new Date().toLocaleDateString()} ${new Date().toLocaleTimeString()}</p>`;
        content += `<h2>1. Experimental Scope</h2>`;
        content += `<h3>Factors (Independent Variables)</h3>`;
        content += `<table><thead><tr><th>Name</th><th>Unit</th><th>Low (-1)</th><th>High (+1)</th><th>Levels</th></tr></thead><tbody>`;
        factors.forEach(f => content += `<tr><td>${f.name}</td><td>${f.unit || '-'}</td><td>${f.low}</td><td>${f.high}</td><td>${f.levels}</td></tr>`);
        content += `</tbody></table>`;

        Object.entries(results.resultsByResponse).forEach(([name, res]) => {
            content += `<h2>2. Analysis: ${name}</h2>`;
            content += `<div class='stat-box'><b>R-Squared:</b> ${res.fitStatistics.rSquared.toFixed(4)}</div>`;
            content += `<div class='stat-box'><b>Adj R²:</b> ${res.fitStatistics.adjRSquared.toFixed(4)}</div>`;
            content += `<div class='stat-box'><b>Pred R²:</b> ${res.fitStatistics.predictedRSquared.toFixed(4)}</div>`;
            content += `<div class='stat-box'><b>Adeq Precision:</b> ${res.fitStatistics.adequatePrecision.toFixed(2)}</div>`;
            content += `<h3>Final Coded Equation</h3><div class='equation'>${res.fitStatistics.equation}</div>`;
            content += `<h3>ANOVA & Interpretation</h3><div class='markdown'>${res.anovaText.replace(/\n/g, '<br/>')}</div>`;
            content += `<h3>Diagnostics Summary</h3><ul>`;
            content += `<li><b>Model Linearity:</b> ${res.diagnosticInterpretations.predVsActual}</li>`;
            content += `<li><b>Error Variance:</b> ${res.diagnosticInterpretations.residualsVsRun}</li>`;
            content += `<li><b>Transformation Analysis:</b> ${res.diagnosticInterpretations.boxCox}</li>`;
            content += `</ul>`;
        });

        if (topSuggestions.length > 0) {
            content += `<h2>3. Optimization Solutions</h2>`;
            content += `<p>Goal: ${optGoal} (Limits: ${optMin} to ${optMax})</p>`;
            content += `<table><thead><tr><th>Rank</th><th>Predicted ${plotResponse}</th><th>Desirability</th>`;
            factors.forEach(f => content += `<th>${f.name}</th>`);
            content += `</tr></thead><tbody>`;
            topSuggestions.forEach((s, i) => {
                content += `<tr><td>Solution #${i + 1}</td><td>${s.prediction.toFixed(4)}</td><td>${(s.desirability * 100).toFixed(1)}%</td>`;
                factors.forEach(f => content += `<td>${s.factors[f.name].toFixed(3)}</td>`);
                content += `</tr>`;
            });
            content += `</tbody></table>`;
        }
        content += `<div class='footer'>This report was algorithmically generated based on validated regression models. Statistical results assume independent and identically distributed errors.</div>`;

        const blob = new Blob(['\ufeff' + header + content + '</body></html>'], { type: 'application/msword' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `QbD_Full_Report_${plotResponse.replace(/\s+/g, '_')}.doc`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => initial[f.name] = ((parseFloat(f.low) + parseFloat(f.high)) / 2).toString());
        setPredictionInputs(initial);
        if (factors.length >= 2) { setPlotX(factors[0].name); setPlotY(factors[1].name); }
        if (responses.length > 0) setPlotResponse(responses[0].name);
    }, [factors, responses]);

    const activeResult = results.resultsByResponse[plotResponse];

    const getObservedRange = useCallback((resName: string) => {
        const res = results.resultsByResponse[resName];
        if (!res?.diagnostics?.actual?.length) return { min: 0, max: 100 };
        const data = res.diagnostics.actual.filter(v => !isNaN(v));
        return { min: Math.min(...data), max: Math.max(...data) };
    }, [results]);

    useEffect(() => {
        const range = getObservedRange(plotResponse);
        setOptMin(range.min); setOptMax(range.max); setOptTarget((range.min + range.max) / 2);
        const resDef = responses.find(r => r.name === plotResponse);
        if (resDef) setOptGoal(resDef.goal);
    }, [plotResponse, getObservedRange, responses]);

    const toCoded = (val: number, factorName: string) => {
        const factor = factors.find(f => f.name === factorName);
        if (!factor) return 0;
        const low = parseFloat(factor.low), high = parseFloat(factor.high);
        const mid = (high + low) / 2, halfRange = (high - low) / 2;
        return halfRange === 0 ? 0 : (val - mid) / halfRange;
    };

    const calculatePredictionInternal = useCallback((inputs: Record<string, string | number>) => {
        if (!activeResult?.modelCoefficients) return 0;
        const { intercept, linear, quadratic, interactions } = activeResult.modelCoefficients;
        let y = intercept || 0;
        if (linear) Object.entries(linear).forEach(([name, coeff]) => {
            const v = typeof inputs[name] === 'string' ? parseFloat(inputs[name] as string) : (inputs[name] as number);
            if (!isNaN(v)) y += coeff * toCoded(v, name);
        });
        if (quadratic) Object.entries(quadratic).forEach(([name, coeff]) => {
            const v = typeof inputs[name] === 'string' ? parseFloat(inputs[name] as string) : (inputs[name] as number);
            if (!isNaN(v)) y += coeff * Math.pow(toCoded(v, name), 2);
        });
        if (interactions) interactions.forEach(t => {
            const v1 = typeof inputs[t.factor1] === 'string' ? parseFloat(inputs[t.factor1] as string) : (inputs[t.factor1] as number);
            const v2 = typeof inputs[t.factor2] === 'string' ? parseFloat(inputs[t.factor2] as string) : (inputs[t.factor2] as number);
            if (!isNaN(v1) && !isNaN(v2)) y += t.coefficient * toCoded(v1, t.factor1) * toCoded(v2, t.factor2);
        });
        const r = getObservedRange(plotResponse);
        return Math.max(r.min, Math.min(r.max, y));
    }, [activeResult, factors, getObservedRange, plotResponse]);

    const calculatePrediction = () => setPredictedValue(calculatePredictionInternal(predictionInputs));

    const calculateDesirability = useCallback((val: number) => {
        const range = optMax - optMin;
        if (range <= 0 || isNaN(val)) return 0;
        if (optGoal === 'Maximize') return val <= optMin ? 0 : val >= optMax ? 1 : (val - optMin) / range;
        if (optGoal === 'Minimize') return val <= optMin ? 1 : val >= optMax ? 0 : (optMax - val) / range;
        if (val < optMin || val > optMax) return 0;
        if (val === optTarget) return 1;
        return val < optTarget ? (val - optMin) / (optTarget - optMin) : (optMax - val) / (optMax - optTarget);
    }, [optMax, optMin, optGoal, optTarget]);

    const findOptimalConditions = () => {
        if (!activeResult) return;
        const suggestions: OptResult[] = [];
        for (let i = 0; i < 20000; i++) {
            const trial: Record<string, number> = {};
            factors.forEach(f => trial[f.name] = parseFloat(f.low) + Math.random() * (parseFloat(f.high) - parseFloat(f.low)));
            const p = calculatePredictionInternal(trial);
            suggestions.push({ factors: trial, prediction: p, desirability: calculateDesirability(p) });
        }
        suggestions.sort((a, b) => b.desirability - a.desirability);
        const unique: OptResult[] = [];
        for (const s of suggestions) {
            if (unique.length >= 3) break;
            if (!unique.some(e => factors.every(f => Math.abs(e.factors[f.name] - s.factors[f.name]) < (Math.abs(parseFloat(f.high) - parseFloat(f.low)) * 0.1)))) unique.push(s);
        }
        setTopSuggestions(unique);
    };

    useEffect(() => {
        if (!window.Plotly || !plotX || !plotY || !activeResult) return;
        const fX = factors.find(f => f.name === plotX), fY = factors.find(f => f.name === plotY);
        if (!fX || !fY) return;
        const xMin = parseFloat(fX.low), xMax = parseFloat(fX.high), yMin = parseFloat(fY.low), yMax = parseFloat(fY.high);
        const steps = 60, xVals = [], yVals = [], zMat = [], dMat = [];
        for (let i = 0; i <= steps; i++) xVals.push(xMin + (i * (xMax - xMin) / steps));
        for (let i = 0; i <= steps; i++) yVals.push(yMin + (i * (yMax - yMin) / steps));
        for (let j = 0; j <= steps; j++) {
            const rZ = [], rD = [];
            for (let i = 0; i <= steps; i++) {
                const p = calculatePredictionInternal({ ...predictionInputs, [plotX]: xVals[i], [plotY]: yVals[j] });
                rZ.push(p); rD.push(calculateDesirability(p));
            }
            zMat.push(rZ); dMat.push(rD);
        }
        const commonLayout = { margin: { l: 40, r: 20, t: 40, b: 40 }, font: { family: 'Inter', size: 10 }, paper_bgcolor: 'rgba(0,0,0,0)', plot_bgcolor: 'rgba(0,0,0,0)' };
        if (containerRefs.plot3d.current) window.Plotly.react(containerRefs.plot3d.current, [{ z: zMat, x: xVals, y: yVals, type: 'surface', colorscale: 'Viridis', contours: { z: { show: true, project: { z: true } } } }], { ...commonLayout, title: 'Response Surface', scene: { xaxis: { title: plotX }, yaxis: { title: plotY }, zaxis: { title: plotResponse }, camera: { eye: { x: 1.6, y: 1.6, z: 1.1 } } } });
        if (containerRefs.plotContour.current) window.Plotly.react(containerRefs.plotContour.current, [{ z: zMat, x: xVals, y: yVals, type: 'contour', colorscale: 'Portland', contours: { showlabels: true } }], { ...commonLayout, title: 'Contour Model', xaxis: { title: plotX }, yaxis: { title: plotY } });
        if (containerRefs.plotDesirability.current) window.Plotly.react(containerRefs.plotDesirability.current, [{ z: dMat, x: xVals, y: yVals, type: 'contour', colorscale: [[0, '#ef4444'], [0.5, '#facc15'], [1, '#22c55e']], zmin: 0, zmax: 1, contours: { showlabels: true } }], { ...commonLayout, title: 'Desirability Landscape', xaxis: { title: plotX }, yaxis: { title: plotY } });
    }, [plotX, plotY, plotResponse, activeResult, predictionInputs, topSuggestions, calculatePredictionInternal, calculateDesirability, factors]);

    useEffect(() => {
        if (!window.Plotly || !activeResult?.diagnostics) return;
        const d = activeResult.diagnostics;
        const diagLayout = { margin: { t: 30, b: 40, l: 40, r: 10 }, font: { family: 'Inter', size: 9 }, paper_bgcolor: 'rgba(0,0,0,0)', plot_bgcolor: 'rgba(255,255,255,0.4)' };
        const pva = document.getElementById('plotPredVsActual');
        if (pva) window.Plotly.react(pva, [{ x: d.actual, y: d.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9' } }, { x: [Math.min(...d.actual), Math.max(...d.actual)], y: [Math.min(...d.actual), Math.max(...d.actual)], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8' } }], { ...diagLayout, title: 'Actual vs Predicted', xaxis: { title: 'Actual' }, yaxis: { title: 'Predicted' }, showlegend: false });
        const rvr = document.getElementById('plotResidVsRun');
        if (rvr) window.Plotly.react(rvr, [{ x: d.runOrder, y: d.residuals, type: 'scatter', mode: 'markers', marker: { color: '#f97316' } }], { ...diagLayout, title: 'Residuals vs Run', xaxis: { title: 'Run' }, yaxis: { title: 'Residual' }, shapes: [{ type: 'line', x0: Math.min(...d.runOrder), x1: Math.max(...d.runOrder), y0: 0, y1: 0, line: { color: '#000', dash: 'dot' } }] });
        const bc = document.getElementById('plotBoxCox');
        if (bc && d.boxCox) {
            const s: any[] = [];
            if (d.boxCox.ciLimit) s.push({ type: 'line', x0: Math.min(...d.boxCox.lambda), x1: Math.max(...d.boxCox.lambda), y0: d.boxCox.ciLimit, y1: d.boxCox.ciLimit, line: { color: '#ef4444', dash: 'dash', width: 1 } });
            if (d.boxCox.lambdaBest !== undefined) s.push({ type: 'line', x0: d.boxCox.lambdaBest, x1: d.boxCox.lambdaBest, y0: Math.min(...d.boxCox.lnRSS), y1: Math.max(...d.boxCox.lnRSS), line: { color: '#22c55e', width: 2 } });
            if (d.boxCox.lambdaLow !== undefined) s.push({ type: 'line', x0: d.boxCox.lambdaLow, x1: d.boxCox.lambdaLow, y0: Math.min(...d.boxCox.lnRSS), y1: Math.max(...d.boxCox.lnRSS), line: { color: '#ef4444', dash: 'dot', width: 1 } });
            if (d.boxCox.lambdaHigh !== undefined) s.push({ type: 'line', x0: d.boxCox.lambdaHigh, x1: d.boxCox.lambdaHigh, y0: Math.min(...d.boxCox.lnRSS), y1: Math.max(...d.boxCox.lnRSS), line: { color: '#ef4444', dash: 'dot', width: 1 } });
            window.Plotly.react(bc, [{ x: d.boxCox.lambda, y: d.boxCox.lnRSS, type: 'scatter', mode: 'lines', line: { color: '#8b5cf6', width: 3 } }], { ...diagLayout, title: 'Box-Cox Plot', xaxis: { title: 'Lambda' }, yaxis: { title: 'ln(RSS)' }, shapes: s });
        }
    }, [activeResult]);

    if (!activeResult) return <div className="p-12 text-center text-slate-400 bg-white rounded-2xl border-2 border-dashed border-slate-200">Select a response to view the analysis report.</div>;

    const stats = activeResult.fitStatistics;

