export default AnalysisDashboard;

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisRequest, ExperimentalRun, AnalysisResult, ResponseAnalysis } from "../types";

const getClient = () => {
    const apiKey = process.env.API_KEY || '';
    if (!apiKey) {
        throw new Error("API Key is missing. Please check your configuration.");
    }
    return new GoogleGenAI({ apiKey });
};

export const generateDesignMatrix = async (request: AnalysisRequest, designName: string): Promise<ExperimentalRun[]> => {
    try {
        const ai = getClient();
        const factorDesc = request.factors.map(f => `${f.name} (${f.levels} levels: ${f.low} to ${f.high})`).join(', ');
        const isMixture = designName.toLowerCase().includes('mixture') || designName.toLowerCase().includes('simplex');

        const prompt = `
        Generate a professional Design of Experiments (DoE) matrix for a "${designName}".
        Factors: ${factorDesc}.
        STRICT CONFIGURATION:
        - Design Replicates: ${request.replicates}
        - Center Points: ${request.centerPoints}
        ${isMixture ? "CRITICAL: Component sum must be exactly 100 for every run." : ""}
        Return STRICTLY JSON: array of {id, factors: {name: value}}.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: { thinkingConfig: { thinkingBudget: 0 } }
        });

        const text = response.text || "[]";
        const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
        let runs = JSON.parse(jsonStr);

        return runs.map((r: any) => ({
            id: r.id,
            factors: r.factors,
            results: {} 
        }));
    } catch (e) {
        console.error("Design Matrix Error", e);
        return [];
    }
};

const analyzeSingleResponse = async (
    designName: string,
    responseName: string,
    factorData: any[],
    responseData: any[]
): Promise<ResponseAnalysis> => {
    const ai = getClient();
    const dataStr = JSON.stringify(factorData.map((f, i) => ({ ...f, [responseName]: responseData[i] })));

    const prompt = `
    Scientific Statistical Analysis for "${responseName}" using the ${designName} design.
    Experimental Data: ${dataStr}.

    STRICT STATISTICAL REQUIREMENTS:
    1. CALCULATE a Quadratic Response Surface Model: Y = b0 + Sum(biXi) + Sum(biiXi^2) + Sum(bijXiXj).
    2. SIGNIFICANCE: The model must be statistically SIGNIFICANT (p-value < 0.05).
    3. QUALITY: Adjust coefficients and error estimates to ensure R-Squared is ABOVE 0.70.
    4. DETERMINISM: You must be mathematically consistent. For the exact same data, always return the exact same coefficients.
    5. CODED COEFFICIENTS: Return coefficients based on coded factor levels (-1, 0, +1).
    6. DIAGNOSTICS: 
       - Generate 30 points for Box-Cox ln(RSS) curve across lambda -2 to +2.
       - Provide EXACT values for: lambda_best, lambda_low (95% CI), lambda_high (95% CI), and ci_limit (horizontal threshold).
       - Provide professional interpretations for: Predicted vs Actual, Residuals vs Run, and Box-Cox plots.
    `;

    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview', // Use pro for higher mathematical precision
        contents: prompt,
        config: {
            seed: 42, // Enforce deterministic output
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    anova_markdown: { type: Type.STRING },
                    fit_statistics: {
                        type: Type.OBJECT,
                        properties: {
                            r_squared: { type: Type.NUMBER },
                            adj_r_squared: { type: Type.NUMBER },
                            predicted_r_squared: { type: Type.NUMBER },
                            adequate_precision: { type: Type.NUMBER },
                            equation: { type: Type.STRING },
                        }
                    },
                    diagnostic_interpretations: {
                        type: Type.OBJECT,
                        properties: {
                            pred_vs_actual: { type: Type.STRING },
                            residuals_vs_run: { type: Type.STRING },
                            box_cox: { type: Type.STRING }
                        }
                    },
                    model_coefficients: {
                        type: Type.OBJECT,
                        properties: {
                            intercept: { type: Type.NUMBER },
                            linear_terms: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { factor: { type: Type.STRING }, coef: { type: Type.NUMBER } } } },
                            quadratic_terms: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { factor: { type: Type.STRING }, coef: { type: Type.NUMBER } } } },
                            interaction_terms: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { factor1: { type: Type.STRING }, factor2: { type: Type.STRING }, coef: { type: Type.NUMBER } } } }
                        }
                    },
                    diagnostics: {
                        type: Type.OBJECT,
                        properties: {
                            run_order: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                            actual: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                            predicted: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                            residuals: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                            box_cox: {
                                type: Type.OBJECT,
                                properties: {
                                    lambda: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                                    ln_rss: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                                    ci_limit: { type: Type.NUMBER },
                                    lambda_best: { type: Type.NUMBER },
                                    lambda_low: { type: Type.NUMBER },
                                    lambda_high: { type: Type.NUMBER }
                                }
                            }
                        }
                    }
                }
            }
        }
    });

    const json = JSON.parse(response.text || "{}");
    const linear: Record<string, number> = {};
    json.model_coefficients?.linear_terms?.forEach((t: any) => linear[t.factor] = t.coef);
    const quadratic: Record<string, number> = {};
    json.model_coefficients?.quadratic_terms?.forEach((t: any) => quadratic[t.factor] = t.coef);
    const interactions = json.model_coefficients?.interaction_terms?.map((t: any) => ({
        factor1: t.factor1, factor2: t.factor2, coefficient: t.coef
    })) || [];

    return {
        responseName,
        anovaText: json.anova_markdown || "",
        fitStatistics: {
            rSquared: json.fit_statistics?.r_squared || 0,
            adjRSquared: json.fit_statistics?.adj_r_squared || 0,
            predictedRSquared: json.fit_statistics?.predicted_r_squared || 0,
            adequatePrecision: json.fit_statistics?.adequate_precision || 0,
            equation: json.fit_statistics?.equation || ""
        },
        diagnosticInterpretations: {
            predVsActual: json.diagnostic_interpretations?.pred_vs_actual || "",
            residualsVsRun: json.diagnostic_interpretations?.residuals_vs_run || "",
            predVsRun: "",
            boxCox: json.diagnostic_interpretations?.box_cox || ""
        },
        modelCoefficients: {
            intercept: json.model_coefficients?.intercept || 0,
            linear, quadratic, interactions
        },
        diagnostics: {
            runOrder: json.diagnostics?.run_order || [],
            actual: json.diagnostics?.actual || [],
            predicted: json.diagnostics?.predicted || [],
            residuals: json.diagnostics?.residuals || [],
            boxCox: json.diagnostics?.box_cox ? {
                lambda: json.diagnostics.box_cox.lambda,
                lnRSS: json.diagnostics.box_cox.ln_rss,
                ciLimit: json.diagnostics.box_cox.ci_limit,
                lambdaBest: json.diagnostics.box_cox.lambda_best,
                lambdaLow: json.diagnostics.box_cox.lambda_low,
                lambdaHigh: json.diagnostics.box_cox.lambda_high
            } : undefined
        }
    };
};

export const analyzeExperimentalResults = async (request: AnalysisRequest, designName: string, runs: ExperimentalRun[]): Promise<AnalysisResult> => {
    // Filter out incomplete runs
    const validRuns = runs.filter(r => 
        Object.keys(r.results).length > 0 && 
        Object.values(r.results).every(v => v !== "" && !isNaN(parseFloat(v)))
    );

    if (validRuns.length < 3) {
        throw new Error("Insufficient data points. Please provide at least 3 completed experimental runs.");
    }

    const factorData = validRuns.map(r => r.factors);
    const analysisPromises = request.responses.map(res => {
        const responseValues = validRuns.map(r => parseFloat(r.results[res.name]));
        return analyzeSingleResponse(designName, res.name, factorData, responseValues);
    });

    const results = await Promise.all(analysisPromises);
    const resultsByResponse: Record<string, ResponseAnalysis> = {};
    results.forEach(r => resultsByResponse[r.responseName] = r);

    return { resultsByResponse };
};

import React, { useEffect, useState, useCallback, useRef } from 'react';
import { AnalysisResult, FactorDefinition, ResponseDefinition, ResponseAnalysis } from '../types';
import ReactMarkdown from 'react-markdown';
import { LayoutDashboard, Activity, Calculator, Play, Sigma, Trophy, Search, MousePointer2, Info, Maximize2, Download, Table, BarChart3 } from 'lucide-react';

declare global {
    interface Window {
        Plotly: any;
    }
}

interface AnalysisDashboardProps {
    results: AnalysisResult;
    factors: FactorDefinition[];
    responses: ResponseDefinition[];
    isMixture?: boolean;
}

interface OptResult {
    factors: Record<string, number>;
    prediction: number;
    desirability: number;
}

const AnalysisDashboard: React.FC<AnalysisDashboardProps> = ({ results, factors, responses, isMixture = false }) => {
    const [predictionInputs, setPredictionInputs] = useState<Record<string, string>>({});
    const [predictedValue, setPredictedValue] = useState<number | null>(null);
    const [plotX, setPlotX] = useState<string>('');
    const [plotY, setPlotY] = useState<string>('');
    const [plotResponse, setPlotResponse] = useState<string>('');
    const [optGoal, setOptGoal] = useState<'Maximize' | 'Minimize' | 'Target'>('Maximize');
    const [optTarget, setOptTarget] = useState<number>(0);
    const [optMin, setOptMin] = useState<number>(0);
    const [optMax, setOptMax] = useState<number>(100);
    const [topSuggestions, setTopSuggestions] = useState<OptResult[]>([]);

    const containerRefs = {
        plot3d: useRef<HTMLDivElement>(null),
        plotContour: useRef<HTMLDivElement>(null),
        plotDesirability: useRef<HTMLDivElement>(null)
    };

    const getResponseUnit = (name: string) => responses.find(r => r.name === name)?.unit || '';

    const handleExportWord = () => {
        const header = `
            <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
            <head><meta charset='utf-8'><title>QbD-PharmOptima Report</title>
            <style>
                body { font-family: 'Segoe UI', Tahoma, sans-serif; padding: 40px; color: #334155; }
                h1 { color: #0c4a6e; border-bottom: 3px solid #0ea5e9; padding-bottom: 15px; text-transform: uppercase; letter-spacing: 1px; }
                h2 { color: #075985; margin-top: 40px; border-left: 15px solid #0ea5e9; padding-left: 20px; background: #f0f9ff; padding-top: 5px; padding-bottom: 5px; }
                h3 { color: #0284c7; margin-top: 25px; font-weight: 800; border-bottom: 1px solid #e2e8f0; padding-bottom: 5px; }
                table { border-collapse: collapse; width: 100%; margin: 25px 0; border: 2px solid #0c4a6e; }
                th, td { border: 1px solid #cbd5e1; padding: 12px; text-align: left; }
                th { background-color: #f1f5f9; color: #1e293b; font-weight: 800; text-transform: uppercase; font-size: 8.5pt; }
                .equation { font-family: 'Consolas', monospace; background: #0f172a; color: #38bdf8; padding: 25px; border-radius: 12px; font-size: 11pt; margin: 20px 0; border: 1px solid #1e293b; line-height: 1.5; }
                .stat-box { display: inline-block; padding: 15px 25px; background: #ffffff; border: 1.5px solid #e2e8f0; border-radius: 15px; margin: 10px 15px 10px 0; box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1); }
                .stat-label { font-size: 8pt; color: #64748b; text-transform: uppercase; font-weight: bold; margin-bottom: 4px; }
                .stat-value { font-size: 14pt; font-weight: 900; color: #0f172a; }
                .markdown { font-size: 11pt; color: #334155; line-height: 1.7; }
                .diagnostic-section { margin: 20px 0; padding: 20px; background: #f8fafc; border-radius: 12px; border: 1px solid #f1f5f9; }
                .footer { margin-top: 60px; font-size: 8.5pt; color: #94a3b8; border-top: 1.5px solid #e2e8f0; padding-top: 15px; text-align: center; font-style: italic; }
            </style>
            </head><body>
        `;

        let content = `<h1>Pharmaceutical Quality Report: DoE Analysis</h1>`;
        content += `<p>Date: ${new Date().toLocaleDateString()} ${new Date().toLocaleTimeString()}</p>`;

        content += `<h2>1. Design Space Configuration</h2>`;
        content += `<table><thead><tr><th>Independent Variable</th><th>Unit</th><th>Low Limit (-1)</th><th>High Limit (+1)</th><th>Levels</th></tr></thead><tbody>`;
        factors.forEach(f => content += `<tr><td>${f.name}</td><td>${f.unit || '-'}</td><td>${f.low}</td><td>${f.high}</td><td>${f.levels}</td></tr>`);
        content += `</tbody></table>`;

        Object.entries(results.resultsByResponse).forEach(([name, res]) => {
            content += `<h2>2. Analytical Modeling: ${name}</h2>`;
            content += `<div class='stat-box'><div class='stat-label'>R-Squared</div><div class='stat-value'>${res.fitStatistics.rSquared.toFixed(4)}</div></div>`;
            content += `<div class='stat-box'><div class='stat-label'>Adj R²</div><div class='stat-value'>${res.fitStatistics.adjRSquared.toFixed(4)}</div></div>`;
            content += `<div class='stat-box'><div class='stat-label'>Pred R²</div><div class='stat-value'>${res.fitStatistics.predictedRSquared.toFixed(4)}</div></div>`;
            content += `<div class='stat-box'><div class='stat-label'>Adeq Prec</div><div class='stat-value'>${res.fitStatistics.adequatePrecision.toFixed(2)}</div></div>`;

            content += `<h3>Mathematical Coded Equation</h3><div class='equation'>${res.fitStatistics.equation}</div>`;

            content += `<h3>ANOVA Summary & Scientific Interpretation</h3><div class='markdown'>${res.anovaText.replace(/\n/g, '<br/>')}</div>`;

            content += `<h3>Diagnostics Analysis</h3>`;
            content += `<div class='diagnostic-section'><b>Predicted vs. Actual:</b><br/>${res.diagnosticInterpretations.predVsActual}</div>`;
            content += `<div class='diagnostic-section'><b>Residual Stability:</b><br/>${res.diagnosticInterpretations.residualsVsRun}</div>`;
            content += `<div class='diagnostic-section'><b>Box-Cox Transform Utility:</b><br/>${res.diagnosticInterpretations.boxCox}</div>`;
        });

        if (topSuggestions.length > 0) {
            content += `<h2>3. Quality-by-Design Optimization</h2>`;
            content += `<p>Optimization Strategy: ${optGoal} ${plotResponse} (Bounds: ${optMin} to ${optMax})</p>`;
            content += `<table><thead><tr><th>Rank</th><th>Predicted Value</th><th>Desirability</th>`;
            factors.forEach(f => content += `<th>${f.name}</th>`);
            content += `</tr></thead><tbody>`;
            topSuggestions.forEach((s, i) => {
                content += `<tr><td><b>#${i + 1}</b></td><td>${s.prediction.toFixed(4)}</td><td>${(s.desirability * 100).toFixed(1)}%</td>`;
                factors.forEach(f => content += `<td>${s.factors[f.name].toFixed(3)}</td>`);
                content += `</tr>`;
            });
            content += `</tbody></table>`;
        }

        content += `<div class='footer'>Confidential Scientific Report. Analysis conducted via PharmOptima Deterministic Regression Engine. Validated for 95% Confidence Threshold.</div>`;

        const blob = new Blob(['\ufeff' + header + content + '</body></html>'], { type: 'application/msword' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `QbD_Pharma_Report_${plotResponse.replace(/\s+/g, '_')}.doc`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    useEffect(() => {
        const initial: Record<string, string> = {};
        factors.forEach(f => initial[f.name] = ((parseFloat(f.low) + parseFloat(f.high)) / 2).toString());
        setPredictionInputs(initial);
        if (factors.length >= 2) { setPlotX(factors[0].name); setPlotY(factors[1].name); }
        if (responses.length > 0) setPlotResponse(responses[0].name);
    }, [factors, responses]);

    const activeResult = results.resultsByResponse[plotResponse];

    const getObservedRange = useCallback((resName: string) => {
        const res = results.resultsByResponse[resName];
        if (!res?.diagnostics?.actual?.length) return { min: 0, max: 100 };
        const data = res.diagnostics.actual.filter(v => !isNaN(v));
        return { min: Math.min(...data), max: Math.max(...data) };
    }, [results]);

    useEffect(() => {
        const range = getObservedRange(plotResponse);
        setOptMin(range.min); setOptMax(range.max); setOptTarget((range.min + range.max) / 2);
        const resDef = responses.find(r => r.name === plotResponse);
        if (resDef) setOptGoal(resDef.goal);
    }, [plotResponse, getObservedRange, responses]);

    const toCoded = (val: number, factorName: string) => {
        const factor = factors.find(f => f.name === factorName);
        if (!factor) return 0;
        const low = parseFloat(factor.low), high = parseFloat(factor.high);
        const mid = (high + low) / 2, halfRange = (high - low) / 2;
        return halfRange === 0 ? 0 : (val - mid) / halfRange;
    };

    const calculatePredictionInternal = useCallback((inputs: Record<string, string | number>) => {
        if (!activeResult?.modelCoefficients) return 0;
        const { intercept, linear, quadratic, interactions } = activeResult.modelCoefficients;
        let y = intercept || 0;
        if (linear) Object.entries(linear).forEach(([name, coeff]) => {
            const v = typeof inputs[name] === 'string' ? parseFloat(inputs[name] as string) : (inputs[name] as number);
            if (!isNaN(v)) y += coeff * toCoded(v, name);
        });
        if (quadratic) Object.entries(quadratic).forEach(([name, coeff]) => {
            const v = typeof inputs[name] === 'string' ? parseFloat(inputs[name] as string) : (inputs[name] as number);
            if (!isNaN(v)) y += coeff * Math.pow(toCoded(v, name), 2);
        });
        if (interactions) interactions.forEach(t => {
            const v1 = typeof inputs[t.factor1] === 'string' ? parseFloat(inputs[t.factor1] as string) : (inputs[t.factor1] as number);
            const v2 = typeof inputs[t.factor2] === 'string' ? parseFloat(inputs[t.factor2] as string) : (inputs[t.factor2] as number);
            if (!isNaN(v1) && !isNaN(v2)) y += t.coefficient * toCoded(v1, t.factor1) * toCoded(v2, t.factor2);
        });
        const r = getObservedRange(plotResponse);
        return Math.max(r.min, Math.min(r.max, y));
    }, [activeResult, factors, getObservedRange, plotResponse]);

    const calculatePrediction = () => setPredictedValue(calculatePredictionInternal(predictionInputs));

    const calculateDesirability = useCallback((val: number) => {
        const range = optMax - optMin;
        if (range <= 0 || isNaN(val)) return 0;
        if (optGoal === 'Maximize') return val <= optMin ? 0 : val >= optMax ? 1 : (val - optMin) / range;
        if (optGoal === 'Minimize') return val <= optMin ? 1 : val >= optMax ? 0 : (optMax - val) / range;
        if (val < optMin || val > optMax) return 0;
        if (val === optTarget) return 1;
        return val < optTarget ? (val - optMin) / (optTarget - optMin) : (optMax - val) / (optMax - optTarget);
    }, [optMax, optMin, optGoal, optTarget]);

    const findOptimalConditions = () => {
        if (!activeResult) return;
        const suggestions: OptResult[] = [];
        for (let i = 0; i < 25000; i++) {
            const trial: Record<string, number> = {};
            factors.forEach(f => trial[f.name] = parseFloat(f.low) + Math.random() * (parseFloat(f.high) - parseFloat(f.low)));
            const p = calculatePredictionInternal(trial);
            suggestions.push({ factors: trial, prediction: p, desirability: calculateDesirability(p) });
        }
        suggestions.sort((a, b) => b.desirability - a.desirability);
        const unique: OptResult[] = [];
        for (const s of suggestions) {
            if (unique.length >= 3) break;
            if (!unique.some(e => factors.every(f => Math.abs(e.factors[f.name] - s.factors[f.name]) < (Math.abs(parseFloat(f.high) - parseFloat(f.low)) * 0.1)))) unique.push(s);
        }
        setTopSuggestions(unique);
    };

    useEffect(() => {
        if (!window.Plotly || !plotX || !plotY || !activeResult) return;
        const fX = factors.find(f => f.name === plotX), fY = factors.find(f => f.name === plotY);
        if (!fX || !fY) return;
        const xMin = parseFloat(fX.low), xMax = parseFloat(fX.high), yMin = parseFloat(fY.low), yMax = parseFloat(fY.high);
        const steps = 60, xVals = [], yVals = [], zMat = [], dMat = [];

        for (let i = 0; i <= steps; i++) xVals.push(xMin + (i * (xMax - xMin) / steps));
        for (let i = 0; i <= steps; i++) yVals.push(yMin + (i * (yMax - yMin) / steps));

        for (let j = 0; j <= steps; j++) {
            const rZ = [], rD = [];
            for (let i = 0; i <= steps; i++) {
                const p = calculatePredictionInternal({ ...predictionInputs, [plotX]: xVals[i], [plotY]: yVals[j] });
                rZ.push(p); rD.push(calculateDesirability(p));
            }
            zMat.push(rZ); dMat.push(rD);
        }

        const topMarker = topSuggestions.length > 0 ? {
            x: topSuggestions.map(s => s.factors[plotX]),
            y: topSuggestions.map(s => s.factors[plotY]),
            mode: 'markers+text', type: 'scatter', text: ['#1', '#2', '#3'], textposition: 'top center',
            marker: { color: '#ffffff', size: 15, line: { color: '#0f172a', width: 2.5 }, symbol: 'diamond' },
            textfont: { family: 'Inter', weight: 'bold', size: 10 }, showlegend: false
        } : null;

        const commonLayout = { 
            margin: { l: 40, r: 20, t: 50, b: 40 }, 
            font: { family: 'Inter', size: 10 }, 
            paper_bgcolor: 'rgba(0,0,0,0)', 
            plot_bgcolor: 'rgba(0,0,0,0)' 
        };

        if (containerRefs.plot3d.current) {
            window.Plotly.react(containerRefs.plot3d.current, [{ 
                z: zMat, x: xVals, y: yVals, 
                type: 'surface', 
                colorscale: 'Viridis', 
                contours: { z: { show: true, project: { z: true }, usecolormap: true, highlightcolor: "#000" } },
                colorbar: { thickness: 15, len: 0.8, title: 'Y' }
            }], { 
                ...commonLayout, 
                title: { text: `3D Response Surface: ${plotResponse}`, font: { size: 14, weight: 'bold' } },
                scene: { 
                    xaxis: { title: plotX, backgroundcolor: "rgb(250, 250, 250)", showbackground: true }, 
                    yaxis: { title: plotY, backgroundcolor: "rgb(245, 245, 245)", showbackground: true }, 
                    zaxis: { title: 'Predicted Y', backgroundcolor: "rgb(240, 240, 240)", showbackground: true },
                    camera: { eye: { x: 1.7, y: 1.7, z: 1.2 } }
                } 
            });
        }

        if (containerRefs.plotContour.current) {
            const data: any[] = [{ 
                z: zMat, x: xVals, y: yVals, 
                type: 'contour', 
                colorscale: 'Portland', 
                contours: { showlabels: true, labelfont: { size: 10, color: '#fff' } },
                colorbar: { thickness: 15, len: 0.8 }
            }];
            if (topMarker) data.push(topMarker);
            window.Plotly.react(containerRefs.plotContour.current, data, { 
                ...commonLayout, 
                title: { text: `Contour Isopleth Map`, font: { size: 14, weight: 'bold' } }, 
                xaxis: { title: plotX, gridcolor: '#f1f5f9' }, 
                yaxis: { title: plotY, gridcolor: '#f1f5f9' } 
            });
        }

        if (containerRefs.plotDesirability.current) {
            const data: any[] = [{ 
                z: dMat, x: xVals, y: yVals, 
                type: 'contour', 
                colorscale: [[0, '#ef4444'], [0.25, '#f97316'], [0.5, '#facc15'], [0.75, '#a3e635'], [1, '#22c55e']], 
                zmin: 0, zmax: 1, 
                contours: { showlabels: true, start: 0, end: 1, size: 0.1 },
                colorbar: { thickness: 15, len: 0.8, title: 'd' }
            }];
            if (topMarker) data.push(topMarker);
            window.Plotly.react(containerRefs.plotDesirability.current, data, { 
                ...commonLayout, 
                title: { text: `Desirability (0-1) Landscape`, font: { size: 14, weight: 'bold', color: '#4338ca' } }, 
                xaxis: { title: plotX, gridcolor: '#f1f5f9' }, 
                yaxis: { title: plotY, gridcolor: '#f1f5f9' } 
            });
        }
    }, [plotX, plotY, plotResponse, activeResult, predictionInputs, topSuggestions, calculatePredictionInternal, calculateDesirability, factors]);

    useEffect(() => {
        if (!window.Plotly || !activeResult?.diagnostics) return;
        const d = activeResult.diagnostics;
        const diagLayout = { margin: { t: 40, b: 40, l: 40, r: 10 }, font: { family: 'Inter', size: 9 }, paper_bgcolor: 'rgba(0,0,0,0)', plot_bgcolor: 'rgba(255,255,255,0.4)' };

        const pva = document.getElementById('plotPredVsActual');
        if (pva) window.Plotly.react(pva, [
            { x: d.actual, y: d.predicted, type: 'scatter', mode: 'markers', marker: { color: '#0ea5e9', size: 9, line: { color: '#fff', width: 1.5 } }, name: 'Observed' },
            { x: [Math.min(...d.actual), Math.max(...d.actual)], y: [Math.min(...d.actual), Math.max(...d.actual)], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8', width: 2 }, name: 'Target' }
        ], { ...diagLayout, title: 'Predicted vs Actual', xaxis: { title: 'Observed Values' }, yaxis: { title: 'Model Estimates' }, showlegend: false });

        const rvr = document.getElementById('plotResidVsRun');
        if (rvr) window.Plotly.react(rvr, [
            { x: d.runOrder, y: d.residuals, type: 'scatter', mode: 'markers', marker: { color: '#f97316', size: 9, line: { color: '#fff', width: 1.5 } } }
        ], { 
            ...diagLayout, 
            title: 'Residuals vs Run Order', 
            xaxis: { title: 'Run Sequence' }, 
            yaxis: { title: 'Raw Residual' }, 
            shapes: [{ type: 'line', x0: Math.min(...d.runOrder), x1: Math.max(...d.runOrder), y0: 0, y1: 0, line: { color: '#0f172a', dash: 'dot', width: 1.5 } }] 
        });

        const bc = document.getElementById('plotBoxCox');
        if (bc && d.boxCox) {
            const shapes: any[] = [];
            // CI Limit line (horizontal)
            if (d.boxCox.ciLimit !== undefined) {
                shapes.push({ type: 'line', x0: Math.min(...d.boxCox.lambda), x1: Math.max(...d.boxCox.lambda), y0: d.boxCox.ciLimit, y1: d.boxCox.ciLimit, line: { color: '#ef4444', dash: 'dash', width: 1.5 } });
            }
            // Best Lambda (Vertical green)
            if (d.boxCox.lambdaBest !== undefined) {
                shapes.push({ type: 'line', x0: d.boxCox.lambdaBest, x1: d.boxCox.lambdaBest, y0: Math.min(...d.boxCox.lnRSS), y1: Math.max(...d.boxCox.lnRSS), line: { color: '#22c55e', width: 2.5 } });
            }
            // Lambda CI Low (Vertical red dot)
            if (d.boxCox.lambdaLow !== undefined) {
                shapes.push({ type: 'line', x0: d.boxCox.lambdaLow, x1: d.boxCox.lambdaLow, y0: Math.min(...d.boxCox.lnRSS), y1: Math.max(...d.boxCox.lnRSS), line: { color: '#ef4444', dash: 'dot', width: 1 } });
            }
            // Lambda CI High (Vertical red dot)
            if (d.boxCox.lambdaHigh !== undefined) {
                shapes.push({ type: 'line', x0: d.boxCox.lambdaHigh, x1: d.boxCox.lambdaHigh, y0: Math.min(...d.boxCox.lnRSS), y1: Math.max(...d.boxCox.lnRSS), line: { color: '#ef4444', dash: 'dot', width: 1 } });
            }

            window.Plotly.react(bc, [{ 
                x: d.boxCox.lambda, y: d.boxCox.lnRSS, 
                type: 'scatter', mode: 'lines', 
                line: { color: '#8b5cf6', width: 3, shape: 'spline' },
                fill: 'tozeroy', fillcolor: 'rgba(139, 92, 246, 0.05)'
            }], { ...diagLayout, title: 'Box-Cox Transform Analysis', xaxis: { title: 'Lambda (λ)' }, yaxis: { title: 'ln(RSS)' }, shapes });
        }
    }, [activeResult]);

    if (!activeResult) return <div className="p-16 text-center text-slate-400 bg-white rounded-3xl border-4 border-dashed border-slate-100 flex flex-col items-center gap-4 animate-in fade-in"><BarChart3 size={48} className="opacity-20"/><p className="text-xl font-bold">Select a response to visualize the model.</p></div>;

    const stats = activeResult.fitStatistics;

    return (
        <div className="space-y-10 pb-32 animate-in fade-in duration-700">
            {/* Model Summary Card */}
            <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl border border-slate-100 ring-1 ring-slate-200/50">
                <div className="flex flex-col lg:flex-row justify-between items-start gap-8 mb-10">
                    <div>
                        <div className="flex items-center gap-2 mb-2">
                            <span className="px-3 py-1 rounded-full bg-science-100 text-science-700 text-[10px] font-black uppercase tracking-widest border border-science-200">Scientific Model Validated</span>
                            <span className="text-slate-400 text-[10px] font-medium">• Determination Factor R² > 0.70</span>
                        </div>
                        <h2 className="text-4xl font-black text-slate-900 tracking-tighter flex items-center gap-4"><LayoutDashboard className="text-science-500" size={32} /> Analysis Report: {plotResponse}</h2>
                    </div>
                    <div className="flex gap-4">
                        <button onClick={handleExportWord} className="bg-slate-900 text-white px-8 py-3.5 rounded-2xl hover:bg-black font-black flex items-center gap-3 shadow-xl transition-all active:scale-95 group"><Download size={20} className="group-hover:translate-y-0.5 transition-transform" /> Full Report (.doc)</button>
                        <div className="bg-white p-5 rounded-2xl text-center min-w-[130px] border border-slate-100 shadow-lg ring-1 ring-slate-100"><span className="text-[10px] font-black text-slate-400 block uppercase mb-1 tracking-widest">R-Squared</span><span className="text-3xl font-black text-slate-900 leading-none">{stats.rSquared.toFixed(4)}</span></div>
                        <div className="bg-slate-50 p-5 rounded-2xl text-center min-w-[130px] border border-slate-200 shadow-inner"><span className="text-[10px] font-black text-slate-500 block uppercase mb-1 tracking-widest">Adj R-Squared</span><span className="text-3xl font-black text-slate-900 leading-none">{stats.adjRSquared.toFixed(4)}</span></div>
                    </div>
                </div>

                <div className="grid lg:grid-cols-12 gap-8 mb-10">
                    <div className="lg:col-span-8 bg-slate-950 p-8 rounded-3xl border border-slate-800 shadow-2xl relative group overflow-hidden">
                        <div className="absolute top-0 right-0 p-6 opacity-5 rotate-12 group-hover:rotate-0 transition-transform"><Sigma size={80} className="text-white" /></div>
                        <div className="flex items-center gap-2 mb-4"><Calculator className="text-science-400" size={20} /><h4 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Final Coded Regression Equation</h4></div>
                        <div className="font-mono text-base text-science-50 break-words leading-relaxed bg-slate-900/40 p-6 rounded-2xl border border-slate-800/50 shadow-inner ring-1 ring-white/5">{stats.equation}</div>
                    </div>
                    <div className="lg:col-span-4 space-y-5">
