                                    <span className="text-2xl font-bold text-slate-400 lowercase">{getResponseUnit(plotResponse)}</span>
                                </div>
                            </div>
                        )}
                    </div>
                    <div className="mt-12 flex items-start gap-6 bg-science-50/70 p-8 rounded-[2.5rem] border border-science-100 shadow-sm transition-all hover:bg-white hover:border-science-200">
                        <Sigma size={24} className="text-science-500 shrink-0 mt-1.5" />
                        <div className="space-y-2">
                            <p className="text-sm text-slate-800 leading-relaxed font-black">Analytical Validity Notice:</p>
                            <p className="text-[11px] text-slate-500 leading-relaxed font-medium">This predictor utilizes deterministic 95% confidence interval coefficients calculated from the input data set. To prevent scientific extrapolation and ensure QbD compliance, result estimations are strictly clamped to the experimental boundaries: <span className="text-science-600 font-bold">[{getObservedRange(plotResponse).min.toFixed(3)} - {getObservedRange(plotResponse).max.toFixed(3)}]</span>.</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

