            { x: [Math.min(...d.actual), Math.max(...d.actual)], y: [Math.min(...d.actual), Math.max(...d.actual)], type: 'scatter', mode: 'lines', line: { dash: 'dash', color: '#94a3b8', width: 2 }, name: 'Target' }
