                            <p className="text-[11px] text-slate-500 leading-relaxed font-medium">This predictor utilizes deterministic 95% confidence interval coefficients calculated from the input data set. To prevent scientific extrapolation and ensure QbD compliance, result estimations are strictly clamped to the experimental boundaries: <span className="text-science-600 font-bold">[{getObservedRange(plotResponse).min.toFixed(3)} - {getObservedRange(plotResponse).max.toFixed(3)}]</span>.</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

